-- R3.2 (#2237): collapse the fifteen database schemas into five and the sixteen owner roles into one.
--
-- Schemas: vortex_module and vortex_page join vortex_definition; vortex_activity and vortex_search join
-- vortex_record; vortex_connection, vortex_context, vortex_event, vortex_file, vortex_invalidation,
-- vortex_operations and vortex_workflow become vortex_platform. vortex_identity and vortex_access are unchanged.
--
-- Roles: the fifteen per-schema owner roles merge into vortex_owner. vortex_record_adapter and
-- vortex_record_inventory stay separate restricted roles because their record_data policies scope rows to the
-- caller's organisation; merging them into an unrestricted owner would let the owner's unrestricted policies
-- override that scoping. Objects that postgres owns stay with postgres.
--
-- Objects move with ALTER ... SET SCHEMA, which keeps identity, dependent objects, policies and privileges.
-- The functions whose text names a moved schema or a merged role are then re-created with their final bodies.
-- Privileges the merged roles held on objects owned by other roles are copied to vortex_owner first, and
-- the schemas merged into another schema hand their privileges to it.

do $role$
begin
  if not exists (select 1 from pg_catalog.pg_roles where rolname = 'vortex_owner') then
    create role vortex_owner nologin noinherit nosuperuser nocreatedb nocreaterole noreplication nobypassrls;
  else
    alter role vortex_owner nologin noinherit nosuperuser nocreatedb nocreaterole noreplication nobypassrls;
  end if;
end
$role$;
-- Reassigning objects needs the privileges of every role involved; the merged roles are dropped below.
grant vortex_owner to postgres with admin false, inherit true, set true;
grant vortex_access_owner to postgres with admin false, inherit true, set true;
grant vortex_activity_owner to postgres with admin false, inherit true, set true;
grant vortex_connection_owner to postgres with admin false, inherit true, set true;
grant vortex_context_owner to postgres with admin false, inherit true, set true;
grant vortex_definition_owner to postgres with admin false, inherit true, set true;
grant vortex_event_owner to postgres with admin false, inherit true, set true;
grant vortex_file_owner to postgres with admin false, inherit true, set true;
grant vortex_identity_owner to postgres with admin false, inherit true, set true;
grant vortex_invalidation_owner to postgres with admin false, inherit true, set true;
grant vortex_module_owner to postgres with admin false, inherit true, set true;
grant vortex_operations_owner to postgres with admin false, inherit true, set true;
grant vortex_page_owner to postgres with admin false, inherit true, set true;
grant vortex_record_owner to postgres with admin false, inherit true, set true;
grant vortex_search_owner to postgres with admin false, inherit true, set true;
grant vortex_workflow_owner to postgres with admin false, inherit true, set true;

create schema vortex_platform authorization vortex_owner;

-- The new owner of an object needs CREATE on the schema that holds it, and USAGE to move it.
do $schema_create$
declare
  entry record;
begin
  for entry in
    select n.nspname, owner.rolname as owner
    from pg_catalog.pg_namespace as n
    join pg_catalog.pg_roles as owner on owner.oid = n.nspowner
    where n.nspname like 'vortex\_%' or n.nspname = 'record_data'
  loop
    execute pg_catalog.format('set local role %I', entry.owner);
    execute pg_catalog.format('grant usage, create on schema %I to vortex_owner', entry.nspname);
    reset role;
  end loop;
end
$schema_create$;

reassign owned by vortex_access_owner, vortex_activity_owner, vortex_connection_owner, vortex_context_owner, vortex_definition_owner, vortex_event_owner, vortex_file_owner, vortex_identity_owner, vortex_invalidation_owner, vortex_module_owner, vortex_operations_owner, vortex_page_owner, vortex_record_owner, vortex_search_owner, vortex_workflow_owner to vortex_owner;

-- postgres owns functions that move into these schemas and are re-created there.
grant create on schema vortex_definition, vortex_record to postgres;
grant create on schema vortex_record to vortex_record_inventory;

-- Tables move to their new schema; function signatures that name their row types follow.
set local role vortex_owner;
alter table vortex_module.installation_bindings set schema vortex_definition;
alter table vortex_module.installation_runtime_bundle_parts set schema vortex_definition;
alter table vortex_module.installation_runtime_bundles set schema vortex_definition;
alter table vortex_module.preview_installations set schema vortex_definition;
reset role;

set local role postgres;
