-- Privileges on a merged schema pass to the schema that absorbs it.
do $schema_privileges$
declare
  entry record;
begin
  for entry in
    select merged.destination,
           case when role.rolname = any (array['vortex_access_owner','vortex_activity_owner','vortex_connection_owner','vortex_context_owner','vortex_definition_owner','vortex_event_owner','vortex_file_owner','vortex_identity_owner','vortex_invalidation_owner','vortex_module_owner','vortex_operations_owner','vortex_page_owner','vortex_record_owner','vortex_search_owner','vortex_workflow_owner']) then 'vortex_owner' else role.rolname end as grantee,
           privilege.privilege_type,
           privilege.is_grantable,
           destination_owner.rolname as destination_owner
    from (values ('vortex_module', 'vortex_definition'), ('vortex_page', 'vortex_definition'), ('vortex_activity', 'vortex_record'), ('vortex_search', 'vortex_record'), ('vortex_connection', 'vortex_platform'), ('vortex_context', 'vortex_platform'), ('vortex_event', 'vortex_platform'), ('vortex_file', 'vortex_platform'), ('vortex_invalidation', 'vortex_platform'), ('vortex_operations', 'vortex_platform'), ('vortex_workflow', 'vortex_platform')) as merged (source, destination)
    join pg_catalog.pg_namespace as source_schema on source_schema.nspname = merged.source
    join pg_catalog.pg_namespace as destination_schema on destination_schema.nspname = merged.destination
    join pg_catalog.pg_roles as destination_owner on destination_owner.oid = destination_schema.nspowner
    cross join lateral pg_catalog.aclexplode(source_schema.nspacl) as privilege
    join pg_catalog.pg_roles as role on role.oid = privilege.grantee
    where not (destination_owner.rolname = 'vortex_owner'
      and (case when role.rolname = any (array['vortex_access_owner','vortex_activity_owner','vortex_connection_owner','vortex_context_owner','vortex_definition_owner','vortex_event_owner','vortex_file_owner','vortex_identity_owner','vortex_invalidation_owner','vortex_module_owner','vortex_operations_owner','vortex_page_owner','vortex_record_owner','vortex_search_owner','vortex_workflow_owner']) then 'vortex_owner' else role.rolname end) = 'vortex_owner')
  loop
    execute pg_catalog.format('set local role %I', entry.destination_owner);
    execute pg_catalog.format(
      'grant %s on schema %I to %I%s',
      entry.privilege_type, entry.destination, entry.grantee,
      case when entry.is_grantable then ' with grant option' else '' end
    );
    reset role;
  end loop;
end
$schema_privileges$;

-- Privileges the merged roles held on objects other roles own pass to vortex_owner.
do $owner_privileges$
declare
  entry record;
begin
  for entry in
    select 'schema' as kind, n.nspname::text as object, null::text as column_name, privilege.privilege_type, privilege.is_grantable, (select pg_catalog.pg_roles.rolname from pg_catalog.pg_roles where pg_catalog.pg_roles.oid = privilege.grantor) as owner
    from pg_catalog.pg_namespace as n
    join pg_catalog.pg_roles as owner on owner.oid = n.nspowner
    cross join lateral pg_catalog.aclexplode(n.nspacl) as privilege
    join pg_catalog.pg_roles as grantee on grantee.oid = privilege.grantee
    where grantee.rolname = any (array['vortex_access_owner','vortex_activity_owner','vortex_connection_owner','vortex_context_owner','vortex_definition_owner','vortex_event_owner','vortex_file_owner','vortex_identity_owner','vortex_invalidation_owner','vortex_module_owner','vortex_operations_owner','vortex_page_owner','vortex_record_owner','vortex_search_owner','vortex_workflow_owner']) and owner.rolname <> 'vortex_owner'
      and n.nspname <> all (array['vortex_module','vortex_page','vortex_activity','vortex_search','vortex_connection','vortex_context','vortex_event','vortex_file','vortex_invalidation','vortex_operations','vortex_workflow'])
    union all
    select case when c.relkind = 'S' then 'sequence' else 'table' end, pg_catalog.format('%I.%I', n.nspname, c.relname), null, privilege.privilege_type, privilege.is_grantable, (select pg_catalog.pg_roles.rolname from pg_catalog.pg_roles where pg_catalog.pg_roles.oid = privilege.grantor)
    from pg_catalog.pg_class as c
    join pg_catalog.pg_namespace as n on n.oid = c.relnamespace
    join pg_catalog.pg_roles as owner on owner.oid = c.relowner
    cross join lateral pg_catalog.aclexplode(c.relacl) as privilege
    join pg_catalog.pg_roles as grantee on grantee.oid = privilege.grantee
    where c.relkind in ('r', 'p', 'v', 'm', 'S') and grantee.rolname = any (array['vortex_access_owner','vortex_activity_owner','vortex_connection_owner','vortex_context_owner','vortex_definition_owner','vortex_event_owner','vortex_file_owner','vortex_identity_owner','vortex_invalidation_owner','vortex_module_owner','vortex_operations_owner','vortex_page_owner','vortex_record_owner','vortex_search_owner','vortex_workflow_owner']) and owner.rolname <> 'vortex_owner'
    union all
    select 'column', pg_catalog.format('%I.%I', n.nspname, c.relname), a.attname::text, privilege.privilege_type, privilege.is_grantable, (select pg_catalog.pg_roles.rolname from pg_catalog.pg_roles where pg_catalog.pg_roles.oid = privilege.grantor)
    from pg_catalog.pg_attribute as a
    join pg_catalog.pg_class as c on c.oid = a.attrelid
    join pg_catalog.pg_namespace as n on n.oid = c.relnamespace
    join pg_catalog.pg_roles as owner on owner.oid = c.relowner
    cross join lateral pg_catalog.aclexplode(a.attacl) as privilege
    join pg_catalog.pg_roles as grantee on grantee.oid = privilege.grantee
    where grantee.rolname = any (array['vortex_access_owner','vortex_activity_owner','vortex_connection_owner','vortex_context_owner','vortex_definition_owner','vortex_event_owner','vortex_file_owner','vortex_identity_owner','vortex_invalidation_owner','vortex_module_owner','vortex_operations_owner','vortex_page_owner','vortex_record_owner','vortex_search_owner','vortex_workflow_owner']) and owner.rolname <> 'vortex_owner'
    union all
    select 'function', p.oid::pg_catalog.regprocedure::text, null, privilege.privilege_type, privilege.is_grantable, (select pg_catalog.pg_roles.rolname from pg_catalog.pg_roles where pg_catalog.pg_roles.oid = privilege.grantor)
    from pg_catalog.pg_proc as p
    join pg_catalog.pg_roles as owner on owner.oid = p.proowner
    cross join lateral pg_catalog.aclexplode(p.proacl) as privilege
    join pg_catalog.pg_roles as grantee on grantee.oid = privilege.grantee
    where grantee.rolname = any (array['vortex_access_owner','vortex_activity_owner','vortex_connection_owner','vortex_context_owner','vortex_definition_owner','vortex_event_owner','vortex_file_owner','vortex_identity_owner','vortex_invalidation_owner','vortex_module_owner','vortex_operations_owner','vortex_page_owner','vortex_record_owner','vortex_search_owner','vortex_workflow_owner']) and owner.rolname <> 'vortex_owner'
  loop
    execute pg_catalog.format('set local role %I', entry.owner);
    execute case entry.kind
      when 'column' then pg_catalog.format('grant %s (%I) on table %s to vortex_owner%s', entry.privilege_type, entry.column_name, entry.object, case when entry.is_grantable then ' with grant option' else '' end)
      else pg_catalog.format('grant %s on %s %s to vortex_owner%s', entry.privilege_type, entry.kind, entry.object, case when entry.is_grantable then ' with grant option' else '' end)
    end;
    reset role;
  end loop;
end
$owner_privileges$;

-- Policies written for a merged owner role now name vortex_owner.
do $policies$
declare
  entry record;
begin
  for entry in
    select policy.polname, pg_catalog.format('%I.%I', n.nspname, c.relname) as relation, owner.rolname as owner,
           (select pg_catalog.string_agg(distinct case when role_name.rolname = any (array['vortex_access_owner','vortex_activity_owner','vortex_connection_owner','vortex_context_owner','vortex_definition_owner','vortex_event_owner','vortex_file_owner','vortex_identity_owner','vortex_invalidation_owner','vortex_module_owner','vortex_operations_owner','vortex_page_owner','vortex_record_owner','vortex_search_owner','vortex_workflow_owner']) then 'vortex_owner' else coalesce(role_name.rolname, 'public') end, ', ')
            from unnest(policy.polroles) as policy_role (oid)
            left join pg_catalog.pg_roles as role_name on role_name.oid = policy_role.oid) as roles
    from pg_catalog.pg_policy as policy
    join pg_catalog.pg_class as c on c.oid = policy.polrelid
    join pg_catalog.pg_namespace as n on n.oid = c.relnamespace
    join pg_catalog.pg_roles as owner on owner.oid = c.relowner
    where policy.polroles && array(select oid from pg_catalog.pg_roles where rolname = any (array['vortex_access_owner','vortex_activity_owner','vortex_connection_owner','vortex_context_owner','vortex_definition_owner','vortex_event_owner','vortex_file_owner','vortex_identity_owner','vortex_invalidation_owner','vortex_module_owner','vortex_operations_owner','vortex_page_owner','vortex_record_owner','vortex_search_owner','vortex_workflow_owner']))
  loop
    execute pg_catalog.format('set local role %I', entry.owner);
    execute pg_catalog.format('alter policy %I on %s to %s', entry.polname, entry.relation, entry.roles);
    reset role;
  end loop;
end
$policies$;

-- DROP OWNED cannot revoke what another role granted, so each grantor revokes the merged roles' privileges.
do $revoke_privileges$
declare
  entry record;
begin
  for entry in
    select 'schema' as kind, n.nspname::text as object, null::text as column_name, privilege.privilege_type, privilege.is_grantable, grantee.rolname as grantee_name, (select pg_catalog.pg_roles.rolname from pg_catalog.pg_roles where pg_catalog.pg_roles.oid = privilege.grantor) as owner
    from pg_catalog.pg_namespace as n
    join pg_catalog.pg_roles as owner on owner.oid = n.nspowner
    cross join lateral pg_catalog.aclexplode(n.nspacl) as privilege
    join pg_catalog.pg_roles as grantee on grantee.oid = privilege.grantee
    where grantee.rolname = any (array['vortex_access_owner','vortex_activity_owner','vortex_connection_owner','vortex_context_owner','vortex_definition_owner','vortex_event_owner','vortex_file_owner','vortex_identity_owner','vortex_invalidation_owner','vortex_module_owner','vortex_operations_owner','vortex_page_owner','vortex_record_owner','vortex_search_owner','vortex_workflow_owner'])
    union all
    select case when c.relkind = 'S' then 'sequence' else 'table' end, pg_catalog.format('%I.%I', n.nspname, c.relname), null, privilege.privilege_type, privilege.is_grantable, grantee.rolname as grantee_name, (select pg_catalog.pg_roles.rolname from pg_catalog.pg_roles where pg_catalog.pg_roles.oid = privilege.grantor)
    from pg_catalog.pg_class as c
    join pg_catalog.pg_namespace as n on n.oid = c.relnamespace
    join pg_catalog.pg_roles as owner on owner.oid = c.relowner
    cross join lateral pg_catalog.aclexplode(c.relacl) as privilege
    join pg_catalog.pg_roles as grantee on grantee.oid = privilege.grantee
    where c.relkind in ('r', 'p', 'v', 'm', 'S') and grantee.rolname = any (array['vortex_access_owner','vortex_activity_owner','vortex_connection_owner','vortex_context_owner','vortex_definition_owner','vortex_event_owner','vortex_file_owner','vortex_identity_owner','vortex_invalidation_owner','vortex_module_owner','vortex_operations_owner','vortex_page_owner','vortex_record_owner','vortex_search_owner','vortex_workflow_owner'])
    union all
    select 'column', pg_catalog.format('%I.%I', n.nspname, c.relname), a.attname::text, privilege.privilege_type, privilege.is_grantable, grantee.rolname as grantee_name, (select pg_catalog.pg_roles.rolname from pg_catalog.pg_roles where pg_catalog.pg_roles.oid = privilege.grantor)
    from pg_catalog.pg_attribute as a
    join pg_catalog.pg_class as c on c.oid = a.attrelid
    join pg_catalog.pg_namespace as n on n.oid = c.relnamespace
    join pg_catalog.pg_roles as owner on owner.oid = c.relowner
    cross join lateral pg_catalog.aclexplode(a.attacl) as privilege
    join pg_catalog.pg_roles as grantee on grantee.oid = privilege.grantee
    where grantee.rolname = any (array['vortex_access_owner','vortex_activity_owner','vortex_connection_owner','vortex_context_owner','vortex_definition_owner','vortex_event_owner','vortex_file_owner','vortex_identity_owner','vortex_invalidation_owner','vortex_module_owner','vortex_operations_owner','vortex_page_owner','vortex_record_owner','vortex_search_owner','vortex_workflow_owner'])
    union all
    select 'function', p.oid::pg_catalog.regprocedure::text, null, privilege.privilege_type, privilege.is_grantable, grantee.rolname as grantee_name, (select pg_catalog.pg_roles.rolname from pg_catalog.pg_roles where pg_catalog.pg_roles.oid = privilege.grantor)
    from pg_catalog.pg_proc as p
    join pg_catalog.pg_roles as owner on owner.oid = p.proowner
    cross join lateral pg_catalog.aclexplode(p.proacl) as privilege
    join pg_catalog.pg_roles as grantee on grantee.oid = privilege.grantee
    where grantee.rolname = any (array['vortex_access_owner','vortex_activity_owner','vortex_connection_owner','vortex_context_owner','vortex_definition_owner','vortex_event_owner','vortex_file_owner','vortex_identity_owner','vortex_invalidation_owner','vortex_module_owner','vortex_operations_owner','vortex_page_owner','vortex_record_owner','vortex_search_owner','vortex_workflow_owner'])
  loop
    execute pg_catalog.format('set local role %I', entry.owner);
    execute case entry.kind
      when 'column' then pg_catalog.format('revoke %s (%I) on table %s from %I', entry.privilege_type, entry.column_name, entry.object, entry.grantee_name)
      else pg_catalog.format('revoke %s on %s %s from %I', entry.privilege_type, entry.kind, entry.object, entry.grantee_name)
    end;
    reset role;
  end loop;
end
$revoke_privileges$;

-- Validating a re-created function needs EXECUTE for its owner; a few owners had it revoked, so restore it for now.
create temporary table owner_without_execute on commit drop as
select p.oid::pg_catalog.regprocedure::text as function_name, owner.rolname as owner
from pg_catalog.pg_proc as p
join pg_catalog.pg_namespace as n on n.oid = p.pronamespace
join pg_catalog.pg_roles as owner on owner.oid = p.proowner
where n.nspname in ('vortex_identity', 'vortex_access', 'vortex_definition', 'vortex_record', 'vortex_platform')
  and p.proacl is not null
  and not exists (
    select 1 from pg_catalog.aclexplode(p.proacl) as privilege
    where privilege.grantee = p.proowner and privilege.privilege_type = 'EXECUTE'
  );
do $owner_execute$
declare
  entry record;
begin
  for entry in select function_name, owner from owner_without_execute loop
    execute pg_catalog.format('set local role %I', entry.owner);
    execute pg_catalog.format('grant execute on function %s to %I', entry.function_name, entry.owner);
    reset role;
  end loop;
end
$owner_execute$;

-- Functions re-created with final bodies.

-- Functions owned by vortex_owner
set local role vortex_owner;

create or replace function vortex_access.evaluate_organization_permission_eligibility(
  p_declaration jsonb
)
returns table (
  outcome text,
  operation_key text,
  target_kind text,
  target_application_root_id uuid,
  organization_id uuid,
  organization_account_id uuid,
  access_version bigint,
  checked_at timestamptz,
  valid_until timestamptz,
  correlation_id uuid,
  reason_code text
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  declaration_action jsonb;
  declaration_target jsonb;
  declaration_permission jsonb;
  declaration_authentication jsonb;
  declaration_authority jsonb;
  scope_candidate jsonb;
  permission_candidate jsonb;
  scope_name text;
  operation_value text;
  target_kind_value text;
  target_application_value uuid;
  permission_application_value uuid;
  permission_owner_kind_value text;
  authority_kind_value text;
  context_value jsonb;
  context_organization_value uuid;
  context_account_value uuid;
  context_access_version_value bigint;
  context_application_value uuid;
  context_expires_value timestamptz;
  context_correlation_value uuid;
  authentication_deadline timestamptz;
  authentication_satisfied boolean := true;
  context_current boolean := true;
  target_context_satisfied boolean := true;
  unsupported_context boolean := false;
  decision_checked_at timestamptz;
begin
  if p_declaration is null
    or pg_catalog.jsonb_typeof(p_declaration) <> 'object'
    or not p_declaration ?& array[
      'operationKey', 'action', 'target', 'requiredPermission',
      'recentAuthentication', 'authority'
    ]
    or exists (
      select 1
      from pg_catalog.jsonb_object_keys(p_declaration) as supplied(key)
      where supplied.key <> all (array[
        'operationKey', 'action', 'target', 'requiredPermission',
        'recentAuthentication', 'authority'
      ])
    )
    or pg_catalog.jsonb_typeof(p_declaration -> 'operationKey') <> 'string'
    or pg_catalog.char_length(p_declaration ->> 'operationKey') not between 3 and 120
    or (p_declaration ->> 'operationKey') !~
      '^[a-z][a-z0-9]*(?:_[a-z0-9]+)*(?:\.[a-z][a-z0-9]*(?:_[a-z0-9]+)*)+$'
    or (p_declaration ->> 'operationKey') ~ '(^|\.)[^.]{41,}(\.|$)' then
    raise exception using errcode = '22023',
      message = 'Organization permission declaration is invalid';
  end if;

  declaration_action := p_declaration -> 'action';
  declaration_target := p_declaration -> 'target';
  declaration_permission := p_declaration -> 'requiredPermission';
  declaration_authentication := p_declaration -> 'recentAuthentication';
  declaration_authority := p_declaration -> 'authority';

  if pg_catalog.jsonb_typeof(declaration_action) <> 'object'
    or not declaration_action ? 'actionKind'
    or exists (
      select 1
      from pg_catalog.jsonb_object_keys(declaration_action) as supplied(key)
      where supplied.key <> all (array['actionKind', 'namedAction'])
    )
    or pg_catalog.jsonb_typeof(declaration_action -> 'actionKind') <> 'string'
    or declaration_action ->> 'actionKind' not in (
      'create', 'read', 'update', 'delete', 'restore', 'export', 'share', 'manage', 'named'
    )
    or (
      (declaration_action ->> 'actionKind') = 'named'
      and (
        not declaration_action ? 'namedAction'
        or pg_catalog.jsonb_typeof(declaration_action -> 'namedAction') <> 'string'
        or pg_catalog.char_length(declaration_action ->> 'namedAction') not between 1 and 40
        or (declaration_action ->> 'namedAction') !~
          '^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$'
      )
    )
    or (
      (declaration_action ->> 'actionKind') <> 'named'
      and declaration_action ? 'namedAction'
    ) then
    raise exception using errcode = '22023',
      message = 'Organization permission declaration is invalid';
  end if;

  if pg_catalog.jsonb_typeof(declaration_target) <> 'object'
    or not declaration_target ? 'kind'
    or pg_catalog.jsonb_typeof(declaration_target -> 'kind') <> 'string'
    or declaration_target ->> 'kind' not in ('organization', 'application')
    or (
      declaration_target ->> 'kind' = 'organization'
      and exists (
        select 1
        from pg_catalog.jsonb_object_keys(declaration_target) as supplied(key)
        where supplied.key <> 'kind'
      )
    )
    or (
      declaration_target ->> 'kind' = 'application'
      and (
        not declaration_target ? 'applicationRootId'
        or not vortex_platform.is_non_nil_uuid(
          declaration_target ->> 'applicationRootId'
        )
        or exists (
          select 1
          from pg_catalog.jsonb_object_keys(declaration_target) as supplied(key)
          where supplied.key <> all (array['kind', 'applicationRootId'])
        )
      )
    ) then
    raise exception using errcode = '22023',
      message = 'Organization permission declaration is invalid';
  end if;

  if pg_catalog.jsonb_typeof(declaration_authentication) <> 'object'
    or not declaration_authentication ? 'kind'
    or pg_catalog.jsonb_typeof(declaration_authentication -> 'kind') <> 'string'
    or declaration_authentication ->> 'kind' not in ('none', 'primary', 'multi_factor')
    or (
      declaration_authentication ->> 'kind' = 'none'
      and exists (
        select 1
        from pg_catalog.jsonb_object_keys(declaration_authentication) as supplied(key)
        where supplied.key <> 'kind'
      )
    )
    or (
      declaration_authentication ->> 'kind' in ('primary', 'multi_factor')
      and (
        not declaration_authentication ? 'maximumAgeSeconds'
        or pg_catalog.jsonb_typeof(
          declaration_authentication -> 'maximumAgeSeconds'
        ) <> 'number'
        or exists (
          select 1
          from pg_catalog.jsonb_object_keys(declaration_authentication) as supplied(key)
          where supplied.key <> all (array['kind', 'maximumAgeSeconds'])
        )
      )
    ) then
    raise exception using errcode = '22023',
      message = 'Organization permission declaration is invalid';
  end if;

  if declaration_authentication ->> 'kind' in ('primary', 'multi_factor')
    and (
      (declaration_authentication ->> 'maximumAgeSeconds')::numeric < 1
      or (declaration_authentication ->> 'maximumAgeSeconds')::numeric >
        9007199254740991
      or (declaration_authentication ->> 'maximumAgeSeconds')::numeric <>
        pg_catalog.trunc(
          (declaration_authentication ->> 'maximumAgeSeconds')::numeric
        )
    ) then
    raise exception using errcode = '22023',
      message = 'Organization permission declaration is invalid';
  end if;

  if pg_catalog.jsonb_typeof(declaration_authority) <> 'object'
    or not declaration_authority ? 'kind'
    or pg_catalog.jsonb_typeof(declaration_authority -> 'kind') <> 'string'
    or declaration_authority ->> 'kind' not in ('permission', 'delegated_management')
    or (
      declaration_authority ->> 'kind' = 'permission'
      and exists (
        select 1
        from pg_catalog.jsonb_object_keys(declaration_authority) as supplied(key)
        where supplied.key <> 'kind'
      )
    )
    or (
      declaration_authority ->> 'kind' = 'delegated_management'
      and (
        not declaration_authority ?& array['before', 'after']
        or exists (
          select 1
          from pg_catalog.jsonb_object_keys(declaration_authority) as supplied(key)
          where supplied.key <> all (array['kind', 'before', 'after'])
        )
      )
    ) then
    raise exception using errcode = '22023',
      message = 'Organization permission declaration is invalid';
  end if;

  if declaration_authority ->> 'kind' = 'delegated_management' then
    foreach scope_name in array array['before', 'after'] loop
      scope_candidate := declaration_authority -> scope_name;
      if pg_catalog.jsonb_typeof(scope_candidate) <> 'object'
        or not scope_candidate ? 'kind'
        or pg_catalog.jsonb_typeof(scope_candidate -> 'kind') <> 'string'
        or scope_candidate ->> 'kind' not in (
          'none', 'organization_catalogue', 'bounded'
        )
        or (
          scope_candidate ->> 'kind' in ('none', 'organization_catalogue')
          and exists (
            select 1
            from pg_catalog.jsonb_object_keys(scope_candidate) as supplied(key)
            where supplied.key <> 'kind'
          )
        )
        or (
          scope_candidate ->> 'kind' = 'bounded'
          and (
            not scope_candidate ? 'permissions'
            or pg_catalog.jsonb_typeof(scope_candidate -> 'permissions') <> 'array'
            or pg_catalog.jsonb_array_length(scope_candidate -> 'permissions') = 0
            or exists (
              select 1
              from pg_catalog.jsonb_object_keys(scope_candidate) as supplied(key)
              where supplied.key <> all (array['kind', 'permissions'])
            )
          )
        ) then
        raise exception using errcode = '22023',
          message = 'Organization permission declaration is invalid';
      end if;
    end loop;

    if declaration_authority -> 'before' ->> 'kind' = 'none'
      and declaration_authority -> 'after' ->> 'kind' = 'none' then
      raise exception using errcode = '22023',
        message = 'Organization permission declaration is invalid';
    end if;
  end if;

  for permission_candidate in
    select candidate.value
    from (
      select declaration_permission as value
      union all
      select scoped.value
      from pg_catalog.jsonb_array_elements(
        case
          when declaration_authority ->> 'kind' = 'delegated_management'
            and declaration_authority -> 'before' ->> 'kind' = 'bounded'
          then declaration_authority -> 'before' -> 'permissions'
          else '[]'::jsonb
        end
      ) as scoped(value)
      union all
      select scoped.value
      from pg_catalog.jsonb_array_elements(
        case
          when declaration_authority ->> 'kind' = 'delegated_management'
            and declaration_authority -> 'after' ->> 'kind' = 'bounded'
          then declaration_authority -> 'after' -> 'permissions'
          else '[]'::jsonb
        end
      ) as scoped(value)
    ) as candidate
  loop
    if pg_catalog.jsonb_typeof(permission_candidate) <> 'object'
      or not permission_candidate ?& array['ownerKind', 'ownerId', 'permissionId']
      or pg_catalog.jsonb_typeof(permission_candidate -> 'ownerKind') <> 'string'
      or permission_candidate ->> 'ownerKind' not in ('platform', 'application', 'module')
      or not vortex_platform.is_non_nil_uuid(permission_candidate ->> 'ownerId')
      or not vortex_platform.is_non_nil_uuid(permission_candidate ->> 'permissionId')
      or exists (
        select 1
        from pg_catalog.jsonb_object_keys(permission_candidate) as supplied(key)
        where supplied.key <> all (array[
          'applicationRootId', 'ownerKind', 'ownerId', 'permissionId'
        ])
      )
      or (
        permission_candidate ->> 'ownerKind' = 'platform'
        and permission_candidate ? 'applicationRootId'
      )
      or (
        permission_candidate ->> 'ownerKind' in ('application', 'module')
        and (
          not permission_candidate ? 'applicationRootId'
          or not vortex_platform.is_non_nil_uuid(
            permission_candidate ->> 'applicationRootId'
          )
        )
      )
      or (
        permission_candidate ->> 'ownerKind' = 'application'
        and pg_catalog.lower(permission_candidate ->> 'ownerId') <>
          pg_catalog.lower(permission_candidate ->> 'applicationRootId')
      ) then
      raise exception using errcode = '22023',
        message = 'Organization permission declaration is invalid';
    end if;
  end loop;

  if declaration_authority ->> 'kind' = 'delegated_management' then
    foreach scope_name in array array['before', 'after'] loop
      scope_candidate := declaration_authority -> scope_name;
      if scope_candidate ->> 'kind' = 'bounded'
        and (
          select pg_catalog.count(*)
          from pg_catalog.jsonb_array_elements(scope_candidate -> 'permissions')
        ) <> (
          select pg_catalog.count(distinct pg_catalog.concat_ws(
            ':',
            pg_catalog.lower(permission.value ->> 'applicationRootId'),
            permission.value ->> 'ownerKind',
            pg_catalog.lower(permission.value ->> 'ownerId'),
            pg_catalog.lower(permission.value ->> 'permissionId')
          ))
          from pg_catalog.jsonb_array_elements(
            scope_candidate -> 'permissions'
          ) as permission(value)
        ) then
        raise exception using errcode = '22023',
          message = 'Organization permission declaration is invalid';
      end if;
    end loop;
  end if;

  operation_value := p_declaration ->> 'operationKey';
  target_kind_value := declaration_target ->> 'kind';
  target_application_value := case
    when target_kind_value = 'application'
      then (declaration_target ->> 'applicationRootId')::uuid
    else null
  end;
  permission_application_value := case
    when declaration_permission ? 'applicationRootId'
      then (declaration_permission ->> 'applicationRootId')::uuid
    else null
  end;
  permission_owner_kind_value := declaration_permission ->> 'ownerKind';
  authority_kind_value := declaration_authority ->> 'kind';

  if (target_kind_value = 'organization' and permission_owner_kind_value <> 'platform')
    or (
      target_kind_value = 'application'
      and (
        permission_owner_kind_value = 'platform'
        or permission_application_value is distinct from target_application_value
      )
    ) then
    raise exception using errcode = '22023',
      message = 'Organization permission declaration is invalid';
  end if;

  context_value := vortex_access.validated_human_request_context();
  context_organization_value := (context_value ->> 'organizationId')::uuid;
  context_account_value := (context_value ->> 'organizationAccountId')::uuid;
  context_access_version_value := (context_value ->> 'accessVersion')::bigint;
  context_application_value := case
    when context_value ? 'applicationRootId'
      then (context_value ->> 'applicationRootId')::uuid
    else null
  end;
  context_expires_value := (context_value ->> 'expiresAt')::timestamptz;
  context_correlation_value := (context_value ->> 'correlationId')::uuid;
  decision_checked_at := pg_catalog.clock_timestamp();
  context_current := context_expires_value > decision_checked_at;

  unsupported_context := context_value ? 'delegatedContext'
    or context_value ? 'supportContext';
  target_context_satisfied := target_kind_value = 'organization'
    or coalesce(context_application_value = target_application_value, false);

  authentication_deadline := vortex_access.recent_authentication_deadline_internal(
    context_value, decision_checked_at, declaration_authentication
  );
  authentication_satisfied := authentication_deadline is not null;

  return query
  with permission_eligibility as materialized (
    select evaluated.path_valid_until
    from vortex_access.evaluate_permission_role_path_internal(
      context_value, decision_checked_at, declaration_permission,
      declaration_action, null::uuid
    ) as evaluated
  ), management_scopes as materialized (
    select declaration_authority -> 'before' as scope
    where authority_kind_value = 'delegated_management'
    union all
    select declaration_authority -> 'after'
    where authority_kind_value = 'delegated_management'
  ), delegation_requirements as materialized (
    select 'organization_catalogue'::text as requirement_kind,
      null::uuid as application_root_id, null::text as owner_kind,
      null::uuid as owner_id, null::uuid as permission_id
    where exists (
      select 1 from management_scopes as managed
      where managed.scope ->> 'kind' = 'organization_catalogue'
    )
    union all
    select distinct 'bounded',
      case when permission.value ? 'applicationRootId'
        then (permission.value ->> 'applicationRootId')::uuid
        else null::uuid
      end,
      permission.value ->> 'ownerKind',
      (permission.value ->> 'ownerId')::uuid,
      (permission.value ->> 'permissionId')::uuid
    from management_scopes as managed
    cross join lateral pg_catalog.jsonb_array_elements(
      case when managed.scope ->> 'kind' = 'bounded'
        then managed.scope -> 'permissions'
        else '[]'::jsonb
      end
    ) as permission(value)
  ), current_delegation_paths as materialized (
    select 1 as route_rank, delegation.delegation_authority_id,
      null::uuid as membership_id, delegation.scope_kind,
      delegation.bounded_permissions,
      least(
        context_expires_value,
        coalesce(delegation.expires_at, context_expires_value)
      ) as path_valid_until
    from vortex_access.organization_delegation_authorities as delegation
    where delegation.organization_id = context_organization_value
      and delegation.holder_kind = 'organization_account'
      and delegation.organization_account_id = context_account_value
      and delegation.state = 'live'
      and delegation.starts_at <= decision_checked_at
      and (
        delegation.expires_at is null
        or delegation.expires_at > decision_checked_at
      )

    union all

    select 2, delegation.delegation_authority_id,
      membership.membership_id, delegation.scope_kind,
      delegation.bounded_permissions,
      least(
        context_expires_value,
        coalesce(delegation.expires_at, context_expires_value),
        coalesce(membership.expires_at, context_expires_value)
      )
    from vortex_access.organization_delegation_authorities as delegation
    join vortex_access.organization_groups as organization_group
      on organization_group.organization_id = delegation.organization_id
      and organization_group.group_id = delegation.group_id
      and organization_group.state = 'active'
    join vortex_access.organization_group_memberships as membership
      on membership.organization_id = delegation.organization_id
      and membership.group_id = delegation.group_id
      and membership.organization_account_id = context_account_value
      and membership.state = 'live'
      and membership.starts_at <= decision_checked_at
      and (
        membership.expires_at is null
        or membership.expires_at > decision_checked_at
      )
    where delegation.organization_id = context_organization_value
      and delegation.holder_kind = 'group'
      and delegation.state = 'live'
      and delegation.starts_at <= decision_checked_at
      and (
        delegation.expires_at is null
        or delegation.expires_at > decision_checked_at
      )
  ), current_bounded_path_permissions as materialized (
    select path.delegation_authority_id, path.membership_id,
      case when stored.value ? 'applicationRootId'
        then (stored.value ->> 'applicationRootId')::uuid
        else null::uuid
      end as application_root_id,
      stored.value ->> 'ownerKind' as owner_kind,
      (stored.value ->> 'ownerId')::uuid as owner_id,
      (stored.value ->> 'permissionId')::uuid as permission_id
    from current_delegation_paths as path
    cross join lateral pg_catalog.jsonb_array_elements(
      path.bounded_permissions
    ) as stored(value)
    join vortex_access.permission_registrations as registration
      on registration.organization_id = context_organization_value
      and registration.state = 'active'
    join vortex_access.permission_catalogue_entries as catalogue
      on catalogue.organization_id = registration.organization_id
      and catalogue.registration_kind = registration.registration_kind
      and catalogue.registration_owner_id is not distinct from
        registration.registration_owner_id
      and catalogue.registration_revision = registration.revision
      and catalogue.application_root_id is not distinct from case
        when stored.value ? 'applicationRootId'
          then (stored.value ->> 'applicationRootId')::uuid
        else null::uuid
      end
      and catalogue.owner_kind = stored.value ->> 'ownerKind'
      and catalogue.owner_id = (stored.value ->> 'ownerId')::uuid
      and catalogue.permission_id = (stored.value ->> 'permissionId')::uuid
      and catalogue.meaning_fingerprint =
        stored.value ->> 'meaningFingerprint'
    join vortex_access.permission_continuities as continuity
      on continuity.organization_id = catalogue.organization_id
      and continuity.application_root_id is not distinct from
        catalogue.application_root_id
      and continuity.owner_kind = catalogue.owner_kind
      and continuity.owner_id = catalogue.owner_id
      and continuity.permission_id = catalogue.permission_id
      and continuity.registration_kind = catalogue.registration_kind
      and continuity.registration_owner_id is not distinct from
        catalogue.registration_owner_id
      and continuity.last_processed_registration_revision = registration.revision
      and continuity.state = 'available'
      and continuity.continuity_revision =
        (stored.value ->> 'continuityRevision')::numeric::bigint
      and continuity.meaning_fingerprint =
        stored.value ->> 'meaningFingerprint'
    where path.scope_kind = 'bounded'
  ), delegation_path_candidates as (
    select requirement.requirement_kind, requirement.application_root_id,
      requirement.owner_kind, requirement.owner_id,
      requirement.permission_id, path.route_rank,
      path.delegation_authority_id, path.membership_id,
      path.path_valid_until,
      pg_catalog.row_number() over (
        partition by requirement.requirement_kind,
          requirement.application_root_id, requirement.owner_kind,
          requirement.owner_id, requirement.permission_id
        order by path.route_rank, path.delegation_authority_id,
          path.membership_id nulls first
      ) as path_ordinal
    from delegation_requirements as requirement
    join current_delegation_paths as path
      on path.scope_kind = 'organization_catalogue'
      or (
        requirement.requirement_kind = 'bounded'
        and exists (
          select 1
          from current_bounded_path_permissions as covered
          where covered.delegation_authority_id =
              path.delegation_authority_id
            and covered.membership_id is not distinct from path.membership_id
            and covered.application_root_id is not distinct from
              requirement.application_root_id
            and covered.owner_kind = requirement.owner_kind
            and covered.owner_id = requirement.owner_id
            and covered.permission_id = requirement.permission_id
        )
      )
    where requirement.requirement_kind <> 'organization_catalogue'
      or path.scope_kind = 'organization_catalogue'
  ), selected_delegation_paths as materialized (
    select candidate.requirement_kind, candidate.application_root_id,
      candidate.owner_kind, candidate.owner_id, candidate.permission_id,
      candidate.path_valid_until
    from delegation_path_candidates as candidate
    where candidate.path_ordinal = 1
  ), delegation_summary as (
    select pg_catalog.count(*) as requirement_count,
      pg_catalog.count(selected.requirement_kind) as selected_count,
      pg_catalog.min(selected.path_valid_until) as path_valid_until
    from delegation_requirements as requirement
    left join selected_delegation_paths as selected
      on selected.requirement_kind = requirement.requirement_kind
      and selected.application_root_id is not distinct from
        requirement.application_root_id
      and selected.owner_kind is not distinct from requirement.owner_kind
      and selected.owner_id is not distinct from requirement.owner_id
      and selected.permission_id is not distinct from requirement.permission_id
  ), decision as (
    select exists(select 1 from permission_eligibility) as permission_available,
      (
        select pg_catalog.min(selected.path_valid_until)
        from permission_eligibility as selected
      ) as path_valid_until,
      authority_kind_value = 'permission'
        or (
          delegation.requirement_count > 0
          and delegation.requirement_count = delegation.selected_count
        ) as delegation_satisfied,
      delegation.path_valid_until as delegation_valid_until
    from (select 1) as singleton
    cross join delegation_summary as delegation
  )
  select
    case
      when not context_current
        or unsupported_context or not target_context_satisfied then 'refused'
      when not decision.permission_available then 'refused'
      when decision.path_valid_until is null then 'refused'
      when not authentication_satisfied then 'refused'
      when not decision.delegation_satisfied then 'refused'
      else 'eligible'
    end,
    operation_value,
    target_kind_value,
    target_application_value,
    context_organization_value,
    context_account_value,
    context_access_version_value,
    decision_checked_at,
    case
      when context_current
        and not unsupported_context
        and target_context_satisfied
        and decision.permission_available
        and decision.path_valid_until is not null
        and authentication_satisfied
        and decision.delegation_satisfied
      then least(
        decision.path_valid_until,
        authentication_deadline,
        coalesce(decision.delegation_valid_until, context_expires_value)
      )
      else null
    end,
    context_correlation_value,
    case
      when not context_current
        or unsupported_context or not target_context_satisfied
        then 'target_policy_unavailable'
      when not decision.permission_available then 'permission_unavailable'
      when decision.path_valid_until is null then 'permission_not_effective'
      when not authentication_satisfied then 'authentication_unsatisfied'
      when not decision.delegation_satisfied then 'delegation_insufficient'
      else null
    end
  from decision;
end
$function$;

comment on function vortex_access.evaluate_organization_permission_eligibility(jsonb) is
  'Returns transaction-bound permission and current delegation eligibility from one trusted operation declaration; it is not a final protected-operation decision.';
alter function vortex_access.evaluate_organization_permission_eligibility(jsonb)
  owner to vortex_owner;

create or replace function vortex_definition.abandon_private_form_draft(
  p_draft_id uuid,
  p_expected_revision bigint
)
returns table (outcome text, result jsonb)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  scope record;
  stored vortex_definition.form_drafts%rowtype;
begin
  if p_draft_id is null or not vortex_platform.is_non_nil_uuid(p_draft_id::text)
    or p_expected_revision is null
    or p_expected_revision not between 1 and 9007199254740991 then
    raise exception using errcode = '22023',
      message = 'Private form draft abandon command is invalid';
  end if;

  select context.* into strict scope
  from vortex_definition.private_form_draft_context_internal() as context;

  select draft.* into stored
  from vortex_definition.form_drafts as draft
  where draft.draft_id = p_draft_id
    and draft.organization_id = scope.organization_id
    and draft.organization_account_id = scope.organization_account_id
    and draft.identity_id = scope.identity_id
    and draft.application_root_id = scope.application_root_id
  for update;
  if not found or stored.expires_at <= pg_catalog.clock_timestamp() then
    return query select 'unavailable'::text, null::jsonb;
    return;
  end if;

  if stored.revision <> p_expected_revision then
    return query select 'stale_revision'::text, null::jsonb;
    return;
  end if;

  delete from vortex_definition.form_drafts as draft
  where draft.draft_id = p_draft_id;

  stored.revision := stored.revision + 1;
  stored.updated_at := pg_catalog.clock_timestamp();
  stored.field_values := '{}'::jsonb;
  stored.validation_state := '{}'::jsonb;

  return query select 'abandoned'::text,
    vortex_definition.private_form_draft_to_json_internal(stored, 'abandoned');
end
$function$;

comment on function vortex_definition.abandon_private_form_draft(uuid, bigint) is
  'Abandons and deletes one exact owned live private form draft at its expected revision.';

alter function vortex_definition.abandon_private_form_draft(uuid, bigint)
  owner to vortex_owner;

create or replace function vortex_definition.activate_application_installation(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_expected_module_bindings jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  initial_authority record;
  current_authority record;
  application_release vortex_definition.releases%rowtype;
  permission_snapshot record;
  pin record;
  locked_binding vortex_definition.installation_bindings%rowtype;
  storage_provision record;
  expected_count integer;
  pin_count integer;
  all_provisioned boolean;
  all_active boolean;
  changed_value boolean;
  binding_evidence jsonb;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision not between 1 and 9007199254740991
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_expected_module_bindings) = 0
    or exists (
      select 1 from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      where pg_catalog.jsonb_typeof(item.value) <> 'object'
        or not item.value ?& array['moduleRootId', 'bindingRevision']
        or item.value - array['moduleRootId', 'bindingRevision'] <> '{}'::jsonb
        or (item.value ->> 'moduleRootId')::uuid =
          '00000000-0000-0000-0000-000000000000'::uuid
        or (item.value ->> 'bindingRevision')::bigint not between 1 and 9007199254740991
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      group by (item.value ->> 'moduleRootId')::uuid
      having pg_catalog.count(*) <> 1
    )
    or p_expected_module_bindings is distinct from (
      select pg_catalog.jsonb_agg(item.value order by (item.value ->> 'moduleRootId')::uuid)
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
    ) then
    raise exception using errcode = '22023',
      message = 'Application installation activation command is invalid';
  end if;

  select locked.* into strict initial_authority
  from vortex_access.lock_application_installation_authority() as locked;

  select release.* into strict application_release
  from vortex_definition.releases as release
  join vortex_definition.roots as root on root.root_id = release.root_id
  where root.root_id = p_application_root_id
    and root.organization_id = initial_authority.organization_id
    and root.kind = 'application'
    and release.release_revision = p_application_release_revision
    and release.validation_contract_version = any (vortex_definition.accepted_contract_version('application'))
    and release.compilation_output #>> '{kind}' = 'application'
    and release.compilation_output #>> '{canonical,envelope,rootId}' = p_application_root_id::text
    and release.compilation_output #>> '{validationContractVersion}' = any (vortex_definition.accepted_contract_version('application'));

  select pg_catalog.count(*)::integer into pin_count
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  );
  expected_count := pg_catalog.jsonb_array_length(p_expected_module_bindings);
  if pin_count = 0 or expected_count <> pin_count
    or exists (
      select 1
      from vortex_definition.reachable_module_dependency_edges(
        p_application_root_id, p_application_release_revision
      ) as required
      where not exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
        where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
      )
    ) then
    raise exception using errcode = '23514',
      message = 'Application installation binding set is incomplete';
  end if;

  for pin in
    select required.*
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    order by required.target_root_id
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'vortex_definition.binding:' || initial_authority.organization_id::text || ':' ||
          p_application_root_id::text || ':' || pin.target_root_id::text,
        0
      )
    );
    perform 1
    from vortex_definition.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = pin.target_root_id
    for update;
  end loop;

  select locked.* into strict current_authority
  from vortex_access.lock_application_installation_authority() as locked;
  if current_authority.organization_id <> initial_authority.organization_id
    or current_authority.organization_account_id <> initial_authority.organization_account_id
    or current_authority.access_version <> initial_authority.access_version
    or current_authority.correlation_id <> initial_authority.correlation_id then
    raise exception using errcode = '40001',
      message = 'Application installation authority changed';
  end if;

  select pg_catalog.bool_and(coalesce(
      binding.state = 'provisioned'
      and binding.binding_revision = expected.binding_revision
      and binding.application_release_revision = p_application_release_revision
      and binding.module_release_revision = required.target_release_revision, false
    )),
    pg_catalog.bool_and(coalesce(
      binding.state = 'active'
      and binding.binding_revision = expected.binding_revision
      and binding.application_release_revision = p_application_release_revision
      and binding.module_release_revision = required.target_release_revision, false
    ))
  into all_provisioned, all_active
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  ) as required
  left join vortex_definition.installation_bindings as binding
    on binding.organization_id = initial_authority.organization_id
    and binding.application_root_id = p_application_root_id
    and binding.module_root_id = required.target_root_id
  left join lateral (
    select (expected.value ->> 'bindingRevision')::bigint as binding_revision
    from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
    where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
  ) as expected on true
  ;
  if all_provisioned is null or (not all_provisioned and not all_active)
    or exists (
      select 1 from vortex_definition.installation_bindings as binding
      where binding.organization_id = initial_authority.organization_id
        and binding.application_root_id = p_application_root_id
        and binding.state <> 'detached'
        and not exists (
          select 1 from vortex_definition.reachable_module_dependency_edges(
            p_application_root_id, p_application_release_revision
          ) as required
          where required.target_root_id = binding.module_root_id
        )
    ) then
    raise exception using errcode = '40001',
      message = 'Application installation bindings changed or are incomplete';
  end if;

  for pin in
    select required.*
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    order by required.target_root_id
  loop
    select binding.* into strict locked_binding
    from vortex_definition.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = pin.target_root_id;

    select provision.* into strict storage_provision
    from vortex_record.read_exact_module_storage_provision(
      pin.target_root_id, pin.target_release_revision
    ) as provision;

    if locked_binding.storage_contract_ids <> storage_provision.storage_contract_ids then
      raise exception using errcode = '40001',
        message = 'Application installation storage evidence changed or is incomplete';
    end if;
  end loop;

  select snapshot.* into permission_snapshot
  from vortex_access.read_application_permission_snapshot(
    initial_authority.organization_id, p_application_root_id
  ) as snapshot;
  if not found
    or permission_snapshot.release_revision <> p_application_release_revision
    or permission_snapshot.definition_key <> (
      select root.key from vortex_definition.roots as root
      where root.root_id = p_application_root_id
    )
    or permission_snapshot.release_version <> application_release.release_version
    or permission_snapshot.validation_contract_version <> application_release.validation_contract_version
    or permission_snapshot.content_fingerprint <> application_release.content_fingerprint
    or permission_snapshot.resolution_fingerprint <> application_release.resolution_fingerprint then
    raise exception using errcode = '40001',
      message = 'Application permission registration is stale or unavailable';
  end if;

  changed_value := all_provisioned;
  if changed_value then
    if exists (
      select 1 from vortex_definition.reachable_module_dependency_edges(
        p_application_root_id, p_application_release_revision
      ) as required
      join vortex_definition.installation_bindings as binding
        on binding.organization_id = initial_authority.organization_id
        and binding.application_root_id = p_application_root_id
        and binding.module_root_id = required.target_root_id
      where binding.binding_revision = 9007199254740991
    ) then
      raise exception using errcode = '22003',
        message = 'Application installation binding revision is exhausted';
    end if;
    update vortex_definition.installation_bindings as binding
    set state = 'active', binding_revision = binding.binding_revision + 1,
      changed_at = pg_catalog.statement_timestamp()
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = required.target_root_id
      and binding.state = 'provisioned';
    if not found then
      raise exception using errcode = '40001',
        message = 'Application installation bindings changed';
    end if;
  end if;

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'organizationId', binding.organization_id,
    'applicationRootId', binding.application_root_id,
    'moduleRootId', binding.module_root_id,
    'bindingRevision', binding.binding_revision,
    'applicationReleaseRevision', binding.application_release_revision,
    'moduleReleaseRevision', binding.module_release_revision,
    'state', binding.state
  ) order by binding.module_root_id) into binding_evidence
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  ) as required
  join vortex_definition.installation_bindings as binding
    on binding.organization_id = initial_authority.organization_id
    and binding.application_root_id = p_application_root_id
    and binding.module_root_id = required.target_root_id;

  return pg_catalog.jsonb_build_object(
    'organizationId', initial_authority.organization_id,
    'applicationRootId', p_application_root_id,
    'applicationReleaseRevision', p_application_release_revision,
    'state', 'active', 'changed', changed_value,
    'moduleBindings', binding_evidence
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Application installation evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Application installation evidence is ambiguous';
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '22023',
      message = 'Application installation activation command is invalid';
end
$function$;

comment on function vortex_definition.activate_application_installation(uuid, bigint, jsonb) is
  'Revision-checked atomic activation of the complete exact Module pin set for one Application release.';

create or replace function vortex_definition.assert_prepared_installation_runtime_bundle(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_expected_module_bindings jsonb,
  p_pin_fingerprint text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  expected_sections constant text[] := array[
    'pages', 'navigation', 'flows', 'trigger_index', 'theme', 'component_registry',
    'access_plan', 'tool_bundle'
  ];
  checked_context jsonb;
  selected_organization_id uuid;
  prepared_source jsonb;
  source_manifest jsonb;
  application_content jsonb;
  expected_access_plan jsonb;
  access_plan_text text;
  access_plan_value jsonb;
  stored_bundle vortex_definition.installation_runtime_bundles%rowtype;
  part_item record;
  metadata_item jsonb;
  metadata_count integer;
  stored_part_count integer;
  section_value text;
  ordinal_value bigint;
  byte_size_value bigint;
  total_size_value bigint := 0;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991
    or p_pin_fingerprint is null
    or p_pin_fingerprint !~ '^sha256:[a-f0-9]{64}$'
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_expected_module_bindings) < 1 then
    raise exception using errcode = '22023',
      message = 'Prepared runtime bundle assertion is invalid';
  end if;
  checked_context := vortex_access.validated_human_request_context();
  selected_organization_id := (checked_context ->> 'organizationId')::uuid;
  if selected_organization_id is null then
    raise exception using errcode = '42501',
      message = 'Prepared runtime bundle authority is unavailable';
  end if;
  prepared_source := vortex_definition.read_prepared_installation_runtime_source(
    p_application_root_id,
    p_application_release_revision,
    p_expected_module_bindings
  );
  if prepared_source is null
    or (prepared_source ->> 'organizationId')::uuid is distinct from selected_organization_id
    or prepared_source ->> 'pinFingerprint' is distinct from p_pin_fingerprint then
    raise exception using errcode = '40001',
      message = 'Prepared runtime bundle source changed';
  end if;
  source_manifest := pg_catalog.jsonb_build_object(
    'bundleFormatVersion', 2,
    'application', pg_catalog.jsonb_build_object(
      'rootId', prepared_source #> '{application,rootId}',
      'definitionKey', prepared_source #> '{application,key}',
      'releaseRevision', prepared_source #> '{application,releaseRevision}',
      'releaseVersion', prepared_source #> '{application,releaseVersion}',
      'validationContractVersion', prepared_source #> '{application,validationContractVersion}',
      'contentFingerprint', prepared_source #> '{application,contentFingerprint}',
      'resolutionFingerprint', prepared_source #> '{application,resolutionFingerprint}'
    ),
    'modules', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'rootId', module.value -> 'rootId',
          'definitionKey', module.value -> 'key',
          'releaseRevision', module.value -> 'releaseRevision',
          'releaseVersion', module.value -> 'releaseVersion',
          'validationContractVersion', module.value -> 'validationContractVersion',
          'contentFingerprint', module.value -> 'contentFingerprint',
          'resolutionFingerprint', module.value -> 'resolutionFingerprint'
        ) order by (module.value ->> 'rootId') collate "C")
      from pg_catalog.jsonb_array_elements(prepared_source -> 'modules') as module(value)
    ), '[]'::jsonb),
    'pinFingerprint', prepared_source -> 'pinFingerprint',
    'preparedRecordAccessPlan', pg_catalog.jsonb_build_object(
      'planKey', prepared_source #> '{preparedRecordAccessPlan,planKey}',
      'mappingFingerprint', prepared_source #> '{preparedRecordAccessPlan,mappingFingerprint}'
    )
  );
  select stored.* into strict stored_bundle
  from vortex_definition.installation_runtime_bundles as stored
  where stored.organization_id = selected_organization_id
    and stored.application_root_id = p_application_root_id
    and stored.application_release_revision = p_application_release_revision
    and stored.bundle_format_version = 2;
  if stored_bundle.pin_fingerprint is distinct from p_pin_fingerprint
    or stored_bundle.source_manifest is distinct from source_manifest then
    raise exception using errcode = '23505',
      message = 'Prepared runtime bundle identity differs';
  end if;

  if pg_catalog.jsonb_typeof(stored_bundle.parts) is distinct from 'array'
    or pg_catalog.jsonb_array_length(stored_bundle.parts) < pg_catalog.cardinality(expected_sections)
    or exists (
      select 1
      from pg_catalog.unnest(expected_sections) as required(section)
      where not exists (
        select 1 from pg_catalog.jsonb_array_elements(stored_bundle.parts) as item(value)
        where item.value ->> 'section' = required.section
      )
    ) then
    raise exception using errcode = '55000',
      message = 'Prepared runtime bundle parts are incomplete';
  end if;
  select pg_catalog.count(*)::integer into metadata_count
  from pg_catalog.jsonb_array_elements(stored_bundle.parts) as item(value);
  select pg_catalog.count(*)::integer into stored_part_count
  from vortex_definition.installation_runtime_bundle_parts as part
  where part.organization_id = selected_organization_id
    and part.application_root_id = p_application_root_id
    and part.application_release_revision = p_application_release_revision
    and part.bundle_format_version = 2;
  if metadata_count is distinct from stored_part_count then
    raise exception using errcode = '55000',
      message = 'Prepared runtime bundle part count differs';
  end if;
  for metadata_item in
    select item.value from pg_catalog.jsonb_array_elements(stored_bundle.parts) as item(value)
  loop
    if pg_catalog.jsonb_typeof(metadata_item) is distinct from 'object'
      or not metadata_item ?& array['section','ordinal','byteSize','sha256']
      or metadata_item - array['section','ordinal','byteSize','sha256'] <> '{}'::jsonb
      or pg_catalog.jsonb_typeof(metadata_item -> 'section') is distinct from 'string'
      or pg_catalog.jsonb_typeof(metadata_item -> 'ordinal') is distinct from 'number'
      or pg_catalog.jsonb_typeof(metadata_item -> 'byteSize') is distinct from 'number'
      or pg_catalog.jsonb_typeof(metadata_item -> 'sha256') is distinct from 'string'
      or not (metadata_item ->> 'section' = any (expected_sections))
      or (metadata_item ->> 'ordinal') !~ '^(0|[1-9][0-9]*)$'
      or pg_catalog.length(metadata_item ->> 'ordinal') > 10
      or (metadata_item ->> 'byteSize') !~ '^[1-9][0-9]*$'
      or pg_catalog.length(metadata_item ->> 'byteSize') > 7
      or (metadata_item ->> 'sha256') !~ '^sha256:[a-f0-9]{64}$' then
      raise exception using errcode = '55000',
        message = 'Prepared runtime bundle part metadata is invalid';
    end if;
    section_value := metadata_item ->> 'section';
    ordinal_value := (metadata_item ->> 'ordinal')::bigint;
    byte_size_value := (metadata_item ->> 'byteSize')::bigint;
    if ordinal_value > 2147483647 or byte_size_value > 1048575 then
      raise exception using errcode = '55000',
        message = 'Prepared runtime bundle part metadata exceeds its limit';
    end if;
    total_size_value := total_size_value + byte_size_value;
    if total_size_value > 9007199254740991 then
      raise exception using errcode = '55000',
        message = 'Prepared runtime bundle total size exceeds its limit';
    end if;
    select part.* into strict part_item
    from vortex_definition.installation_runtime_bundle_parts as part
    where part.organization_id = selected_organization_id
      and part.application_root_id = p_application_root_id
      and part.application_release_revision = p_application_release_revision
      and part.bundle_format_version = 2
      and part.section = section_value
      and part.ordinal = ordinal_value::integer;
    if pg_catalog.octet_length(part_item.content_bytes) is distinct from byte_size_value
      or ('sha256:' || pg_catalog.encode(
        extensions.digest(part_item.content_bytes, 'sha256'), 'hex'
      )) is distinct from metadata_item ->> 'sha256' then
      raise exception using errcode = '55000',
        message = 'Prepared runtime bundle bytes do not match their manifest';
    end if;
  end loop;
  if total_size_value is distinct from stored_bundle.total_size_bytes
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(stored_bundle.parts) as item(value)
      group by item.value ->> 'section', (item.value ->> 'ordinal')::integer
      having pg_catalog.count(*) > 1
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(stored_bundle.parts) as item(value)
      group by item.value ->> 'section'
      having pg_catalog.min((item.value ->> 'ordinal')::integer) <> 0
        or pg_catalog.max((item.value ->> 'ordinal')::integer) <>
          pg_catalog.count(*) - 1
    )
    or exists (
      select 1
      from pg_catalog.unnest(expected_sections) as required(section)
      where not exists (
        select 1
        from pg_catalog.jsonb_array_elements(stored_bundle.parts) as item(value)
        where item.value ->> 'section' = required.section
      )
    ) then
    raise exception using errcode = '55000',
      message = 'Prepared runtime bundle metadata is incomplete';
  end if;

  application_content := prepared_source #> '{application,compilationOutput,canonical,content}';
  select pg_catalog.jsonb_build_object(
    'preparedRecordAccessPlan', prepared_source -> 'preparedRecordAccessPlan',
    'declaredPermissions', pg_catalog.jsonb_build_object(
      'application', application_content -> 'permissions',
      'modules', coalesce((
        select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'rootId', module.value -> 'rootId',
            'permissions', module.value #> '{compilationOutput,canonical,content,permissions}'
          ) order by (module.value ->> 'rootId') collate "C")
        from pg_catalog.jsonb_array_elements(prepared_source -> 'modules') as module(value)
      ), '[]'::jsonb)
    )
  ) into expected_access_plan;
  select pg_catalog.string_agg(pg_catalog.convert_from(part.content_bytes, 'UTF8'), ''
    order by part.ordinal)
  into access_plan_text
  from vortex_definition.installation_runtime_bundle_parts as part
  where part.organization_id = selected_organization_id
    and part.application_root_id = p_application_root_id
    and part.application_release_revision = p_application_release_revision
    and part.bundle_format_version = 2
    and part.section = 'access_plan';
  begin
    access_plan_value := access_plan_text::jsonb;
  exception when others then
    raise exception using errcode = '55000',
      message = 'Prepared runtime bundle access plan is invalid';
  end;
  if access_plan_value is distinct from expected_access_plan then
    raise exception using errcode = '23505',
      message = 'Prepared runtime bundle Record plan differs from current source';
  end if;
  return pg_catalog.jsonb_build_object(
    'outcome', 'verified',
    'organizationId', selected_organization_id,
    'applicationRootId', p_application_root_id,
    'applicationReleaseRevision', p_application_release_revision,
    'bundleFormatVersion', 2,
    'pinFingerprint', stored_bundle.pin_fingerprint,
    'sourceManifest', stored_bundle.source_manifest
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Prepared runtime bundle is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Prepared runtime bundle evidence is ambiguous';
end
$function$;

comment on function vortex_definition.assert_prepared_installation_runtime_bundle(uuid,bigint,jsonb,text) is
  'Re-derives first-install source and plan identity, then verifies the complete immutable format-2 bundle and its stored bytes before activation.';

create or replace function vortex_definition.assert_preview_installation_authority_internal()
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  permission_decision record;
  checked_context jsonb;
begin
  select evaluated.* into strict permission_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.definition_drafts.manage',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '0548c061-b1a9-48e5-a04a-eb1d0dae0644'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  ) as evaluated;
  checked_context := vortex_access.validated_human_request_context();
  if permission_decision.outcome is distinct from 'eligible'
    or checked_context is null
    or (checked_context ->> 'organizationId')::uuid
      is distinct from permission_decision.organization_id
    or (checked_context ->> 'organizationAccountId')::uuid
      is distinct from permission_decision.organization_account_id
    or (checked_context ->> 'accessVersion')::bigint
      is distinct from permission_decision.access_version
    or (checked_context ->> 'correlationId')::uuid
      is distinct from permission_decision.correlation_id then
    raise exception using errcode = '42501', message = 'Preview installation authority is unavailable';
  end if;
  return checked_context;
end
$function$;

comment on function vortex_definition.assert_preview_installation_authority_internal() is
  'Validates the current human request context and definition-draft management permission for private preview installation operations.';

CREATE OR REPLACE FUNCTION vortex_definition.count_storage_adoption_dependents_internal(p_module_root_id uuid, p_storage_contract_id uuid, p_dependent_release_revisions bigint[]) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  dependent_count bigint;
begin
  if p_module_root_id is null
    or p_module_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_dependent_release_revisions is null
    or pg_catalog.array_position(p_dependent_release_revisions, null) is not null then
    raise exception using errcode = '22023',
      message = 'Storage adoption dependent count command is invalid';
  end if;

  -- Every organisation's binding counts: the mappings are shared by every
  -- installation of the Module. A provisioned binding is counted with an active
  -- one because activation does not recheck storage, so it could otherwise
  -- activate over a retired field; only a detached binding stops depending on
  -- the source field. The caller holds the storage-lineage lock, which every
  -- provision of these releases takes before it writes a binding, so no new
  -- dependent can appear unseen.
  select pg_catalog.count(*) into dependent_count
  from vortex_definition.installation_bindings as binding
  where binding.module_root_id = p_module_root_id
    and binding.state in ('provisioned', 'active')
    and p_storage_contract_id = any (binding.storage_contract_ids)
    and binding.module_release_revision = any (p_dependent_release_revisions);
  return dependent_count;
end
$$;

COMMENT ON FUNCTION vortex_definition.count_storage_adoption_dependents_internal(p_module_root_id uuid, p_storage_contract_id uuid, p_dependent_release_revisions bigint[]) IS 'Private storage adoption fact: counts every organisation''s provisioned and active bindings of the Module that install one of the named releases needing the source storage.';

REVOKE ALL ON FUNCTION vortex_definition.count_storage_adoption_dependents_internal(p_module_root_id uuid, p_storage_contract_id uuid, p_dependent_release_revisions bigint[]) FROM PUBLIC;
GRANT ALL ON FUNCTION vortex_definition.count_storage_adoption_dependents_internal(p_module_root_id uuid, p_storage_contract_id uuid, p_dependent_release_revisions bigint[]) TO vortex_owner;

create or replace function vortex_definition.create_preview_installation(
  p_application_root_id uuid,
  p_expected_draft_revision bigint,
  p_candidate jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  preview_lifetime constant interval := interval '24 hours';
  checked_context jsonb;
  organization_id_value uuid;
  organization_account_id_value uuid;
  identity_id_value uuid;
  preview_installation_id_value uuid;
  draft_revision_value bigint;
  created_at_value timestamptz;
  expires_at_value timestamptz;
  compilation_value jsonb;
  module_dependency jsonb;
  module_release_revision bigint;
  module_root_id_value uuid;
  module_closure jsonb := '[]'::jsonb;
  resolved_modules_value jsonb := '[]'::jsonb;
  storage_identities_value jsonb := '[]'::jsonb;
  binding_count bigint;
  resolution_count bigint;
begin
  if not vortex_platform.is_non_nil_uuid(p_application_root_id::text)
    or p_expected_draft_revision is null
    or p_expected_draft_revision not between 1 and 9007199254740991
    or p_candidate is null
    or pg_catalog.jsonb_typeof(p_candidate) <> 'object'
    or pg_catalog.jsonb_typeof(p_candidate -> 'compilation') is distinct from 'object'
    or not (p_candidate ? 'currentReleaseRevision')
    or pg_catalog.jsonb_typeof(p_candidate -> 'currentReleaseRevision')
      not in ('number', 'null') then
    raise exception using errcode = '22023', message = 'Preview installation command is invalid';
  end if;
  checked_context := vortex_definition.assert_preview_installation_authority_internal();
  organization_id_value := (checked_context ->> 'organizationId')::uuid;
  organization_account_id_value := (checked_context ->> 'organizationAccountId')::uuid;
  identity_id_value := (checked_context ->> 'identityId')::uuid;
  if checked_context ->> 'applicationRootId' is distinct from p_application_root_id::text then
    raise exception using errcode = '42501', message = 'Preview installation context is unavailable';
  end if;

  compilation_value := p_candidate -> 'compilation';
  if compilation_value ->> 'kind' is distinct from 'application'
    or compilation_value #>> '{canonical,envelope,rootId}'
      is distinct from p_application_root_id::text then
    raise exception using errcode = '23514', message = 'Compiled Application candidate identity is invalid';
  end if;
  if pg_catalog.jsonb_typeof(
      compilation_value #> '{canonical,envelope,draftRevision}'
    ) is distinct from 'number' then
    raise exception using errcode = '23514', message = 'Compiled Application candidate revision is invalid';
  end if;
  begin
    draft_revision_value := (compilation_value #>> '{canonical,envelope,draftRevision}')::bigint;
  exception when invalid_text_representation then
    raise exception using errcode = '23514', message = 'Compiled Application candidate revision is invalid';
  end;
  if draft_revision_value <> p_expected_draft_revision
    or draft_revision_value not between 1 and 9007199254740991
    or pg_catalog.jsonb_typeof(compilation_value #> '{resolvedDependencies}') <> 'array'
    or pg_catalog.jsonb_typeof(compilation_value #> '{canonical,content,moduleBindings}') <> 'array' then
    raise exception using errcode = '23514', message = 'Compiled Application candidate does not match its request';
  end if;

  select draft.draft_revision into draft_revision_value
  from vortex_definition.roots as root
  join vortex_definition.drafts as draft on draft.root_id = root.root_id
  where root.root_id = p_application_root_id
    and root.organization_id = organization_id_value
    and root.kind = 'application'
  for share of draft;
  if not found or draft_revision_value <> p_expected_draft_revision then
    raise exception using errcode = '40001', message = 'Application draft revision changed';
  end if;

  select pg_catalog.count(*) into binding_count
  from pg_catalog.jsonb_array_elements(
    compilation_value #> '{canonical,content,moduleBindings}'
  ) as item(value);
  select pg_catalog.count(*) into resolution_count
  from pg_catalog.jsonb_array_elements(compilation_value -> 'resolvedDependencies') as item(value)
  where item.value ->> 'kind' = 'module';
  if binding_count <> resolution_count or exists (
    select 1
    from pg_catalog.jsonb_array_elements(
      compilation_value #> '{canonical,content,moduleBindings}'
    ) as binding(value)
    where not exists (
      select 1
      from pg_catalog.jsonb_array_elements(compilation_value -> 'resolvedDependencies') as resolved(value)
      where resolved.value ->> 'kind' = 'module'
        and resolved.value ->> 'rootId' = binding.value ->> 'moduleRootId'
        and resolved.value ->> 'exactVersion' = binding.value ->> 'resolvedVersion'
    )
  ) or (
    select pg_catalog.count(*) <> pg_catalog.count(distinct item.value ->> 'moduleRootId')
    from pg_catalog.jsonb_array_elements(
      compilation_value #> '{canonical,content,moduleBindings}'
    ) as item(value)
  ) or (
    select pg_catalog.count(*) <> pg_catalog.count(distinct item.value ->> 'rootId')
    from pg_catalog.jsonb_array_elements(compilation_value -> 'resolvedDependencies') as item(value)
    where item.value ->> 'kind' = 'module'
  ) then
    raise exception using errcode = '23514', message = 'Compiled Application Module evidence is inconsistent';
  end if;

  perform vortex_definition.expire_preview_installations(100);
  preview_installation_id_value := pg_catalog.gen_random_uuid();
  created_at_value := pg_catalog.statement_timestamp();
  expires_at_value := created_at_value + preview_lifetime;
  insert into vortex_definition.preview_installations (
    preview_installation_id, organization_id, application_root_id,
    draft_revision, previewer_identity_id, previewer_organization_account_id, candidate,
    resolved_modules, storage_identities, created_at, expires_at
  ) values (
    preview_installation_id_value, organization_id_value, p_application_root_id,
    p_expected_draft_revision, identity_id_value, organization_account_id_value, p_candidate,
    '[]'::jsonb, '[]'::jsonb, created_at_value, expires_at_value
  );

  with recursive module_closure(module_root_id, release_version) as (
    select (binding.value ->> 'moduleRootId')::uuid, binding.value ->> 'resolvedVersion'
    from pg_catalog.jsonb_array_elements(
      compilation_value #> '{canonical,content,moduleBindings}'
    ) as binding(value)
    union
    select (dependency.value ->> 'moduleRootId')::uuid,
      dependency.value ->> 'resolvedVersion'
    from module_closure as parent
    join vortex_definition.releases as release
      on release.root_id = parent.module_root_id
      and release.release_version = parent.release_version
    cross join lateral pg_catalog.jsonb_array_elements(
      release.compilation_output #> '{canonical,content,dependencies}'
    ) as dependency(value)
  )
  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'moduleRootId', closure.module_root_id,
        'releaseVersion', closure.release_version
      ) order by closure.module_root_id, closure.release_version
    ),
    '[]'::jsonb
  ) into module_closure
  from module_closure as closure;

  for module_dependency in
    select item.value
    from pg_catalog.jsonb_array_elements(module_closure) as item(value)
    order by item.value ->> 'moduleRootId', item.value ->> 'releaseVersion'
  loop
    begin
      module_root_id_value := (module_dependency ->> 'moduleRootId')::uuid;
    exception when invalid_text_representation then
      raise exception using errcode = '23514', message = 'Compiled Module identity is invalid';
    end;
    if not vortex_platform.is_non_nil_uuid(module_root_id_value::text)
      or module_dependency ->> 'releaseVersion' is null then
      raise exception using errcode = '23514', message = 'Compiled Module release is invalid';
    end if;
    select release.release_revision into strict module_release_revision
    from vortex_definition.releases as release
    join vortex_definition.roots as root on root.root_id = release.root_id
    where release.root_id = module_root_id_value
      and release.release_version = module_dependency ->> 'releaseVersion'
      and root.kind = 'module';
    resolved_modules_value := resolved_modules_value || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'moduleRootId', module_root_id_value,
        'moduleReleaseRevision', module_release_revision,
        'releaseVersion', module_dependency ->> 'releaseVersion'
      )
    );
    storage_identities_value := storage_identities_value || vortex_record.provision_preview_module_storage(
      preview_installation_id_value, module_root_id_value, module_release_revision
    );
  end loop;

  update vortex_definition.preview_installations as preview
  set resolved_modules = resolved_modules_value,
      storage_identities = storage_identities_value
  where preview.preview_installation_id = preview_installation_id_value;

  return pg_catalog.jsonb_build_object(
    'previewInstallationId', preview_installation_id_value,
    'organizationId', organization_id_value,
    'applicationRootId', p_application_root_id,
    'draftRevision', p_expected_draft_revision,
    'previewerIdentityId', identity_id_value,
    'previewerOrganizationAccountId', organization_account_id_value,
    'candidate', p_candidate,
    'resolvedModules', resolved_modules_value,
    'storageIdentities', storage_identities_value,
    'createdAt', created_at_value,
    'expiresAt', expires_at_value
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002', message = 'Exact Application or Module evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000', message = 'Exact Application or Module evidence is ambiguous';
end
$function$;

comment on function vortex_definition.create_preview_installation(uuid, bigint, jsonb) is
  'Creates a 24-hour preview of one current Application draft, with fresh isolated storage for its exact published Module dependencies and no live installation registrations.';

create or replace function vortex_definition.create_private_form_draft(
  p_form_id uuid,
  p_flow_id uuid,
  p_node_id uuid,
  p_subject_record_id uuid,
  p_field_values jsonb,
  p_validation_state jsonb
)
returns table (outcome text, result jsonb)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  scope record;
  created_at timestamptz;
  new_draft_id uuid;
  stored vortex_definition.form_drafts%rowtype;
begin
  if p_form_id is null or not vortex_platform.is_non_nil_uuid(p_form_id::text)
    or (p_flow_id is not null and not vortex_platform.is_non_nil_uuid(p_flow_id::text))
    or (p_node_id is not null and not vortex_platform.is_non_nil_uuid(p_node_id::text))
    or (p_subject_record_id is not null
      and not vortex_platform.is_non_nil_uuid(p_subject_record_id::text))
    or not vortex_definition.private_form_draft_values_are_valid(p_field_values)
    or not vortex_definition.private_form_draft_validation_is_valid(p_validation_state) then
    raise exception using errcode = '22023',
      message = 'Private form draft create command is invalid';
  end if;

  select context.* into strict scope
  from vortex_definition.private_form_draft_context_internal() as context;

  -- An untouched draft that has reached its expiry no longer holds the scope.
  delete from vortex_definition.form_drafts as draft
  where draft.organization_id = scope.organization_id
    and draft.organization_account_id = scope.organization_account_id
    and draft.application_root_id = scope.application_root_id
    and draft.form_id = p_form_id
    and draft.flow_id is not distinct from p_flow_id
    and draft.node_id is not distinct from p_node_id
    and draft.subject_record_id is not distinct from p_subject_record_id
    and draft.expires_at <= pg_catalog.clock_timestamp();

  perform 1
  from vortex_definition.form_drafts as draft
  where draft.organization_id = scope.organization_id
    and draft.organization_account_id = scope.organization_account_id
    and draft.application_root_id = scope.application_root_id
    and draft.installation_release_revision = scope.release_revision
    and draft.form_id = p_form_id
    and draft.flow_id is not distinct from p_flow_id
    and draft.node_id is not distinct from p_node_id
    and draft.subject_record_id is not distinct from p_subject_record_id
  for update;
  if found then
    return query select 'exists'::text, null::jsonb;
    return;
  end if;

  created_at := pg_catalog.clock_timestamp();
  new_draft_id := pg_catalog.gen_random_uuid();
  begin
    insert into vortex_definition.form_drafts (
      draft_id, organization_id, organization_account_id, identity_id,
      application_root_id, installation_release_revision,
      form_id, flow_id, node_id, subject_record_id,
      revision, field_values, validation_state,
      created_at, updated_at, expires_at, correlation_id
    ) values (
      new_draft_id, scope.organization_id, scope.organization_account_id, scope.identity_id,
      scope.application_root_id, scope.release_revision,
      p_form_id, p_flow_id, p_node_id, p_subject_record_id,
      1, p_field_values, p_validation_state,
      created_at, created_at,
      vortex_definition.private_form_draft_expiry_internal(created_at), scope.correlation_id
    )
    returning * into stored;
  exception
    when unique_violation then
      return query select 'exists'::text, null::jsonb;
      return;
  end;

  return query select 'created'::text,
    vortex_definition.private_form_draft_to_json_internal(stored, 'active');
end
$function$;

comment on function vortex_definition.create_private_form_draft(uuid, uuid, uuid, uuid, jsonb, jsonb) is
  'Creates revision 1 of a private form draft for the current person and exact active installation, or reports the scope is already held.';

alter function vortex_definition.create_private_form_draft(uuid, uuid, uuid, uuid, jsonb, jsonb)
  owner to vortex_owner;

create or replace function vortex_definition.detach_application_installation(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_expected_module_bindings jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  initial_authority record;
  current_authority record;
  pin record;
  expected_count integer;
  pin_count integer;
  all_active boolean;
  all_provisioned boolean;
  all_detached boolean;
  changed_value boolean;
  binding_evidence jsonb;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision not between 1 and 9007199254740991
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_expected_module_bindings) = 0
    or exists (
      select 1 from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      where pg_catalog.jsonb_typeof(item.value) <> 'object'
        or not item.value ?& array['moduleRootId', 'bindingRevision']
        or item.value - array['moduleRootId', 'bindingRevision'] <> '{}'::jsonb
        or (item.value ->> 'moduleRootId')::uuid =
          '00000000-0000-0000-0000-000000000000'::uuid
        or (item.value ->> 'bindingRevision')::bigint not between 1 and 9007199254740991
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      group by (item.value ->> 'moduleRootId')::uuid
      having pg_catalog.count(*) <> 1
    )
    or p_expected_module_bindings is distinct from (
      select pg_catalog.jsonb_agg(item.value order by (item.value ->> 'moduleRootId')::uuid)
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
    ) then
    raise exception using errcode = '22023',
      message = 'Application installation detach command is invalid';
  end if;

  select locked.* into strict initial_authority
  from vortex_access.lock_application_installation_authority() as locked;

  if not exists (
    select 1
    from vortex_definition.roots as root
    join vortex_definition.releases as release on release.root_id = root.root_id
    where root.root_id = p_application_root_id
      and root.organization_id = initial_authority.organization_id
      and root.kind = 'application'
      and release.release_revision = p_application_release_revision
      and release.validation_contract_version = any (vortex_definition.accepted_contract_version('application'))
      and release.compilation_output #>> '{kind}' = 'application'
      and release.compilation_output #>> '{canonical,envelope,rootId}' = p_application_root_id::text
      and release.compilation_output #>> '{validationContractVersion}' = any (vortex_definition.accepted_contract_version('application'))
  ) then
    raise exception using errcode = 'P0002',
      message = 'Exact Application release is unavailable';
  end if;

  select pg_catalog.count(*)::integer into pin_count
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  );
  expected_count := pg_catalog.jsonb_array_length(p_expected_module_bindings);
  if pin_count = 0 or expected_count <> pin_count
    or exists (
      select 1
      from vortex_definition.reachable_module_dependency_edges(
        p_application_root_id, p_application_release_revision
      ) as required
      where not exists (
        select 1 from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
        where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
      )
    ) then
    raise exception using errcode = '23514',
      message = 'Application installation binding set is incomplete';
  end if;

  for pin in
    select required.*
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    order by required.target_root_id
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'vortex_definition.binding:' || initial_authority.organization_id::text || ':' ||
          p_application_root_id::text || ':' || pin.target_root_id::text,
        0
      )
    );
    perform 1
    from vortex_definition.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = pin.target_root_id
    for update;
  end loop;

  select locked.* into strict current_authority
  from vortex_access.lock_application_installation_authority() as locked;
  if current_authority.organization_id <> initial_authority.organization_id
    or current_authority.organization_account_id <> initial_authority.organization_account_id
    or current_authority.access_version <> initial_authority.access_version
    or current_authority.correlation_id <> initial_authority.correlation_id then
    raise exception using errcode = '40001',
      message = 'Application installation authority changed';
  end if;

  -- Each accepted state must hold for the complete exact set; mixed states are refused.
  select pg_catalog.bool_and(coalesce(
      binding.state = 'active'
      and binding.binding_revision = expected.binding_revision
      and binding.application_release_revision = p_application_release_revision
      and binding.module_release_revision = required.target_release_revision, false
    )),
    pg_catalog.bool_and(coalesce(
      binding.state = 'provisioned'
      and binding.binding_revision = expected.binding_revision
      and binding.application_release_revision = p_application_release_revision
      and binding.module_release_revision = required.target_release_revision, false
    )),
    pg_catalog.bool_and(coalesce(
      binding.state = 'detached'
      and binding.binding_revision = expected.binding_revision
      and binding.application_release_revision = p_application_release_revision
      and binding.module_release_revision = required.target_release_revision, false
    ))
  into all_active, all_provisioned, all_detached
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  ) as required
  left join vortex_definition.installation_bindings as binding
    on binding.organization_id = initial_authority.organization_id
    and binding.application_root_id = p_application_root_id
    and binding.module_root_id = required.target_root_id
  left join lateral (
    select (expected.value ->> 'bindingRevision')::bigint as binding_revision
    from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
    where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
  ) as expected on true
  ;
  if all_active is null or (not all_active and not all_provisioned and not all_detached)
    or exists (
      select 1 from vortex_definition.installation_bindings as binding
      where binding.organization_id = initial_authority.organization_id
        and binding.application_root_id = p_application_root_id
        and binding.state <> 'detached'
        and not exists (
          select 1 from vortex_definition.reachable_module_dependency_edges(
            p_application_root_id, p_application_release_revision
          ) as required
          where required.target_root_id = binding.module_root_id
        )
    ) then
    raise exception using errcode = '40001',
      message = 'Application installation bindings changed or are incomplete';
  end if;

  changed_value := all_active or all_provisioned;
  if changed_value then
    if exists (
      select 1 from vortex_definition.reachable_module_dependency_edges(
        p_application_root_id, p_application_release_revision
      ) as required
      join vortex_definition.installation_bindings as binding
        on binding.organization_id = initial_authority.organization_id
        and binding.application_root_id = p_application_root_id
        and binding.module_root_id = required.target_root_id
      where binding.binding_revision = 9007199254740991
    ) then
      raise exception using errcode = '22003',
        message = 'Application installation binding revision is exhausted';
    end if;
    update vortex_definition.installation_bindings as binding
    set state = 'detached', binding_revision = binding.binding_revision + 1,
      changed_at = pg_catalog.statement_timestamp()
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = required.target_root_id
      and binding.state in ('active', 'provisioned');
    if not found then
      raise exception using errcode = '40001',
        message = 'Application installation bindings changed';
    end if;
  end if;

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'organizationId', binding.organization_id,
    'applicationRootId', binding.application_root_id,
    'moduleRootId', binding.module_root_id,
    'bindingRevision', binding.binding_revision,
    'applicationReleaseRevision', binding.application_release_revision,
    'moduleReleaseRevision', binding.module_release_revision,
    'state', binding.state
  ) order by binding.module_root_id) into binding_evidence
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  ) as required
  join vortex_definition.installation_bindings as binding
    on binding.organization_id = initial_authority.organization_id
    and binding.application_root_id = p_application_root_id
    and binding.module_root_id = required.target_root_id;

  return pg_catalog.jsonb_build_object(
    'organizationId', initial_authority.organization_id,
    'applicationRootId', p_application_root_id,
    'applicationReleaseRevision', p_application_release_revision,
    'state', 'detached', 'changed', changed_value,
    'moduleBindings', binding_evidence
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Application installation evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Application installation evidence is ambiguous';
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '22023',
      message = 'Application installation detach command is invalid';
end
$function$;

comment on function vortex_definition.detach_application_installation(uuid, bigint, jsonb) is
  'Revision-checked atomic detach of one complete Application Module binding set while retaining storage and records.';

create or replace function vortex_definition.discard_preview_installation(
  p_preview_installation_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked_context jsonb;
  preview_row vortex_definition.preview_installations%rowtype;
begin
  if not vortex_platform.is_non_nil_uuid(p_preview_installation_id::text) then
    raise exception using errcode = '22023', message = 'Preview installation identity is invalid';
  end if;
  checked_context := vortex_definition.assert_preview_installation_authority_internal();
  select preview.* into preview_row
  from vortex_definition.preview_installations as preview
  where preview.preview_installation_id = p_preview_installation_id
    and preview.organization_id = (checked_context ->> 'organizationId')::uuid
    and preview.previewer_identity_id = (checked_context ->> 'identityId')::uuid
    and preview.previewer_organization_account_id =
      (checked_context ->> 'organizationAccountId')::uuid
    and preview.application_root_id = (checked_context ->> 'applicationRootId')::uuid
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'Preview installation is unavailable';
  end if;
  perform vortex_record.drop_preview_installation_storage(
    preview_row.preview_installation_id
  );
  delete from vortex_definition.preview_installations as preview
  where preview.preview_installation_id = preview_row.preview_installation_id;
  return pg_catalog.jsonb_build_object(
    'discarded', true,
    'previewInstallationId', preview_row.preview_installation_id
  );
end
$function$;

comment on function vortex_definition.discard_preview_installation(uuid) is
  'Immediately drops a preview installation and its isolated Record storage, only for the creating organisation account.';

create or replace function vortex_definition.drain_installation(
  p_activity_id uuid,
  p_root_id uuid,
  p_release_revision bigint,
  p_expected_module_bindings jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  initial_authority record;
  current_authority record;
  target_kind text;
  application_release vortex_definition.releases%rowtype;
  pin record;
  expected_count integer;
  pin_count integer;
  all_active boolean;
  all_draining boolean;
  changed_value boolean;
  binding_evidence jsonb;
begin
  if p_activity_id is null
    or p_activity_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_root_id is null
    or p_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_release_revision not between 1 and 9007199254740991
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_expected_module_bindings) = 0
    or exists (
      select 1 from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      where pg_catalog.jsonb_typeof(item.value) <> 'object'
        or not item.value ?& array['moduleRootId', 'bindingRevision']
        or item.value - array['moduleRootId', 'bindingRevision'] <> '{}'::jsonb
        or (item.value ->> 'moduleRootId')::uuid =
          '00000000-0000-0000-0000-000000000000'::uuid
        or (item.value ->> 'bindingRevision')::bigint not between 1 and 9007199254740991
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      group by (item.value ->> 'moduleRootId')::uuid
      having pg_catalog.count(*) <> 1
    )
    or p_expected_module_bindings is distinct from (
      select pg_catalog.jsonb_agg(item.value order by (item.value ->> 'moduleRootId')::uuid)
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
    ) then
    raise exception using errcode = '22023',
      message = 'Installation drain command is invalid';
  end if;

  select locked.* into strict initial_authority
  from vortex_access.lock_application_installation_authority() as locked;

  select root.kind into target_kind
  from vortex_definition.roots as root
  where root.root_id = p_root_id
    and root.organization_id = initial_authority.organization_id;
  if not found then
    raise exception using errcode = 'P0002',
      message = 'Installation is unavailable';
  end if;

  -- A Module is never installed on its own; its storage and records exist because an
  -- installed Application binds that exact release. Uninstalling a Module an installed
  -- Application still depends on is refused.
  if target_kind = 'module' then
    if exists (
      select 1 from vortex_definition.installation_bindings as binding
      where binding.organization_id = initial_authority.organization_id
        and binding.module_root_id = p_root_id
        and binding.state in ('provisioned', 'active', 'draining')
    ) then
      raise exception using errcode = '42501',
        message = 'Installation is required by an installed application';
    end if;
    raise exception using errcode = 'P0002',
      message = 'Installation is unavailable';
  end if;

  select release.* into strict application_release
  from vortex_definition.releases as release
  join vortex_definition.roots as root on root.root_id = release.root_id
  where root.root_id = p_root_id
    and root.organization_id = initial_authority.organization_id
    and root.kind = 'application'
    and release.release_revision = p_release_revision
    and release.validation_contract_version = any (vortex_definition.accepted_contract_version('application'))
    and release.compilation_output #>> '{kind}' = 'application'
    and release.compilation_output #>> '{canonical,envelope,rootId}' = p_root_id::text
    and release.compilation_output #>> '{validationContractVersion}' = any (vortex_definition.accepted_contract_version('application'));

  select pg_catalog.count(*)::integer into pin_count
  from vortex_definition.reachable_module_dependency_edges(p_root_id, p_release_revision);
  expected_count := pg_catalog.jsonb_array_length(p_expected_module_bindings);
  if pin_count = 0 or expected_count <> pin_count
    or exists (
      select 1
      from vortex_definition.reachable_module_dependency_edges(p_root_id, p_release_revision) as required
      where not exists (
        select 1 from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
        where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
      )
    ) then
    raise exception using errcode = '23514',
      message = 'Installation binding set is incomplete';
  end if;

  for pin in
    select required.*
    from vortex_definition.reachable_module_dependency_edges(p_root_id, p_release_revision) as required
    order by required.target_root_id
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'vortex_definition.binding:' || initial_authority.organization_id::text || ':' ||
          p_root_id::text || ':' || pin.target_root_id::text,
        0
      )
    );
    perform 1
    from vortex_definition.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_root_id
      and binding.module_root_id = pin.target_root_id
    for update;
  end loop;

  select locked.* into strict current_authority
  from vortex_access.lock_application_installation_authority() as locked;
  if current_authority.organization_id <> initial_authority.organization_id
    or current_authority.organization_account_id <> initial_authority.organization_account_id
    or current_authority.access_version <> initial_authority.access_version
    or current_authority.correlation_id <> initial_authority.correlation_id then
    raise exception using errcode = '40001',
      message = 'Installation authority changed';
  end if;

  select pg_catalog.bool_and(coalesce(
      binding.state = 'active'
      and binding.binding_revision = expected.binding_revision
      and binding.application_release_revision = p_release_revision
      and binding.module_release_revision = required.target_release_revision, false
    )),
    pg_catalog.bool_and(coalesce(
      binding.state = 'draining'
      and binding.binding_revision = expected.binding_revision
      and binding.application_release_revision = p_release_revision
      and binding.module_release_revision = required.target_release_revision, false
    ))
  into all_active, all_draining
  from vortex_definition.reachable_module_dependency_edges(p_root_id, p_release_revision) as required
  left join vortex_definition.installation_bindings as binding
    on binding.organization_id = initial_authority.organization_id
    and binding.application_root_id = p_root_id
    and binding.module_root_id = required.target_root_id
  left join lateral (
    select (expected.value ->> 'bindingRevision')::bigint as binding_revision
    from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
    where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
  ) as expected on true;
  if all_active is null or (not all_active and not all_draining)
    or exists (
      select 1 from vortex_definition.installation_bindings as binding
      where binding.organization_id = initial_authority.organization_id
        and binding.application_root_id = p_root_id
        and binding.state <> 'detached'
        and not exists (
          select 1
          from vortex_definition.reachable_module_dependency_edges(p_root_id, p_release_revision) as required
          where required.target_root_id = binding.module_root_id
        )
    ) then
    raise exception using errcode = '40001',
      message = 'Installation bindings changed or are incomplete';
  end if;

  changed_value := all_active;
  if changed_value then
    if exists (
      select 1
      from vortex_definition.reachable_module_dependency_edges(p_root_id, p_release_revision) as required
      join vortex_definition.installation_bindings as binding
        on binding.organization_id = initial_authority.organization_id
        and binding.application_root_id = p_root_id
        and binding.module_root_id = required.target_root_id
      where binding.binding_revision = 9007199254740991
    ) then
      raise exception using errcode = '22003',
        message = 'Installation binding revision is exhausted';
    end if;
    update vortex_definition.installation_bindings as binding
    set state = 'draining', binding_revision = binding.binding_revision + 1,
      changed_at = pg_catalog.statement_timestamp()
    from vortex_definition.reachable_module_dependency_edges(p_root_id, p_release_revision) as required
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_root_id
      and binding.module_root_id = required.target_root_id
      and binding.state = 'active';
    if not found then
      raise exception using errcode = '40001',
        message = 'Installation bindings changed';
    end if;
  end if;

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'organizationId', binding.organization_id,
    'applicationRootId', binding.application_root_id,
    'moduleRootId', binding.module_root_id,
    'bindingRevision', binding.binding_revision,
    'applicationReleaseRevision', binding.application_release_revision,
    'moduleReleaseRevision', binding.module_release_revision,
    'state', binding.state
  ) order by binding.module_root_id) into binding_evidence
  from vortex_definition.reachable_module_dependency_edges(p_root_id, p_release_revision) as required
  join vortex_definition.installation_bindings as binding
    on binding.organization_id = initial_authority.organization_id
    and binding.application_root_id = p_root_id
    and binding.module_root_id = required.target_root_id;

  if changed_value then
    perform vortex_definition.append_application_installation_activity_internal(
      p_activity_id, p_root_id, 'drain_application_installation'
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', initial_authority.organization_id,
    'applicationRootId', p_root_id,
    'applicationReleaseRevision', p_release_revision,
    'state', 'draining', 'changed', changed_value,
    'moduleBindings', binding_evidence
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Installation evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Installation evidence is ambiguous';
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '22023',
      message = 'Installation drain command is invalid';
end
$function$;

comment on function vortex_definition.drain_installation(uuid, uuid, bigint, jsonb) is
  'Protected first uninstall step: moves one exact active Application installation to draining, or refuses a Module an installed Application depends on, recording Activity from the trusted channel.';

create or replace function vortex_definition.expire_preview_installations(
  p_limit integer
)
returns integer
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked_context jsonb;
  preview_row record;
  expired_count integer := 0;
begin
  if p_limit is null or p_limit not between 1 and 100 then
    raise exception using errcode = '22023', message = 'Preview expiry batch size is invalid';
  end if;
  checked_context := vortex_definition.assert_preview_installation_authority_internal();
  for preview_row in
    select preview.preview_installation_id
    from vortex_definition.preview_installations as preview
    where preview.organization_id = (checked_context ->> 'organizationId')::uuid
      and preview.expires_at <= pg_catalog.statement_timestamp()
    order by preview.expires_at, preview.preview_installation_id
    limit p_limit
    for update skip locked
  loop
    perform vortex_record.drop_preview_installation_storage(
      preview_row.preview_installation_id
    );
    delete from vortex_definition.preview_installations as preview
    where preview.preview_installation_id = preview_row.preview_installation_id;
    expired_count := expired_count + 1;
  end loop;
  return expired_count;
end
$function$;

comment on function vortex_definition.expire_preview_installations(integer) is
  'Purges a bounded batch of expired preview installations in the current human organisation, including their isolated Record storage.';

create or replace function vortex_definition.expire_private_form_drafts(p_limit integer default 500)
returns integer
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked jsonb;
begin
  if p_limit is null or p_limit not between 1 and 10000 then
    raise exception using errcode = '22023',
      message = 'Private form draft expiry command is invalid';
  end if;

  checked := vortex_access.validated_human_request_context();
  if not vortex_platform.is_non_nil_uuid(checked ->> 'organizationId') then
    raise exception using errcode = '42501',
      message = 'Private form draft scope is unavailable';
  end if;

  return vortex_definition.private_form_draft_purge_internal(
    (checked ->> 'organizationId')::uuid,
    p_limit
  );
end
$function$;

comment on function vortex_definition.expire_private_form_drafts(integer) is
  'Deletes a bounded batch of the current organisation''s private form drafts untouched for thirty days.';

alter function vortex_definition.expire_private_form_drafts(integer)
  owner to vortex_owner;

create or replace function vortex_definition.has_active_application_release_binding_internal(
  p_organization_id uuid,
  p_application_root_id uuid,
  p_application_release_revision bigint
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $function$
  select exists (
    select 1
    from vortex_definition.installation_bindings as binding
    where binding.organization_id = p_organization_id
      and binding.application_root_id = p_application_root_id
      and binding.application_release_revision = p_application_release_revision
      and binding.state = 'active'
  );
$function$;

comment on function vortex_definition.has_active_application_release_binding_internal(
  uuid, uuid, bigint
) is
  'Private exact active Application release binding existence predicate for owner-controlled installation decisions; returns no binding rows or authority.';

create or replace function vortex_definition.lock_active_installation_runtime_mapping_internal(p_expected_identity jsonb)
returns jsonb language plpgsql volatile security definer set search_path=''
as $function$
declare
  checked_context jsonb;
  selected_org uuid;
  selected_app uuid;
  selected_revision bigint;
  active_count integer;
  registered_app record;
  registered_identity jsonb;
  bindings jsonb;
  pin_facts jsonb;
  pin_hash text;
  identity_value jsonb;
  before_identity jsonb;
  item jsonb;
  installation jsonb;
  application_evidence jsonb;
  module_evidence jsonb;
  release_identity jsonb;
begin
  checked_context:=vortex_access.validated_human_request_context();
  if checked_context ->> 'callerKind' is distinct from 'human'
    or not checked_context ? 'applicationRootId'
    or pg_catalog.clock_timestamp()>=(checked_context ->> 'expiresAt')::timestamptz
    or (checked_context ? 'delegatedContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{delegatedContext,expiresAt}')::timestamptz)
    or (checked_context ? 'supportContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{supportContext,expiresAt}')::timestamptz) then
    raise exception using errcode='42501', message='Active Application context is unavailable';
  end if;
  selected_org:=(checked_context ->> 'organizationId')::uuid;
  selected_app:=(checked_context ->> 'applicationRootId')::uuid;
  select pg_catalog.min(binding.application_release_revision),pg_catalog.count(*)::integer
  into selected_revision,active_count from vortex_definition.installation_bindings as binding
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if active_count not between 1 and 10000 or selected_revision is null or exists(
    select 1 from vortex_definition.installation_bindings as binding
    where binding.organization_id=selected_org and binding.application_root_id=selected_app
      and binding.state<>'detached'
      and (binding.state<>'active' or binding.application_release_revision<>selected_revision)) then
    raise exception using errcode='P0002', message='Active Application installation is unavailable';
  end if;
  select snapshot.* into strict registered_app
  from vortex_access.read_application_permission_snapshot(selected_org,selected_app) as snapshot;
  if registered_app.release_revision is distinct from selected_revision then
    raise exception using errcode='40001', message='Active Application registration changed';
  end if;
  registered_identity:=pg_catalog.jsonb_build_object(
    'rootId',selected_app,'definitionKey',registered_app.definition_key,
    'releaseRevision',selected_revision,'releaseVersion',registered_app.release_version,
    'validationContractVersion',registered_app.validation_contract_version,
    'contentFingerprint',registered_app.content_fingerprint,
    'resolutionFingerprint',registered_app.resolution_fingerprint);
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'bindingRevision',binding.binding_revision,'state',binding.state) order by binding.module_root_id),
    pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'contentFingerprint',module_release.content_fingerprint,
      'resolutionFingerprint',module_release.resolution_fingerprint) order by binding.module_root_id)
  into bindings,pin_facts from vortex_definition.installation_bindings as binding
  join vortex_definition.releases as module_release
    on module_release.root_id=binding.module_root_id
    and module_release.release_revision=binding.module_release_revision
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if exists(select 1 from pg_catalog.jsonb_array_elements(pin_facts) as pin(value)
    where (pin.value ->> 'contentFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or (pin.value ->> 'resolutionFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or pin.value ->> 'contentFingerprint' is null
      or pin.value ->> 'resolutionFingerprint' is null) then
    raise exception using errcode='55000', message='Active Application pins are unavailable';
  end if;
  pin_hash:='sha256:' || pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(pin_facts::text,'UTF8')),'hex');
  identity_value:=pg_catalog.jsonb_build_object(
    'tenantId',checked_context -> 'tenantId','organizationId',selected_org,
    'organizationAccountId',checked_context -> 'organizationAccountId',
    'identityId',checked_context -> 'identityId','sessionId',checked_context -> 'sessionId',
    'accessVersion',checked_context -> 'accessVersion','correlationId',checked_context -> 'correlationId',
    'applicationRootId',selected_app,'applicationReleaseRevision',selected_revision,
    'registeredApplication',registered_identity,'moduleBindings',bindings,
    'pinFacts',pin_facts,'pinFingerprint',pin_hash);
  if p_expected_identity is distinct from identity_value then
    raise exception using errcode='40001', message='Active Application identity changed';
  end if;
  before_identity:=identity_value;
  for item in select pin.value from pg_catalog.jsonb_array_elements(bindings) as pin(value)
    order by (pin.value ->> 'moduleRootId')::uuid
  loop
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      'vortex_definition.binding:' || selected_org::text || ':' || selected_app::text || ':' ||
        (item ->> 'moduleRootId'),0));
    perform 1 from vortex_definition.installation_bindings as binding
    where binding.organization_id=selected_org and binding.application_root_id=selected_app
      and binding.module_root_id=(item ->> 'moduleRootId')::uuid for update;
  checked_context:=vortex_access.validated_human_request_context();
  if checked_context ->> 'callerKind' is distinct from 'human'
    or not checked_context ? 'applicationRootId'
    or pg_catalog.clock_timestamp()>=(checked_context ->> 'expiresAt')::timestamptz
    or (checked_context ? 'delegatedContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{delegatedContext,expiresAt}')::timestamptz)
    or (checked_context ? 'supportContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{supportContext,expiresAt}')::timestamptz) then
    raise exception using errcode='42501', message='Active Application context is unavailable';
  end if;
  selected_org:=(checked_context ->> 'organizationId')::uuid;
  selected_app:=(checked_context ->> 'applicationRootId')::uuid;
  select pg_catalog.min(binding.application_release_revision),pg_catalog.count(*)::integer
  into selected_revision,active_count from vortex_definition.installation_bindings as binding
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if active_count not between 1 and 10000 or selected_revision is null or exists(
    select 1 from vortex_definition.installation_bindings as binding
    where binding.organization_id=selected_org and binding.application_root_id=selected_app
      and binding.state<>'detached'
      and (binding.state<>'active' or binding.application_release_revision<>selected_revision)) then
    raise exception using errcode='P0002', message='Active Application installation is unavailable';
  end if;
  select snapshot.* into strict registered_app
  from vortex_access.read_application_permission_snapshot(selected_org,selected_app) as snapshot;
  if registered_app.release_revision is distinct from selected_revision then
    raise exception using errcode='40001', message='Active Application registration changed';
  end if;
  registered_identity:=pg_catalog.jsonb_build_object(
    'rootId',selected_app,'definitionKey',registered_app.definition_key,
    'releaseRevision',selected_revision,'releaseVersion',registered_app.release_version,
    'validationContractVersion',registered_app.validation_contract_version,
    'contentFingerprint',registered_app.content_fingerprint,
    'resolutionFingerprint',registered_app.resolution_fingerprint);
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'bindingRevision',binding.binding_revision,'state',binding.state) order by binding.module_root_id),
    pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'contentFingerprint',module_release.content_fingerprint,
      'resolutionFingerprint',module_release.resolution_fingerprint) order by binding.module_root_id)
  into bindings,pin_facts from vortex_definition.installation_bindings as binding
  join vortex_definition.releases as module_release
    on module_release.root_id=binding.module_root_id
    and module_release.release_revision=binding.module_release_revision
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if exists(select 1 from pg_catalog.jsonb_array_elements(pin_facts) as pin(value)
    where (pin.value ->> 'contentFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or (pin.value ->> 'resolutionFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or pin.value ->> 'contentFingerprint' is null
      or pin.value ->> 'resolutionFingerprint' is null) then
    raise exception using errcode='55000', message='Active Application pins are unavailable';
  end if;
  pin_hash:='sha256:' || pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(pin_facts::text,'UTF8')),'hex');
  identity_value:=pg_catalog.jsonb_build_object(
    'tenantId',checked_context -> 'tenantId','organizationId',selected_org,
    'organizationAccountId',checked_context -> 'organizationAccountId',
    'identityId',checked_context -> 'identityId','sessionId',checked_context -> 'sessionId',
    'accessVersion',checked_context -> 'accessVersion','correlationId',checked_context -> 'correlationId',
    'applicationRootId',selected_app,'applicationReleaseRevision',selected_revision,
    'registeredApplication',registered_identity,'moduleBindings',bindings,
    'pinFacts',pin_facts,'pinFingerprint',pin_hash);
    if identity_value is distinct from before_identity then
      raise exception using errcode='40001', message='Active Application identity changed while waiting';
    end if;
  end loop;
  installation:=vortex_definition.read_active_installation_for_scope_internal(selected_org,selected_app);
  if (installation ->> 'applicationReleaseRevision')::bigint is distinct from selected_revision
    or exists(select 1 from pg_catalog.jsonb_array_elements(installation -> 'moduleBindings') as current(value)
      where not exists(select 1 from pg_catalog.jsonb_array_elements(bindings) as expected(value)
        where current.value -> 'moduleRootId'=expected.value -> 'moduleRootId'
          and current.value -> 'moduleReleaseRevision'=expected.value -> 'moduleReleaseRevision'
          and current.value -> 'bindingRevision'=expected.value -> 'bindingRevision'
          and current.value ->> 'state'='active'))
    or pg_catalog.jsonb_array_length(installation -> 'moduleBindings')<>active_count then
    raise exception using errcode='40001', message='Active Application pin closure changed';
  end if;
  application_evidence:=vortex_definition.project_consumer_release_evidence('application',selected_app,selected_revision);
  release_identity:=pg_catalog.jsonb_build_object(
    'rootId',application_evidence -> 'rootId','definitionKey',application_evidence -> 'key',
    'releaseRevision',application_evidence -> 'releaseRevision','releaseVersion',application_evidence -> 'releaseVersion',
    'validationContractVersion',application_evidence -> 'validationContractVersion',
    'contentFingerprint',application_evidence -> 'contentFingerprint',
    'resolutionFingerprint',application_evidence -> 'resolutionFingerprint');
  if application_evidence ->> 'kind' is distinct from 'application'
    or (application_evidence ->> 'organizationId')::uuid is distinct from selected_org
    or release_identity is distinct from registered_identity then
    raise exception using errcode='23514', message='Active Application publication differs';
  end if;
  select pg_catalog.jsonb_agg(vortex_definition.project_consumer_release_evidence(
    'module',(pin.value ->> 'moduleRootId')::uuid,(pin.value ->> 'moduleReleaseRevision')::bigint)
    order by (pin.value ->> 'moduleRootId')::uuid)
  into module_evidence from pg_catalog.jsonb_array_elements(bindings) as pin(value);
  if pg_catalog.jsonb_array_length(module_evidence)<>active_count or exists(
    select 1 from pg_catalog.jsonb_array_elements(module_evidence) as module(value)
    where module.value ->> 'kind' is distinct from 'module'
      or (module.value ->> 'organizationId')::uuid is distinct from selected_org
      or not exists(select 1 from pg_catalog.jsonb_array_elements(pin_facts) as pin(value)
        where pin.value -> 'moduleRootId'=module.value -> 'rootId'
          and pin.value -> 'moduleReleaseRevision'=module.value -> 'releaseRevision'
          and pin.value -> 'contentFingerprint'=module.value -> 'contentFingerprint'
          and pin.value -> 'resolutionFingerprint'=module.value -> 'resolutionFingerprint')) then
    raise exception using errcode='23514', message='Active Module publication differs';
  end if;
  checked_context:=vortex_access.validated_human_request_context();
  if checked_context ->> 'callerKind' is distinct from 'human'
    or not checked_context ? 'applicationRootId'
    or pg_catalog.clock_timestamp()>=(checked_context ->> 'expiresAt')::timestamptz
    or (checked_context ? 'delegatedContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{delegatedContext,expiresAt}')::timestamptz)
    or (checked_context ? 'supportContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{supportContext,expiresAt}')::timestamptz) then
    raise exception using errcode='42501', message='Active Application context is unavailable';
  end if;
  selected_org:=(checked_context ->> 'organizationId')::uuid;
  selected_app:=(checked_context ->> 'applicationRootId')::uuid;
  select pg_catalog.min(binding.application_release_revision),pg_catalog.count(*)::integer
  into selected_revision,active_count from vortex_definition.installation_bindings as binding
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if active_count not between 1 and 10000 or selected_revision is null or exists(
    select 1 from vortex_definition.installation_bindings as binding
    where binding.organization_id=selected_org and binding.application_root_id=selected_app
      and binding.state<>'detached'
      and (binding.state<>'active' or binding.application_release_revision<>selected_revision)) then
    raise exception using errcode='P0002', message='Active Application installation is unavailable';
  end if;
  select snapshot.* into strict registered_app
  from vortex_access.read_application_permission_snapshot(selected_org,selected_app) as snapshot;
  if registered_app.release_revision is distinct from selected_revision then
    raise exception using errcode='40001', message='Active Application registration changed';
  end if;
  registered_identity:=pg_catalog.jsonb_build_object(
    'rootId',selected_app,'definitionKey',registered_app.definition_key,
    'releaseRevision',selected_revision,'releaseVersion',registered_app.release_version,
    'validationContractVersion',registered_app.validation_contract_version,
    'contentFingerprint',registered_app.content_fingerprint,
    'resolutionFingerprint',registered_app.resolution_fingerprint);
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'bindingRevision',binding.binding_revision,'state',binding.state) order by binding.module_root_id),
    pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'contentFingerprint',module_release.content_fingerprint,
      'resolutionFingerprint',module_release.resolution_fingerprint) order by binding.module_root_id)
  into bindings,pin_facts from vortex_definition.installation_bindings as binding
  join vortex_definition.releases as module_release
    on module_release.root_id=binding.module_root_id
    and module_release.release_revision=binding.module_release_revision
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if exists(select 1 from pg_catalog.jsonb_array_elements(pin_facts) as pin(value)
    where (pin.value ->> 'contentFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or (pin.value ->> 'resolutionFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or pin.value ->> 'contentFingerprint' is null
      or pin.value ->> 'resolutionFingerprint' is null) then
    raise exception using errcode='55000', message='Active Application pins are unavailable';
  end if;
  pin_hash:='sha256:' || pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(pin_facts::text,'UTF8')),'hex');
  identity_value:=pg_catalog.jsonb_build_object(
    'tenantId',checked_context -> 'tenantId','organizationId',selected_org,
    'organizationAccountId',checked_context -> 'organizationAccountId',
    'identityId',checked_context -> 'identityId','sessionId',checked_context -> 'sessionId',
    'accessVersion',checked_context -> 'accessVersion','correlationId',checked_context -> 'correlationId',
    'applicationRootId',selected_app,'applicationReleaseRevision',selected_revision,
    'registeredApplication',registered_identity,'moduleBindings',bindings,
    'pinFacts',pin_facts,'pinFingerprint',pin_hash);
  if identity_value is distinct from before_identity then
    raise exception using errcode='40001', message='Active Application mapping changed';
  end if;
  return pg_catalog.jsonb_build_object('identity',identity_value,'installation',installation,
    'application',application_evidence,'modules',module_evidence);
exception when no_data_found or too_many_rows then
  raise exception using errcode='P0002', message='Active Application mapping is unavailable';
end
$function$;

comment on function vortex_definition.lock_active_installation_runtime_mapping_internal(jsonb) is 'Locks and proves exact active publication mapping under the current HUMAN request; expected identity is only a guard.';

create or replace function vortex_definition.lock_prepared_installation_runtime_mapping_internal(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_expected_module_bindings jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  none_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  initial_authority record;
  current_authority record;
  registration_revision bigint;
  required_count integer;
  expected_count integer;
  binding_item jsonb;
  pin_facts jsonb;
  binding_facts jsonb;
  pin_fingerprint text;
begin
  if p_application_root_id is null or p_application_root_id = none_uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_expected_module_bindings) < 1
    or exists (
      select 1 from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      where pg_catalog.jsonb_typeof(item.value) is distinct from 'object'
        or not item.value ?& array[
          'moduleRootId', 'moduleReleaseRevision', 'bindingRevision', 'state'
        ]
        or item.value - array[
          'moduleRootId', 'moduleReleaseRevision', 'bindingRevision', 'state'
        ] <> '{}'::jsonb
        or (item.value ->> 'moduleRootId') !~* '^[0-9a-f-]{36}$'
        or (item.value ->> 'moduleReleaseRevision') !~ '^[1-9][0-9]*$'
        or (item.value ->> 'bindingRevision') !~ '^[1-9][0-9]*$'
        or item.value ->> 'state' is distinct from 'provisioned'
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      group by (item.value ->> 'moduleRootId')::uuid
      having pg_catalog.count(*) <> 1
    )
    or p_expected_module_bindings is distinct from (
      select pg_catalog.jsonb_agg(item.value order by (item.value ->> 'moduleRootId')::uuid)
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
    ) then
    raise exception using errcode = '22023',
      message = 'Prepared installation mapping command is invalid';
  end if;

  select locked.* into strict initial_authority
  from vortex_access.lock_application_installation_authority() as locked;

  select snapshot.release_revision into registration_revision
  from vortex_access.read_application_permission_snapshot(
    initial_authority.organization_id, p_application_root_id
  ) as snapshot;
  if registration_revision is distinct from p_application_release_revision then
    raise exception using errcode = '42501',
      message = 'Prepared installation registration is unavailable';
  end if;

  if not exists (
    select 1
    from vortex_definition.roots as root
    join vortex_definition.releases as release
      on release.root_id = root.root_id
      and release.release_revision = p_application_release_revision
    where root.root_id = p_application_root_id
      and root.organization_id = initial_authority.organization_id
      and root.kind = 'application'
      and release.validation_contract_version = any (
        vortex_definition.accepted_contract_version('application')
      )
      and release.compilation_output #>> '{kind}' = 'application'
      and release.compilation_output #>> '{canonical,envelope,rootId}' = p_application_root_id::text
      and release.compilation_output #>> '{validationContractVersion}' = any (
        vortex_definition.accepted_contract_version('application')
      )
  ) then
    raise exception using errcode = 'P0002',
      message = 'Prepared installation Application release is unavailable';
  end if;

  select pg_catalog.count(*)::integer into required_count
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  );
  expected_count := pg_catalog.jsonb_array_length(p_expected_module_bindings);
  if required_count = 0 or expected_count <> required_count
    or exists (
      select 1
      from vortex_definition.reachable_module_dependency_edges(
        p_application_root_id, p_application_release_revision
      ) as required
      where not exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
        where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
          and (expected.value ->> 'moduleReleaseRevision')::bigint = required.target_release_revision
      )
    ) then
    raise exception using errcode = '23514',
      message = 'Prepared installation pin set is incomplete';
  end if;

  for binding_item in
    select item.value
    from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
    order by (item.value ->> 'moduleRootId')::uuid
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'vortex_definition.binding:' || initial_authority.organization_id::text || ':' ||
          p_application_root_id::text || ':' || (binding_item ->> 'moduleRootId'),
        0
      )
    );
    perform 1
    from vortex_definition.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = (binding_item ->> 'moduleRootId')::uuid
    for update;
  end loop;

  select locked.* into strict current_authority
  from vortex_access.lock_application_installation_authority() as locked;
  if current_authority.organization_id <> initial_authority.organization_id
    or current_authority.organization_account_id <> initial_authority.organization_account_id
    or current_authority.access_version <> initial_authority.access_version
    or current_authority.correlation_id <> initial_authority.correlation_id then
    raise exception using errcode = '40001',
      message = 'Prepared installation authority changed';
  end if;

  if exists (
    select 1
    from vortex_definition.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.state <> 'detached'
      and not exists (
        select 1
        from vortex_definition.reachable_module_dependency_edges(
          p_application_root_id, p_application_release_revision
        ) as required
        where required.target_root_id = binding.module_root_id
      )
  ) or exists (
    select 1
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    left join vortex_definition.installation_bindings as binding
      on binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = required.target_root_id
    left join lateral (
      select (expected.value ->> 'bindingRevision')::bigint as binding_revision
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
      where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
        and (expected.value ->> 'moduleReleaseRevision')::bigint = required.target_release_revision
    ) as expected on true
    where binding.state is distinct from 'provisioned'
      or binding.application_release_revision is distinct from p_application_release_revision
      or binding.module_release_revision is distinct from required.target_release_revision
      or binding.binding_revision is distinct from expected.binding_revision
  ) then
    raise exception using errcode = '40001',
      message = 'Prepared installation binding set changed';
  end if;

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId', pin.target_root_id,
      'moduleReleaseRevision', pin.target_release_revision,
      'contentFingerprint', release.content_fingerprint,
      'resolutionFingerprint', release.resolution_fingerprint
    ) order by pin.target_root_id)
  into pin_facts
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  ) as pin
  join vortex_definition.releases as release
    on release.root_id = pin.target_root_id
    and release.release_revision = pin.target_release_revision;
  if pin_facts is null or pg_catalog.jsonb_array_length(pin_facts) <> required_count then
    raise exception using errcode = '55000',
      message = 'Prepared installation source pins are unavailable';
  end if;
  pin_fingerprint := 'sha256:' || pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(pin_facts::text, 'UTF8')),
    'hex'
  );

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId', binding.module_root_id,
      'moduleReleaseRevision', binding.module_release_revision,
      'bindingRevision', binding.binding_revision,
      'state', binding.state
    ) order by binding.module_root_id)
  into binding_facts
  from vortex_definition.installation_bindings as binding
  where binding.organization_id = initial_authority.organization_id
    and binding.application_root_id = p_application_root_id
    and binding.state = 'provisioned';
  if binding_facts is distinct from p_expected_module_bindings then
    raise exception using errcode = '40001',
      message = 'Prepared installation expected bindings changed';
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', initial_authority.organization_id,
    'organizationAccountId', initial_authority.organization_account_id,
    'applicationRootId', p_application_root_id,
    'applicationReleaseRevision', p_application_release_revision,
    'accessVersion', initial_authority.access_version,
    'correlationId', initial_authority.correlation_id,
    'registeredReleaseRevision', registration_revision,
    'pinFingerprint', pin_fingerprint,
    'pinFacts', pin_facts,
    'moduleBindings', binding_facts
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Prepared installation mapping evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Prepared installation mapping evidence is ambiguous';
end
$function$;

comment on function vortex_definition.lock_prepared_installation_runtime_mapping_internal(uuid,bigint,jsonb) is
  'Locks the current human installation authority and exact complete provisioned Module pin mapping for first-install runtime preparation.';

CREATE OR REPLACE FUNCTION vortex_definition.lock_storage_adoption_binding_internal(p_organization_id uuid, p_application_root_id uuid, p_module_root_id uuid, p_storage_contract_id uuid, p_source_release_revision bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  own_binding vortex_definition.installation_bindings%rowtype;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_module_root_id is null
    or p_module_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_source_release_revision is null
    or p_source_release_revision not between 1 and 9007199254740991 then
    raise exception using errcode = '22023',
      message = 'Storage adoption binding command is invalid';
  end if;

  -- The same identity and order every binding writer uses, so this never
  -- interleaves with a provision, activation or detach of the same binding.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'vortex_definition.binding:' || p_organization_id::text || ':' ||
        p_application_root_id::text || ':' || p_module_root_id::text,
      0
    )
  );

  select binding.* into own_binding
  from vortex_definition.installation_bindings as binding
  where binding.organization_id = p_organization_id
    and binding.application_root_id = p_application_root_id
    and binding.module_root_id = p_module_root_id
  for update;
  if not found
    or own_binding.module_release_revision <> p_source_release_revision
    or not (p_storage_contract_id = any (own_binding.storage_contract_ids)) then
    raise exception using errcode = '55000',
      message = 'Storage adoption installation does not install the source release';
  end if;
  -- An installation still using the source field cannot lose it.
  if own_binding.state <> 'detached' then
    raise exception using errcode = '55006',
      message = 'Storage adoption installation is still using the source storage';
  end if;
end
$$;

COMMENT ON FUNCTION vortex_definition.lock_storage_adoption_binding_internal(p_organization_id uuid, p_application_root_id uuid, p_module_root_id uuid, p_storage_contract_id uuid, p_source_release_revision bigint) IS 'Private storage adoption fact: locks the caller''s own binding in canonical order and requires it detached at the exact source release.';

REVOKE ALL ON FUNCTION vortex_definition.lock_storage_adoption_binding_internal(p_organization_id uuid, p_application_root_id uuid, p_module_root_id uuid, p_storage_contract_id uuid, p_source_release_revision bigint) FROM PUBLIC;
GRANT ALL ON FUNCTION vortex_definition.lock_storage_adoption_binding_internal(p_organization_id uuid, p_application_root_id uuid, p_module_root_id uuid, p_storage_contract_id uuid, p_source_release_revision bigint) TO vortex_owner;

create or replace function vortex_definition.private_form_draft_context_internal()
returns table (
  organization_id uuid,
  organization_account_id uuid,
  identity_id uuid,
  application_root_id uuid,
  release_revision bigint,
  correlation_id uuid
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked jsonb;
  installation jsonb;
  selected_application_root_id uuid;
begin
  checked := vortex_access.validated_human_request_context();
  if not (checked ?& array['organizationAccountId', 'identityId', 'applicationRootId'])
    or not vortex_platform.is_non_nil_uuid(checked ->> 'applicationRootId')
    or not vortex_platform.is_non_nil_uuid(checked ->> 'organizationAccountId')
    or not vortex_platform.is_non_nil_uuid(checked ->> 'identityId') then
    raise exception using errcode = '42501',
      message = 'Private form draft scope is unavailable';
  end if;
  selected_application_root_id := (checked ->> 'applicationRootId')::uuid;

  installation := vortex_definition.read_current_active_installation();
  if installation is null
    or pg_catalog.jsonb_typeof(installation) <> 'object'
    or (installation ->> 'organizationId')::uuid
      is distinct from (checked ->> 'organizationId')::uuid
    or (installation ->> 'applicationRootId')::uuid is distinct from selected_application_root_id
    or pg_catalog.jsonb_typeof(installation -> 'applicationReleaseRevision')
      is distinct from 'number'
    or not vortex_platform.is_non_nil_uuid(checked ->> 'correlationId') then
    raise exception using errcode = '42501',
      message = 'Private form draft scope is unavailable';
  end if;

  return query select
    (checked ->> 'organizationId')::uuid,
    (checked ->> 'organizationAccountId')::uuid,
    (checked ->> 'identityId')::uuid,
    selected_application_root_id,
    (installation ->> 'applicationReleaseRevision')::bigint,
    (checked ->> 'correlationId')::uuid;
end
$function$;

comment on function vortex_definition.private_form_draft_context_internal() is
  'Resolves the validated human request scope and active Application installation for private form drafts.';

alter function vortex_definition.private_form_draft_context_internal()
  owner to vortex_owner;

create or replace function vortex_definition.provision_module_contribution_storage(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_module_root_id uuid,
  p_module_release_revision bigint,
  p_expected_binding_revision bigint,
  p_contribution_mode text,
  p_contributions jsonb
)
returns table (
  state text,
  changed boolean,
  binding_revision bigint,
  application_root_id uuid,
  application_release_revision bigint,
  module_root_id uuid,
  module_release_revision bigint,
  contribution_ids uuid[]
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  permission_decision record;
  delegation_decision record;
  checked_context jsonb;
  application_release vortex_definition.releases%rowtype;
  stored_binding vortex_definition.installation_bindings%rowtype;
  provision record;
  retire_contributions boolean;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision not between 1 and 9007199254740991
    or p_module_root_id is null
    or p_module_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_module_release_revision not between 1 and 9007199254740991
    or (p_expected_binding_revision is not null
      and p_expected_binding_revision not between 1 and 9007199254740991)
    or p_contribution_mode is null
    or p_contribution_mode not in ('attach', 'detach')
    or pg_catalog.jsonb_typeof(p_contributions) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_contributions) < 1
    or pg_catalog.jsonb_array_length(p_contributions) > 100 then
    raise exception using errcode = '22023',
      message = 'Module contribution storage command is invalid';
  end if;

  select evaluated.* into strict permission_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  ) as evaluated;
  if permission_decision.outcome is distinct from 'eligible' then
    raise exception using errcode = '42501', message = 'Module installation authority is unavailable';
  end if;

  select evaluated.* into strict delegation_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install_scope',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object(
        'kind', 'delegated_management',
        'before', pg_catalog.jsonb_build_object('kind', 'organization_catalogue'),
        'after', pg_catalog.jsonb_build_object('kind', 'organization_catalogue')
      )
    )
  ) as evaluated;
  if delegation_decision.outcome is distinct from 'eligible'
    or delegation_decision.organization_id <> permission_decision.organization_id
    or delegation_decision.organization_account_id <> permission_decision.organization_account_id
    or delegation_decision.access_version <> permission_decision.access_version
    or delegation_decision.correlation_id <> permission_decision.correlation_id then
    raise exception using errcode = '42501', message = 'Module installation delegation is unavailable';
  end if;

  checked_context := vortex_access.validated_human_request_context();
  if (checked_context ->> 'organizationId')::uuid <> permission_decision.organization_id
    or (checked_context ->> 'organizationAccountId')::uuid <>
      permission_decision.organization_account_id
    or (checked_context ->> 'accessVersion')::bigint <> permission_decision.access_version
    or (checked_context ->> 'correlationId')::uuid <> permission_decision.correlation_id then
    raise exception using errcode = '40001', message = 'Module installation context changed';
  end if;

  -- The binding identity is locked before its stored lineage can change, exactly
  -- as the installation storage provisioner does.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'vortex_definition.binding:' || permission_decision.organization_id::text || ':' ||
        p_application_root_id::text || ':' || p_module_root_id::text,
      0
    )
  );

  select release.* into strict application_release
  from vortex_definition.releases as release
  join vortex_definition.roots as root on root.root_id = release.root_id
  where release.root_id = p_application_root_id
    and release.release_revision = p_application_release_revision
    and root.kind = 'application'
    and root.organization_id = permission_decision.organization_id;
  if application_release.validation_contract_version
      <> all (vortex_definition.accepted_contract_version('application'))
    or application_release.compilation_output #>> '{kind}' <> 'application'
    or application_release.compilation_output #>> '{canonical,envelope,rootId}'
      <> p_application_root_id::text
    or application_release.compilation_output #>> '{validationContractVersion}'
      <> all (vortex_definition.accepted_contract_version('application')) then
    raise exception using errcode = '23514', message = 'Exact Application release is unavailable';
  end if;
  if not exists (
    select 1
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as edge
    where edge.target_root_id = p_module_root_id
      and edge.target_release_revision = p_module_release_revision
  ) then
    raise exception using errcode = '23514',
      message = 'Exact application Module binding is unavailable';
  end if;

  select binding.* into stored_binding
  from vortex_definition.installation_bindings as binding
  where binding.organization_id = permission_decision.organization_id
    and binding.application_root_id = p_application_root_id
    and binding.module_root_id = p_module_root_id
  for update;
  if not found
    or stored_binding.application_release_revision <> p_application_release_revision
    or stored_binding.module_release_revision <> p_module_release_revision
    or (p_expected_binding_revision is not null
      and stored_binding.binding_revision <> p_expected_binding_revision)
    or (p_contribution_mode = 'attach' and stored_binding.state = 'detached') then
    raise exception using errcode = '40001',
      message = 'Module installation binding changed';
  end if;

  -- Every target is the exact dependency release this Application release
  -- pins; an attach also needs the target's own storage installed here.
  if exists (
    with edges as (
      select edge.target_root_id, edge.target_release_revision
      from vortex_definition.reachable_module_dependency_edges(
        p_application_root_id, p_application_release_revision
      ) as edge
    )
    select 1
    from pg_catalog.jsonb_array_elements(p_contributions) as item(value)
    where not exists (
      select 1
      from edges
      join vortex_definition.releases as release
        on release.root_id = edges.target_root_id
        and release.release_revision = edges.target_release_revision
      where edges.target_root_id::text = pg_catalog.lower(item.value ->> 'targetModuleRootId')
        and edges.target_root_id <> p_module_root_id
        and release.release_version = item.value ->> 'targetModuleReleaseVersion'
        and (
          p_contribution_mode = 'detach'
          or exists (
            select 1
            from vortex_definition.installation_bindings as target_binding
            where target_binding.organization_id = permission_decision.organization_id
              and target_binding.application_root_id = p_application_root_id
              and target_binding.module_root_id = edges.target_root_id
              and target_binding.module_release_revision = edges.target_release_revision
              and target_binding.state <> 'detached'
          )
        )
    )
  ) then
    raise exception using errcode = '23514',
      message = 'Exact application target Module binding is unavailable';
  end if;

  -- Contributed field mappings live on shared target storage. One lock per
  -- contributor serialises attach and detach across organisations, so a
  -- detach sees every committed installation that still uses the mappings.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('vortex_definition.contribution:' || p_module_root_id::text, 0)
  );

  if p_contribution_mode = 'attach' then
    select storage.* into strict provision
    from vortex_record.provision_exact_module_contributions(
      p_module_root_id, p_module_release_revision, p_contributions
    ) as storage;
    return query select 'attached'::text, provision.changed,
      stored_binding.binding_revision, stored_binding.application_root_id,
      stored_binding.application_release_revision, stored_binding.module_root_id,
      stored_binding.module_release_revision, provision.contribution_ids;
    return;
  end if;

  -- Another live installation of the contributor keeps its mappings active;
  -- the last one retires them. Columns and values are retained either way.
  retire_contributions := not exists (
    select 1
    from vortex_definition.installation_bindings as other_binding
    where other_binding.module_root_id = p_module_root_id
      and other_binding.state <> 'detached'
      and (other_binding.organization_id, other_binding.application_root_id)
        <> (permission_decision.organization_id, p_application_root_id)
  );
  select storage.* into strict provision
  from vortex_record.detach_exact_module_contributions(
    p_module_root_id, p_module_release_revision, p_contributions, retire_contributions
  ) as storage;
  return query select 'detached'::text, provision.changed,
    stored_binding.binding_revision, stored_binding.application_root_id,
    stored_binding.application_release_revision, stored_binding.module_root_id,
    stored_binding.module_release_revision, provision.contribution_ids;
exception
  when no_data_found then
    raise exception using errcode = 'P0002', message = 'Module contribution evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000', message = 'Module contribution evidence is ambiguous';
end
$function$;

comment on function vortex_definition.provision_module_contribution_storage(
  uuid, bigint, uuid, bigint, bigint, text, jsonb
) is 'Protected exact-release contributor storage attach or detach; attaches the resolved additive bindings to their target storage, or retires them while retaining every column and value.';

create or replace function vortex_definition.provision_module_installation_storage(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_module_root_id uuid,
  p_module_release_revision bigint,
  p_expected_binding_revision bigint
)
returns table (
  state text,
  changed boolean,
  binding_revision bigint,
  application_root_id uuid,
  application_release_revision bigint,
  module_root_id uuid,
  module_release_revision bigint,
  storage_contract_ids uuid[]
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  permission_decision record;
  delegation_decision record;
  checked_context jsonb;
  application_release vortex_definition.releases%rowtype;
  stored_binding vortex_definition.installation_bindings%rowtype;
  provision record;
  next_binding_revision bigint;
  binding_exists boolean;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision not between 1 and 9007199254740991
    or p_module_root_id is null
    or p_module_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_module_release_revision not between 1 and 9007199254740991
    or (p_expected_binding_revision is not null
      and p_expected_binding_revision not between 1 and 9007199254740991) then
    raise exception using errcode = '22023', message = 'Module installation storage command is invalid';
  end if;

  select evaluated.* into strict permission_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  ) as evaluated;
  if permission_decision.outcome is distinct from 'eligible' then
    raise exception using errcode = '42501', message = 'Module installation authority is unavailable';
  end if;

  select evaluated.* into strict delegation_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install_scope',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object(
        'kind', 'delegated_management',
        'before', pg_catalog.jsonb_build_object('kind', 'organization_catalogue'),
        'after', pg_catalog.jsonb_build_object('kind', 'organization_catalogue')
      )
    )
  ) as evaluated;
  if delegation_decision.outcome is distinct from 'eligible'
    or delegation_decision.organization_id <> permission_decision.organization_id
    or delegation_decision.organization_account_id <> permission_decision.organization_account_id
    or delegation_decision.access_version <> permission_decision.access_version
    or delegation_decision.correlation_id <> permission_decision.correlation_id then
    raise exception using errcode = '42501', message = 'Module installation delegation is unavailable';
  end if;

  checked_context := vortex_access.validated_human_request_context();
  if (checked_context ->> 'organizationId')::uuid <> permission_decision.organization_id
    or (checked_context ->> 'organizationAccountId')::uuid <>
      permission_decision.organization_account_id
    or (checked_context ->> 'accessVersion')::bigint <> permission_decision.access_version
    or (checked_context ->> 'correlationId')::uuid <> permission_decision.correlation_id then
    raise exception using errcode = '40001', message = 'Module installation context changed';
  end if;

  -- The binding identity is locked before its row can exist. Storage lineage
  -- locks are acquired later by the Record helper in canonical UUID order.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'vortex_definition.binding:' || permission_decision.organization_id::text || ':' ||
        p_application_root_id::text || ':' || p_module_root_id::text,
      0
    )
  );

  select release.* into strict application_release
  from vortex_definition.releases as release
  join vortex_definition.roots as root on root.root_id = release.root_id
  where release.root_id = p_application_root_id
    and release.release_revision = p_application_release_revision
    and root.kind = 'application'
    and root.organization_id = permission_decision.organization_id;
  if application_release.validation_contract_version <> all (vortex_definition.accepted_contract_version('application'))
    or application_release.compilation_output #>> '{kind}' <> 'application'
    or application_release.compilation_output #>> '{canonical,envelope,rootId}'
      <> p_application_root_id::text
    or application_release.compilation_output #>> '{validationContractVersion}' <> all (vortex_definition.accepted_contract_version('application')) then
    raise exception using errcode = '23514', message = 'Exact Application release is unavailable';
  end if;
  if not exists (
    select 1
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as edge
    where edge.target_root_id = p_module_root_id
      and edge.target_release_revision = p_module_release_revision
  ) then
    raise exception using errcode = '23514', message = 'Exact application Module binding is unavailable';
  end if;

  select binding.* into stored_binding
  from vortex_definition.installation_bindings as binding
  where binding.organization_id = permission_decision.organization_id
    and binding.application_root_id = p_application_root_id
    and binding.module_root_id = p_module_root_id
  for update;
  binding_exists := found;

  if binding_exists then
    if stored_binding.state in ('active', 'draining')
      or (
        p_expected_binding_revision is null
        and (
          stored_binding.application_release_revision <> p_application_release_revision
          or stored_binding.module_release_revision <> p_module_release_revision
          or stored_binding.state <> 'provisioned'
        )
      )
      or (
        p_expected_binding_revision is not null
        and stored_binding.binding_revision <> p_expected_binding_revision
      ) then
      raise exception using errcode = '40001', message = 'Module installation binding changed';
    end if;
  end if;
  if not binding_exists and p_expected_binding_revision is not null then
    raise exception using errcode = '40001', message = 'Module installation binding is unavailable';
  end if;

  select storage.* into strict provision
  from vortex_record.provision_exact_module_storage(
    p_module_root_id, p_module_release_revision
  ) as storage;

  if binding_exists
    and stored_binding.application_release_revision = p_application_release_revision
    and stored_binding.module_release_revision = p_module_release_revision
    and stored_binding.state = 'provisioned' then
    if stored_binding.storage_contract_ids <> provision.storage_contract_ids then
      raise exception using errcode = '55000', message = 'Stored Module installation evidence is incompatible';
    end if;
    return query select stored_binding.state, false, stored_binding.binding_revision,
      stored_binding.application_root_id, stored_binding.application_release_revision,
      stored_binding.module_root_id, stored_binding.module_release_revision,
      stored_binding.storage_contract_ids;
    return;
  end if;

  if binding_exists then
    if stored_binding.binding_revision = 9007199254740991 then
      raise exception using errcode = '22003', message = 'Module installation binding revision is exhausted';
    end if;
    next_binding_revision := stored_binding.binding_revision + 1;
    update vortex_definition.installation_bindings as binding
    set binding_revision = next_binding_revision,
        application_release_revision = p_application_release_revision,
        module_release_revision = p_module_release_revision,
        state = 'provisioned',
        storage_contract_ids = provision.storage_contract_ids,
        changed_at = pg_catalog.statement_timestamp()
    where binding.organization_id = permission_decision.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = p_module_root_id
      and binding.binding_revision = p_expected_binding_revision;
    if not found then
      raise exception using errcode = '40001', message = 'Module installation binding changed';
    end if;
  else
    next_binding_revision := 1;
    insert into vortex_definition.installation_bindings (
      organization_id, application_root_id, module_root_id, binding_revision,
      application_release_revision, module_release_revision, state,
      storage_contract_ids
    ) values (
      permission_decision.organization_id, p_application_root_id, p_module_root_id, 1,
      p_application_release_revision, p_module_release_revision, 'provisioned',
      provision.storage_contract_ids
    );
  end if;

  return query select 'provisioned'::text, true, next_binding_revision,
    p_application_root_id, p_application_release_revision, p_module_root_id,
    p_module_release_revision, provision.storage_contract_ids;
exception
  when no_data_found then
    raise exception using errcode = 'P0002', message = 'Module installation evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000', message = 'Module installation evidence is ambiguous';
end
$function$;

comment on function vortex_definition.provision_module_installation_storage(
  uuid, bigint, uuid, bigint, bigint
) is 'Protected exact-release storage provisioning; commits only an inactive Module binding.';

create or replace function vortex_definition.read_active_installation_bundle_identity()
returns jsonb language plpgsql volatile security definer set search_path=''
as $function$
declare
  checked_context jsonb;
  selected_org uuid;
  selected_app uuid;
  selected_revision bigint;
  active_count integer;
  registered_app record;
  registered_identity jsonb;
  bindings jsonb;
  pin_facts jsonb;
  pin_hash text;
  identity_value jsonb;
  before_identity jsonb;
  stored_bundle vortex_definition.installation_runtime_bundles%rowtype;
  bundle_index jsonb;
  current_manifest jsonb;
  manifest_pins jsonb;
  mapping jsonb;
  stable_plan jsonb;
  active_source jsonb;
  source_manifest jsonb;
begin
  checked_context:=vortex_access.validated_human_request_context();
  if checked_context ->> 'callerKind' is distinct from 'human'
    or not checked_context ? 'applicationRootId'
    or pg_catalog.clock_timestamp()>=(checked_context ->> 'expiresAt')::timestamptz
    or (checked_context ? 'delegatedContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{delegatedContext,expiresAt}')::timestamptz)
    or (checked_context ? 'supportContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{supportContext,expiresAt}')::timestamptz) then
    raise exception using errcode='42501', message='Active Application context is unavailable';
  end if;
  selected_org:=(checked_context ->> 'organizationId')::uuid;
  selected_app:=(checked_context ->> 'applicationRootId')::uuid;
  select pg_catalog.min(binding.application_release_revision),pg_catalog.count(*)::integer
  into selected_revision,active_count from vortex_definition.installation_bindings as binding
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if active_count not between 1 and 10000 or selected_revision is null or exists(
    select 1 from vortex_definition.installation_bindings as binding
    where binding.organization_id=selected_org and binding.application_root_id=selected_app
      and binding.state<>'detached'
      and (binding.state<>'active' or binding.application_release_revision<>selected_revision)) then
    raise exception using errcode='P0002', message='Active Application installation is unavailable';
  end if;
  select snapshot.* into strict registered_app
  from vortex_access.read_application_permission_snapshot(selected_org,selected_app) as snapshot;
  if registered_app.release_revision is distinct from selected_revision then
    raise exception using errcode='40001', message='Active Application registration changed';
  end if;
  registered_identity:=pg_catalog.jsonb_build_object(
    'rootId',selected_app,'definitionKey',registered_app.definition_key,
    'releaseRevision',selected_revision,'releaseVersion',registered_app.release_version,
    'validationContractVersion',registered_app.validation_contract_version,
    'contentFingerprint',registered_app.content_fingerprint,
    'resolutionFingerprint',registered_app.resolution_fingerprint);
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'bindingRevision',binding.binding_revision,'state',binding.state) order by binding.module_root_id),
    pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'contentFingerprint',module_release.content_fingerprint,
      'resolutionFingerprint',module_release.resolution_fingerprint) order by binding.module_root_id)
  into bindings,pin_facts from vortex_definition.installation_bindings as binding
  join vortex_definition.releases as module_release
    on module_release.root_id=binding.module_root_id
    and module_release.release_revision=binding.module_release_revision
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if exists(select 1 from pg_catalog.jsonb_array_elements(pin_facts) as pin(value)
    where (pin.value ->> 'contentFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or (pin.value ->> 'resolutionFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or pin.value ->> 'contentFingerprint' is null
      or pin.value ->> 'resolutionFingerprint' is null) then
    raise exception using errcode='55000', message='Active Application pins are unavailable';
  end if;
  pin_hash:='sha256:' || pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(pin_facts::text,'UTF8')),'hex');
  identity_value:=pg_catalog.jsonb_build_object(
    'tenantId',checked_context -> 'tenantId','organizationId',selected_org,
    'organizationAccountId',checked_context -> 'organizationAccountId',
    'identityId',checked_context -> 'identityId','sessionId',checked_context -> 'sessionId',
    'accessVersion',checked_context -> 'accessVersion','correlationId',checked_context -> 'correlationId',
    'applicationRootId',selected_app,'applicationReleaseRevision',selected_revision,
    'registeredApplication',registered_identity,'moduleBindings',bindings,
    'pinFacts',pin_facts,'pinFingerprint',pin_hash);
  before_identity:=identity_value;
  select stored.* into stored_bundle from vortex_definition.installation_runtime_bundles as stored
  where stored.organization_id=selected_org and stored.application_root_id=selected_app
    and stored.application_release_revision=selected_revision and stored.bundle_format_version=2;
  if found then
    current_manifest:=stored_bundle.source_manifest;
    select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',module.value -> 'rootId','moduleReleaseRevision',module.value -> 'releaseRevision',
      'contentFingerprint',module.value -> 'contentFingerprint',
      'resolutionFingerprint',module.value -> 'resolutionFingerprint')
      order by (module.value ->> 'rootId')::uuid)
    into manifest_pins from pg_catalog.jsonb_array_elements(current_manifest -> 'modules') as module(value);
    if current_manifest ->> 'bundleFormatVersion' is distinct from '2'
      or current_manifest -> 'application' is distinct from registered_identity
      or current_manifest ->> 'pinFingerprint' is distinct from pin_hash
      or stored_bundle.pin_fingerprint is distinct from pin_hash
      or manifest_pins is distinct from pin_facts
      or pg_catalog.jsonb_typeof(current_manifest -> 'preparedRecordAccessPlan') is distinct from 'object'
      or current_manifest #>> '{preparedRecordAccessPlan,planKey}' is distinct from (
        'sha256:' || pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
          'vortex.installation-runtime-bundle.prepared-record-access-plan.v2|' ||
            selected_org::text || '|' || selected_app::text || '|' ||
            selected_revision::text || '|2|' || pin_hash,'UTF8')),'hex'))
      or current_manifest #>> '{preparedRecordAccessPlan,mappingFingerprint}' is null
      or (current_manifest #>> '{preparedRecordAccessPlan,planKey}') !~ '^sha256:[a-f0-9]{64}$'
      or (current_manifest #>> '{preparedRecordAccessPlan,mappingFingerprint}') !~ '^sha256:[a-f0-9]{64}$' then
      raise exception using errcode='23514', message='Active runtime bundle manifest differs';
    end if;
    bundle_index:=vortex_definition.read_installation_runtime_bundle_index(selected_app,selected_revision,2);
  else
    -- Missing format2 takes a genuine locked active-only cold source path.
    -- The mapping locker derives identity inline and cannot recurse into this reader.
    mapping:=vortex_definition.lock_active_installation_runtime_mapping_internal(before_identity);
    stable_plan:=vortex_record.resolve_active_bundle_record_access_plan_internal(before_identity);
    active_source:=pg_catalog.jsonb_build_object(
      'organizationId',mapping #> '{identity,organizationId}',
      'applicationRootId',mapping #> '{identity,applicationRootId}',
      'applicationReleaseRevision',mapping #> '{identity,applicationReleaseRevision}',
      'accessVersion',mapping #> '{identity,accessVersion}',
      'correlationId',mapping #> '{identity,correlationId}',
      'pinFingerprint',mapping #> '{identity,pinFingerprint}',
      'mappingFingerprint',stable_plan -> 'mappingFingerprint',
      'moduleBindings',mapping #> '{identity,moduleBindings}',
      'application',mapping -> 'application','modules',mapping -> 'modules',
      'preparedRecordAccessPlan',stable_plan);
  source_manifest := pg_catalog.jsonb_build_object(
    'bundleFormatVersion', 2,
    'application', pg_catalog.jsonb_build_object(
      'rootId', active_source #> '{application,rootId}',
      'definitionKey', active_source #> '{application,key}',
      'releaseRevision', active_source #> '{application,releaseRevision}',
      'releaseVersion', active_source #> '{application,releaseVersion}',
      'validationContractVersion', active_source #> '{application,validationContractVersion}',
      'contentFingerprint', active_source #> '{application,contentFingerprint}',
      'resolutionFingerprint', active_source #> '{application,resolutionFingerprint}'
    ),
    'modules', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'rootId', module.value -> 'rootId',
          'definitionKey', module.value -> 'key',
          'releaseRevision', module.value -> 'releaseRevision',
          'releaseVersion', module.value -> 'releaseVersion',
          'validationContractVersion', module.value -> 'validationContractVersion',
          'contentFingerprint', module.value -> 'contentFingerprint',
          'resolutionFingerprint', module.value -> 'resolutionFingerprint'
        ) order by (module.value ->> 'rootId') collate "C")
      from pg_catalog.jsonb_array_elements(active_source -> 'modules') as module(value)
    ), '[]'::jsonb),
    'pinFingerprint', active_source -> 'pinFingerprint',
    'preparedRecordAccessPlan', pg_catalog.jsonb_build_object(
      'planKey', active_source #> '{preparedRecordAccessPlan,planKey}',
      'mappingFingerprint', active_source #> '{preparedRecordAccessPlan,mappingFingerprint}'
    )
  );

    active_source:=active_source || pg_catalog.jsonb_build_object('sourceManifest',source_manifest);
  end if;
  checked_context:=vortex_access.validated_human_request_context();
  if checked_context ->> 'callerKind' is distinct from 'human'
    or not checked_context ? 'applicationRootId'
    or pg_catalog.clock_timestamp()>=(checked_context ->> 'expiresAt')::timestamptz
    or (checked_context ? 'delegatedContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{delegatedContext,expiresAt}')::timestamptz)
    or (checked_context ? 'supportContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{supportContext,expiresAt}')::timestamptz) then
    raise exception using errcode='42501', message='Active Application context is unavailable';
  end if;
  selected_org:=(checked_context ->> 'organizationId')::uuid;
  selected_app:=(checked_context ->> 'applicationRootId')::uuid;
  select pg_catalog.min(binding.application_release_revision),pg_catalog.count(*)::integer
  into selected_revision,active_count from vortex_definition.installation_bindings as binding
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if active_count not between 1 and 10000 or selected_revision is null or exists(
    select 1 from vortex_definition.installation_bindings as binding
    where binding.organization_id=selected_org and binding.application_root_id=selected_app
      and binding.state<>'detached'
      and (binding.state<>'active' or binding.application_release_revision<>selected_revision)) then
    raise exception using errcode='P0002', message='Active Application installation is unavailable';
  end if;
  select snapshot.* into strict registered_app
  from vortex_access.read_application_permission_snapshot(selected_org,selected_app) as snapshot;
  if registered_app.release_revision is distinct from selected_revision then
    raise exception using errcode='40001', message='Active Application registration changed';
  end if;
  registered_identity:=pg_catalog.jsonb_build_object(
    'rootId',selected_app,'definitionKey',registered_app.definition_key,
    'releaseRevision',selected_revision,'releaseVersion',registered_app.release_version,
    'validationContractVersion',registered_app.validation_contract_version,
    'contentFingerprint',registered_app.content_fingerprint,
    'resolutionFingerprint',registered_app.resolution_fingerprint);
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'bindingRevision',binding.binding_revision,'state',binding.state) order by binding.module_root_id),
    pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId',binding.module_root_id,'moduleReleaseRevision',binding.module_release_revision,
      'contentFingerprint',module_release.content_fingerprint,
      'resolutionFingerprint',module_release.resolution_fingerprint) order by binding.module_root_id)
  into bindings,pin_facts from vortex_definition.installation_bindings as binding
  join vortex_definition.releases as module_release
    on module_release.root_id=binding.module_root_id
    and module_release.release_revision=binding.module_release_revision
  where binding.organization_id=selected_org and binding.application_root_id=selected_app
    and binding.state='active';
  if exists(select 1 from pg_catalog.jsonb_array_elements(pin_facts) as pin(value)
    where (pin.value ->> 'contentFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or (pin.value ->> 'resolutionFingerprint') !~ '^sha256:[a-f0-9]{64}$'
      or pin.value ->> 'contentFingerprint' is null
      or pin.value ->> 'resolutionFingerprint' is null) then
    raise exception using errcode='55000', message='Active Application pins are unavailable';
  end if;
  pin_hash:='sha256:' || pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(pin_facts::text,'UTF8')),'hex');
  identity_value:=pg_catalog.jsonb_build_object(
    'tenantId',checked_context -> 'tenantId','organizationId',selected_org,
    'organizationAccountId',checked_context -> 'organizationAccountId',
    'identityId',checked_context -> 'identityId','sessionId',checked_context -> 'sessionId',
    'accessVersion',checked_context -> 'accessVersion','correlationId',checked_context -> 'correlationId',
    'applicationRootId',selected_app,'applicationReleaseRevision',selected_revision,
    'registeredApplication',registered_identity,'moduleBindings',bindings,
    'pinFacts',pin_facts,'pinFingerprint',pin_hash);
  if identity_value is distinct from before_identity then
    raise exception using errcode='40001', message='Active runtime bundle identity changed';
  end if;
  return pg_catalog.jsonb_build_object('identity',identity_value,
    'bundleIndex',bundle_index,'repairNeeded',bundle_index is null,'coldSource',active_source);
exception when no_data_found or too_many_rows then
  raise exception using errcode='P0002', message='Active runtime bundle identity is unavailable';
end
$function$;

comment on function vortex_definition.read_active_installation_bundle_identity() is 'Returns fresh active format2 identity and index, or a private exact locked active cold source for the same HUMAN request; carries no viewer permission decision.';

create or replace function vortex_definition.read_active_installation_for_scope_internal(
  p_organization_id uuid,
  p_application_root_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  selected_organization_id uuid;
  selected_application_root_id uuid;
  selected_application_release_revision bigint;
  selected_bindings jsonb;
begin
  if p_organization_id is null or p_application_root_id is null then
    raise exception using errcode = '22023', message = 'Active Application context is required';
  end if;
  selected_organization_id := p_organization_id;
  selected_application_root_id := p_application_root_id;

  select pg_catalog.min(binding.application_release_revision)
  into selected_application_release_revision
  from vortex_definition.installation_bindings as binding
  where binding.organization_id = selected_organization_id
    and binding.application_root_id = selected_application_root_id
    and binding.state = 'active';
  if selected_application_release_revision is null then
    raise exception using errcode = 'P0002', message = 'Active Application installation is unavailable';
  end if;
  if exists (
    select 1 from vortex_definition.installation_bindings as binding
    where binding.organization_id = selected_organization_id
      and binding.application_root_id = selected_application_root_id
      and binding.state = 'active'
      and binding.application_release_revision <> selected_application_release_revision
  ) then
    raise exception using errcode = '55000', message = 'Active Application installation is mixed';
  end if;

  if not exists (
    select 1
    from vortex_definition.roots as root
    join vortex_definition.releases as release
      on release.root_id = root.root_id
      and release.release_revision = selected_application_release_revision
    where root.root_id = selected_application_root_id
      and root.kind = 'application'
      and root.organization_id = selected_organization_id
      and release.compilation_output #>> '{kind}' = 'application'
  ) then
    raise exception using errcode = '23514', message = 'Active Application release evidence is invalid';
  end if;

  if not exists (
    select 1
    from vortex_definition.reachable_module_dependency_edges(
      selected_application_root_id, selected_application_release_revision
    )
  ) or exists (
    select 1
    from vortex_definition.reachable_module_dependency_edges(
      selected_application_root_id, selected_application_release_revision
    ) as node
    left join vortex_definition.installation_bindings as binding
      on binding.organization_id = selected_organization_id
      and binding.application_root_id = selected_application_root_id
      and binding.module_root_id = node.target_root_id
    where binding.state is distinct from 'active'
      or binding.application_release_revision is distinct from selected_application_release_revision
      or binding.module_release_revision is distinct from node.target_release_revision
  ) or exists (
    select 1
    from vortex_definition.installation_bindings as binding
    where binding.organization_id = selected_organization_id
      and binding.application_root_id = selected_application_root_id
      and binding.state = 'active'
      and not exists (
        select 1
        from vortex_definition.reachable_module_dependency_edges(
          selected_application_root_id, selected_application_release_revision
        ) as node
        where node.target_root_id = binding.module_root_id
          and node.target_release_revision = binding.module_release_revision
      )
  ) then
    raise exception using errcode = '55000', message = 'Active Application Module bindings are incomplete';
  end if;

  select pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'organizationId', binding.organization_id,
      'applicationRootId', binding.application_root_id,
      'moduleRootId', binding.module_root_id,
      'bindingRevision', binding.binding_revision,
      'applicationReleaseRevision', binding.application_release_revision,
      'moduleReleaseRevision', binding.module_release_revision,
      'state', binding.state
    ) order by binding.module_root_id
  ) into selected_bindings
  from vortex_definition.installation_bindings as binding
  where binding.organization_id = selected_organization_id
    and binding.application_root_id = selected_application_root_id
    and binding.application_release_revision = selected_application_release_revision
    and binding.state = 'active';

  return pg_catalog.jsonb_build_object(
    'organizationId', selected_organization_id,
    'applicationRootId', selected_application_root_id,
    'applicationReleaseRevision', selected_application_release_revision,
    'moduleBindings', selected_bindings
  );
end
$function$;

comment on function vortex_definition.read_active_installation_for_scope_internal(uuid, uuid) is
  'Resolves the complete exact active Module binding set for one already-validated organisation/Application scope.';

create or replace function vortex_definition.read_active_shared_record_consumers_internal(
  p_module_root_id uuid,
  p_record_type_id uuid,
  p_storage_contract_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  selected_organization_id uuid;
  selected_application_root_id uuid;
  selected_access_version bigint;
  candidate_application_root_id uuid;
  application_installation jsonb;
  application_root vortex_definition.roots%rowtype;
  application_release vortex_definition.releases%rowtype;
  permission_snapshot record;
  module_binding_fact jsonb;
  module_binding vortex_definition.installation_bindings%rowtype;
  module_root vortex_definition.roots%rowtype;
  module_release vortex_definition.releases%rowtype;
  storage_provision record;
  module_bindings jsonb;
  targets jsonb := '[]'::jsonb;
  target jsonb;
  target_record_types jsonb;
  target_record_type_count integer;
  own_module_binding_count integer;
  binding_count integer;
begin
  if p_module_root_id is null
    or p_module_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_record_type_id is null
    or p_record_type_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Shared record consumer selection is invalid';
  end if;

  context_value := vortex_access.validated_human_request_context();
  if pg_catalog.jsonb_typeof(context_value) is distinct from 'object'
    or not (context_value ?& array[
      'callerKind', 'tenantId', 'organizationId', 'organizationAccountId',
      'applicationRootId', 'accessVersion', 'correlationId'
    ])
    or context_value ->> 'callerKind' is distinct from 'human'
    or not vortex_platform.is_non_nil_uuid(context_value ->> 'tenantId')
    or not vortex_platform.is_non_nil_uuid(context_value ->> 'organizationId')
    or not vortex_platform.is_non_nil_uuid(context_value ->> 'organizationAccountId')
    or not vortex_platform.is_non_nil_uuid(context_value ->> 'applicationRootId')
    or not vortex_platform.is_non_nil_uuid(context_value ->> 'correlationId')
    or not pg_catalog.pg_input_is_valid(context_value ->> 'accessVersion', 'bigint')
    or (context_value ->> 'accessVersion')::bigint not between 1 and 9007199254740991 then
    raise exception using errcode = '42501',
      message = 'Shared record consumer request context is unavailable';
  end if;
  selected_organization_id := (context_value ->> 'organizationId')::uuid;
  selected_application_root_id := (context_value ->> 'applicationRootId')::uuid;
  selected_access_version := (context_value ->> 'accessVersion')::bigint;

  <<application_loop>>
  for candidate_application_root_id in
    select distinct binding.application_root_id
    from vortex_definition.installation_bindings as binding
    where binding.organization_id = selected_organization_id
      and binding.module_root_id = p_module_root_id
      and binding.state = 'active'
    order by binding.application_root_id
  loop
    select snapshot.* into permission_snapshot
    from vortex_access.read_application_permission_snapshot(
      selected_organization_id, candidate_application_root_id
    ) as snapshot;
    if not found then
      continue application_loop;
    end if;

    select root.* into application_root
    from vortex_definition.roots as root
    where root.root_id = candidate_application_root_id;
    if not found
      or application_root.kind is distinct from 'application'
      or application_root.organization_id is distinct from selected_organization_id
      or application_root.key is null or application_root.key = '' then
      continue application_loop;
    end if;

    if not pg_catalog.pg_input_is_valid(permission_snapshot.release_revision::text, 'bigint')
      or permission_snapshot.release_revision not between 1 and 9007199254740991 then
      continue application_loop;
    end if;
    select release.* into application_release
    from vortex_definition.releases as release
    where release.root_id = candidate_application_root_id
      and release.release_revision = permission_snapshot.release_revision;
    if not found
      or application_release.validation_contract_version is null
      or not (application_release.validation_contract_version = any (
        vortex_definition.accepted_contract_version('application')
      ))
      or application_release.release_version is null
      or application_release.release_version = ''
      or application_release.content_fingerprint is null
      or application_release.content_fingerprint !~ '^sha256:[a-f0-9]{64}$'
      or application_release.resolution_fingerprint is null
      or application_release.resolution_fingerprint !~ '^sha256:[a-f0-9]{64}$'
      or pg_catalog.jsonb_typeof(application_release.compilation_output) is distinct from 'object'
      or application_release.compilation_output ->> 'kind' is distinct from 'application'
      or application_release.compilation_output ->> 'validationContractVersion'
        is distinct from application_release.validation_contract_version
      or application_release.compilation_output #>> '{canonical,envelope,rootId}'
        is distinct from candidate_application_root_id::text
      or application_release.compilation_output #>> '{canonical,envelope,kind}'
        is distinct from 'application'
      or application_release.compilation_output #>> '{canonical,envelope,validationContractVersion}'
        is distinct from application_release.validation_contract_version then
      continue application_loop;
    end if;

    if permission_snapshot.organization_id is distinct from selected_organization_id
      or permission_snapshot.application_root_id is distinct from candidate_application_root_id
      or permission_snapshot.registration_revision is null
      or permission_snapshot.registration_revision not between 1 and 9007199254740991
      or permission_snapshot.release_revision is distinct from application_release.release_revision
      or permission_snapshot.definition_key is distinct from application_root.key
      or permission_snapshot.release_version is distinct from application_release.release_version
      or permission_snapshot.validation_contract_version
        is distinct from application_release.validation_contract_version
      or permission_snapshot.content_fingerprint is distinct from application_release.content_fingerprint
      or permission_snapshot.resolution_fingerprint is distinct from application_release.resolution_fingerprint
      or permission_snapshot.catalogue_fingerprint is null
      or permission_snapshot.catalogue_fingerprint !~ '^sha256:[a-f0-9]{64}$' then
      continue application_loop;
    end if;

    begin
      application_installation := vortex_definition.read_active_installation_for_scope_internal(
        selected_organization_id, candidate_application_root_id
      );
    exception
      when sqlstate 'P0002' or sqlstate '55000' or sqlstate '23514' then
        continue application_loop;
    end;

    if pg_catalog.jsonb_typeof(application_installation) is distinct from 'object'
      or not (application_installation ?& array[
        'organizationId', 'applicationRootId', 'applicationReleaseRevision', 'moduleBindings'
      ])
      or (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(application_installation)) <> 4
      or application_installation ->> 'organizationId' is distinct from selected_organization_id::text
      or application_installation ->> 'applicationRootId' is distinct from candidate_application_root_id::text
      or application_installation ->> 'applicationReleaseRevision'
        is distinct from application_release.release_revision::text
      or pg_catalog.jsonb_typeof(application_installation -> 'moduleBindings') is distinct from 'array'
      or pg_catalog.jsonb_array_length(application_installation -> 'moduleBindings') = 0 then
      raise exception using errcode = '55000',
        message = 'Active shared record consumer evidence is malformed';
    end if;

    select pg_catalog.count(*)::integer into binding_count
    from pg_catalog.jsonb_array_elements(application_installation -> 'moduleBindings') as item(value);
    module_bindings := '[]'::jsonb;
    own_module_binding_count := 0;

    for module_binding_fact in
      select item.value
      from pg_catalog.jsonb_array_elements(application_installation -> 'moduleBindings') as item(value)
      order by (item.value ->> 'moduleRootId')::uuid
    loop
      if pg_catalog.jsonb_typeof(module_binding_fact) is distinct from 'object'
        or not (module_binding_fact ?& array[
          'organizationId', 'applicationRootId', 'moduleRootId', 'bindingRevision',
          'applicationReleaseRevision', 'moduleReleaseRevision', 'state'
        ])
        or (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(module_binding_fact)) <> 7
        or not vortex_platform.is_non_nil_uuid(module_binding_fact ->> 'moduleRootId')
        or not pg_catalog.pg_input_is_valid(module_binding_fact ->> 'bindingRevision', 'bigint')
        or (module_binding_fact ->> 'bindingRevision')::bigint not between 1 and 9007199254740991
        or not pg_catalog.pg_input_is_valid(module_binding_fact ->> 'moduleReleaseRevision', 'bigint')
        or (module_binding_fact ->> 'moduleReleaseRevision')::bigint not between 1 and 9007199254740991
        or module_binding_fact ->> 'organizationId' is distinct from selected_organization_id::text
        or module_binding_fact ->> 'applicationRootId' is distinct from candidate_application_root_id::text
        or module_binding_fact ->> 'applicationReleaseRevision'
          is distinct from application_release.release_revision::text
        or module_binding_fact ->> 'state' is distinct from 'active' then
        raise exception using errcode = '55000',
          message = 'Active shared record consumer binding evidence is malformed';
      end if;

      select binding.* into module_binding
      from vortex_definition.installation_bindings as binding
      where binding.organization_id = selected_organization_id
        and binding.application_root_id = candidate_application_root_id
        and binding.module_root_id = (module_binding_fact ->> 'moduleRootId')::uuid;
      if not found
        or module_binding.state is distinct from 'active'
        or module_binding.binding_revision is distinct from (module_binding_fact ->> 'bindingRevision')::bigint
        or module_binding.application_release_revision is distinct from application_release.release_revision
        or module_binding.module_release_revision is distinct from (module_binding_fact ->> 'moduleReleaseRevision')::bigint then
        raise exception using errcode = '40001',
          message = 'Active shared record consumer binding changed during selection';
      end if;

      select root.* into module_root
      from vortex_definition.roots as root
      where root.root_id = module_binding.module_root_id;
      if not found or module_root.kind is distinct from 'module'
        or module_root.key is null or module_root.key = '' then
        continue application_loop;
      end if;
      select release.* into module_release
      from vortex_definition.releases as release
      where release.root_id = module_binding.module_root_id
        and release.release_revision = module_binding.module_release_revision;
      if not found
        or module_release.validation_contract_version is null
        or not (module_release.validation_contract_version = any (
          vortex_definition.accepted_contract_version('module')
        ))
        or module_release.release_version is null
        or module_release.release_version = ''
        or module_release.content_fingerprint is null
        or module_release.content_fingerprint !~ '^sha256:[a-f0-9]{64}$'
        or module_release.resolution_fingerprint is null
        or module_release.resolution_fingerprint !~ '^sha256:[a-f0-9]{64}$'
        or pg_catalog.jsonb_typeof(module_release.compilation_output) is distinct from 'object'
        or module_release.compilation_output ->> 'kind' is distinct from 'module'
        or module_release.compilation_output ->> 'validationContractVersion'
          is distinct from module_release.validation_contract_version
        or module_release.compilation_output #>> '{canonical,envelope,rootId}'
          is distinct from module_binding.module_root_id::text
        or module_release.compilation_output #>> '{canonical,envelope,kind}'
          is distinct from 'module'
        or module_release.compilation_output #>> '{canonical,envelope,validationContractVersion}'
          is distinct from module_release.validation_contract_version then
        continue application_loop;
      end if;

      begin
        select provision.* into strict storage_provision
        from vortex_record.read_exact_module_storage_provision(
          module_binding.module_root_id, module_binding.module_release_revision
        ) as provision;
      exception
        when no_data_found then
          continue application_loop;
      end;
      if storage_provision.module_root_id is distinct from module_binding.module_root_id
        or storage_provision.release_revision is distinct from module_binding.module_release_revision
        or storage_provision.storage_contract_ids is null
        or pg_catalog.cardinality(storage_provision.storage_contract_ids) = 0
        or module_binding.storage_contract_ids is distinct from storage_provision.storage_contract_ids
        or exists (
          select 1
          from pg_catalog.unnest(storage_provision.storage_contract_ids) as stored(contract_id)
          where stored.contract_id is null
            or stored.contract_id = '00000000-0000-0000-0000-000000000000'::uuid
        )
        or exists (
          select 1
          from pg_catalog.unnest(storage_provision.storage_contract_ids) as stored(contract_id)
          group by stored.contract_id having pg_catalog.count(*) <> 1
        )
        or storage_provision.storage_contract_ids is distinct from (
          select pg_catalog.array_agg(stored.contract_id order by stored.contract_id)
          from pg_catalog.unnest(storage_provision.storage_contract_ids) as stored(contract_id)
        ) then
        continue application_loop;
      end if;

      if module_binding.module_root_id = p_module_root_id then
        own_module_binding_count := own_module_binding_count + 1;
        target_record_types := module_release.compilation_output #> '{canonical,content,recordTypes}';
        if pg_catalog.jsonb_typeof(target_record_types) is distinct from 'array' then
          raise exception using errcode = '55000',
            message = 'Shared record type release evidence is malformed';
        end if;
        select pg_catalog.count(*)::integer into target_record_type_count
        from pg_catalog.jsonb_array_elements(target_record_types) as item(value)
        where item.value ->> 'recordTypeId' = p_record_type_id::text;
        if target_record_type_count <> 1 or not exists (
          select 1
          from pg_catalog.jsonb_array_elements(target_record_types) as item(value)
          where item.value ->> 'recordTypeId' = p_record_type_id::text
            and item.value ->> 'storageContractId' = p_storage_contract_id::text
            and item.value ->> 'storageScope' = 'organization_shared'
        ) then
          continue application_loop;
        end if;
        if not (p_storage_contract_id = any (storage_provision.storage_contract_ids)) then
          continue application_loop;
        end if;
      end if;

      module_bindings := module_bindings || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'moduleRootId', module_binding.module_root_id,
          'bindingRevision', module_binding.binding_revision,
          'applicationReleaseRevision', module_binding.application_release_revision,
          'moduleReleaseRevision', module_binding.module_release_revision,
          'state', module_binding.state,
          'contentFingerprint', module_release.content_fingerprint,
          'resolutionFingerprint', module_release.resolution_fingerprint,
          'generatorContractVersion', '1.0.0',
          'storageContractIds', pg_catalog.to_jsonb(storage_provision.storage_contract_ids)
        )
      );
    end loop;

    if own_module_binding_count <> 1
      or pg_catalog.jsonb_array_length(module_bindings) <> binding_count then
      continue application_loop;
    end if;

    target := pg_catalog.jsonb_build_object(
      'applicationRootId', candidate_application_root_id,
      'applicationReleaseRevision', application_release.release_revision,
      'moduleRootId', p_module_root_id,
      'moduleReleaseRevision', (
        select binding.module_release_revision
        from vortex_definition.installation_bindings as binding
        where binding.organization_id = selected_organization_id
          and binding.application_root_id = candidate_application_root_id
          and binding.module_root_id = p_module_root_id
          and binding.state = 'active'
      ),
      'bindingRevision', (
        select binding.binding_revision
        from vortex_definition.installation_bindings as binding
        where binding.organization_id = selected_organization_id
          and binding.application_root_id = candidate_application_root_id
          and binding.module_root_id = p_module_root_id
          and binding.state = 'active'
      ),
      'recordTypeId', p_record_type_id,
      'storageContractId', p_storage_contract_id,
      'registrationRevision', permission_snapshot.registration_revision,
      'definitionKey', application_root.key,
      'releaseVersion', application_release.release_version,
      'validationContractVersion', application_release.validation_contract_version,
      'contentFingerprint', application_release.content_fingerprint,
      'resolutionFingerprint', application_release.resolution_fingerprint,
      'catalogueFingerprint', permission_snapshot.catalogue_fingerprint,
      'moduleBindings', module_bindings
    );
    targets := targets || pg_catalog.jsonb_build_array(target);
  end loop;

  if pg_catalog.jsonb_array_length(targets) = 0 then
    raise exception using errcode = '42501',
      message = 'No active shared record consumer is available';
  end if;
  if not exists (
    select 1
    from pg_catalog.jsonb_array_elements(targets) as item(value)
    where item.value ->> 'applicationRootId' = selected_application_root_id::text
  ) then
    raise exception using errcode = '42501',
      message = 'Origin Application is not a proved shared record consumer';
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', selected_organization_id,
    'accessVersion', selected_access_version,
    'targets', targets
  );
end
$function$;

comment on function vortex_definition.read_active_shared_record_consumers_internal(uuid, uuid, uuid) is
  'Selects every exact active App consumer of one organization-shared record from the complete installed Module lineage and active exact release registration.';

CREATE OR REPLACE FUNCTION vortex_definition.read_application_installation_bindings(p_application_root_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  authority record;
  binding_evidence jsonb;
  registered_release_revision bigint;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Application installation read command is invalid';
  end if;

  select locked.* into strict authority
  from vortex_access.lock_application_installation_authority() as locked;

  if not exists (
    select 1
    from vortex_definition.roots as root
    where root.root_id = p_application_root_id
      and root.organization_id = authority.organization_id
      and root.kind = 'application'
  ) then
    raise exception using errcode = 'P0002',
      message = 'Application installation is unavailable';
  end if;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'organizationId', binding.organization_id,
      'applicationRootId', binding.application_root_id,
      'moduleRootId', binding.module_root_id,
      'bindingRevision', binding.binding_revision,
      'applicationReleaseRevision', binding.application_release_revision,
      'moduleReleaseRevision', binding.module_release_revision,
      'state', binding.state
    ) order by binding.module_root_id), '[]'::jsonb)
  into binding_evidence
  from vortex_definition.installation_bindings as binding
  where binding.organization_id = authority.organization_id
    and binding.application_root_id = p_application_root_id;

  -- The exact release the active permission registration was prepared from,
  -- or null when it is absent or withdrawn. The fixed activation requires it
  -- to name the release being activated.
  select snapshot.release_revision into registered_release_revision
  from vortex_access.read_application_permission_snapshot(
    authority.organization_id, p_application_root_id
  ) as snapshot;

  return pg_catalog.jsonb_build_object(
    'organizationId', authority.organization_id,
    'applicationRootId', p_application_root_id,
    'registeredReleaseRevision', registered_release_revision,
    'moduleBindings', binding_evidence
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Application installation evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Application installation evidence is ambiguous';
end
$$;

COMMENT ON FUNCTION vortex_definition.read_application_installation_bindings(p_application_root_id uuid) IS 'Installer-only read of one Application''s current Module binding revisions and registered release under application-management authority.';

REVOKE ALL ON FUNCTION vortex_definition.read_application_installation_bindings(p_application_root_id uuid) FROM PUBLIC;
GRANT ALL ON FUNCTION vortex_definition.read_application_installation_bindings(p_application_root_id uuid) TO vortex_request;

create or replace function vortex_definition.read_application_release_adoption_target(
  p_application_root_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked_context jsonb;
  permission_decision record;
  target_value jsonb;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Application release adoption target command is invalid';
  end if;

  checked_context := vortex_access.validated_human_request_context();
  if not checked_context ? 'applicationRootId'
    or (checked_context ->> 'applicationRootId')::uuid is distinct from p_application_root_id then
    raise exception using errcode = '42501',
      message = 'Application release adoption target context is unavailable';
  end if;

  -- The offered target is only revealed to a caller who may manage this
  -- organisation's application installations. The decision is made by the same
  -- Access evaluator every other platform-permission check uses.
  select evaluated.* into strict permission_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.manage',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  ) as evaluated;
  if permission_decision.outcome is distinct from 'eligible'
    or (checked_context ->> 'organizationId')::uuid <> permission_decision.organization_id
    or (checked_context ->> 'organizationAccountId')::uuid <>
      permission_decision.organization_account_id
    or (checked_context ->> 'accessVersion')::bigint <> permission_decision.access_version
    or (checked_context ->> 'correlationId')::uuid <> permission_decision.correlation_id then
    raise exception using errcode = '42501',
      message = 'Application release adoption target authority is unavailable';
  end if;

  -- Only an application this organisation has installed offers an adoption
  -- target. Module owns installation facts: its fixed Module-owned reader
  -- refuses an organisation/application scope with no complete active
  -- installation, so this function never reads Module storage directly.
  perform vortex_definition.read_active_installation_for_scope_internal(
    permission_decision.organization_id,
    p_application_root_id
  );

  -- Publication advances the root pointer but never touches the installation,
  -- so the offered target is the discovery pointer, not the active release.
  select pg_catalog.jsonb_build_object(
    'organizationId', root.organization_id,
    'applicationRootId', root.root_id,
    'currentReleaseRevision', root.current_release_revision,
    'currentReleaseVersion', release.release_version
  )
  into target_value
  from vortex_definition.roots as root
  left join vortex_definition.releases as release
    on release.root_id = root.root_id
    and release.release_revision = root.current_release_revision
  where root.root_id = p_application_root_id
    and root.kind = 'application'
    and root.organization_id = permission_decision.organization_id;

  if target_value is null then
    raise exception using errcode = 'P0002',
      message = 'Application release adoption target is unavailable';
  end if;

  return target_value;
end
$function$;

comment on function vortex_definition.read_application_release_adoption_target(uuid) is
  'Returns the published-current release identity an organisation with an installed application may deliberately adopt, for a caller holding platform.organization.applications.manage.';
alter function vortex_definition.read_application_release_adoption_target(uuid) owner to vortex_owner;

CREATE OR REPLACE FUNCTION vortex_definition.read_current_active_installation() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  checked_context jsonb;
begin
  checked_context := vortex_access.validated_human_request_context();
  if not checked_context ? 'applicationRootId' then
    raise exception using errcode = '22023', message = 'Active Application context is required';
  end if;
  return vortex_definition.read_active_installation_for_scope_internal(
    (checked_context ->> 'organizationId')::uuid,
    (checked_context ->> 'applicationRootId')::uuid
  );
end
$$;

COMMENT ON FUNCTION vortex_definition.read_current_active_installation() IS 'Returns the complete exact active Module binding set selected from validated human Application context.';

REVOKE ALL ON FUNCTION vortex_definition.read_current_active_installation() FROM PUBLIC;
GRANT ALL ON FUNCTION vortex_definition.read_current_active_installation() TO vortex_request;
GRANT ALL ON FUNCTION vortex_definition.read_current_active_installation() TO vortex_record_adapter;
GRANT ALL ON FUNCTION vortex_definition.read_current_active_installation() TO postgres;
GRANT ALL ON FUNCTION vortex_definition.read_current_active_installation() TO vortex_owner;

create or replace function vortex_definition.read_current_detached_installation_for_transfer_internal()
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked_context jsonb;
  selected_organization_id uuid;
  selected_application_root_id uuid;
  selected_application_release_revision bigint;
  selected_bindings jsonb;
  binding_row vortex_definition.installation_bindings%rowtype;
begin
  checked_context := vortex_access.validated_human_request_context();
  if not checked_context ? 'applicationRootId' then
    raise exception using errcode = '22023', message = 'Detached Application context is required';
  end if;
  selected_organization_id := (checked_context ->> 'organizationId')::uuid;
  selected_application_root_id := (checked_context ->> 'applicationRootId')::uuid;

  -- The retained/disabled entry must observe one stable binding set.  Use the
  -- same lifecycle key as installation transitions, then hold every matching
  -- binding through the transfer transaction.
  for binding_row in
    select binding.*
    from vortex_definition.installation_bindings as binding
    where binding.organization_id = selected_organization_id
      and binding.application_root_id = selected_application_root_id
    order by binding.module_root_id
  loop
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      'vortex_definition.binding:' || binding_row.organization_id::text || ':' ||
        binding_row.application_root_id::text || ':' || binding_row.module_root_id::text,
      0
    ));
  end loop;
  perform 1
  from vortex_definition.installation_bindings as binding
  where binding.organization_id = selected_organization_id
    and binding.application_root_id = selected_application_root_id
  for share;

  select pg_catalog.min(binding.application_release_revision)
  into selected_application_release_revision
  from vortex_definition.installation_bindings as binding
  where binding.organization_id = selected_organization_id
    and binding.application_root_id = selected_application_root_id
    and binding.state = 'detached';
  if selected_application_release_revision is null then
    raise exception using errcode = 'P0002', message = 'Detached Application installation is unavailable';
  end if;
  if exists (
    select 1 from vortex_definition.installation_bindings as binding
    where binding.organization_id = selected_organization_id
      and binding.application_root_id = selected_application_root_id
      and binding.state = 'detached'
      and binding.application_release_revision <> selected_application_release_revision
  ) then
    raise exception using errcode = '55000', message = 'Detached Application installation is mixed';
  end if;

  if not exists (
    select 1
    from vortex_definition.roots as root
    join vortex_definition.releases as release
      on release.root_id = root.root_id
      and release.release_revision = selected_application_release_revision
    where root.root_id = selected_application_root_id
      and root.kind = 'application'
      and root.organization_id = selected_organization_id
      and release.compilation_output #>> '{kind}' = 'application'
  ) then
    raise exception using errcode = '23514', message = 'Detached Application release evidence is invalid';
  end if;

  if not exists (
    select 1 from vortex_definition.release_dependencies as dependency
    where dependency.root_id = selected_application_root_id
      and dependency.release_revision = selected_application_release_revision
      and dependency.dependency_kind = 'module'
  ) or exists (
    with recursive module_edges as (
      select dependency.target_root_id, dependency.target_release_revision,
        dependency.dependency_reference, dependency.dependency_version,
        dependency.dependency_content_fingerprint, dependency.evidence_fingerprint
      from vortex_definition.release_dependencies as dependency
      where dependency.root_id = selected_application_root_id
        and dependency.release_revision = selected_application_release_revision
        and dependency.dependency_kind = 'module'
      union
      select dependency.target_root_id, dependency.target_release_revision,
        dependency.dependency_reference, dependency.dependency_version,
        dependency.dependency_content_fingerprint, dependency.evidence_fingerprint
      from module_edges as parent
      join vortex_definition.release_dependencies as dependency
        on dependency.root_id = parent.target_root_id
        and dependency.release_revision = parent.target_release_revision
        and dependency.dependency_kind = 'module'
    )
    select 1
    from module_edges as edge
    left join vortex_definition.releases as module_release
      on module_release.root_id = edge.target_root_id
      and module_release.release_revision = edge.target_release_revision
    left join vortex_definition.roots as module_root
      on module_root.root_id = edge.target_root_id
    where module_root.kind is distinct from 'module'
      or module_root.key is distinct from edge.dependency_reference
      or module_release.release_version is distinct from edge.dependency_version
      or module_release.content_fingerprint is distinct from edge.dependency_content_fingerprint
      or module_release.resolution_fingerprint is distinct from edge.evidence_fingerprint
  ) or exists (
    with recursive module_nodes as (
      select dependency.target_root_id, dependency.target_release_revision
      from vortex_definition.release_dependencies as dependency
      where dependency.root_id = selected_application_root_id
        and dependency.release_revision = selected_application_release_revision
        and dependency.dependency_kind = 'module'
      union
      select dependency.target_root_id, dependency.target_release_revision
      from module_nodes as parent
      join vortex_definition.release_dependencies as dependency
        on dependency.root_id = parent.target_root_id
        and dependency.release_revision = parent.target_release_revision
        and dependency.dependency_kind = 'module'
    )
    select 1 from module_nodes group by target_root_id
    having pg_catalog.count(distinct target_release_revision) <> 1
  ) or exists (
    with recursive module_nodes as (
      select dependency.target_root_id, dependency.target_release_revision
      from vortex_definition.release_dependencies as dependency
      where dependency.root_id = selected_application_root_id
        and dependency.release_revision = selected_application_release_revision
        and dependency.dependency_kind = 'module'
      union
      select dependency.target_root_id, dependency.target_release_revision
      from module_nodes as parent
      join vortex_definition.release_dependencies as dependency
        on dependency.root_id = parent.target_root_id
        and dependency.release_revision = parent.target_release_revision
        and dependency.dependency_kind = 'module'
    )
    select 1
    from module_nodes as node
    left join vortex_definition.installation_bindings as binding
      on binding.organization_id = selected_organization_id
      and binding.application_root_id = selected_application_root_id
      and binding.module_root_id = node.target_root_id
    where binding.state is distinct from 'detached'
      or binding.application_release_revision is distinct from selected_application_release_revision
      or binding.module_release_revision is distinct from node.target_release_revision
  ) or exists (
    select 1
    from vortex_definition.installation_bindings as binding
    where binding.organization_id = selected_organization_id
      and binding.application_root_id = selected_application_root_id
      and binding.state = 'detached'
      and not exists (
        with recursive module_nodes as (
          select dependency.target_root_id, dependency.target_release_revision
          from vortex_definition.release_dependencies as dependency
          where dependency.root_id = selected_application_root_id
            and dependency.release_revision = selected_application_release_revision
            and dependency.dependency_kind = 'module'
          union
          select dependency.target_root_id, dependency.target_release_revision
          from module_nodes as parent
          join vortex_definition.release_dependencies as dependency
            on dependency.root_id = parent.target_root_id
            and dependency.release_revision = parent.target_release_revision
            and dependency.dependency_kind = 'module'
        )
        select 1 from module_nodes as node
        where node.target_root_id = binding.module_root_id
          and node.target_release_revision = binding.module_release_revision
      )
  ) then
    raise exception using errcode = '55000', message = 'Detached Application Module bindings are incomplete';
  end if;

  select pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'organizationId', binding.organization_id,
      'applicationRootId', binding.application_root_id,
      'moduleRootId', binding.module_root_id,
      'bindingRevision', binding.binding_revision,
      'applicationReleaseRevision', binding.application_release_revision,
      'moduleReleaseRevision', binding.module_release_revision,
      'state', binding.state
    ) order by binding.module_root_id
  ) into selected_bindings
  from vortex_definition.installation_bindings as binding
  where binding.organization_id = selected_organization_id
    and binding.application_root_id = selected_application_root_id
    and binding.application_release_revision = selected_application_release_revision
    and binding.state = 'detached';

  return pg_catalog.jsonb_build_object(
    'organizationId', selected_organization_id,
    'applicationRootId', selected_application_root_id,
    'applicationReleaseRevision', selected_application_release_revision,
    'moduleBindings', selected_bindings
  );
end
$function$;

comment on function vortex_definition.read_current_detached_installation_for_transfer_internal() is
  'Private exact detached installation reader for the fixed retained/disabled ownership-transfer operation.';

CREATE OR REPLACE FUNCTION vortex_definition.read_current_offboarding_inventory_installation_internal() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  installation jsonb;
  installation_state text;
  context_value jsonb;
  storage_contract_ids jsonb;
begin
  context_value := vortex_access.validated_human_request_context();
  if not context_value ? 'applicationRootId' then
    raise exception using errcode = '22023',
      message = 'Offboarding inventory requires an application context';
  end if;

  begin
    installation := vortex_definition.read_current_active_installation();
    installation_state := 'active';
  exception
    when no_data_found then
      installation := vortex_definition.read_current_detached_installation_for_transfer_internal();
      installation_state := 'detached';
  end;

  select coalesce(pg_catalog.jsonb_agg(contract_id order by contract_id), '[]'::jsonb)
  into storage_contract_ids
  from (
    select distinct unnest(binding.storage_contract_ids) as contract_id
    from vortex_definition.installation_bindings as binding
    where binding.organization_id = (context_value ->> 'organizationId')::uuid
      and binding.application_root_id = (context_value ->> 'applicationRootId')::uuid
      and binding.state = installation_state
      and binding.application_release_revision =
        (installation ->> 'applicationReleaseRevision')::bigint
  ) as contracts;

  if storage_contract_ids = '[]'::jsonb then
    raise exception using errcode = '55000',
      message = 'Offboarding inventory installation bindings are unavailable';
  end if;

  return installation || pg_catalog.jsonb_build_object(
    'installationState', installation_state,
    'storageContractIds', storage_contract_ids
  );
end
$$;

COMMENT ON FUNCTION vortex_definition.read_current_offboarding_inventory_installation_internal() IS 'Private exact active-or-detached installation reader with the bound storage contracts for account-offboarding inventory.';

REVOKE ALL ON FUNCTION vortex_definition.read_current_offboarding_inventory_installation_internal() FROM PUBLIC;

GRANT ALL ON FUNCTION vortex_definition.read_current_offboarding_inventory_installation_internal() TO vortex_record_adapter;

create or replace function vortex_definition.read_installation_runtime_bundle_index(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_bundle_format_version integer
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  checked_context jsonb;
  selected_organization_id uuid;
  stored_bundle vortex_definition.installation_runtime_bundles%rowtype;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991
    or p_bundle_format_version is distinct from 2 then
    raise exception using errcode = '22023',
      message = 'Installation runtime bundle key is invalid';
  end if;

  checked_context := vortex_access.validated_human_request_context();
  selected_organization_id := (checked_context ->> 'organizationId')::uuid;
  if selected_organization_id is null then
    raise exception using errcode = '42501',
      message = 'Installation runtime bundle organisation is unavailable';
  end if;

  select stored.* into stored_bundle
  from vortex_definition.installation_runtime_bundles as stored
  where stored.organization_id = selected_organization_id
    and stored.application_root_id = p_application_root_id
    and stored.application_release_revision = p_application_release_revision
    and stored.bundle_format_version = p_bundle_format_version;
  if not found then
    raise exception using errcode = 'P0002',
      message = 'Installation runtime bundle is unavailable';
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', stored_bundle.organization_id,
    'applicationRootId', stored_bundle.application_root_id,
    'applicationReleaseRevision', stored_bundle.application_release_revision,
    'bundleFormatVersion', stored_bundle.bundle_format_version,
    'pinFingerprint', stored_bundle.pin_fingerprint,
    'sourceManifest', stored_bundle.source_manifest,
    'parts', stored_bundle.parts,
    'totalSizeBytes', stored_bundle.total_size_bytes,
    'builtAt', stored_bundle.built_at
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Installation runtime bundle is unavailable';
end
$function$;

comment on function vortex_definition.read_installation_runtime_bundle_index(
  uuid, bigint, integer
) is
  'Reads one exact immutable runtime bundle index inside the verified organisation context.';

create or replace function vortex_definition.read_installation_runtime_bundle_parts(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_bundle_format_version integer,
  p_sections jsonb
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  allowed_sections constant text[] := array[
    'pages', 'navigation', 'flows', 'trigger_index', 'theme', 'component_registry',
    'access_plan', 'tool_bundle'
  ];
  checked_context jsonb;
  selected_organization_id uuid;
  requested_sections text[];
  parts_value jsonb;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991
    or p_bundle_format_version is null or p_bundle_format_version < 1
    or p_sections is null or pg_catalog.jsonb_typeof(p_sections) is distinct from 'array' then
    raise exception using errcode = '22023',
      message = 'Installation runtime bundle read command is invalid';
  end if;
  if pg_catalog.jsonb_array_length(p_sections) not between 1 and
    pg_catalog.cardinality(allowed_sections) then
    raise exception using errcode = '22023',
      message = 'Installation runtime bundle read command is invalid';
  end if;
  if exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_sections) as requested(value)
      where pg_catalog.jsonb_typeof(requested.value) is distinct from 'string'
        or not ((requested.value #>> '{}') = any (allowed_sections))
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_sections) as requested(value)
      group by requested.value
      having pg_catalog.count(*) > 1
    ) then
    raise exception using errcode = '22023',
      message = 'Installation runtime bundle read command is invalid';
  end if;
  select pg_catalog.array_agg(requested.value #>> '{}' order by requested.ordinality)
  into requested_sections
  from pg_catalog.jsonb_array_elements(p_sections) with ordinality as requested(value, ordinality);

  checked_context := vortex_access.validated_human_request_context();
  selected_organization_id := (checked_context ->> 'organizationId')::uuid;
  if selected_organization_id is null then
    raise exception using errcode = '42501',
      message = 'Installation runtime bundle organisation is unavailable';
  end if;

  if not exists (
    select 1 from vortex_definition.installation_runtime_bundles as stored
    where stored.organization_id = selected_organization_id
      and stored.application_root_id = p_application_root_id
      and stored.application_release_revision = p_application_release_revision
      and stored.bundle_format_version = p_bundle_format_version
  ) then
    raise exception using errcode = 'P0002',
      message = 'Installation runtime bundle is unavailable';
  end if;

  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'section', part.section,
      'ordinal', part.ordinal,
      'byteSize', pg_catalog.octet_length(part.content_bytes),
      'sha256', 'sha256:' || pg_catalog.encode(
        extensions.digest(part.content_bytes, 'sha256'), 'hex'
      ),
      'content', pg_catalog.convert_from(part.content_bytes, 'UTF8')
    ) order by pg_catalog.array_position(requested_sections, part.section), part.ordinal
  ), '[]'::jsonb)
  into parts_value
  from vortex_definition.installation_runtime_bundle_parts as part
  where part.organization_id = selected_organization_id
    and part.application_root_id = p_application_root_id
    and part.application_release_revision = p_application_release_revision
    and part.bundle_format_version = p_bundle_format_version
    and part.section = any (requested_sections);

  return parts_value;
end
$function$;

comment on function vortex_definition.read_installation_runtime_bundle_parts(
  uuid, bigint, integer, jsonb
) is
  'Reads selected immutable runtime bundle parts by exact key inside the verified organisation context.';

CREATE OR REPLACE FUNCTION vortex_definition.read_lifecycle_activation_targets_internal(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) RETURNS TABLE(storage_contract_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  context_value jsonb;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_expected_module_bindings) = 0
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
      where pg_catalog.jsonb_typeof(item.value) <> 'object'
        or not item.value ?& array['moduleRootId', 'bindingRevision']
        or item.value - array['moduleRootId', 'bindingRevision'] <> '{}'::jsonb
    ) then
    raise exception using errcode = '22023',
      message = 'Lifecycle activation target command is invalid';
  end if;

  context_value := vortex_access.validated_human_request_context();
  if (context_value ->> 'organizationId')::uuid is distinct from p_organization_id then
    raise exception using errcode = '42501',
      message = 'Lifecycle activation targets are unavailable';
  end if;

  return query
  select storage_id.value
  from vortex_definition.installation_bindings as binding
  join pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
    on expected.value ->> 'moduleRootId' = binding.module_root_id::text
    and expected.value ->> 'bindingRevision' = binding.binding_revision::text
  join pg_catalog.unnest(binding.storage_contract_ids) as storage_id(value) on true
  where binding.organization_id = p_organization_id
    and binding.application_root_id = p_application_root_id
    and binding.application_release_revision = p_application_release_revision
    -- Activation has already flipped this exact binding set to 'active' under
    -- its own advisory and row locks earlier in this transaction.
    and binding.state = 'active'
  for share of binding;
end
$$;

COMMENT ON FUNCTION vortex_definition.read_lifecycle_activation_targets_internal(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) IS 'Private activation-time installation fact: the exact storage contracts of one already-activated Application binding set, shared for the transaction.';

REVOKE ALL ON FUNCTION vortex_definition.read_lifecycle_activation_targets_internal(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) FROM PUBLIC;
GRANT ALL ON FUNCTION vortex_definition.read_lifecycle_activation_targets_internal(p_organization_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_expected_module_bindings jsonb) TO vortex_owner;

CREATE OR REPLACE FUNCTION vortex_definition.read_offboarding_inventory_contract_applications_internal(p_storage_contract_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  context_value jsonb;
  affected_applications jsonb;
begin
  if p_storage_contract_id is null or p_storage_contract_id = nil_uuid then
    raise exception using errcode = '22023',
      message = 'Offboarding inventory selector is invalid';
  end if;

  context_value := vortex_access.validated_human_request_context();

  -- Provisioned bindings are not installed and are excluded; detached bindings
  -- are a disabled installation of a real application and stay visible, exactly
  -- as the inventory's installation reader treats them.
  select coalesce(
    pg_catalog.jsonb_agg(
      distinct binding.application_root_id order by binding.application_root_id
    ),
    '[]'::jsonb
  )
  into affected_applications
  from vortex_definition.installation_bindings as binding
  where binding.organization_id = (context_value ->> 'organizationId')::uuid
    and binding.state in ('active', 'detached')
    and p_storage_contract_id = any (binding.storage_contract_ids);

  return affected_applications;
end
$$;

COMMENT ON FUNCTION vortex_definition.read_offboarding_inventory_contract_applications_internal(p_storage_contract_id uuid) IS 'Private adapter-only bridge returning the installed application root IDs one storage contract is bound into, for account-offboarding shared impact.';

REVOKE ALL ON FUNCTION vortex_definition.read_offboarding_inventory_contract_applications_internal(p_storage_contract_id uuid) FROM PUBLIC;

GRANT ALL ON FUNCTION vortex_definition.read_offboarding_inventory_contract_applications_internal(p_storage_contract_id uuid) TO vortex_record_adapter;

create or replace function vortex_definition.read_prepared_installation_runtime_source(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_expected_module_bindings jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  mapping jsonb;
  prepared_record_plan jsonb;
  application_evidence jsonb;
  module_evidence jsonb;
begin
  mapping := vortex_definition.lock_prepared_installation_runtime_mapping_internal(
    p_application_root_id,
    p_application_release_revision,
    p_expected_module_bindings
  );
  select vortex_definition.project_consumer_release_evidence(
    'application', p_application_root_id, p_application_release_revision
  ) into application_evidence;
  if application_evidence is null
    or (application_evidence ->> 'organizationId')::uuid
      is distinct from (mapping ->> 'organizationId')::uuid then
    raise exception using errcode = 'P0002',
      message = 'Prepared Application source is unavailable';
  end if;

  select coalesce(pg_catalog.jsonb_agg(
      vortex_definition.project_consumer_release_evidence(
        'module', (pin.value ->> 'moduleRootId')::uuid,
        (pin.value ->> 'moduleReleaseRevision')::bigint
      ) order by (pin.value ->> 'moduleRootId')::uuid
    ), '[]'::jsonb)
  into module_evidence
  from pg_catalog.jsonb_array_elements(mapping -> 'moduleBindings') as pin(value);

  prepared_record_plan := vortex_record.resolve_prepared_record_access_plan_internal(
    p_application_root_id,
    p_application_release_revision,
    mapping -> 'moduleBindings'
  );
  if prepared_record_plan is null
    or pg_catalog.jsonb_typeof(prepared_record_plan) is distinct from 'object'
    or not prepared_record_plan ?& array['planKey', 'mappingFingerprint', 'plan'] then
    raise exception using errcode = '55000',
      message = 'Prepared Record access plan is unavailable';
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', mapping -> 'organizationId',
    'applicationRootId', mapping -> 'applicationRootId',
    'applicationReleaseRevision', mapping -> 'applicationReleaseRevision',
    'accessVersion', mapping -> 'accessVersion',
    'correlationId', mapping -> 'correlationId',
    'pinFingerprint', mapping -> 'pinFingerprint',
    'mappingFingerprint', prepared_record_plan -> 'mappingFingerprint',
    'moduleBindings', mapping -> 'moduleBindings',
    'application', application_evidence,
    'modules', module_evidence,
    'preparedRecordAccessPlan', prepared_record_plan
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Prepared runtime source evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Prepared runtime source evidence is ambiguous';
end
$function$;

comment on function vortex_definition.read_prepared_installation_runtime_source(uuid,bigint,jsonb) is
  'Reads exact immutable Application and complete Module source plus the current prepared Record plan inside the verified human installation transaction.';

create or replace function vortex_definition.read_preview_installation(
  p_preview_installation_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  checked_context jsonb;
  preview_row vortex_definition.preview_installations%rowtype;
begin
  if not vortex_platform.is_non_nil_uuid(p_preview_installation_id::text) then
    raise exception using errcode = '22023', message = 'Preview installation identity is invalid';
  end if;
  checked_context := vortex_definition.assert_preview_installation_authority_internal();
  select preview.* into preview_row
  from vortex_definition.preview_installations as preview
  where preview.preview_installation_id = p_preview_installation_id
    and preview.organization_id = (checked_context ->> 'organizationId')::uuid
    and preview.previewer_identity_id = (checked_context ->> 'identityId')::uuid
    and preview.previewer_organization_account_id =
      (checked_context ->> 'organizationAccountId')::uuid
    and preview.application_root_id = (checked_context ->> 'applicationRootId')::uuid
    and preview.expires_at > pg_catalog.statement_timestamp();
  if not found then
    return null;
  end if;
  return pg_catalog.jsonb_build_object(
    'previewInstallationId', preview_row.preview_installation_id,
    'organizationId', preview_row.organization_id,
    'applicationRootId', preview_row.application_root_id,
    'draftRevision', preview_row.draft_revision,
    'previewerIdentityId', preview_row.previewer_identity_id,
    'previewerOrganizationAccountId', preview_row.previewer_organization_account_id,
    'candidate', preview_row.candidate,
    'resolvedModules', preview_row.resolved_modules,
    'storageIdentities', preview_row.storage_identities,
    'createdAt', preview_row.created_at,
    'expiresAt', preview_row.expires_at
  );
end
$function$;

comment on function vortex_definition.read_preview_installation(uuid) is
  'Reads a non-expired preview installation only for its creating organisation account in the validated human request.';

create or replace function vortex_definition.read_preview_record_installation_internal(
  p_preview_installation_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_value jsonb;
  preview_row vortex_definition.preview_installations%rowtype;
  module_bindings_value jsonb;
begin
  if not vortex_platform.is_non_nil_uuid(p_preview_installation_id::text) then
    return null;
  end if;

  begin
    context_value := vortex_definition.assert_preview_installation_authority_internal();
  exception when insufficient_privilege then
    return null;
  end;
  select preview.* into preview_row
  from vortex_definition.preview_installations as preview
  where preview.preview_installation_id = p_preview_installation_id
    and preview.organization_id = (context_value ->> 'organizationId')::uuid
    and preview.application_root_id = (context_value ->> 'applicationRootId')::uuid
    and preview.previewer_identity_id = (context_value ->> 'identityId')::uuid
    and preview.previewer_organization_account_id =
      (context_value ->> 'organizationAccountId')::uuid
    and preview.expires_at > pg_catalog.statement_timestamp()
  for key share;
  if not found then
    return null;
  end if;

  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'moduleRootId', item.value -> 'moduleRootId',
      'moduleReleaseRevision', item.value -> 'moduleReleaseRevision',
      'bindingRevision', 1,
      'state', 'active'
    ) order by item.value ->> 'moduleRootId' collate "C"
  ), '[]'::jsonb)
  into module_bindings_value
  from pg_catalog.jsonb_array_elements(preview_row.resolved_modules) as item(value);

  return pg_catalog.jsonb_build_object(
    'previewInstallationId', preview_row.preview_installation_id,
    'organizationId', preview_row.organization_id,
    'applicationRootId', preview_row.application_root_id,
    'applicationReleaseRevision', preview_row.draft_revision,
    'moduleBindings', module_bindings_value,
    'candidate', preview_row.candidate,
    'resolvedModules', preview_row.resolved_modules,
    'storageIdentities', preview_row.storage_identities
  );
end
$function$;

comment on function vortex_definition.read_preview_record_installation_internal(uuid) is
  'Private owner-only preview installation reader for the protected Record port, restricted to the exact human identity, organisation account and Application context until expiry.';

create or replace function vortex_definition.read_private_form_draft(
  p_form_id uuid,
  p_flow_id uuid,
  p_node_id uuid,
  p_subject_record_id uuid
)
returns table (outcome text, result jsonb)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  scope record;
  stored vortex_definition.form_drafts%rowtype;
begin
  if p_form_id is null or not vortex_platform.is_non_nil_uuid(p_form_id::text)
    or (p_flow_id is not null and not vortex_platform.is_non_nil_uuid(p_flow_id::text))
    or (p_node_id is not null and not vortex_platform.is_non_nil_uuid(p_node_id::text))
    or (p_subject_record_id is not null
      and not vortex_platform.is_non_nil_uuid(p_subject_record_id::text)) then
    raise exception using errcode = '22023',
      message = 'Private form draft read command is invalid';
  end if;

  select context.* into strict scope
  from vortex_definition.private_form_draft_context_internal() as context;

  -- Only the draft bound to the exact current installed release is resumable.
  select draft.* into stored
  from vortex_definition.form_drafts as draft
  where draft.organization_id = scope.organization_id
    and draft.organization_account_id = scope.organization_account_id
    and draft.identity_id = scope.identity_id
    and draft.application_root_id = scope.application_root_id
    and draft.installation_release_revision = scope.release_revision
    and draft.form_id = p_form_id
    and draft.flow_id is not distinct from p_flow_id
    and draft.node_id is not distinct from p_node_id
    and draft.subject_record_id is not distinct from p_subject_record_id
    and draft.expires_at > pg_catalog.clock_timestamp();
  if found then
    return query select 'available'::text,
      vortex_definition.private_form_draft_to_json_internal(stored, 'active');
    return;
  end if;

  -- A live draft for this scope bound to a replaced installation is stale, not
  -- silently combined with the changed form.
  perform 1
  from vortex_definition.form_drafts as draft
  where draft.organization_id = scope.organization_id
    and draft.organization_account_id = scope.organization_account_id
    and draft.identity_id = scope.identity_id
    and draft.application_root_id = scope.application_root_id
    and draft.installation_release_revision <> scope.release_revision
    and draft.form_id = p_form_id
    and draft.flow_id is not distinct from p_flow_id
    and draft.node_id is not distinct from p_node_id
    and draft.subject_record_id is not distinct from p_subject_record_id
    and draft.expires_at > pg_catalog.clock_timestamp();
  if found then
    return query select 'stale_installation'::text, null::jsonb;
    return;
  end if;

  return query select 'unavailable'::text, null::jsonb;
end
$function$;

comment on function vortex_definition.read_private_form_draft(uuid, uuid, uuid, uuid) is
  'Reads one exact live private form draft of the current person, rechecking the exact active installation before returning any value.';

alter function vortex_definition.read_private_form_draft(uuid, uuid, uuid, uuid)
  owner to vortex_owner;

create or replace function vortex_definition.read_provisioned_lifecycle_setup_targets_internal(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_expected_module_bindings jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  initial_authority record;
  current_authority record;
  install_decision record;
  install_scope_decision record;
  initial_context jsonb;
  current_context jsonb;
  completion_time timestamptz;
  context_expires_at timestamptz;
  delegated_expires_at timestamptz;
  application_definition_key text;
  application_release vortex_definition.releases%rowtype;
  permission_snapshot record;
  pin record;
  locked_binding vortex_definition.installation_bindings%rowtype;
  module_release vortex_definition.releases%rowtype;
  storage_provision record;
  expected_module_root_id uuid;
  expected_binding_revision bigint;
  previous_module_root_id uuid;
  module_root_text text;
  binding_revision_text text;
  closure_count bigint;
  expected_count integer;
  module_bindings jsonb := '[]'::jsonb;
  normalized_pins jsonb;
  all_storage_contract_ids uuid[] := array[]::uuid[];
  union_storage_contract_ids uuid[];
  storage_contract_id_count bigint;
  distinct_storage_contract_id_count bigint;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991 then
    raise exception using errcode = '22023',
      message = 'Provisioned Application lifecycle setup command is invalid';
  end if;

  if p_expected_module_bindings is null
    or pg_catalog.jsonb_typeof(p_expected_module_bindings) is distinct from 'array' then
    raise exception using errcode = '22023',
      message = 'Provisioned Application lifecycle setup binding pins are invalid';
  end if;
  expected_count := pg_catalog.jsonb_array_length(p_expected_module_bindings);
  if expected_count < 1 or expected_count > 10000 then
    raise exception using errcode = '22023',
      message = 'Provisioned Application lifecycle setup binding pins are invalid';
  end if;

  previous_module_root_id := null;
  for pin in
    select item.value
    from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value)
  loop
    if pg_catalog.jsonb_typeof(pin.value) is distinct from 'object' then
      raise exception using errcode = '22023',
        message = 'Provisioned Application lifecycle setup binding pins are invalid';
    end if;
    if not (pin.value ?& array['moduleRootId', 'bindingRevision'])
      or pin.value - array['moduleRootId', 'bindingRevision'] <> '{}'::jsonb
      or (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(pin.value)) <> 2 then
      raise exception using errcode = '22023',
        message = 'Provisioned Application lifecycle setup binding pins are invalid';
    end if;
    if pg_catalog.jsonb_typeof(pin.value -> 'moduleRootId') is distinct from 'string'
      or pg_catalog.jsonb_typeof(pin.value -> 'bindingRevision') is distinct from 'number' then
      raise exception using errcode = '22023',
        message = 'Provisioned Application lifecycle setup binding pins are invalid';
    end if;

    module_root_text := pin.value ->> 'moduleRootId';
    if module_root_text !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or not pg_catalog.pg_input_is_valid(module_root_text, 'uuid') then
      raise exception using errcode = '22023',
        message = 'Provisioned Application lifecycle setup binding pins are invalid';
    end if;
    expected_module_root_id := module_root_text::uuid;
    if expected_module_root_id = '00000000-0000-0000-0000-000000000000'::uuid
      or module_root_text is distinct from expected_module_root_id::text then
      raise exception using errcode = '22023',
        message = 'Provisioned Application lifecycle setup binding pins are invalid';
    end if;

    binding_revision_text := pin.value ->> 'bindingRevision';
    if binding_revision_text !~ '^[1-9][0-9]*$'
      or not pg_catalog.pg_input_is_valid(binding_revision_text, 'bigint') then
      raise exception using errcode = '22023',
        message = 'Provisioned Application lifecycle setup binding pins are invalid';
    end if;
    expected_binding_revision := binding_revision_text::bigint;
    if expected_binding_revision not between 1 and 9007199254740991
      or (previous_module_root_id is not null
        and previous_module_root_id >= expected_module_root_id) then
      raise exception using errcode = '22023',
        message = 'Provisioned Application lifecycle setup binding pins are invalid';
    end if;
    previous_module_root_id := expected_module_root_id;
  end loop;

  select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'moduleRootId', (item.value ->> 'moduleRootId')::uuid,
        'bindingRevision', (item.value ->> 'bindingRevision')::bigint
      )
      order by (item.value ->> 'moduleRootId')::uuid
    )
  into strict normalized_pins
  from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as item(value);
  if p_expected_module_bindings is distinct from normalized_pins then
    raise exception using errcode = '22023',
      message = 'Provisioned Application lifecycle setup binding pins are invalid';
  end if;

  select locked.* into strict initial_authority
  from vortex_access.lock_application_installation_authority() as locked;
  initial_context := vortex_access.validated_human_request_context();
  if initial_context ->> 'callerKind' is distinct from 'human'
    or (initial_context ->> 'organizationId')::uuid is distinct from initial_authority.organization_id
    or (initial_context ->> 'organizationAccountId')::uuid is distinct from initial_authority.organization_account_id
    or (initial_context ->> 'accessVersion')::bigint is distinct from initial_authority.access_version
    or (initial_context ->> 'correlationId')::uuid is distinct from initial_authority.correlation_id
    or (initial_context ->> 'applicationRootId')::uuid is distinct from p_application_root_id then
    raise exception using errcode = '42501',
      message = 'Provisioned Application lifecycle setup authority is unavailable';
  end if;

  select release.* into strict application_release
  from vortex_definition.releases as release
  join vortex_definition.roots as root on root.root_id = release.root_id
  where root.root_id = p_application_root_id
    and root.organization_id = initial_authority.organization_id
    and root.kind = 'application'
    and release.release_revision = p_application_release_revision;

  select root.key into strict application_definition_key
  from vortex_definition.roots as root
  where root.root_id = p_application_root_id
    and root.organization_id = initial_authority.organization_id
    and root.kind = 'application';

  if not application_release.validation_contract_version = any (
      vortex_definition.accepted_contract_version('application')
    )
    or application_release.compilation_output #>> '{kind}' is distinct from 'application'
    or application_release.compilation_output #>> '{canonical,envelope,rootId}'
      is distinct from p_application_root_id::text
    or application_release.compilation_output #>> '{validationContractVersion}'
      is distinct from application_release.validation_contract_version then
    raise exception using errcode = '23514',
      message = 'Exact Application release is unavailable';
  end if;

  select snapshot.* into strict permission_snapshot
  from vortex_access.read_application_permission_snapshot(
    initial_authority.organization_id, p_application_root_id
  ) as snapshot;
  if permission_snapshot.organization_id is distinct from initial_authority.organization_id
    or permission_snapshot.application_root_id is distinct from p_application_root_id
    or permission_snapshot.registration_revision not between 1 and 9007199254740991
    or permission_snapshot.release_revision is distinct from p_application_release_revision
    or permission_snapshot.definition_key is distinct from application_definition_key
    or permission_snapshot.release_version is distinct from application_release.release_version
    or permission_snapshot.validation_contract_version is distinct from application_release.validation_contract_version
    or permission_snapshot.content_fingerprint is distinct from application_release.content_fingerprint
    or permission_snapshot.resolution_fingerprint is distinct from application_release.resolution_fingerprint then
    raise exception using errcode = '40001',
      message = 'Application permission registration is stale or unavailable';
  end if;

  select pg_catalog.count(*) into closure_count
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  );
  if closure_count < 1
    or closure_count > 10000
    or closure_count <> expected_count
    or exists (
      select 1
      from vortex_definition.reachable_module_dependency_edges(
        p_application_root_id, p_application_release_revision
      ) as required
      where not exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
        where (expected.value ->> 'moduleRootId')::uuid = required.target_root_id
      )
    ) then
    raise exception using errcode = '23514',
      message = 'Application installation binding set is incomplete';
  end if;

  for pin in
    select required.target_root_id
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    order by required.target_root_id
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'vortex_definition.binding:' || initial_authority.organization_id::text || ':' ||
          p_application_root_id::text || ':' || pin.target_root_id::text,
        0
      )
    );
  end loop;

  for pin in
    select required.target_root_id
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    order by required.target_root_id
  loop
    perform 1
    from vortex_definition.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = pin.target_root_id
    for share;
  end loop;

  for locked_binding in
    select binding.*
    from vortex_definition.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.state <> 'detached'
    order by binding.module_root_id
    for share
  loop
    if locked_binding.state <> 'detached'
      and not exists (
        select 1
        from vortex_definition.reachable_module_dependency_edges(
          p_application_root_id, p_application_release_revision
        ) as required
        where required.target_root_id = locked_binding.module_root_id
      ) then
      raise exception using errcode = '40001',
        message = 'Application installation bindings changed or are incomplete';
    end if;
  end loop;

  for pin in
    select required.*
    from vortex_definition.reachable_module_dependency_edges(
      p_application_root_id, p_application_release_revision
    ) as required
    order by required.target_root_id
  loop
    select (expected.value ->> 'bindingRevision')::bigint
    into strict expected_binding_revision
    from pg_catalog.jsonb_array_elements(p_expected_module_bindings) as expected(value)
    where (expected.value ->> 'moduleRootId')::uuid = pin.target_root_id;

    select binding.* into strict locked_binding
    from vortex_definition.installation_bindings as binding
    where binding.organization_id = initial_authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.module_root_id = pin.target_root_id;

    select release.* into strict module_release
    from vortex_definition.releases as release
    where release.root_id = locked_binding.module_root_id
      and release.release_revision = locked_binding.module_release_revision;

    if locked_binding.binding_revision is distinct from expected_binding_revision
      or locked_binding.application_release_revision is distinct from p_application_release_revision
      or locked_binding.module_release_revision is distinct from pin.target_release_revision
      or locked_binding.state is distinct from 'provisioned'
      or module_release.content_fingerprint is distinct from pin.dependency_content_fingerprint
      or module_release.resolution_fingerprint is distinct from pin.evidence_fingerprint then
      raise exception using errcode = '40001',
        message = 'Application installation bindings changed or are incomplete';
    end if;

    select provision.* into strict storage_provision
    from vortex_record.read_exact_module_storage_provision(
      pin.target_root_id, pin.target_release_revision
    ) as provision;
    if storage_provision.module_root_id is distinct from pin.target_root_id
      or storage_provision.release_revision is distinct from pin.target_release_revision
      or storage_provision.storage_contract_ids is null
      or (
        pg_catalog.cardinality(storage_provision.storage_contract_ids) > 0
        and (
          pg_catalog.array_ndims(storage_provision.storage_contract_ids) is distinct from 1
          or pg_catalog.array_lower(storage_provision.storage_contract_ids, 1) is distinct from 1
        )
      )
      or locked_binding.storage_contract_ids is distinct from storage_provision.storage_contract_ids
      or exists (
        select 1
        from pg_catalog.unnest(storage_provision.storage_contract_ids) as stored(contract_id)
        where stored.contract_id is null
          or stored.contract_id = '00000000-0000-0000-0000-000000000000'::uuid
      ) then
      raise exception using errcode = '40001',
        message = 'Application installation storage evidence changed or is incomplete';
    end if;

    select pg_catalog.count(*),
      pg_catalog.count(distinct stored.contract_id)
    into storage_contract_id_count, distinct_storage_contract_id_count
    from pg_catalog.unnest(storage_provision.storage_contract_ids) as stored(contract_id);
    if storage_contract_id_count <> distinct_storage_contract_id_count then
      raise exception using errcode = '40001',
        message = 'Application installation storage evidence is invalid';
    end if;

    all_storage_contract_ids := all_storage_contract_ids || storage_provision.storage_contract_ids;
    module_bindings := module_bindings || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'moduleRootId', pin.target_root_id,
        'moduleReleaseRevision', pin.target_release_revision,
        'bindingRevision', locked_binding.binding_revision,
        'state', 'provisioned',
        'storageContractIds', pg_catalog.to_jsonb(storage_provision.storage_contract_ids)
      )
    );
  end loop;

  select coalesce(
      pg_catalog.array_agg(distinct stored.contract_id order by stored.contract_id),
      array[]::uuid[]
    )
  into union_storage_contract_ids
  from pg_catalog.unnest(all_storage_contract_ids) as stored(contract_id);

  select locked.* into strict current_authority
  from vortex_access.lock_application_installation_authority() as locked;
  select evaluated.* into strict install_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  ) as evaluated;
  select evaluated.* into strict install_scope_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install_scope',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object(
        'kind', 'delegated_management',
        'before', pg_catalog.jsonb_build_object('kind', 'organization_catalogue'),
        'after', pg_catalog.jsonb_build_object('kind', 'organization_catalogue')
      )
    )
  ) as evaluated;
  current_context := vortex_access.validated_human_request_context();
  if current_authority.organization_id is distinct from initial_authority.organization_id
    or current_authority.organization_account_id is distinct from initial_authority.organization_account_id
    or current_authority.access_version is distinct from initial_authority.access_version
    or current_authority.correlation_id is distinct from initial_authority.correlation_id
    or current_context is distinct from initial_context
    or current_context ->> 'callerKind' is distinct from 'human'
    or (current_context ->> 'organizationId')::uuid is distinct from current_authority.organization_id
    or (current_context ->> 'organizationAccountId')::uuid is distinct from current_authority.organization_account_id
    or (current_context ->> 'accessVersion')::bigint is distinct from current_authority.access_version
    or (current_context ->> 'correlationId')::uuid is distinct from current_authority.correlation_id
    or (current_context ->> 'applicationRootId')::uuid is distinct from p_application_root_id then
    raise exception using errcode = '40001',
      message = 'Application installation authority changed';
  end if;

  if install_decision.outcome is distinct from 'eligible'
    or install_decision.operation_key is distinct from
      'platform.organization.applications.install'
    or install_decision.target_kind is distinct from 'organization'
    or install_decision.target_application_root_id is not null
    or install_decision.organization_id is distinct from current_authority.organization_id
    or install_decision.organization_account_id is distinct from current_authority.organization_account_id
    or install_decision.access_version is distinct from current_authority.access_version
    or install_decision.correlation_id is distinct from current_authority.correlation_id
    or install_decision.reason_code is not null
    or install_scope_decision.outcome is distinct from 'eligible'
    or install_scope_decision.operation_key is distinct from
      'platform.organization.applications.install_scope'
    or install_scope_decision.target_kind is distinct from 'organization'
    or install_scope_decision.target_application_root_id is not null
    or install_scope_decision.organization_id is distinct from current_authority.organization_id
    or install_scope_decision.organization_account_id is distinct from
      current_authority.organization_account_id
    or install_scope_decision.access_version is distinct from current_authority.access_version
    or install_scope_decision.correlation_id is distinct from current_authority.correlation_id
    or install_scope_decision.reason_code is not null then
    raise exception using errcode = '42501',
      message = 'Application installation authority is unavailable';
  end if;

  completion_time := pg_catalog.clock_timestamp();
  context_expires_at := (current_context ->> 'expiresAt')::timestamptz;
  if install_decision.checked_at is null
    or install_decision.checked_at > completion_time
    or install_decision.valid_until is null
    or install_decision.valid_until <= completion_time
    or install_scope_decision.checked_at is null
    or install_scope_decision.checked_at > completion_time
    or install_scope_decision.valid_until is null
    or install_scope_decision.valid_until <= completion_time
    or not pg_catalog.isfinite(context_expires_at)
    or context_expires_at <= completion_time then
    raise exception using errcode = '42501',
      message = 'Application installation context expired';
  end if;
  if current_context ? 'delegatedContext' then
    delegated_expires_at := (current_context #>> '{delegatedContext,expiresAt}')::timestamptz;
    if not pg_catalog.isfinite(delegated_expires_at)
      or delegated_expires_at <= completion_time then
      raise exception using errcode = '42501',
        message = 'Application installation delegation expired';
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', initial_authority.organization_id,
    'applicationRootId', p_application_root_id,
    'applicationReleaseRevision', p_application_release_revision,
    'registrationRevision', permission_snapshot.registration_revision,
    'moduleBindings', module_bindings,
    'storageContractIds', pg_catalog.to_jsonb(union_storage_contract_ids)
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Application lifecycle setup evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Application lifecycle setup evidence is ambiguous';
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '22023',
      message = 'Provisioned Application lifecycle setup command is invalid';
end
$function$;

comment on function vortex_definition.read_provisioned_lifecycle_setup_targets_internal(uuid, bigint, jsonb) is
  'Module-owned complete exact provisioned lifecycle setup targets for the authorized Record setup reader.';

CREATE OR REPLACE FUNCTION vortex_definition.record_application_installation_outcome(p_activity_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_state text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  authority record;
  pin_count integer;
  changed_count integer;
begin
  if p_activity_id is null
    or p_activity_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision not between 1 and 9007199254740991
    or p_state is null
    or p_state not in ('active', 'detached') then
    raise exception using errcode = '22023',
      message = 'Application installation outcome command is invalid';
  end if;

  select locked.* into strict authority
  from vortex_access.lock_application_installation_authority() as locked;

  select pg_catalog.count(*)::integer into pin_count
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  );

  -- Activity records only a change this transaction made: every pinned binding
  -- must be in the reported state for this exact release and changed since this
  -- transaction began. The fixed activate/detach operations stamp changed_at
  -- with their statement time and keep the rows locked until commit, so a
  -- binding they changed here satisfies this and an untouched one does not.
  select pg_catalog.count(*)::integer into changed_count
  from vortex_definition.reachable_module_dependency_edges(
    p_application_root_id, p_application_release_revision
  ) as required
  join vortex_definition.installation_bindings as binding
    on binding.organization_id = authority.organization_id
    and binding.application_root_id = p_application_root_id
    and binding.module_root_id = required.target_root_id
  where binding.state = p_state
    and binding.application_release_revision = p_application_release_revision
    and binding.module_release_revision = required.target_release_revision
    and binding.changed_at >= pg_catalog.transaction_timestamp();

  if pin_count = 0 or changed_count <> pin_count then
    raise exception using errcode = '40001',
      message = 'Application installation outcome is not a change of this transaction';
  end if;

  perform vortex_definition.append_application_installation_activity_internal(
    p_activity_id,
    p_application_root_id,
    case p_state
      when 'active' then 'activate_application_installation'
      else 'withdraw_application_installation'
    end
  );
end
$$;

COMMENT ON FUNCTION vortex_definition.record_application_installation_outcome(p_activity_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_state text) IS 'Appends content-free Activity for an Application activation or withdrawal made earlier in the same protected transaction.';

REVOKE ALL ON FUNCTION vortex_definition.record_application_installation_outcome(p_activity_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_state text) FROM PUBLIC;
GRANT ALL ON FUNCTION vortex_definition.record_application_installation_outcome(p_activity_id uuid, p_application_root_id uuid, p_application_release_revision bigint, p_state text) TO vortex_request;

CREATE OR REPLACE FUNCTION vortex_definition.record_lifecycle_provisioned_setup_target_internal(p_organization_id uuid, p_application_root_id uuid, p_expected_binding_revision bigint, p_storage_contract_id uuid, p_workflow_id uuid, p_expected_workflow_revision bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  provisioned_release_revision bigint;
  matched boolean;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_expected_binding_revision is null
    or p_expected_binding_revision not between 1 and 9007199254740991
    or p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    -- A workflow reference is either completely absent or completely present.
    or (p_workflow_id is null) <> (p_expected_workflow_revision is null)
    or (p_workflow_id is not null
      and p_workflow_id = '00000000-0000-0000-0000-000000000000'::uuid)
    or (p_expected_workflow_revision is not null
      and p_expected_workflow_revision not between 1 and 9007199254740991) then
    return false;
  end if;

  select binding.application_release_revision into provisioned_release_revision
  from vortex_definition.installation_bindings as binding
  where binding.organization_id = p_organization_id
    and binding.application_root_id = p_application_root_id
    and binding.state = 'provisioned'
    and binding.binding_revision = p_expected_binding_revision
    and p_storage_contract_id = any (binding.storage_contract_ids)
  order by binding.module_root_id
  limit 1
  for share;
  if not found then
    return false;
  end if;

  if p_workflow_id is null then
    return true;
  end if;

  -- There is no free-standing workflow revision in a compiled definition: the
  -- Application release revision is the workflow revision runtime pins.
  if provisioned_release_revision <> p_expected_workflow_revision then
    return false;
  end if;

  select true into matched
  from vortex_definition.releases as application_release
  join vortex_definition.roots as application_root
    on application_root.root_id = application_release.root_id
  where application_release.root_id = p_application_root_id
    and application_release.release_revision = provisioned_release_revision
    and application_root.organization_id = p_organization_id
    and application_root.kind = 'application'
    and application_release.compilation_output #>> '{kind}' = 'application'
    and application_release.compilation_output #>> '{canonical,envelope,rootId}'
      = p_application_root_id::text
    and application_release.compilation_output #>> '{validationContractVersion}'
      = application_release.validation_contract_version
    and exists (
      select 1
      from pg_catalog.jsonb_array_elements(
        case
          when pg_catalog.jsonb_typeof(
            application_release.compilation_output #> '{canonical,content,workflows}'
          ) = 'array'
            then application_release.compilation_output #> '{canonical,content,workflows}'
          else '[]'::jsonb
        end
      ) as workflow(value)
      where pg_catalog.jsonb_typeof(workflow.value) = 'object'
        and workflow.value ->> 'workflowId' = p_workflow_id::text
    )
  for share of application_release, application_root;

  return coalesce(matched, false);
end
$$;

COMMENT ON FUNCTION vortex_definition.record_lifecycle_provisioned_setup_target_internal(p_organization_id uuid, p_application_root_id uuid, p_expected_binding_revision bigint, p_storage_contract_id uuid, p_workflow_id uuid, p_expected_workflow_revision bigint) IS 'Private provisioned-setup installation fact for one exact Application binding revision and, optionally, one workflow of that exact immutable release; never used by the #566 administration save.';

REVOKE ALL ON FUNCTION vortex_definition.record_lifecycle_provisioned_setup_target_internal(p_organization_id uuid, p_application_root_id uuid, p_expected_binding_revision bigint, p_storage_contract_id uuid, p_workflow_id uuid, p_expected_workflow_revision bigint) FROM PUBLIC;
GRANT ALL ON FUNCTION vortex_definition.record_lifecycle_provisioned_setup_target_internal(p_organization_id uuid, p_application_root_id uuid, p_expected_binding_revision bigint, p_storage_contract_id uuid, p_workflow_id uuid, p_expected_workflow_revision bigint) TO vortex_owner;

CREATE OR REPLACE FUNCTION vortex_definition.record_lifecycle_target_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  matched boolean;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or (p_application_root_id is not null
      and p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid) then
    return false;
  end if;
  select true into matched
  from vortex_definition.installation_bindings as binding
  where binding.organization_id = p_organization_id
    and binding.state = 'active'
    and p_storage_contract_id = any (binding.storage_contract_ids)
    and (
      p_application_root_id is null
      or binding.application_root_id = p_application_root_id
    )
  limit 1
  for share;
  return coalesce(matched, false);
end
$$;

COMMENT ON FUNCTION vortex_definition.record_lifecycle_target_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid) IS 'Private installation fact for record lifecycle policy administration; shares the matching active installation binding for the transaction.';

REVOKE ALL ON FUNCTION vortex_definition.record_lifecycle_target_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid) FROM PUBLIC;
GRANT ALL ON FUNCTION vortex_definition.record_lifecycle_target_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid) TO vortex_owner;

CREATE OR REPLACE FUNCTION vortex_definition.record_lifecycle_workflow_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid, p_workflow_id uuid, p_expected_workflow_revision bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  active_release_revision bigint;
  matched boolean;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_workflow_id is null
    or p_workflow_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_expected_workflow_revision is null
    or p_expected_workflow_revision not between 1 and 9007199254740991 then
    return false;
  end if;

  select binding.application_release_revision into active_release_revision
  from vortex_definition.installation_bindings as binding
  where binding.organization_id = p_organization_id
    and binding.application_root_id = p_application_root_id
    and binding.state = 'active'
    and p_storage_contract_id = any (binding.storage_contract_ids)
  order by binding.module_root_id
  limit 1
  for share;
  if not found or active_release_revision <> p_expected_workflow_revision then
    return false;
  end if;

  select true into matched
  from vortex_definition.releases as application_release
  join vortex_definition.roots as application_root
    on application_root.root_id = application_release.root_id
  where application_release.root_id = p_application_root_id
    and application_release.release_revision = active_release_revision
    and application_root.organization_id = p_organization_id
    and application_root.kind = 'application'
    and application_release.compilation_output #>> '{kind}' = 'application'
    and application_release.compilation_output #>> '{canonical,envelope,rootId}'
      = p_application_root_id::text
    and application_release.compilation_output #>> '{validationContractVersion}'
      = application_release.validation_contract_version
    and exists (
      select 1
      from pg_catalog.jsonb_array_elements(
        case
          when pg_catalog.jsonb_typeof(
            application_release.compilation_output #> '{canonical,content,workflows}'
          ) = 'array'
            then application_release.compilation_output #> '{canonical,content,workflows}'
          else '[]'::jsonb
        end
      ) as workflow(value)
      where pg_catalog.jsonb_typeof(workflow.value) = 'object'
        and workflow.value ->> 'workflowId' = p_workflow_id::text
    )
  for share of application_release, application_root;

  return coalesce(matched, false);
end
$$;

COMMENT ON FUNCTION vortex_definition.record_lifecycle_workflow_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid, p_workflow_id uuid, p_expected_workflow_revision bigint) IS 'Private exact-active-Application workflow fact for record lifecycle policy administration; locks the matching installation and immutable Application release.';

REVOKE ALL ON FUNCTION vortex_definition.record_lifecycle_workflow_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid, p_workflow_id uuid, p_expected_workflow_revision bigint) FROM PUBLIC;
GRANT ALL ON FUNCTION vortex_definition.record_lifecycle_workflow_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid, p_workflow_id uuid, p_expected_workflow_revision bigint) TO vortex_owner;

create or replace function vortex_definition.remove_abandoned_runtime_bundles_internal(
  p_limit integer
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  abandoned_bundle_ttl constant interval := interval '7 days';
  maximum_batch_size constant integer := 100;
  candidate_key record;
  bundle_row vortex_definition.installation_runtime_bundles%rowtype;
  removed_bundle_keys jsonb := '[]'::jsonb;
  bundles_removed bigint := 0;
  bundle_parts_removed bigint := 0;
  access_plans_removed bigint := 0;
  orphaned_access_plans_removed bigint := 0;
  changed_rows bigint;
begin
  if p_limit is null or p_limit < 1 or p_limit > maximum_batch_size then
    raise exception using errcode = '22023',
      message = 'Runtime bundle cleanup batch is invalid';
  end if;

  for candidate_key in
    select bundle.organization_id, bundle.application_root_id,
      bundle.application_release_revision, bundle.bundle_format_version
    from vortex_definition.installation_runtime_bundles as bundle
    where not exists (
      select 1
      from vortex_definition.installation_bindings as binding
      where binding.organization_id = bundle.organization_id
        and binding.application_root_id = bundle.application_root_id
        and binding.application_release_revision = bundle.application_release_revision
        and binding.state in ('active', 'draining')
    )
      and (
        exists (
          select 1
          from vortex_definition.installation_bindings as later_binding
          where later_binding.organization_id = bundle.organization_id
            and later_binding.application_root_id = bundle.application_root_id
            and later_binding.application_release_revision > bundle.application_release_revision
            and later_binding.state in ('active', 'draining')
        )
        or (
          bundle.built_at <= pg_catalog.statement_timestamp() - abandoned_bundle_ttl
          and not exists (
            select 1
            from vortex_definition.installation_bindings as previous_binding
            where previous_binding.organization_id = bundle.organization_id
              and previous_binding.application_root_id = bundle.application_root_id
              and previous_binding.application_release_revision = bundle.application_release_revision
              and previous_binding.state = 'detached'
          )
        )
      )
    order by bundle.built_at, bundle.organization_id, bundle.application_root_id,
      bundle.application_release_revision, bundle.bundle_format_version
    limit p_limit
  loop
    perform 1
    from vortex_definition.installation_bindings as binding
    where binding.organization_id = candidate_key.organization_id
      and binding.application_root_id = candidate_key.application_root_id
    order by binding.module_root_id
    for update;

    select bundle.* into bundle_row
    from vortex_definition.installation_runtime_bundles as bundle
    where bundle.organization_id = candidate_key.organization_id
      and bundle.application_root_id = candidate_key.application_root_id
      and bundle.application_release_revision = candidate_key.application_release_revision
      and bundle.bundle_format_version = candidate_key.bundle_format_version
    for update of bundle skip locked;
    if not found then
      continue;
    end if;

    if exists (
      select 1
      from vortex_definition.installation_bindings as binding
      where binding.organization_id = bundle_row.organization_id
        and binding.application_root_id = bundle_row.application_root_id
        and binding.application_release_revision = bundle_row.application_release_revision
        and binding.state in ('active', 'draining')
    ) then
      continue;
    end if;

    if not exists (
        select 1
        from vortex_definition.installation_bindings as later_binding
        where later_binding.organization_id = bundle_row.organization_id
          and later_binding.application_root_id = bundle_row.application_root_id
          and later_binding.application_release_revision > bundle_row.application_release_revision
          and later_binding.state in ('active', 'draining')
      ) and (
        bundle_row.built_at > pg_catalog.statement_timestamp() - abandoned_bundle_ttl
        or exists (
          select 1
          from vortex_definition.installation_bindings as previous_binding
          where previous_binding.organization_id = bundle_row.organization_id
            and previous_binding.application_root_id = bundle_row.application_root_id
            and previous_binding.application_release_revision = bundle_row.application_release_revision
            and previous_binding.state = 'detached'
        )
      ) then
      continue;
    end if;

    delete from vortex_definition.installation_runtime_bundle_parts as part
    where part.organization_id = bundle_row.organization_id
      and part.application_root_id = bundle_row.application_root_id
      and part.application_release_revision = bundle_row.application_release_revision
      and part.bundle_format_version = bundle_row.bundle_format_version;
    get diagnostics changed_rows = row_count;
    bundle_parts_removed := bundle_parts_removed + changed_rows;

    delete from vortex_definition.installation_runtime_bundles as bundle
    where bundle.organization_id = bundle_row.organization_id
      and bundle.application_root_id = bundle_row.application_root_id
      and bundle.application_release_revision = bundle_row.application_release_revision
      and bundle.bundle_format_version = bundle_row.bundle_format_version;
    get diagnostics changed_rows = row_count;
    if changed_rows = 1 then
      bundles_removed := bundles_removed + 1;
      removed_bundle_keys := removed_bundle_keys || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'organizationId', bundle_row.organization_id,
          'applicationRootId', bundle_row.application_root_id,
          'applicationReleaseRevision', bundle_row.application_release_revision
        )
      );
    end if;
  end loop;

  delete from vortex_record.installation_access_plans as plan
  where plan.plan_key in (
    select candidate.plan_key
    from vortex_record.installation_access_plans as candidate
    where exists (
      select 1
      from pg_catalog.jsonb_array_elements(removed_bundle_keys) as removed(bundle_key)
      where (removed.bundle_key ->> 'organizationId')::uuid = candidate.organization_id
        and (removed.bundle_key ->> 'applicationRootId')::uuid = candidate.application_root_id
        and (removed.bundle_key ->> 'applicationReleaseRevision')::bigint =
          candidate.application_release_revision
    )
      and not exists (
        select 1
        from vortex_definition.installation_runtime_bundles as remaining
        where remaining.organization_id = candidate.organization_id
          and remaining.application_root_id = candidate.application_root_id
          and remaining.application_release_revision = candidate.application_release_revision
      )
      and not exists (
        select 1
        from vortex_definition.installation_bindings as binding
        where binding.organization_id = candidate.organization_id
          and binding.application_root_id = candidate.application_root_id
          and binding.application_release_revision = candidate.application_release_revision
          and binding.state in ('active', 'draining')
      )
    order by candidate.plan_key
    limit p_limit
  );
  get diagnostics changed_rows = row_count;
  access_plans_removed := access_plans_removed + changed_rows;

  delete from vortex_record.installation_access_plans as plan
  where plan.plan_key in (
    select candidate.plan_key
    from vortex_record.installation_access_plans as candidate
    where candidate.created_at <= pg_catalog.statement_timestamp() - abandoned_bundle_ttl
      and not exists (
        select 1
        from vortex_definition.installation_runtime_bundles as bundle
        where bundle.organization_id = candidate.organization_id
          and bundle.application_root_id = candidate.application_root_id
          and bundle.application_release_revision = candidate.application_release_revision
      )
      and not exists (
        select 1
        from vortex_definition.installation_bindings as binding
        where binding.organization_id = candidate.organization_id
          and binding.application_root_id = candidate.application_root_id
          and binding.application_release_revision = candidate.application_release_revision
          and binding.state in ('active', 'draining')
      )
    order by candidate.plan_key
    limit p_limit
  );
  get diagnostics changed_rows = row_count;
  orphaned_access_plans_removed := changed_rows;

  return pg_catalog.jsonb_build_object(
    'bundlesRemoved', bundles_removed,
    'bundlePartsRemoved', bundle_parts_removed,
    'accessPlansRemoved', access_plans_removed,
    'orphanedAccessPlansRemoved', orphaned_access_plans_removed
  );
end
$function$;

comment on function vortex_definition.remove_abandoned_runtime_bundles_internal(integer) is
  'Removes one bounded batch of expired never-activated or superseded runtime bundles and orphaned access plans.';

create or replace function vortex_definition.remove_installation_runtime_bundles_internal(
  p_application_root_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  authority record;
  bundle_list jsonb;
  bundles_removed bigint;
  bundle_parts_removed bigint;
  access_plans_removed bigint;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023',
      message = 'Runtime bundle uninstall command is invalid';
  end if;

  select locked.* into strict authority
  from vortex_access.lock_application_installation_authority() as locked;

  if not exists (
    select 1
    from vortex_definition.roots as root
    where root.root_id = p_application_root_id
      and root.organization_id = authority.organization_id
      and root.kind = 'application'
  ) then
    raise exception using errcode = 'P0002',
      message = 'Application installation is unavailable';
  end if;

  perform 1
  from vortex_definition.installation_bindings as binding
  where binding.organization_id = authority.organization_id
    and binding.application_root_id = p_application_root_id
  order by binding.module_root_id
  for update;

  if exists (
    select 1
    from vortex_definition.installation_bindings as binding
    where binding.organization_id = authority.organization_id
      and binding.application_root_id = p_application_root_id
      and binding.state in ('active', 'draining')
  ) then
    raise exception using errcode = '40001',
      message = 'Runtime bundles cannot be removed before installation drain completes';
  end if;

  delete from vortex_definition.installation_runtime_bundle_parts as part
  where part.organization_id = authority.organization_id
    and part.application_root_id = p_application_root_id;
  get diagnostics bundle_parts_removed = row_count;

  with removed_bundles as (
    delete from vortex_definition.installation_runtime_bundles as bundle
    where bundle.organization_id = authority.organization_id
      and bundle.application_root_id = p_application_root_id
    returning bundle.application_release_revision, bundle.bundle_format_version
  )
  select coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'applicationReleaseRevision', removed.application_release_revision,
          'bundleFormatVersion', removed.bundle_format_version
        ) order by removed.application_release_revision, removed.bundle_format_version
      ),
      '[]'::jsonb
    ),
    pg_catalog.count(*)
  into bundle_list, bundles_removed
  from removed_bundles as removed;

  delete from vortex_record.installation_access_plans as plan
  where plan.organization_id = authority.organization_id
    and plan.application_root_id = p_application_root_id;
  get diagnostics access_plans_removed = row_count;

  return pg_catalog.jsonb_build_object(
    'bundles', bundle_list,
    'bundlePartsRemoved', bundle_parts_removed,
    'accessPlansRemoved', access_plans_removed
  );
end
$function$;

comment on function vortex_definition.remove_installation_runtime_bundles_internal(uuid) is
  'Lists and removes all runtime bundle registrations and access plans for one authorised installation after its bindings are detached.';

create or replace function vortex_definition.repair_active_installation_runtime_bundle_internal(
  p_expected_identity jsonb,
  p_parts jsonb
)
returns jsonb language plpgsql volatile security definer set search_path=''
as $function$
declare

  expected_sections constant text[] := array[
    'pages', 'navigation', 'flows', 'trigger_index', 'theme', 'component_registry',
    'access_plan', 'tool_bundle'
  ];
  checked_context jsonb;
  selected_organization_id uuid;
  part_item jsonb;
  section_value text;
  ordinal_value bigint;
  byte_size_value bigint;
  content_text text;
  content_bytes bytea;
  sha256_value text;
  total_size_value bigint := 0;
  parts_manifest jsonb;
  inserted_rows bigint;
  stored_bundle vortex_definition.installation_runtime_bundles%rowtype;
  source_manifest jsonb;
  section_payloads jsonb := '{}'::jsonb;
  section_text text;
  application_content jsonb;
  expected_modules jsonb;
  expected_trigger_index jsonb;
  expected_access_plan jsonb;
  p_application_root_id uuid;
  p_application_release_revision bigint;
  p_bundle_format_version integer:=2;
  p_pin_fingerprint text;
  active_source jsonb;
  mapping jsonb;
  final_mapping jsonb;
  stable_plan jsonb;
begin
  if pg_catalog.jsonb_typeof(p_expected_identity) is distinct from 'object'
    or pg_catalog.jsonb_typeof(p_parts) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_parts)<pg_catalog.cardinality(expected_sections) then
    raise exception using errcode='22023', message='Active runtime repair command is invalid';
  end if;
  -- This current HUMAN viewer path deliberately has no installation/manage
  -- decision, delegated installer scope or provisioned-binding authority.
  mapping:=vortex_definition.lock_active_installation_runtime_mapping_internal(p_expected_identity);
  stable_plan:=vortex_record.resolve_active_bundle_record_access_plan_internal(p_expected_identity);
  p_application_root_id:=(mapping #>> '{identity,applicationRootId}')::uuid;
  p_application_release_revision:=(mapping #>> '{identity,applicationReleaseRevision}')::bigint;
  p_pin_fingerprint:=mapping #>> '{identity,pinFingerprint}';
  selected_organization_id:=(mapping #>> '{identity,organizationId}')::uuid;
  active_source:=pg_catalog.jsonb_build_object(
    'organizationId',mapping #> '{identity,organizationId}',
    'applicationRootId',mapping #> '{identity,applicationRootId}',
    'applicationReleaseRevision',mapping #> '{identity,applicationReleaseRevision}',
    'pinFingerprint',mapping #> '{identity,pinFingerprint}',
    'application',mapping -> 'application','modules',mapping -> 'modules',
    'preparedRecordAccessPlan',stable_plan);
  -- Exclusive bundle lock follows already-held binding and storage locks.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'vortex_definition.runtime_bundle:' || selected_organization_id::text || ':' ||
      p_application_root_id::text || ':' || p_application_release_revision::text || ':2',0));
  final_mapping:=vortex_definition.lock_active_installation_runtime_mapping_internal(p_expected_identity);
  if final_mapping is distinct from mapping then
    raise exception using errcode='40001', message='Active runtime repair changed while waiting';
  end if;
  source_manifest := pg_catalog.jsonb_build_object(
    'bundleFormatVersion', 2,
    'application', pg_catalog.jsonb_build_object(
      'rootId', active_source #> '{application,rootId}',
      'definitionKey', active_source #> '{application,key}',
      'releaseRevision', active_source #> '{application,releaseRevision}',
      'releaseVersion', active_source #> '{application,releaseVersion}',
      'validationContractVersion', active_source #> '{application,validationContractVersion}',
      'contentFingerprint', active_source #> '{application,contentFingerprint}',
      'resolutionFingerprint', active_source #> '{application,resolutionFingerprint}'
    ),
    'modules', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'rootId', module.value -> 'rootId',
          'definitionKey', module.value -> 'key',
          'releaseRevision', module.value -> 'releaseRevision',
          'releaseVersion', module.value -> 'releaseVersion',
          'validationContractVersion', module.value -> 'validationContractVersion',
          'contentFingerprint', module.value -> 'contentFingerprint',
          'resolutionFingerprint', module.value -> 'resolutionFingerprint'
        ) order by (module.value ->> 'rootId') collate "C")
      from pg_catalog.jsonb_array_elements(active_source -> 'modules') as module(value)
    ), '[]'::jsonb),
    'pinFingerprint', active_source -> 'pinFingerprint',
    'preparedRecordAccessPlan', pg_catalog.jsonb_build_object(
      'planKey', active_source #> '{preparedRecordAccessPlan,planKey}',
      'mappingFingerprint', active_source #> '{preparedRecordAccessPlan,mappingFingerprint}'
    )
  );
  for section_value in
    select required.section
    from pg_catalog.unnest(expected_sections) as required(section)
  loop
    select pg_catalog.string_agg(item.value ->> 'content', '' order by
      (item.value ->> 'ordinal')::integer)
    into section_text
    from pg_catalog.jsonb_array_elements(p_parts) as item(value)
    where item.value ->> 'section' = section_value;
    if section_text is null then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle section is unavailable';
    end if;
    begin
      section_payloads := section_payloads || pg_catalog.jsonb_build_object(
        section_value, section_text::jsonb
      );
    exception when others then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle section is invalid';
    end;
  end loop;
  application_content := active_source #> '{application,compilationOutput,canonical,content}';
  if application_content is null then
    raise exception using errcode = '55000',
      message = 'Installation runtime bundle Application content is unavailable';
  end if;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'identity', pg_catalog.jsonb_build_object(
        'kind', module.value -> 'kind',
        'organizationId', module.value -> 'organizationId',
        'rootId', module.value -> 'rootId',
        'definitionKey', module.value -> 'key',
        'releaseRevision', module.value -> 'releaseRevision',
        'releaseVersion', module.value -> 'releaseVersion',
        'validationContractVersion', module.value -> 'validationContractVersion',
        'contentFingerprint', module.value -> 'contentFingerprint',
        'resolutionFingerprint', module.value -> 'resolutionFingerprint',
        'dependencyManifest', module.value -> 'dependencyManifest'
      ),
      'content', module.value #> '{compilationOutput,canonical,content}'
    ) order by (module.value ->> 'rootId') collate "C"), '[]'::jsonb)
  into expected_modules
  from pg_catalog.jsonb_array_elements(active_source -> 'modules') as module(value);
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'flowId', flow.value -> 'id', 'trigger', trigger.value
    ) order by (flow.value ->> 'id') collate "C", (trigger.value ->> 'id') collate "C"), '[]'::jsonb)
  into expected_trigger_index
  from pg_catalog.jsonb_array_elements(application_content -> 'flows') as flow(value)
  cross join lateral pg_catalog.jsonb_array_elements(flow.value -> 'triggers') as trigger(value);
  select pg_catalog.jsonb_build_object(
    'preparedRecordAccessPlan', active_source -> 'preparedRecordAccessPlan',
    'declaredPermissions', pg_catalog.jsonb_build_object(
      'application', application_content -> 'permissions',
      'modules', coalesce((
        select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'rootId', module.value -> 'rootId',
            'permissions', module.value #> '{compilationOutput,canonical,content,permissions}'
          ) order by (module.value ->> 'rootId') collate "C")
        from pg_catalog.jsonb_array_elements(active_source -> 'modules') as module(value)
      ), '[]'::jsonb)
    )
  ) into expected_access_plan;
  if section_payloads -> 'navigation' is distinct from application_content -> 'navigation'
    or section_payloads -> 'flows' is distinct from pg_catalog.jsonb_build_object(
      'flows', application_content -> 'flows',
      'flowBindings', application_content -> 'flowBindings'
    )
    or section_payloads -> 'trigger_index' is distinct from expected_trigger_index
    or section_payloads -> 'theme' is distinct from application_content -> 'theme'
    or section_payloads -> 'component_registry' is distinct from application_content -> 'platformBlockDependencies'
    or section_payloads -> 'tool_bundle' is distinct from active_source #> '{application,compilationOutput,toolBundle}'
    or section_payloads -> 'access_plan' is distinct from expected_access_plan
    or section_payloads #> '{pages,application,identity}' is distinct from (
      pg_catalog.jsonb_build_object(
        'kind', active_source #> '{application,kind}',
        'organizationId', active_source #> '{application,organizationId}',
        'rootId', active_source #> '{application,rootId}',
        'definitionKey', active_source #> '{application,key}',
        'releaseRevision', active_source #> '{application,releaseRevision}',
        'releaseVersion', active_source #> '{application,releaseVersion}',
        'validationContractVersion', active_source #> '{application,validationContractVersion}',
        'contentFingerprint', active_source #> '{application,contentFingerprint}',
        'resolutionFingerprint', active_source #> '{application,resolutionFingerprint}',
        'dependencyManifest', active_source #> '{application,dependencyManifest}'
      )
      || case
        when active_source #> '{application,compilationOutput,platformCompatibilityVersion}' is null
          then '{}'::jsonb
        else pg_catalog.jsonb_build_object(
          'platformCompatibilityVersion',
          active_source #> '{application,compilationOutput,platformCompatibilityVersion}'
        )
      end
    )
    or section_payloads #> '{pages,application,content}' is distinct from
      application_content - array[
        'navigation', 'flows', 'flowBindings', 'theme',
        'platformBlockDependencies', 'shells', 'pages'
      ]::text[]
    or section_payloads #> '{pages,application,shells}' is distinct from application_content -> 'shells'
    or section_payloads #> '{pages,application,pages}' is distinct from application_content -> 'pages'
    or section_payloads #> '{pages,modules}' is distinct from expected_modules
    or pg_catalog.jsonb_typeof(section_payloads #> '{pages,resolvedCompositions}') is distinct from 'array'
    or pg_catalog.jsonb_array_length(section_payloads #> '{pages,resolvedCompositions}') <>
      pg_catalog.jsonb_array_length(application_content -> 'pages') then
    raise exception using errcode = '23514',
      message = 'Installation runtime bundle sections do not match current immutable source';
  end if;
  for part_item in
    select item.value from pg_catalog.jsonb_array_elements(p_parts) as item(value)
  loop
    if pg_catalog.jsonb_typeof(part_item) is distinct from 'object' then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part is invalid';
    end if;
    if not (part_item ?& array['section', 'ordinal', 'byteSize', 'sha256', 'content'])
      or part_item - array['section', 'ordinal', 'byteSize', 'sha256', 'content'] <> '{}'::jsonb
      or pg_catalog.jsonb_typeof(part_item -> 'section') is distinct from 'string'
      or pg_catalog.jsonb_typeof(part_item -> 'ordinal') is distinct from 'number'
      or pg_catalog.jsonb_typeof(part_item -> 'byteSize') is distinct from 'number'
      or pg_catalog.jsonb_typeof(part_item -> 'sha256') is distinct from 'string'
      or pg_catalog.jsonb_typeof(part_item -> 'content') is distinct from 'string' then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part is invalid';
    end if;

    section_value := part_item ->> 'section';
    if not (section_value = any (expected_sections))
      or (part_item ->> 'ordinal') !~ '^(0|[1-9][0-9]*)$'
      or pg_catalog.length(part_item ->> 'ordinal') > 10
      or (part_item ->> 'byteSize') !~ '^[1-9][0-9]*$'
      or pg_catalog.length(part_item ->> 'byteSize') > 7 then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part is invalid';
    end if;
    ordinal_value := (part_item ->> 'ordinal')::bigint;
    byte_size_value := (part_item ->> 'byteSize')::bigint;
    content_text := part_item ->> 'content';
    if ordinal_value > 2147483647 or byte_size_value > 1048575 then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part exceeds its limit';
    end if;

    content_bytes := pg_catalog.convert_to(content_text, 'UTF8');
    if pg_catalog.octet_length(content_bytes) <> byte_size_value then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part size is invalid';
    end if;
    sha256_value := 'sha256:' || pg_catalog.encode(
      extensions.digest(content_bytes, 'sha256'), 'hex'
    );
    if (part_item ->> 'sha256') !~ '^sha256:[a-f0-9]{64}$'
      or sha256_value <> (part_item ->> 'sha256') then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part fingerprint is invalid';
    end if;
    total_size_value := total_size_value + byte_size_value;
    if total_size_value > 9007199254740991 then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle is too large';
    end if;
  end loop;

  if exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_parts) as item(value)
      group by item.value ->> 'section', (item.value ->> 'ordinal')::integer
      having pg_catalog.count(*) > 1
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_parts) as item(value)
      group by item.value ->> 'section'
      having pg_catalog.min((item.value ->> 'ordinal')::integer) <> 0
        or pg_catalog.max((item.value ->> 'ordinal')::integer) <>
          pg_catalog.count(*) - 1
    )
    or exists (
      select 1
      from pg_catalog.unnest(expected_sections) as required(section)
      where not exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_parts) as item(value)
        where item.value ->> 'section' = required.section
      )
    ) then
    raise exception using errcode = '22023',
      message = 'Installation runtime bundle sections are incomplete';
  end if;

  select pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'section', item.value ->> 'section',
      'ordinal', (item.value ->> 'ordinal')::integer,
      'byteSize', (item.value ->> 'byteSize')::bigint,
      'sha256', item.value ->> 'sha256'
    ) order by pg_catalog.array_position(
      expected_sections, item.value ->> 'section'
    ), (item.value ->> 'ordinal')::integer
  )
  into parts_manifest
  from pg_catalog.jsonb_array_elements(p_parts) as item(value);

  insert into vortex_definition.installation_runtime_bundles (
    organization_id, application_root_id, application_release_revision,
    bundle_format_version, pin_fingerprint, source_manifest, parts, total_size_bytes
  ) values (
    selected_organization_id, p_application_root_id, p_application_release_revision,
    p_bundle_format_version, p_pin_fingerprint, source_manifest, parts_manifest, total_size_value
  ) on conflict (
    organization_id, application_root_id, application_release_revision, bundle_format_version
  ) do nothing;
  get diagnostics inserted_rows = row_count;

  if inserted_rows = 0 then
    select stored.* into stored_bundle
    from vortex_definition.installation_runtime_bundles as stored
    where stored.organization_id = selected_organization_id
      and stored.application_root_id = p_application_root_id
      and stored.application_release_revision = p_application_release_revision
      and stored.bundle_format_version = p_bundle_format_version;
    if not found then
      raise exception using errcode = '40001',
        message = 'Installation runtime bundle changed concurrently';
    end if;
    if stored_bundle.pin_fingerprint <> p_pin_fingerprint
      or stored_bundle.source_manifest is distinct from source_manifest
      or stored_bundle.parts is distinct from parts_manifest
      or stored_bundle.total_size_bytes is distinct from total_size_value
      or (select pg_catalog.count(*) from vortex_definition.installation_runtime_bundle_parts as part
        where part.organization_id = selected_organization_id
          and part.application_root_id = p_application_root_id
          and part.application_release_revision = p_application_release_revision
          and part.bundle_format_version = p_bundle_format_version)
        <> pg_catalog.jsonb_array_length(p_parts)
      or exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_parts) as item(value)
        left join vortex_definition.installation_runtime_bundle_parts as part
          on part.organization_id = selected_organization_id
          and part.application_root_id = p_application_root_id
          and part.application_release_revision = p_application_release_revision
          and part.bundle_format_version = p_bundle_format_version
          and part.section = item.value ->> 'section'
          and part.ordinal = (item.value ->> 'ordinal')::integer
        where part.content_bytes is distinct from pg_catalog.convert_to(item.value ->> 'content', 'UTF8')
      ) then
      raise exception using errcode = '23505',
        message = 'Installation runtime bundle pin fingerprint differs';
    end if;
  else
    for part_item in
      select item.value from pg_catalog.jsonb_array_elements(p_parts) as item(value)
    loop
      insert into vortex_definition.installation_runtime_bundle_parts (
        organization_id, application_root_id, application_release_revision,
        bundle_format_version, section, ordinal, content_bytes
      ) values (
        selected_organization_id, p_application_root_id, p_application_release_revision,
        p_bundle_format_version, part_item ->> 'section',
        (part_item ->> 'ordinal')::integer,
        pg_catalog.convert_to(part_item ->> 'content', 'UTF8')
      );
    end loop;

    select stored.* into strict stored_bundle
    from vortex_definition.installation_runtime_bundles as stored
    where stored.organization_id = selected_organization_id
      and stored.application_root_id = p_application_root_id
      and stored.application_release_revision = p_application_release_revision
      and stored.bundle_format_version = p_bundle_format_version;
  end if;

  final_mapping:=vortex_definition.lock_active_installation_runtime_mapping_internal(p_expected_identity);
  if final_mapping is distinct from mapping then
    raise exception using errcode='40001', message='Active runtime repair identity changed';
  end if;
  return pg_catalog.jsonb_build_object(
    'organizationId', stored_bundle.organization_id,
    'applicationRootId', stored_bundle.application_root_id,
    'applicationReleaseRevision', stored_bundle.application_release_revision,
    'bundleFormatVersion', stored_bundle.bundle_format_version,
    'pinFingerprint', stored_bundle.pin_fingerprint,
    'sourceManifest', stored_bundle.source_manifest,
    'parts', stored_bundle.parts,
    'totalSizeBytes', stored_bundle.total_size_bytes,
    'builtAt', stored_bundle.built_at
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Installation runtime bundle evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Installation runtime bundle evidence is ambiguous';
end
$function$;

comment on function vortex_definition.repair_active_installation_runtime_bundle_internal(jsonb,jsonb) is 'Atomically repairs only the current active immutable format2 bundle under a current HUMAN viewer transaction, with complete source and byte replay equality and no installation authority.';

create or replace function vortex_definition.resolve_addressed_active_application_identity(p_application_key text)
returns jsonb language plpgsql volatile security definer set search_path=''
as $function$
declare
  checked_context jsonb;
  final_context jsonb;
  selected_root uuid;
  installation jsonb;
  registered_app record;
begin
  if p_application_key is null or pg_catalog.length(p_application_key) not between 3 and 120
    or p_application_key !~ '^[a-z][a-z0-9]*(_[a-z0-9]+)*(\.[a-z][a-z0-9]*(_[a-z0-9]+)*)+$' or exists(select 1 from pg_catalog.unnest(pg_catalog.string_to_array(p_application_key,'.')) as segment(value) where pg_catalog.length(segment.value)>40) then
    raise exception using errcode='22023', message='Application address is invalid';
  end if;
  checked_context:=vortex_access.validated_human_request_context();
  if checked_context ->> 'callerKind' is distinct from 'human'
    or checked_context ? 'applicationRootId'
    or pg_catalog.clock_timestamp()>=(checked_context ->> 'expiresAt')::timestamptz
    or (checked_context ? 'delegatedContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{delegatedContext,expiresAt}')::timestamptz)
    or (checked_context ? 'supportContext' and
      pg_catalog.clock_timestamp()>=(checked_context #>> '{supportContext,expiresAt}')::timestamptz) then
    raise exception using errcode='42501', message='Application address is unavailable';
  end if;
  select root.root_id into strict selected_root from vortex_definition.roots as root
  where root.organization_id=(checked_context ->> 'organizationId')::uuid
    and root.kind='application' and root.key=p_application_key;
  installation:=vortex_definition.read_active_installation_for_scope_internal(
    (checked_context ->> 'organizationId')::uuid,selected_root);
  select snapshot.* into strict registered_app
  from vortex_access.read_application_permission_snapshot(
    (checked_context ->> 'organizationId')::uuid,selected_root) as snapshot;
  if registered_app.release_revision is distinct from (installation ->> 'applicationReleaseRevision')::bigint
    or registered_app.definition_key is distinct from p_application_key
    or exists(select 1 from vortex_definition.installation_bindings as binding
      where binding.organization_id=(checked_context ->> 'organizationId')::uuid
        and binding.application_root_id=selected_root and binding.state not in ('active','detached')) then
    raise exception using errcode='40001', message='Application address changed';
  end if;
  final_context:=vortex_access.validated_human_request_context();
  if final_context is distinct from checked_context
    or pg_catalog.clock_timestamp()>=(final_context ->> 'expiresAt')::timestamptz
    or (final_context ? 'delegatedContext' and pg_catalog.clock_timestamp()>=(final_context #>> '{delegatedContext,expiresAt}')::timestamptz)
    or (final_context ? 'supportContext' and pg_catalog.clock_timestamp()>=(final_context #>> '{supportContext,expiresAt}')::timestamptz) then
    raise exception using errcode='40001', message='Application address context changed';
  end if;
  return pg_catalog.jsonb_build_object(
    'organizationId',checked_context -> 'organizationId','applicationRootId',selected_root,
    'definitionKey',p_application_key,'applicationReleaseRevision',installation -> 'applicationReleaseRevision');
exception when no_data_found or too_many_rows then
  raise exception using errcode='P0002', message='Application address is unavailable';
end
$function$;

comment on function vortex_definition.resolve_addressed_active_application_identity(text) is 'Returns one exact active Application address under the current HUMAN organization request, without a Page grant.';

CREATE OR REPLACE FUNCTION vortex_definition.storage_conversion_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid, p_module_root_id uuid, p_module_release_revision bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  matched boolean;
begin
  if p_organization_id is null
    or p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_storage_contract_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_module_root_id is null
    or p_module_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_module_release_revision is null
    or p_module_release_revision not between 1 and 9007199254740991
    or (p_application_root_id is not null
      and p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid) then
    return false;
  end if;
  select true into matched
  from vortex_definition.installation_bindings as binding
  where binding.organization_id = p_organization_id
    and binding.state = 'active'
    and binding.module_root_id = p_module_root_id
    and binding.module_release_revision = p_module_release_revision
    and p_storage_contract_id = any (binding.storage_contract_ids)
    and (
      p_application_root_id is null
      or binding.application_root_id = p_application_root_id
    )
  order by binding.application_root_id
  limit 1
  for share;
  return coalesce(matched, false);
end
$$;

COMMENT ON FUNCTION vortex_definition.storage_conversion_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid, p_module_root_id uuid, p_module_release_revision bigint) IS 'Private installation fact for storage conversion: shares the active installation of the exact Module release that installs the storage contract in this organisation scope.';

REVOKE ALL ON FUNCTION vortex_definition.storage_conversion_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid, p_module_root_id uuid, p_module_release_revision bigint) FROM PUBLIC;
GRANT ALL ON FUNCTION vortex_definition.storage_conversion_is_installed_internal(p_organization_id uuid, p_application_root_id uuid, p_storage_contract_id uuid, p_module_root_id uuid, p_module_release_revision bigint) TO vortex_owner;

create or replace function vortex_definition.update_private_form_draft(
  p_draft_id uuid,
  p_expected_revision bigint,
  p_form_id uuid,
  p_flow_id uuid,
  p_node_id uuid,
  p_subject_record_id uuid,
  p_field_values jsonb,
  p_validation_state jsonb
)
returns table (outcome text, result jsonb)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  scope record;
  stored vortex_definition.form_drafts%rowtype;
  touched_at timestamptz;
begin
  if p_draft_id is null or not vortex_platform.is_non_nil_uuid(p_draft_id::text)
    or p_expected_revision is null
    or p_expected_revision not between 1 and 9007199254740991
    or p_form_id is null or not vortex_platform.is_non_nil_uuid(p_form_id::text)
    or (p_flow_id is not null and not vortex_platform.is_non_nil_uuid(p_flow_id::text))
    or (p_node_id is not null and not vortex_platform.is_non_nil_uuid(p_node_id::text))
    or (p_subject_record_id is not null
      and not vortex_platform.is_non_nil_uuid(p_subject_record_id::text))
    or not vortex_definition.private_form_draft_values_are_valid(p_field_values)
    or not vortex_definition.private_form_draft_validation_is_valid(p_validation_state) then
    raise exception using errcode = '22023',
      message = 'Private form draft update command is invalid';
  end if;

  select context.* into strict scope
  from vortex_definition.private_form_draft_context_internal() as context;

  -- Another person's draft is never locked and is indistinguishable from a
  -- missing one.
  select draft.* into stored
  from vortex_definition.form_drafts as draft
  where draft.draft_id = p_draft_id
    and draft.organization_id = scope.organization_id
    and draft.organization_account_id = scope.organization_account_id
    and draft.identity_id = scope.identity_id
    and draft.application_root_id = scope.application_root_id
  for update;
  if not found
    or stored.expires_at <= pg_catalog.clock_timestamp()
    or stored.form_id <> p_form_id
    or stored.flow_id is distinct from p_flow_id
    or stored.node_id is distinct from p_node_id
    or stored.subject_record_id is distinct from p_subject_record_id then
    return query select 'unavailable'::text, null::jsonb;
    return;
  end if;

  if stored.installation_release_revision <> scope.release_revision then
    return query select 'stale_installation'::text, null::jsonb;
    return;
  end if;

  if stored.revision <> p_expected_revision then
    return query select 'stale_revision'::text, null::jsonb;
    return;
  end if;

  touched_at := pg_catalog.clock_timestamp();
  update vortex_definition.form_drafts as draft
  set field_values = p_field_values,
      validation_state = p_validation_state,
      revision = draft.revision + 1,
      updated_at = touched_at,
      expires_at = vortex_definition.private_form_draft_expiry_internal(touched_at)
  where draft.draft_id = p_draft_id
  returning * into stored;

  return query select 'updated'::text,
    vortex_definition.private_form_draft_to_json_internal(stored, 'active');
end
$function$;

comment on function vortex_definition.update_private_form_draft(uuid, bigint, uuid, uuid, uuid, uuid, jsonb, jsonb) is
  'Compare-and-updates one exact owned live private form draft at its current revision, refusing a stale revision or replaced installation.';

alter function vortex_definition.update_private_form_draft(uuid, bigint, uuid, uuid, uuid, uuid, jsonb, jsonb)
  owner to vortex_owner;

create or replace function vortex_definition.write_installation_runtime_bundle_internal(
  p_application_root_id uuid,
  p_application_release_revision bigint,
  p_bundle_format_version integer,
  p_pin_fingerprint text,
  p_parts jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  expected_sections constant text[] := array[
    'pages', 'navigation', 'flows', 'trigger_index', 'theme', 'component_registry',
    'access_plan', 'tool_bundle'
  ];
  permission_decision record;
  delegation_decision record;
  checked_context jsonb;
  selected_organization_id uuid;
  part_item jsonb;
  section_value text;
  ordinal_value bigint;
  byte_size_value bigint;
  content_text text;
  content_bytes bytea;
  sha256_value text;
  total_size_value bigint := 0;
  parts_manifest jsonb;
  inserted_rows bigint;
  stored_bundle vortex_definition.installation_runtime_bundles%rowtype;
  expected_module_bindings jsonb;
  prepared_source jsonb;
  source_manifest jsonb;
  section_payloads jsonb := '{}'::jsonb;
  section_text text;
  application_content jsonb;
  expected_modules jsonb;
  expected_trigger_index jsonb;
  expected_access_plan jsonb;
begin
  if p_application_root_id is null
    or p_application_root_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_application_release_revision is null
    or p_application_release_revision not between 1 and 9007199254740991
    or p_bundle_format_version is distinct from 2
    or p_pin_fingerprint is null or p_pin_fingerprint !~ '^sha256:[a-f0-9]{64}$'
    or p_parts is null or pg_catalog.jsonb_typeof(p_parts) is distinct from 'array' then
    raise exception using errcode = '22023',
      message = 'Installation runtime bundle command is invalid';
  end if;
  if pg_catalog.jsonb_array_length(p_parts) < pg_catalog.cardinality(expected_sections) then
    raise exception using errcode = '22023',
      message = 'Installation runtime bundle command is invalid';
  end if;

  select evaluated.* into strict permission_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  ) as evaluated;
  if permission_decision.outcome is distinct from 'eligible' then
    raise exception using errcode = '42501',
      message = 'Module installation authority is unavailable';
  end if;

  select evaluated.* into strict delegation_decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', 'platform.organization.applications.install_scope',
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        'permissionId', '7ecd3304-f16c-47d4-94db-0964980091ba'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object(
        'kind', 'delegated_management',
        'before', pg_catalog.jsonb_build_object('kind', 'organization_catalogue'),
        'after', pg_catalog.jsonb_build_object('kind', 'organization_catalogue')
      )
    )
  ) as evaluated;
  if delegation_decision.outcome is distinct from 'eligible'
    or delegation_decision.organization_id <> permission_decision.organization_id
    or delegation_decision.organization_account_id <> permission_decision.organization_account_id
    or delegation_decision.access_version <> permission_decision.access_version
    or delegation_decision.correlation_id <> permission_decision.correlation_id then
    raise exception using errcode = '42501',
      message = 'Module installation delegation is unavailable';
  end if;

  checked_context := vortex_access.validated_human_request_context();
  if (checked_context ->> 'organizationId')::uuid <> permission_decision.organization_id
    or (checked_context ->> 'organizationAccountId')::uuid <>
      permission_decision.organization_account_id
    or (checked_context ->> 'accessVersion')::bigint <> permission_decision.access_version
    or (checked_context ->> 'correlationId')::uuid <> permission_decision.correlation_id then
    raise exception using errcode = '40001',
      message = 'Module installation context changed';
  end if;
  selected_organization_id := permission_decision.organization_id;

  if not exists (
    select 1
    from vortex_definition.roots as root
    join vortex_definition.releases as release
      on release.root_id = root.root_id
      and release.release_revision = p_application_release_revision
    where root.root_id = p_application_root_id
      and root.organization_id = selected_organization_id
      and root.kind = 'application'
      and release.validation_contract_version = any (
        vortex_definition.accepted_contract_version('application')
      )
      and release.compilation_output #>> '{kind}' = 'application'
      and release.compilation_output #>> '{canonical,envelope,rootId}' =
        p_application_root_id::text
      and release.compilation_output #>> '{validationContractVersion}' = any (
        vortex_definition.accepted_contract_version('application')
      )
  ) then
    raise exception using errcode = 'P0002',
      message = 'Installation Application release is unavailable';
  end if;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'moduleRootId', binding.module_root_id,
      'moduleReleaseRevision', binding.module_release_revision,
      'bindingRevision', binding.binding_revision,
      'state', binding.state
    ) order by binding.module_root_id), '[]'::jsonb)
  into expected_module_bindings
  from vortex_definition.installation_bindings as binding
  where binding.organization_id = selected_organization_id
    and binding.application_root_id = p_application_root_id
    and binding.state = 'provisioned';
  prepared_source := vortex_definition.read_prepared_installation_runtime_source(
    p_application_root_id,
    p_application_release_revision,
    expected_module_bindings
  );
  if prepared_source is null
    or (prepared_source ->> 'organizationId')::uuid is distinct from selected_organization_id
    or (prepared_source ->> 'applicationRootId')::uuid is distinct from p_application_root_id
    or (prepared_source ->> 'applicationReleaseRevision')::bigint is distinct from p_application_release_revision
    or prepared_source ->> 'pinFingerprint' is distinct from p_pin_fingerprint then
    raise exception using errcode = '40001',
      message = 'Installation runtime bundle source changed';
  end if;
  source_manifest := pg_catalog.jsonb_build_object(
    'bundleFormatVersion', 2,
    'application', pg_catalog.jsonb_build_object(
      'rootId', prepared_source #> '{application,rootId}',
      'definitionKey', prepared_source #> '{application,key}',
      'releaseRevision', prepared_source #> '{application,releaseRevision}',
      'releaseVersion', prepared_source #> '{application,releaseVersion}',
      'validationContractVersion', prepared_source #> '{application,validationContractVersion}',
      'contentFingerprint', prepared_source #> '{application,contentFingerprint}',
      'resolutionFingerprint', prepared_source #> '{application,resolutionFingerprint}'
    ),
    'modules', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'rootId', module.value -> 'rootId',
          'definitionKey', module.value -> 'key',
          'releaseRevision', module.value -> 'releaseRevision',
          'releaseVersion', module.value -> 'releaseVersion',
          'validationContractVersion', module.value -> 'validationContractVersion',
          'contentFingerprint', module.value -> 'contentFingerprint',
          'resolutionFingerprint', module.value -> 'resolutionFingerprint'
        ) order by (module.value ->> 'rootId') collate "C")
      from pg_catalog.jsonb_array_elements(prepared_source -> 'modules') as module(value)
    ), '[]'::jsonb),
    'pinFingerprint', prepared_source -> 'pinFingerprint',
    'preparedRecordAccessPlan', pg_catalog.jsonb_build_object(
      'planKey', prepared_source #> '{preparedRecordAccessPlan,planKey}',
      'mappingFingerprint', prepared_source #> '{preparedRecordAccessPlan,mappingFingerprint}'
    )
  );
  for section_value in
    select required.section
    from pg_catalog.unnest(expected_sections) as required(section)
  loop
    select pg_catalog.string_agg(item.value ->> 'content', '' order by
      (item.value ->> 'ordinal')::integer)
    into section_text
    from pg_catalog.jsonb_array_elements(p_parts) as item(value)
    where item.value ->> 'section' = section_value;
    if section_text is null then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle section is unavailable';
    end if;
    begin
      section_payloads := section_payloads || pg_catalog.jsonb_build_object(
        section_value, section_text::jsonb
      );
    exception when others then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle section is invalid';
    end;
  end loop;
  application_content := prepared_source #> '{application,compilationOutput,canonical,content}';
  if application_content is null then
    raise exception using errcode = '55000',
      message = 'Installation runtime bundle Application content is unavailable';
  end if;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'identity', pg_catalog.jsonb_build_object(
        'kind', module.value -> 'kind',
        'organizationId', module.value -> 'organizationId',
        'rootId', module.value -> 'rootId',
        'definitionKey', module.value -> 'key',
        'releaseRevision', module.value -> 'releaseRevision',
        'releaseVersion', module.value -> 'releaseVersion',
        'validationContractVersion', module.value -> 'validationContractVersion',
        'contentFingerprint', module.value -> 'contentFingerprint',
        'resolutionFingerprint', module.value -> 'resolutionFingerprint',
        'dependencyManifest', module.value -> 'dependencyManifest'
      ),
      'content', module.value #> '{compilationOutput,canonical,content}'
    ) order by (module.value ->> 'rootId') collate "C"), '[]'::jsonb)
  into expected_modules
  from pg_catalog.jsonb_array_elements(prepared_source -> 'modules') as module(value);
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'flowId', flow.value -> 'id', 'trigger', trigger.value
    ) order by (flow.value ->> 'id') collate "C", (trigger.value ->> 'id') collate "C"), '[]'::jsonb)
  into expected_trigger_index
  from pg_catalog.jsonb_array_elements(application_content -> 'flows') as flow(value)
  cross join lateral pg_catalog.jsonb_array_elements(flow.value -> 'triggers') as trigger(value);
  select pg_catalog.jsonb_build_object(
    'preparedRecordAccessPlan', prepared_source -> 'preparedRecordAccessPlan',
    'declaredPermissions', pg_catalog.jsonb_build_object(
      'application', application_content -> 'permissions',
      'modules', coalesce((
        select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'rootId', module.value -> 'rootId',
            'permissions', module.value #> '{compilationOutput,canonical,content,permissions}'
          ) order by (module.value ->> 'rootId') collate "C")
        from pg_catalog.jsonb_array_elements(prepared_source -> 'modules') as module(value)
      ), '[]'::jsonb)
    )
  ) into expected_access_plan;
  if section_payloads -> 'navigation' is distinct from application_content -> 'navigation'
    or section_payloads -> 'flows' is distinct from pg_catalog.jsonb_build_object(
      'flows', application_content -> 'flows',
      'flowBindings', application_content -> 'flowBindings'
    )
    or section_payloads -> 'trigger_index' is distinct from expected_trigger_index
    or section_payloads -> 'theme' is distinct from application_content -> 'theme'
    or section_payloads -> 'component_registry' is distinct from application_content -> 'platformBlockDependencies'
    or section_payloads -> 'tool_bundle' is distinct from prepared_source #> '{application,compilationOutput,toolBundle}'
    or section_payloads -> 'access_plan' is distinct from expected_access_plan
    or section_payloads #> '{pages,application,identity}' is distinct from (
      pg_catalog.jsonb_build_object(
        'kind', prepared_source #> '{application,kind}',
        'organizationId', prepared_source #> '{application,organizationId}',
        'rootId', prepared_source #> '{application,rootId}',
        'definitionKey', prepared_source #> '{application,key}',
        'releaseRevision', prepared_source #> '{application,releaseRevision}',
        'releaseVersion', prepared_source #> '{application,releaseVersion}',
        'validationContractVersion', prepared_source #> '{application,validationContractVersion}',
        'contentFingerprint', prepared_source #> '{application,contentFingerprint}',
        'resolutionFingerprint', prepared_source #> '{application,resolutionFingerprint}',
        'dependencyManifest', prepared_source #> '{application,dependencyManifest}'
      )
      || case
        when prepared_source #> '{application,compilationOutput,platformCompatibilityVersion}' is null
          then '{}'::jsonb
        else pg_catalog.jsonb_build_object(
          'platformCompatibilityVersion',
          prepared_source #> '{application,compilationOutput,platformCompatibilityVersion}'
        )
      end
    )
    or section_payloads #> '{pages,application,content}' is distinct from
      application_content - array[
        'navigation', 'flows', 'flowBindings', 'theme',
        'platformBlockDependencies', 'shells', 'pages'
      ]::text[]
    or section_payloads #> '{pages,application,shells}' is distinct from application_content -> 'shells'
    or section_payloads #> '{pages,application,pages}' is distinct from application_content -> 'pages'
    or section_payloads #> '{pages,modules}' is distinct from expected_modules
    or pg_catalog.jsonb_typeof(section_payloads #> '{pages,resolvedCompositions}') is distinct from 'array'
    or pg_catalog.jsonb_array_length(section_payloads #> '{pages,resolvedCompositions}') <>
      pg_catalog.jsonb_array_length(application_content -> 'pages') then
    raise exception using errcode = '23514',
      message = 'Installation runtime bundle sections do not match current immutable source';
  end if;
  for part_item in
    select item.value from pg_catalog.jsonb_array_elements(p_parts) as item(value)
  loop
    if pg_catalog.jsonb_typeof(part_item) is distinct from 'object' then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part is invalid';
    end if;
    if not (part_item ?& array['section', 'ordinal', 'byteSize', 'sha256', 'content'])
      or part_item - array['section', 'ordinal', 'byteSize', 'sha256', 'content'] <> '{}'::jsonb
      or pg_catalog.jsonb_typeof(part_item -> 'section') is distinct from 'string'
      or pg_catalog.jsonb_typeof(part_item -> 'ordinal') is distinct from 'number'
      or pg_catalog.jsonb_typeof(part_item -> 'byteSize') is distinct from 'number'
      or pg_catalog.jsonb_typeof(part_item -> 'sha256') is distinct from 'string'
      or pg_catalog.jsonb_typeof(part_item -> 'content') is distinct from 'string' then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part is invalid';
    end if;

    section_value := part_item ->> 'section';
    if not (section_value = any (expected_sections))
      or (part_item ->> 'ordinal') !~ '^(0|[1-9][0-9]*)$'
      or pg_catalog.length(part_item ->> 'ordinal') > 10
      or (part_item ->> 'byteSize') !~ '^[1-9][0-9]*$'
      or pg_catalog.length(part_item ->> 'byteSize') > 7 then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part is invalid';
    end if;
    ordinal_value := (part_item ->> 'ordinal')::bigint;
    byte_size_value := (part_item ->> 'byteSize')::bigint;
    content_text := part_item ->> 'content';
    if ordinal_value > 2147483647 or byte_size_value > 1048575 then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part exceeds its limit';
    end if;

    content_bytes := pg_catalog.convert_to(content_text, 'UTF8');
    if pg_catalog.octet_length(content_bytes) <> byte_size_value then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part size is invalid';
    end if;
    sha256_value := 'sha256:' || pg_catalog.encode(
      extensions.digest(content_bytes, 'sha256'), 'hex'
    );
    if (part_item ->> 'sha256') !~ '^sha256:[a-f0-9]{64}$'
      or sha256_value <> (part_item ->> 'sha256') then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle part fingerprint is invalid';
    end if;
    total_size_value := total_size_value + byte_size_value;
    if total_size_value > 9007199254740991 then
      raise exception using errcode = '22023',
        message = 'Installation runtime bundle is too large';
    end if;
  end loop;

  if exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_parts) as item(value)
      group by item.value ->> 'section', (item.value ->> 'ordinal')::integer
      having pg_catalog.count(*) > 1
    )
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_parts) as item(value)
      group by item.value ->> 'section'
      having pg_catalog.min((item.value ->> 'ordinal')::integer) <> 0
        or pg_catalog.max((item.value ->> 'ordinal')::integer) <>
          pg_catalog.count(*) - 1
    )
    or exists (
      select 1
      from pg_catalog.unnest(expected_sections) as required(section)
      where not exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_parts) as item(value)
        where item.value ->> 'section' = required.section
      )
    ) then
    raise exception using errcode = '22023',
      message = 'Installation runtime bundle sections are incomplete';
  end if;

  select pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'section', item.value ->> 'section',
      'ordinal', (item.value ->> 'ordinal')::integer,
      'byteSize', (item.value ->> 'byteSize')::bigint,
      'sha256', item.value ->> 'sha256'
    ) order by pg_catalog.array_position(
      expected_sections, item.value ->> 'section'
    ), (item.value ->> 'ordinal')::integer
  )
  into parts_manifest
  from pg_catalog.jsonb_array_elements(p_parts) as item(value);

  insert into vortex_definition.installation_runtime_bundles (
    organization_id, application_root_id, application_release_revision,
    bundle_format_version, pin_fingerprint, source_manifest, parts, total_size_bytes
  ) values (
    selected_organization_id, p_application_root_id, p_application_release_revision,
    p_bundle_format_version, p_pin_fingerprint, source_manifest, parts_manifest, total_size_value
  ) on conflict (
    organization_id, application_root_id, application_release_revision, bundle_format_version
  ) do nothing;
  get diagnostics inserted_rows = row_count;

  if inserted_rows = 0 then
    select stored.* into stored_bundle
    from vortex_definition.installation_runtime_bundles as stored
    where stored.organization_id = selected_organization_id
      and stored.application_root_id = p_application_root_id
      and stored.application_release_revision = p_application_release_revision
      and stored.bundle_format_version = p_bundle_format_version;
    if not found then
      raise exception using errcode = '40001',
        message = 'Installation runtime bundle changed concurrently';
    end if;
    if stored_bundle.pin_fingerprint <> p_pin_fingerprint
      or stored_bundle.source_manifest is distinct from source_manifest
      or stored_bundle.parts is distinct from parts_manifest
      or stored_bundle.total_size_bytes is distinct from total_size_value
      or (select pg_catalog.count(*) from vortex_definition.installation_runtime_bundle_parts as part
        where part.organization_id = selected_organization_id
          and part.application_root_id = p_application_root_id
          and part.application_release_revision = p_application_release_revision
          and part.bundle_format_version = p_bundle_format_version)
        <> pg_catalog.jsonb_array_length(p_parts)
      or exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_parts) as item(value)
        left join vortex_definition.installation_runtime_bundle_parts as part
          on part.organization_id = selected_organization_id
          and part.application_root_id = p_application_root_id
          and part.application_release_revision = p_application_release_revision
          and part.bundle_format_version = p_bundle_format_version
          and part.section = item.value ->> 'section'
          and part.ordinal = (item.value ->> 'ordinal')::integer
        where part.content_bytes is distinct from pg_catalog.convert_to(item.value ->> 'content', 'UTF8')
      ) then
      raise exception using errcode = '23505',
        message = 'Installation runtime bundle pin fingerprint differs';
    end if;
  else
    for part_item in
      select item.value from pg_catalog.jsonb_array_elements(p_parts) as item(value)
    loop
      insert into vortex_definition.installation_runtime_bundle_parts (
        organization_id, application_root_id, application_release_revision,
        bundle_format_version, section, ordinal, content_bytes
      ) values (
        selected_organization_id, p_application_root_id, p_application_release_revision,
        p_bundle_format_version, part_item ->> 'section',
        (part_item ->> 'ordinal')::integer,
        pg_catalog.convert_to(part_item ->> 'content', 'UTF8')
      );
    end loop;

    select stored.* into strict stored_bundle
    from vortex_definition.installation_runtime_bundles as stored
    where stored.organization_id = selected_organization_id
      and stored.application_root_id = p_application_root_id
      and stored.application_release_revision = p_application_release_revision
      and stored.bundle_format_version = p_bundle_format_version;
  end if;

  return pg_catalog.jsonb_build_object(
    'organizationId', stored_bundle.organization_id,
    'applicationRootId', stored_bundle.application_root_id,
    'applicationReleaseRevision', stored_bundle.application_release_revision,
    'bundleFormatVersion', stored_bundle.bundle_format_version,
    'pinFingerprint', stored_bundle.pin_fingerprint,
    'sourceManifest', stored_bundle.source_manifest,
    'parts', stored_bundle.parts,
    'totalSizeBytes', stored_bundle.total_size_bytes,
    'builtAt', stored_bundle.built_at
  );
exception
  when no_data_found then
    raise exception using errcode = 'P0002',
      message = 'Installation runtime bundle evidence is unavailable';
  when too_many_rows then
    raise exception using errcode = '55000',
      message = 'Installation runtime bundle evidence is ambiguous';
end
$function$;

comment on function vortex_definition.write_installation_runtime_bundle_internal(
  uuid, bigint, integer, text, jsonb
) is
  'Atomically stores one immutable runtime bundle for an authorised exact Application release and pin fingerprint.';

create or replace function vortex_platform.acknowledge_consumer_occurrence(
  p_consumer_key text,
  p_ack_cursor uuid,
  p_occurrence_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  acknowledgement_time timestamptz := pg_catalog.statement_timestamp();
  already_acknowledged timestamptz;
begin
  if p_consumer_key is null
    or pg_catalog.octet_length(p_consumer_key) not between 1 and 128
    or p_consumer_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_ack_cursor is null or p_ack_cursor = nil_uuid
    or p_occurrence_id is null or p_occurrence_id = nil_uuid then
    raise exception using errcode = '22023', message = 'Event consumer acknowledgement input is invalid';
  end if;

  update vortex_platform.consumer_occurrence_progress
  set acknowledged_at = acknowledgement_time
  where consumer_key = p_consumer_key
    and occurrence_id = p_occurrence_id
    and claim_cursor = p_ack_cursor
    and acknowledged_at is null
    and terminally_failed_at is null
    and lease_expires_at > acknowledgement_time;
  if found then
    return pg_catalog.jsonb_build_object('outcome', 'acknowledged');
  end if;

  select progress.acknowledged_at into already_acknowledged
  from vortex_platform.consumer_occurrence_progress as progress
  where progress.consumer_key = p_consumer_key
    and progress.occurrence_id = p_occurrence_id
    and progress.claim_cursor = p_ack_cursor
  for update;
  if already_acknowledged is not null then
    return pg_catalog.jsonb_build_object('outcome', 'already_acknowledged');
  end if;
  return pg_catalog.jsonb_build_object('outcome', 'claim_unavailable');
end
$function$;

comment on function vortex_platform.acknowledge_consumer_occurrence(text, uuid, uuid) is
  'Completes one live consumer Event occurrence claim; repeated acknowledgement with the same cursor is safe.';

create or replace function vortex_platform.activate_uploaded_file(
  p_file_id uuid,
  p_expected_revision bigint,
  p_owner_record_type_id uuid,
  p_owner_record_id uuid,
  p_owner_field_id uuid,
  p_attachment_reference_id uuid,
  p_replacing_file_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.statement_timestamp();
  established jsonb := vortex_platform.upload_validated_context();
  request_actor jsonb := vortex_platform.upload_request_actor(established);
  reservation vortex_platform.upload_reservations%rowtype;
  uploaded vortex_platform.file_records%rowtype;
  attached_count bigint;
begin
  if p_attachment_reference_id is null
    or not vortex_platform.is_non_nil_uuid(p_attachment_reference_id::text) then
    raise exception using errcode = '22023', message = 'File activation is invalid';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(pg_catalog.concat_ws(E'\x1f',
      'vortex_platform.upload_field', (established ->> 'organizationId')::uuid::text,
      p_owner_record_type_id::text, p_owner_record_id::text, p_owner_field_id::text), 652)
  );

  select stored.* into reservation
  from vortex_platform.upload_reservations as stored
  where stored.file_id = p_file_id
    and stored.organization_id = (established ->> 'organizationId')::uuid
  for update;
  if not found then
    return vortex_platform.upload_refusal('file_not_found');
  end if;
  if request_actor is null or reservation.uploaded_by is distinct from request_actor then
    perform vortex_platform.append_file_activity_internal(
      'file_activation_refused', p_file_id);
    return vortex_platform.upload_refusal('caller_not_authorized');
  end if;
  if reservation.owner_record_type_id is distinct from p_owner_record_type_id
    or reservation.owner_record_id is distinct from p_owner_record_id
    or reservation.owner_field_id is distinct from p_owner_field_id then
    return vortex_platform.upload_refusal('owner_mismatch');
  end if;

  select stored.* into strict uploaded
  from vortex_platform.file_records as stored
  where stored.file_id = p_file_id
  for update;

  if uploaded.lifecycle_state = 'active'
    and p_attachment_reference_id = any (uploaded.owning_attachment_references) then
    return pg_catalog.jsonb_build_object(
      'outcome', 'activated',
      'fileRecord', vortex_platform.upload_file_record(uploaded)
    );
  end if;
  if uploaded.lifecycle_state <> 'scanning' or uploaded.scanner_result <> 'clean' then
    return vortex_platform.upload_refusal('invalid_lifecycle_state');
  end if;
  if reservation.upload_expires_at <= evaluated_at then
    return vortex_platform.upload_refusal('upload_expired');
  end if;
  if reservation.revision is distinct from p_expected_revision then
    return vortex_platform.upload_refusal('revision_conflict');
  end if;
  if reservation.replacing_file_id is distinct from p_replacing_file_id then
    return vortex_platform.upload_refusal('replacement_file_not_found');
  end if;
  if p_replacing_file_id is not null then
    perform 1
    from vortex_platform.file_records as replaced
    where replaced.file_id = p_replacing_file_id
      and replaced.organization_id = reservation.organization_id
      and replaced.owner_record_type_id = reservation.owner_record_type_id
      and replaced.owner_record_id = reservation.owner_record_id
      and replaced.owner_field_id = reservation.owner_field_id
      and replaced.lifecycle_state = 'active'
    for share;
    if not found then
      return vortex_platform.upload_refusal('replacement_file_not_found');
    end if;
  end if;

  if reservation.max_files is not null then
    select pg_catalog.count(*) into attached_count
    from vortex_platform.file_records as attached
    where attached.organization_id = reservation.organization_id
      and attached.owner_record_type_id = reservation.owner_record_type_id
      and attached.owner_record_id = reservation.owner_record_id
      and attached.owner_field_id = reservation.owner_field_id
      and attached.lifecycle_state = 'active'
      and attached.file_id <> p_file_id
      and attached.file_id is distinct from p_replacing_file_id;
    if attached_count >= reservation.max_files then
      raise exception using errcode = '23514',
        message = 'Attachment field already holds its maximum number of files';
    end if;
  end if;

  update vortex_platform.file_records
  set
    lifecycle_state = 'active',
    activated_at = evaluated_at,
    owning_attachment_references = pg_catalog.array_append(
      owning_attachment_references, p_attachment_reference_id
    )
  where file_id = p_file_id
  returning * into uploaded;

  update vortex_platform.upload_reservations
  set revision = revision + 1, updated_at = evaluated_at
  where file_id = p_file_id;

  perform vortex_platform.append_file_activity_internal(
    'file_activated', p_file_id);

  return pg_catalog.jsonb_build_object(
    'outcome', 'activated',
    'fileRecord', vortex_platform.upload_file_record(uploaded)
  );
end
$function$;

comment on function vortex_platform.activate_uploaded_file(uuid, bigint, uuid, uuid, uuid, uuid, uuid) is
  'Activates a clean scanned upload inside the record save that attaches it.';

revoke execute on function
  vortex_platform.activate_uploaded_file(uuid, bigint, uuid, uuid, uuid, uuid, uuid) from public, anon, authenticated, service_role, vortex_runtime, vortex_request, vortex_record_adapter;

grant execute on function
  vortex_platform.activate_uploaded_file(uuid, bigint, uuid, uuid, uuid, uuid, uuid) to vortex_request;

alter function vortex_platform.activate_uploaded_file(uuid, bigint, uuid, uuid, uuid, uuid, uuid)
  owner to vortex_owner;

create or replace function vortex_platform.append_detached_offboarding_reassignment_internal(
  p_storage_contract_id uuid,
  p_record_id uuid,
  p_record_type_id uuid,
  p_occurrence_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  installation jsonb;
begin
  if p_storage_contract_id is null
    or p_record_id is null
    or p_record_type_id is null
    or p_occurrence_id is null
    or p_storage_contract_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_record_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_record_type_id = '00000000-0000-0000-0000-000000000000'::uuid
    or p_occurrence_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using errcode = '22023', message = 'Detached reassignment Event input is invalid';
  end if;
  installation := vortex_definition.read_current_detached_installation_for_transfer_internal();
  return vortex_platform.append_record_occurrences_for_resolved_installation_internal(
    p_storage_contract_id,
    p_record_id,
    pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'occurrenceId', p_occurrence_id,
      'descriptor', pg_catalog.jsonb_build_object(
        'kind', 'standard', 'eventKind', 'reassigned', 'recordTypeId', p_record_type_id
      ),
      'payload', pg_catalog.jsonb_build_object('kind', 'reassigned')
    )),
    installation
  );
end
$function$;

comment on function vortex_platform.append_detached_offboarding_reassignment_internal(uuid, uuid, uuid, uuid) is
  'Appends exactly one content-free record reassignment Event occurrence for a detached installation during protected offboarding.';

create or replace function vortex_platform.append_record_occurrences(
  p_storage_contract_id uuid,
  p_record_id uuid,
  p_occurrences jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
begin
  return vortex_platform.append_record_occurrences_for_resolved_installation_internal(
    p_storage_contract_id, p_record_id, p_occurrences, null::jsonb
  );
end
$function$;

comment on function vortex_platform.append_record_occurrences(uuid, uuid, jsonb) is
