create or replace function vortex_platform.application_is_installed(
  p_organization_id uuid,
  p_application_root_id uuid
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $function$
  select p_organization_id is not null
    and p_application_root_id is not null
    and exists (
      select 1
      from vortex_access.read_application_permission_snapshot(
        p_organization_id, p_application_root_id
      ) as registration
      where vortex_definition.application_root_exists_for_organization_internal(
          p_organization_id, p_application_root_id
        )
        and vortex_definition.has_active_application_release_binding_internal(
          p_organization_id, p_application_root_id, registration.release_revision
        )
    )
$function$;

comment on function vortex_platform.application_is_installed(uuid, uuid) is
  'Private check that an application has an active registration and an active installation binding for its registered release in one organisation.';

alter function vortex_platform.application_is_installed(uuid, uuid)
  owner to vortex_owner;

create or replace function vortex_platform.assert_connection_administration_authority(
  p_context jsonb
)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  decision record;
  operation_value constant text := 'platform.organization.connections.manage';
  failure_sqlstate text;
  failure_message text;
begin
  select evaluated.* into strict decision
  from vortex_access.evaluate_organization_permission_eligibility(
    pg_catalog.jsonb_build_object(
      'operationKey', operation_value,
      'action', pg_catalog.jsonb_build_object('actionKind', 'manage'),
      'target', pg_catalog.jsonb_build_object('kind', 'organization'),
      'requiredPermission', pg_catalog.jsonb_build_object(
        'ownerKind', 'platform',
        -- guard-allow: function-uuid fixed platform permission identity; the owner role has no read access to the declarations table
        'ownerId', 'cabe121e-0baf-4084-9471-cce915d460a8',
        -- guard-allow: function-uuid fixed platform permission identity; the owner role has no read access to the declarations table
        'permissionId', 'ec2908a1-f3cd-4c4a-8bf7-91bffbf4cb3d'
      ),
      'recentAuthentication', pg_catalog.jsonb_build_object('kind', 'none'),
      'authority', pg_catalog.jsonb_build_object('kind', 'permission')
    )
  ) as evaluated;

  if decision.outcome is distinct from 'eligible'
    or decision.operation_key is distinct from operation_value
    or decision.organization_id is distinct from (p_context ->> 'organizationId')::uuid
    or decision.organization_account_id is distinct from
      (p_context ->> 'organizationAccountId')::uuid
    or decision.access_version is distinct from (p_context ->> 'accessVersion')::bigint
    or decision.correlation_id is distinct from (p_context ->> 'correlationId')::uuid then
    raise exception using
      errcode = '42501',
      message = 'Connection administration is unavailable';
  end if;
exception
  -- Only a refused permission decision is the safe denial; any other failure
  -- is a defect and keeps its SQLSTATE and message.
  when sqlstate '42501' then
    raise exception using
      errcode = '42501',
      message = 'Connection administration is unavailable';
  when others then
    get stacked diagnostics failure_sqlstate = returned_sqlstate,
      failure_message = message_text;
    raise warning 'Connection administration authority check failed: SQLSTATE %, %',
      failure_sqlstate, failure_message;
    raise;
end
$function$;

comment on function vortex_platform.assert_connection_administration_authority(jsonb) is null;
alter function vortex_platform.assert_connection_administration_authority(jsonb) owner to vortex_owner;

create or replace function vortex_platform.assert_human_administration_request()
returns void
language plpgsql
stable
security definer
set search_path = ''
as $function$
begin
  if coalesce(vortex_platform.current_context() ->> 'callerKind', '') <> 'human' then
    raise exception using
      errcode = '42501',
      message = 'Connection administration requires a human request context';
  end if;
end
$function$;

comment on function vortex_platform.assert_human_administration_request() is
  'Refuses any caller whose request context is not a human request; used by the connection administration entry points.';
alter function vortex_platform.assert_human_administration_request() owner to vortex_owner;

create or replace function vortex_platform.begin_flow_effect_with_origin(
  p_run_id uuid,
  p_organization_id uuid,
  p_principal_kind text,
  p_principal_id uuid,
  p_origin_kind text,
  p_origin_id uuid,
  p_task_path text,
  p_iteration text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  inserted_run_id uuid;
  existing record;
begin
  if p_run_id is null or not vortex_platform.is_non_nil_uuid(p_run_id::text)
    or p_organization_id is null
    or not vortex_platform.is_non_nil_uuid(p_organization_id::text)
    or p_principal_kind is null
    or p_principal_kind not in ('person', 'specified_account', 'system')
    or p_principal_id is null
    or not vortex_platform.is_non_nil_uuid(p_principal_id::text)
    or p_origin_kind is null
    or p_origin_kind not in ('person', 'event', 'schedule')
    or p_origin_id is null
    or not vortex_platform.is_non_nil_uuid(p_origin_id::text)
    or (p_origin_kind = 'person' and (
      p_principal_kind <> 'person' or p_origin_id <> p_principal_id
    ))
    or (p_origin_kind in ('event', 'schedule') and p_principal_kind = 'person')
    or p_task_path is null
    or pg_catalog.length(p_task_path) not between 1 and 1000
    or p_iteration is null
    or pg_catalog.length(p_iteration) not between 1 and 200 then
    return pg_catalog.jsonb_build_object('kind', 'unavailable');
  end if;

  insert into vortex_platform.flow_effect_ledger (
    run_id, task_path, iteration, organization_id, identity_id,
    principal_kind, principal_id, origin_kind, origin_id, state, started_at
  ) values (
    p_run_id, p_task_path, p_iteration, p_organization_id,
    case when p_principal_kind = 'person' then p_principal_id else null end,
    p_principal_kind, p_principal_id, p_origin_kind, p_origin_id, 'started',
    pg_catalog.statement_timestamp()
  )
  on conflict (run_id, task_path, iteration) do nothing
  returning run_id into inserted_run_id;

  if inserted_run_id is not null then
    return pg_catalog.jsonb_build_object('kind', 'claimed');
  end if;

  select ledger.organization_id, ledger.identity_id, ledger.principal_kind,
    ledger.principal_id, ledger.origin_kind, ledger.origin_id,
    ledger.state, ledger.outcome, ledger.outputs
  into existing
  from vortex_platform.flow_effect_ledger as ledger
  where ledger.run_id = p_run_id
    and ledger.task_path = p_task_path
    and ledger.iteration = p_iteration;

  if not found
    or existing.organization_id is distinct from p_organization_id
    or not (
      (
        existing.principal_kind = p_principal_kind
        and existing.principal_id = p_principal_id
        and existing.origin_kind = p_origin_kind
        and existing.origin_id = p_origin_id
      )
      or (
        existing.principal_kind is null
        and existing.principal_id is null
        and existing.origin_kind is null
        and existing.origin_id is null
        and p_principal_kind = 'person'
        and existing.identity_id = p_principal_id
        and p_origin_kind = 'person'
        and p_origin_id = p_principal_id
      )
    ) then
    return pg_catalog.jsonb_build_object('kind', 'unavailable');
  end if;

  -- The legacy person match preserves safe replay of continuations created before this migration.
  if existing.state = 'completed' then
    return pg_catalog.jsonb_build_object(
      'kind', 'completed',
      'outcome', existing.outcome,
      'outputs', coalesce(existing.outputs, '{}'::jsonb)
    );
  end if;
  return pg_catalog.jsonb_build_object('kind', 'in_progress');
end
$function$;

comment on function vortex_platform.begin_flow_effect_with_origin(
  uuid, uuid, text, uuid, text, uuid, text, text
) is
  'Private effect claim bound to a verified person or execution principal and trigger origin; the run, task path and iteration remain duplicate-safe, including compatible legacy person rows.';

create or replace function vortex_platform.begin_flow_effect(
  p_run_id uuid,
  p_organization_id uuid,
  p_identity_id uuid,
  p_task_path text,
  p_iteration text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  inserted_run_id uuid;
  existing record;
begin
  if not vortex_platform.is_non_nil_uuid(p_run_id::text)
    or not vortex_platform.is_non_nil_uuid(p_organization_id::text)
    or not vortex_platform.is_non_nil_uuid(p_identity_id::text)
    or p_task_path is null
    or pg_catalog.length(p_task_path) not between 1 and 1000
    or p_iteration is null
    or pg_catalog.length(p_iteration) not between 1 and 200 then
    return pg_catalog.jsonb_build_object('kind', 'unavailable');
  end if;

  insert into vortex_platform.flow_effect_ledger (
    run_id, task_path, iteration, organization_id, identity_id, state, started_at
  ) values (
    p_run_id, p_task_path, p_iteration, p_organization_id, p_identity_id, 'started',
    pg_catalog.statement_timestamp()
  )
  on conflict (run_id, task_path, iteration) do nothing
  returning run_id into inserted_run_id;

  if inserted_run_id is not null then
    return pg_catalog.jsonb_build_object('kind', 'claimed');
  end if;

  select ledger.organization_id, ledger.identity_id, ledger.state, ledger.outcome, ledger.outputs
  into existing
  from vortex_platform.flow_effect_ledger as ledger
  where ledger.run_id = p_run_id
    and ledger.task_path = p_task_path
    and ledger.iteration = p_iteration;

  if not found
    or existing.organization_id is distinct from p_organization_id
    or existing.identity_id is distinct from p_identity_id then
    return pg_catalog.jsonb_build_object('kind', 'unavailable');
  end if;

  -- A repeat never runs the effect again: a finished one replays its recorded safe outcome, and one
  -- that started but never recorded an outcome is uncertain and is reported as such.
  if existing.state = 'completed' then
    return pg_catalog.jsonb_build_object(
      'kind', 'completed',
      'outcome', existing.outcome,
      'outputs', coalesce(existing.outputs, '{}'::jsonb)
    );
  end if;
  return pg_catalog.jsonb_build_object('kind', 'in_progress');
end
$function$;

comment on function vortex_platform.begin_flow_effect(
  uuid, uuid, uuid, text, text
) is
  'Private flow-effect claim: the first call for one run, task path and iteration claims the protected effect; every repeat replays the recorded safe outcome or reports it in progress, so a replayed flow can never repeat an effect.';

create or replace function vortex_platform.claim_consumer_occurrences(
  p_consumer_key text,
  p_batch_size integer,
  p_lease_seconds integer
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  maximum_batch_size constant integer := 100;
  maximum_lease_seconds constant integer := 300;
  maximum_causal_depth constant integer := 16;
  maximum_delivery_attempts constant integer := 20;
  maximum_terminal_sweep constant integer := 400;
  claim_time timestamptz := pg_catalog.statement_timestamp();
  claim_cursor uuid := pg_catalog.gen_random_uuid();
  claimed jsonb;
begin
  if p_consumer_key is null
    or pg_catalog.octet_length(p_consumer_key) not between 1 and 128
    or p_consumer_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_batch_size is null
    or p_batch_size not between 1 and maximum_batch_size
    or p_lease_seconds is null
    or p_lease_seconds not between 1 and maximum_lease_seconds then
    raise exception using errcode = '22023', message = 'Event consumer claim input is invalid';
  end if;

  -- A worker that dies mid-delivery reports nothing, so the lease simply
  -- lapses.  Counting the lapsed attempt here is what makes the retry budget
  -- bounded for interrupted work as well as for reported failures, and moves
  -- a blocked sequence to an operator-visible failure state rather than
  -- retrying it forever.  This must be its own statement: a data-modifying CTE
  -- in the claim query below would still read the pre-update snapshot.  The
  -- sweep is bounded and skips locked rows, so the reclaim below independently
  -- refuses to issue attempt maximum_delivery_attempts + 1; anything the sweep
  -- did not reach this time is simply terminalised on a later claim.
  update vortex_platform.consumer_occurrence_progress as progress
  set last_failed_at = coalesce(progress.last_failed_at, claim_time),
      last_failure_code = coalesce(progress.last_failure_code, 'unclassified'),
      terminally_failed_at = case
        when progress.last_failed_at is not null and progress.last_failed_at > claim_time
          then progress.last_failed_at
        else claim_time
      end
  where (progress.consumer_key, progress.occurrence_id) in (
    select exhausted.consumer_key, exhausted.occurrence_id
    from vortex_platform.consumer_occurrence_progress as exhausted
    where exhausted.consumer_key = p_consumer_key
      and exhausted.acknowledged_at is null
      and exhausted.terminally_failed_at is null
      and exhausted.lease_expires_at <= claim_time
      and exhausted.attempt_count >= maximum_delivery_attempts
    order by exhausted.lease_expires_at, exhausted.occurrence_id
    limit maximum_terminal_sweep
    for update skip locked
  );

  -- There is no mutable delivery state on an outbox occurrence.  Missing
  -- progress for an earlier sequence is therefore also an unacknowledged
  -- predecessor, which makes the barrier correct for a newly registered
  -- consumer as well as for a consumer recovering an expired lease.
  with candidate_window as materialized (
    select occurrence.*
    from vortex_platform.event_outbox as occurrence
    left join vortex_platform.consumer_occurrence_progress as progress
      on progress.consumer_key = p_consumer_key
      and progress.occurrence_id = occurrence.occurrence_id
    where progress.acknowledged_at is null
      and progress.terminally_failed_at is null
      and (progress.lease_expires_at is null or progress.lease_expires_at <= claim_time)
      and not exists (
        select 1
        from vortex_platform.event_outbox as predecessor
        left join vortex_platform.consumer_occurrence_progress as predecessor_progress
          on predecessor_progress.consumer_key = p_consumer_key
          and predecessor_progress.occurrence_id = predecessor.occurrence_id
        where predecessor.organization_id = occurrence.organization_id
          and predecessor.storage_contract_id = occurrence.storage_contract_id
          and predecessor.sequence_application_root_id is not distinct from
            occurrence.sequence_application_root_id
          and predecessor.record_id = occurrence.record_id
          and predecessor.record_sequence < occurrence.record_sequence
          and predecessor_progress.acknowledged_at is null
      )
    order by occurrence.occurred_at, occurrence.occurrence_id
    limit 400
  ), candidate as materialized (
    select occurrence.*, causal.depth as causal_depth
    from candidate_window as occurrence
    cross join lateral (
      select pg_catalog.pg_try_advisory_xact_lock(
        pg_catalog.hashtextextended(
          'vortex_platform.consumer:' || p_consumer_key || ':' || occurrence.occurrence_id::text,
          0
        )
      ) as acquired
    ) as claim_lock
    cross join lateral (
      with recursive causal_chain(occurrence_id, causation_id, depth, path) as (
        select occurrence.occurrence_id,
          case
            when occurrence.envelope ->> 'causationId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then (occurrence.envelope ->> 'causationId')::uuid
            else null::uuid
          end,
          0,
          array[occurrence.occurrence_id]
        union all
        select parent.occurrence_id,
          case
            when parent.envelope ->> 'causationId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then (parent.envelope ->> 'causationId')::uuid
            else null::uuid
          end,
          causal_chain.depth + 1,
          causal_chain.path || parent.occurrence_id
        from causal_chain
        join vortex_platform.event_outbox as parent
          on parent.occurrence_id = causal_chain.causation_id
          and parent.organization_id = occurrence.organization_id
        where causal_chain.depth < maximum_causal_depth
          and not parent.occurrence_id = any (causal_chain.path)
      )
      select pg_catalog.max(depth)::integer as depth,
        coalesce(pg_catalog.bool_or(
          depth = maximum_causal_depth
          and causation_id is not null
          and exists (
            select 1 from vortex_platform.event_outbox as deeper
            where deeper.occurrence_id = causal_chain.causation_id
              and deeper.organization_id = occurrence.organization_id
          )
        ), false) as exceeds_limit,
        coalesce(pg_catalog.bool_or(
          causation_id is not null
          and exists (
            select 1 from vortex_platform.event_outbox as repeated
            where repeated.occurrence_id = causal_chain.causation_id
              and repeated.organization_id = occurrence.organization_id
              and repeated.occurrence_id = any (causal_chain.path)
          )
        ), false) as has_cycle
      from causal_chain
    ) as causal
    where claim_lock.acquired
      and not causal.exceeds_limit
      and not causal.has_cycle
    order by occurrence.occurred_at, occurrence.occurrence_id
    limit p_batch_size
  ), claimed as (
    insert into vortex_platform.consumer_occurrence_progress (
      consumer_key, occurrence_id, claim_cursor, claimed_at, lease_expires_at, attempt_count
    )
    select p_consumer_key, occurrence_id, claim_cursor, claim_time,
      claim_time + pg_catalog.make_interval(secs => p_lease_seconds), 1
    from candidate
    on conflict (consumer_key, occurrence_id) do update
      set claim_cursor = excluded.claim_cursor,
          claimed_at = excluded.claimed_at,
          lease_expires_at = excluded.lease_expires_at,
          attempt_count = consumer_occurrence_progress.attempt_count + 1
      where consumer_occurrence_progress.acknowledged_at is null
        and consumer_occurrence_progress.terminally_failed_at is null
        and consumer_occurrence_progress.attempt_count < maximum_delivery_attempts
        and consumer_occurrence_progress.lease_expires_at <= claim_time
    returning occurrence_id, lease_expires_at
  )
  select pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'occurrence', candidate.envelope,
      'causalDepth', candidate.causal_depth,
      'leaseExpiresAt', pg_catalog.to_char(
        pg_catalog.timezone('UTC', claimed.lease_expires_at),
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      )
    ) order by candidate.occurred_at, candidate.occurrence_id
  ) into claimed
  from claimed
  join candidate using (occurrence_id);

  return pg_catalog.jsonb_build_object(
    'ackCursor', case when claimed is null then null else claim_cursor end,
    'occurrences', coalesce(claimed, '[]'::jsonb)
  );
end
$function$;

comment on function vortex_platform.claim_consumer_occurrences(text, integer, integer) is
  'Claims a bounded ordered set of unacknowledged Event occurrences for one consumer with a short renewable lease.';

create or replace function vortex_platform.claim_file_download_grant(p_one_time_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.statement_timestamp();
  established jsonb := vortex_platform.validated_service_context();
  request_actor jsonb := vortex_platform.upload_request_actor(established);
  claimed vortex_platform.download_grants%rowtype;
  stored vortex_platform.file_records%rowtype;
begin
  if request_actor is null then
    return null;
  end if;

  select candidate.* into claimed
  from vortex_platform.download_grants as candidate
  where candidate.one_time_id = p_one_time_id
    and candidate.organization_id = (established ->> 'organizationId')::uuid
  for update;
  if not found
    or claimed.credential_issued_at is not null
    or claimed.expires_at <= evaluated_at
    or claimed.actor is distinct from request_actor then
    return null;
  end if;

  select candidate.* into stored
  from vortex_platform.file_records as candidate
  where candidate.file_id = claimed.file_id
    and candidate.organization_id = claimed.organization_id;
  if not found
    or stored.lifecycle_state <> 'active'
    or stored.scanner_result <> 'clean'
    or stored.owner_record_type_id is distinct from claimed.owner_record_type_id
    or stored.owner_record_id is distinct from claimed.owner_record_id
    or stored.owner_field_id is distinct from claimed.owner_field_id then
    return null;
  end if;

  update vortex_platform.download_grants
  set credential_issued_at = evaluated_at
  where one_time_id = claimed.one_time_id;

  return pg_catalog.jsonb_build_object(
    'grant', pg_catalog.jsonb_build_object(
      'kind', 'download',
      'organizationId', claimed.organization_id,
      'actor', claimed.actor,
      'recordTypeId', claimed.owner_record_type_id,
      'recordId', claimed.owner_record_id,
      'fieldId', claimed.owner_field_id,
      'fileId', claimed.file_id,
      'oneTimeId', claimed.one_time_id,
      'expiresAt', vortex_platform.format_timestamp_utc(claimed.expires_at)
    ),
    'fileRecord', vortex_platform.upload_file_record(stored),
    'correlationId', claimed.correlation_id
  );
end
$function$;

comment on function vortex_platform.claim_file_download_grant(uuid) is
  'Claims an unexpired read grant of the request actor exactly once with its current FileRecord.';

alter function vortex_platform.claim_file_download_grant(uuid) owner to vortex_owner;

create or replace function vortex_platform.claim_file_upload_grant(p_one_time_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.statement_timestamp();
  established jsonb := vortex_platform.upload_validated_context();
  request_actor jsonb := vortex_platform.upload_request_actor(established);
  claimed_file_id uuid;
  reservation vortex_platform.upload_reservations%rowtype;
  claimed vortex_platform.upload_grants%rowtype;
  uploaded vortex_platform.file_records%rowtype;
begin
  select candidate.file_id into claimed_file_id
  from vortex_platform.upload_grants as candidate
  where candidate.one_time_id = p_one_time_id
    and candidate.organization_id = (established ->> 'organizationId')::uuid;
  if not found or request_actor is null then
    return null;
  end if;

  -- Reservation first, then grant: the same order renewal and completion use.
  select stored.* into strict reservation
  from vortex_platform.upload_reservations as stored
  where stored.file_id = claimed_file_id
  for update;

  select stored.* into strict claimed
  from vortex_platform.upload_grants as stored
  where stored.one_time_id = p_one_time_id
  for update;

  select stored.* into strict uploaded
  from vortex_platform.file_records as stored
  where stored.file_id = claimed_file_id;

  if claimed.superseded_at is not null
    or claimed.credential_issued_at is not null
    or claimed.expires_at <= evaluated_at
    or claimed.actor is distinct from request_actor
    or reservation.uploaded_by is distinct from request_actor
    or reservation.upload_expires_at <= evaluated_at
    or uploaded.lifecycle_state <> 'pending' then
    return null;
  end if;

  update vortex_platform.upload_grants
  set credential_issued_at = evaluated_at
  where one_time_id = claimed.one_time_id;

  return pg_catalog.jsonb_build_object(
    'grant', pg_catalog.jsonb_build_object(
      'kind', 'upload',
      'organizationId', claimed.organization_id,
      'actor', claimed.actor,
      'recordTypeId', reservation.owner_record_type_id,
      'recordId', reservation.owner_record_id,
      'fieldId', reservation.owner_field_id,
      'maximumBytes', claimed.maximum_bytes,
      'policyFingerprint', claimed.policy_fingerprint,
      'expiresAt', vortex_platform.format_timestamp_utc(claimed.expires_at),
      'oneTimeId', claimed.one_time_id
    ),
    'fileRecord', vortex_platform.upload_file_record(uploaded),
    'correlationId', reservation.correlation_id
  );
end
$function$;

comment on function vortex_platform.claim_file_upload_grant(uuid) is
  'Issues the one Storage credential of a current, unexpired grant for the uploader of a pending upload.';

alter function vortex_platform.claim_file_upload_grant(uuid) owner to vortex_owner;

create or replace function vortex_platform.complete_flow_effect_with_origin(
  p_run_id uuid,
  p_organization_id uuid,
  p_principal_kind text,
  p_principal_id uuid,
  p_origin_kind text,
  p_origin_id uuid,
  p_task_path text,
  p_iteration text,
  p_outcome text,
  p_outputs jsonb
)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $function$
begin
  if p_run_id is null or not vortex_platform.is_non_nil_uuid(p_run_id::text)
    or p_organization_id is null
    or not vortex_platform.is_non_nil_uuid(p_organization_id::text)
    or p_principal_kind is null
    or p_principal_kind not in ('person', 'specified_account', 'system')
    or p_principal_id is null
    or not vortex_platform.is_non_nil_uuid(p_principal_id::text)
    or p_origin_kind is null
    or p_origin_kind not in ('person', 'event', 'schedule')
    or p_origin_id is null
    or not vortex_platform.is_non_nil_uuid(p_origin_id::text)
    or (p_origin_kind = 'person' and (
      p_principal_kind <> 'person' or p_origin_id <> p_principal_id
    ))
    or (p_origin_kind in ('event', 'schedule') and p_principal_kind = 'person')
    or p_task_path is null
    or pg_catalog.length(p_task_path) not between 1 and 1000
    or p_iteration is null
    or pg_catalog.length(p_iteration) not between 1 and 200
    or p_outcome is null
    or p_outcome not in (
      'completed', 'committed', 'background_pending', 'refused', 'conflict', 'validation',
      'uncertain', 'failed'
    )
    or p_outputs is null
    or pg_catalog.jsonb_typeof(p_outputs) <> 'object'
    or pg_catalog.pg_column_size(p_outputs) > 65536 then
    return false;
  end if;

  update vortex_platform.flow_effect_ledger as ledger
  set state = 'completed',
      outcome = p_outcome,
      outputs = p_outputs,
      completed_at = pg_catalog.statement_timestamp()
  where ledger.run_id = p_run_id
    and ledger.task_path = p_task_path
    and ledger.iteration = p_iteration
    and ledger.organization_id = p_organization_id
    and ledger.principal_kind = p_principal_kind
    and ledger.principal_id = p_principal_id
    and ledger.origin_kind = p_origin_kind
    and ledger.origin_id = p_origin_id
    and ledger.identity_id is not distinct from
      case when p_principal_kind = 'person' then p_principal_id else null end
    and ledger.state = 'started';

  return found;
end
$function$;

comment on function vortex_platform.complete_flow_effect_with_origin(
  uuid, uuid, text, uuid, text, uuid, text, text, text, jsonb
) is
  'Private effect completion for the exact run, principal, trigger origin, task path and iteration claim.';

create or replace function vortex_platform.complete_flow_effect(
  p_run_id uuid,
  p_organization_id uuid,
  p_identity_id uuid,
  p_task_path text,
  p_iteration text,
  p_outcome text,
  p_outputs jsonb
)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $function$
begin
  if p_outcome is null
    or p_outcome not in (
      'completed', 'committed', 'background_pending', 'refused', 'conflict', 'validation',
      'uncertain', 'failed'
    )
    or p_outputs is null
    or pg_catalog.jsonb_typeof(p_outputs) <> 'object'
    or pg_catalog.pg_column_size(p_outputs) > 65536 then
    return false;
  end if;

  update vortex_platform.flow_effect_ledger as ledger
  set state = 'completed',
      outcome = p_outcome,
      outputs = p_outputs,
      completed_at = pg_catalog.statement_timestamp()
  where ledger.run_id = p_run_id
    and ledger.task_path = p_task_path
    and ledger.iteration = p_iteration
    and ledger.organization_id = p_organization_id
    and ledger.identity_id = p_identity_id
    and ledger.state = 'started';

  return found;
end
$function$;

comment on function vortex_platform.complete_flow_effect(
  uuid, uuid, uuid, text, text, text, jsonb
) is
  'Private flow-effect completion: records the safe outcome of the one claimed protected effect of a run, task path and iteration so a repeat replays it.';

create or replace function vortex_platform.consume_flow_continuation(
  p_token_hash text,
  p_organization_id uuid,
  p_identity_id uuid,
  p_flow_id uuid,
  p_release_key text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  claimed record;
begin
  if p_token_hash is null or p_token_hash !~ '^[a-f0-9]{64}$'
    or not vortex_platform.is_non_nil_uuid(p_organization_id::text)
    or not vortex_platform.is_non_nil_uuid(p_identity_id::text)
    or not vortex_platform.is_non_nil_uuid(p_flow_id::text)
    or p_release_key is null then
    return pg_catalog.jsonb_build_object('kind', 'unavailable');
  end if;

  -- One statement both checks every binding and marks the row used, so two concurrent resumes can
  -- never both succeed, and an unknown, expired, replayed, foreign or wrong-release token is one
  -- neutral result.
  update vortex_platform.flow_continuations as continuation
  set consumed_at = pg_catalog.statement_timestamp()
  where continuation.token_hash = p_token_hash
    and continuation.organization_id = p_organization_id
    and continuation.identity_id = p_identity_id
    and continuation.flow_id = p_flow_id
    and continuation.release_key = p_release_key
    and continuation.consumed_at is null
    and continuation.expires_at > pg_catalog.statement_timestamp()
  returning continuation.run_id, continuation.state, continuation.elapsed_milliseconds
  into claimed;

  if not found then
    return pg_catalog.jsonb_build_object('kind', 'unavailable');
  end if;

  return pg_catalog.jsonb_build_object(
    'kind', 'available',
    'runId', claimed.run_id,
    'state', claimed.state,
    'elapsedMilliseconds', claimed.elapsed_milliseconds
  );
end
$function$;

comment on function vortex_platform.consume_flow_continuation(
  text, uuid, uuid, uuid, text
) is
  'Private flow-continuation consume: returns the stored run state once, and only to the exact initiator, organisation and flow release it was issued for while it has not expired; every other case is one neutral unavailable result.';

create or replace function vortex_platform.event_dispatch_backlog_status()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $function$
  with pending as (
    select pg_catalog.min(occurrence.occurred_at) as oldest_occurred_at
    from vortex_platform.consumer_occurrence_progress as progress
    join vortex_platform.event_outbox as occurrence
      on occurrence.occurrence_id = progress.occurrence_id
    where progress.acknowledged_at is null
      and progress.terminally_failed_at is null
  ), failed as (
    select pg_catalog.count(*) as failure_count
    from (
      select 1
      from vortex_platform.consumer_occurrence_progress as progress
      where progress.terminally_failed_at is not null
      limit 1000000
    ) as bounded
  )
  select pg_catalog.jsonb_build_object(
    'oldestPendingAgeSeconds',
      case
        when pending.oldest_occurred_at is null then null
        else least(
          2592000,
          greatest(
            0,
            -- EXTRACT is SQL syntax, not a schema-qualifiable call; it always
            -- resolves from pg_catalog even under the empty search_path.
            pg_catalog.floor(
              extract(
                epoch from (pg_catalog.statement_timestamp() - pending.oldest_occurred_at)
              )
            )
          )
        )::integer
      end,
    'terminalFailureCount', failed.failure_count::integer
  )
  from pending, failed;
$function$;

comment on function vortex_platform.event_dispatch_backlog_status() is
  'Bounded, content-free event delivery backlog: age in seconds of the oldest claimed occurrence not yet acknowledged or terminally failed, and the terminal failure count. Reveals no occurrence identity, consumer identity or payload.';

create or replace function vortex_platform.grant_connection_application_for_administration(
  p_connection_instance_id uuid,
  p_application_root_id uuid,
  p_administrator_activity_id uuid
)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $function$
begin
  perform vortex_platform.assert_human_administration_request();

  perform vortex_platform.grant_connection_application_internal(
    p_connection_instance_id,
    p_application_root_id,
    p_administrator_activity_id
  );
end
$function$;

comment on function vortex_platform.grant_connection_application_for_administration(uuid, uuid, uuid) is
  'Human request entry point for granting an application use of a connection instance; delegates to grant_connection_application_internal.';
alter function vortex_platform.grant_connection_application_for_administration(uuid, uuid, uuid) owner to vortex_owner;

create or replace function vortex_platform.issue_flow_continuation(
  p_token_hash text,
  p_run_id uuid,
  p_organization_id uuid,
  p_identity_id uuid,
  p_flow_id uuid,
  p_release_key text,
  p_state jsonb,
  p_elapsed_milliseconds integer,
  p_lifetime_seconds integer
)
returns timestamptz
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  expiry timestamptz;
begin
  if p_token_hash is null or p_token_hash !~ '^[a-f0-9]{64}$'
    or not vortex_platform.is_non_nil_uuid(p_run_id::text)
    or not vortex_platform.is_non_nil_uuid(p_organization_id::text)
    or not vortex_platform.is_non_nil_uuid(p_identity_id::text)
    or not vortex_platform.is_non_nil_uuid(p_flow_id::text)
    or p_release_key is null
    or pg_catalog.length(p_release_key) not between 1 and 200
    or p_state is null
    or pg_catalog.jsonb_typeof(p_state) <> 'object'
    or pg_catalog.pg_column_size(p_state) > 262144
    or p_elapsed_milliseconds is null
    or p_elapsed_milliseconds not between 0 and 3600000
    or p_lifetime_seconds is null
    or p_lifetime_seconds not between 60 and 3600 then
    raise exception using errcode = '22023', message = 'Flow continuation is invalid';
  end if;

  -- Expired continuations are useless; remove a bounded few on every issue so the table never
  -- needs a separate sweeper.
  delete from vortex_platform.flow_continuations as stale
  where stale.ctid in (
    select candidate.ctid
    from vortex_platform.flow_continuations as candidate
    where candidate.expires_at < pg_catalog.statement_timestamp() - interval '1 day'
    limit 100
  );

  expiry := pg_catalog.statement_timestamp() + pg_catalog.make_interval(secs => p_lifetime_seconds);

  insert into vortex_platform.flow_continuations (
    token_hash, run_id, organization_id, identity_id, flow_id, release_key, state,
    elapsed_milliseconds, created_at, expires_at
  ) values (
    p_token_hash, p_run_id, p_organization_id, p_identity_id, p_flow_id, p_release_key, p_state,
    p_elapsed_milliseconds, pg_catalog.statement_timestamp(), expiry
  );

  return expiry;
end
$function$;

comment on function vortex_platform.issue_flow_continuation(
  text, uuid, uuid, uuid, uuid, text, jsonb, integer, integer
) is
  'Private flow-continuation issue: stores the suspended state of one server-driven flow run bound to its run, initiator, organisation and exact flow release, expiring, under the hash of a server-generated token.';

create or replace function vortex_platform.list_terminally_failed_consumer_occurrences(
  p_consumer_key text,
  p_limit integer
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  maximum_limit constant integer := 100;
  results jsonb;
begin
  if p_consumer_key is null
    or pg_catalog.octet_length(p_consumer_key) not between 1 and 128
    or p_consumer_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_limit is null or p_limit not between 1 and maximum_limit then
    raise exception using errcode = '22023',
      message = 'Event delivery recovery listing input is invalid';
  end if;

  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'occurrenceId', bounded.occurrence_id,
      'attemptCount', bounded.attempt_count,
      'failureCount', bounded.failure_count,
      'lastFailureCode', bounded.last_failure_code,
      'lastFailedAt', pg_catalog.to_char(
        pg_catalog.timezone('UTC', bounded.last_failed_at), 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      ),
      'terminallyFailedAt', pg_catalog.to_char(
        pg_catalog.timezone('UTC', bounded.terminally_failed_at), 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      ),
      'claimedAt', pg_catalog.to_char(
        pg_catalog.timezone('UTC', bounded.claimed_at), 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      )
    ) order by bounded.terminally_failed_at, bounded.occurrence_id
  ), '[]'::jsonb) into results
  from (
    select progress.occurrence_id, progress.attempt_count, progress.failure_count,
      progress.last_failure_code, progress.last_failed_at, progress.terminally_failed_at,
      progress.claimed_at
    from vortex_platform.consumer_occurrence_progress as progress
    where progress.consumer_key = p_consumer_key
      and progress.terminally_failed_at is not null
    order by progress.terminally_failed_at, progress.occurrence_id
    limit p_limit
  ) as bounded;

  return results;
end
$function$;

comment on function vortex_platform.list_terminally_failed_consumer_occurrences(text, integer) is
  'Bounded inspection of currently exhausted, replayable claims for one consumer.';

create or replace function vortex_platform.read_committed_flow_start_intent(
  p_intent_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  stored record;
begin
  if not vortex_platform.is_non_nil_uuid(p_intent_id::text) then
    return pg_catalog.jsonb_build_object('kind', 'unavailable');
  end if;

  select
    intent.intent_id,
    intent.organization_id,
    intent.application_root_id,
    intent.application_release_revision,
    intent.application_release_version,
    intent.flow_owner_kind,
    intent.flow_owner_root_id,
    intent.flow_release_revision,
    intent.flow_release_version,
    intent.flow_release_fingerprint,
    intent.flow_id,
    intent.source_kind,
    intent.source_id,
    intent.trigger_type,
    intent.trigger_id,
    intent.inputs,
    intent.trigger_values,
    intent.caller,
    intent.status,
    intent.accepted_at
  into stored
  from vortex_platform.flow_start_intents as intent
  where intent.intent_id = p_intent_id
    and intent.status = 'pending';

  if not found then
    return pg_catalog.jsonb_build_object('kind', 'unavailable');
  end if;

  if stored.source_kind <> 'event'
    or stored.trigger_type <> 'Event'
    or stored.caller ->> 'kind' is distinct from 'event'
    or stored.caller ->> 'correlationId' is null
    or not vortex_platform.is_non_nil_uuid(stored.caller ->> 'correlationId') then
    return pg_catalog.jsonb_build_object('kind', 'unavailable');
  end if;

  return pg_catalog.jsonb_build_object(
    'kind', 'available',
    'intent', pg_catalog.jsonb_build_object(
      'intentId', stored.intent_id,
      'organizationId', stored.organization_id,
      'applicationRootId', stored.application_root_id,
      'applicationReleaseRevision', stored.application_release_revision,
      'applicationReleaseVersion', stored.application_release_version,
      'flowRelease', pg_catalog.jsonb_build_object(
        'ownerKind', stored.flow_owner_kind,
        'rootId', stored.flow_owner_root_id,
        'revision', stored.flow_release_revision,
        'version', stored.flow_release_version,
        'fingerprint', stored.flow_release_fingerprint
      ),
      'flowId', stored.flow_id,
      'origin', 'event',
      'originId', stored.source_id,
      'trigger', pg_catalog.jsonb_build_object(
        'type', 'Event',
        'id', stored.trigger_id
      ),
      'inputs', stored.inputs,
      'triggerValues', stored.trigger_values,
      'correlationId', stored.caller ->> 'correlationId',
      'acceptedAt', stored.accepted_at
    )
  );
end
$function$;

