create or replace function vortex_platform.read_file_upload(p_file_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  established jsonb := vortex_platform.upload_validated_context();
  reservation vortex_platform.upload_reservations%rowtype;
  uploaded vortex_platform.file_records%rowtype;
  current_grant_id uuid;
begin
  select stored.* into reservation
  from vortex_platform.upload_reservations as stored
  where stored.file_id = p_file_id
    and stored.organization_id = (established ->> 'organizationId')::uuid;
  if not found then
    return null;
  end if;

  select stored.* into strict uploaded
  from vortex_platform.file_records as stored
  where stored.file_id = p_file_id;

  select current_grant.one_time_id into current_grant_id
  from vortex_platform.upload_grants as current_grant
  where current_grant.file_id = p_file_id
    and current_grant.superseded_at is null;

  return pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
    'fileRecord', vortex_platform.upload_file_record(uploaded),
    'uploader', reservation.uploaded_by,
    'maximumBytes', reservation.maximum_bytes,
    'uploadExpiresAt', vortex_platform.format_timestamp_utc(reservation.upload_expires_at),
    'replacingFileId', reservation.replacing_file_id,
    'currentGrantId', current_grant_id,
    'correlationId', reservation.correlation_id,
    'revision', reservation.revision
  ));
end
$function$;

comment on function vortex_platform.read_file_upload(uuid) is
  'Reads one upload of the request organisation with its current grant and revision.';

alter function vortex_platform.read_file_upload(uuid) owner to vortex_owner;

create or replace function vortex_platform.read_open_alert_signals(
  p_limit integer default 100
)
returns table (
  signal_id uuid,
  code text,
  severity text,
  affected_service text,
  deduplication_key text,
  owning_role text,
  runbook_reference text,
  occurrence_count bigint,
  first_seen_at timestamptz,
  last_seen_at timestamptz,
  state text
)
language plpgsql
stable
security definer
set search_path = ''
as $function$
begin
  if p_limit is null or p_limit not between 1 and 500 then
    raise exception using errcode = '22023',
      message = 'Operations alert signal read is invalid';
  end if;

  return query
    select signal.signal_id, signal.code, signal.severity, signal.affected_service,
      signal.deduplication_key, signal.owning_role, signal.runbook_reference,
      signal.occurrence_count, signal.first_seen_at, signal.last_seen_at, signal.state
    from vortex_platform.alert_signals as signal
    where signal.state = 'open'
    order by signal.last_seen_at desc, signal.signal_id
    limit p_limit;
end
$function$;

