create or replace function vortex_platform.reauthorize_connection_instance_for_administration(
  p_connection_instance_id uuid,
  p_expected_revision bigint,
  p_administrator_activity_id uuid,
  p_destination_fingerprint text,
  p_token_expires_at timestamptz
)
returns bigint
language plpgsql
volatile
security definer
set search_path = ''
as $function$
begin
  perform vortex_platform.assert_human_administration_request();

  return vortex_platform.reauthorize_connection_instance_internal(
    p_connection_instance_id,
    p_expected_revision,
    p_administrator_activity_id,
    p_destination_fingerprint,
    p_token_expires_at
  );
end
$function$;

comment on function vortex_platform.reauthorize_connection_instance_for_administration(uuid, bigint, uuid, text, timestamptz) is
  'Human request entry point for a revision-checked credential rotation or reauthorisation; delegates to reauthorize_connection_instance_internal.';
alter function vortex_platform.reauthorize_connection_instance_for_administration(uuid, bigint, uuid, text, timestamp with time zone) owner to vortex_owner;

create or replace function vortex_platform.reauthorize_connection_instance_internal(
  p_connection_instance_id uuid,
  p_expected_revision bigint,
  p_administrator_activity_id uuid,
  p_destination_fingerprint text default null,
  p_token_expires_at timestamptz default null
)
returns bigint
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  operation_at timestamptz := pg_catalog.statement_timestamp();
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  conn_row vortex_platform.connection_instances%rowtype;
  new_revision bigint;
  administration_context jsonb;
begin
  if p_administrator_activity_id is null or p_administrator_activity_id = nil_uuid then
    raise exception using
      errcode = '22023',
      message = 'Connection reauthorization requires non-nil administrator activity ID';
  end if;

  if p_expected_revision is null
    or p_expected_revision not between 1 and 9007199254740991 then
    raise exception using
      errcode = '22023',
      message = 'Connection reauthorization requires a valid expected revision';
  end if;

  if p_destination_fingerprint is not null and p_destination_fingerprint !~ '^[a-f0-9]{64}$' then
    raise exception using
      errcode = '22023',
      message = 'Invalid destination fingerprint: must be 64 lowercase hex characters';
  end if;

  -- Validate administration context before locking, then bind the lock to the
  -- context organisation so a foreign or missing identifier is indistinguishable.
  administration_context := vortex_platform.validated_administration_context(vortex_platform.organization_id());

  select conn.* into conn_row
  from vortex_platform.connection_instances as conn
  where conn.connection_instance_id = p_connection_instance_id
    and conn.organization_id = (administration_context ->> 'organizationId')::uuid
  for update;

  if not found or conn_row.revision <> p_expected_revision then
    raise exception using
      errcode = 'P0002',
      message = 'Connection reauthorization failed: revision mismatch or not found';
  end if;

  if conn_row.state <> 'revoked' then
    raise exception using
      errcode = '23514',
      message = 'Connection reauthorization requires revoked source state';
  end if;

  update vortex_platform.connection_instances
  set state = 'pending',
      last_health_outcome = 'unknown',
      destination_fingerprint = coalesce(p_destination_fingerprint, destination_fingerprint),
      token_expires_at = p_token_expires_at,
      administrator_activity_id = p_administrator_activity_id,
      revision = revision + 1,
      updated_at = operation_at
  where connection_instance_id = p_connection_instance_id
    and revision = p_expected_revision
  returning revision into new_revision;

  perform vortex_platform.append_connection_instance_activity_internal(
    administration_context,
    p_administrator_activity_id,
    p_connection_instance_id,
    'connection_reauthorized',
    operation_at
  );

  return new_revision;
end
$function$;

comment on function vortex_platform.reauthorize_connection_instance_internal(uuid, bigint, uuid, text, timestamp with time zone) is null;

revoke all on function
  vortex_platform.reauthorize_connection_instance_internal(uuid, bigint, uuid, text, timestamptz) from public, anon, authenticated, service_role, vortex_runtime, vortex_request;

grant execute on function
  vortex_platform.reauthorize_connection_instance_internal(uuid, bigint, uuid, text, timestamptz) to vortex_runtime;
alter function vortex_platform.reauthorize_connection_instance_internal(uuid, bigint, uuid, text, timestamp with time zone) owner to vortex_owner;

create or replace function vortex_platform.record_alert_signal(
  p_code text,
  p_severity text,
  p_affected_service text,
  p_deduplication_key text,
  p_owning_role text,
  p_runbook_reference text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  observed_at timestamptz := pg_catalog.clock_timestamp();
  stored vortex_platform.alert_signals%rowtype;
begin
  if p_code is null or not vortex_platform.alert_signal_namespaced_key_is_valid(p_code)
    or p_severity is null
    or p_severity not in ('warning', 'error', 'critical')
    or p_affected_service is null
    or not vortex_platform.alert_signal_builder_key_is_valid(p_affected_service)
    or p_deduplication_key is null
    or pg_catalog.length(p_deduplication_key) not between 16 and 200
    or p_deduplication_key !~ '^[a-z0-9][a-z0-9._:-]*$'
    or p_owning_role is null
    or not vortex_platform.alert_signal_builder_key_is_valid(p_owning_role)
    or p_runbook_reference is null
    or not vortex_platform.alert_signal_namespaced_key_is_valid(p_runbook_reference) then
    raise exception using errcode = '22023',
      message = 'Operations alert signal is invalid';
  end if;

  insert into vortex_platform.alert_signals (
    signal_id, code, severity, affected_service, deduplication_key,
    owning_role, runbook_reference, occurrence_count, first_seen_at, last_seen_at, state
  ) values (
    pg_catalog.gen_random_uuid(), p_code, p_severity, p_affected_service,
    p_deduplication_key, p_owning_role, p_runbook_reference, 1, observed_at, observed_at,
    'open'
  )
  on conflict (deduplication_key) do update set
    code = excluded.code,
    severity = excluded.severity,
    affected_service = excluded.affected_service,
    owning_role = excluded.owning_role,
    runbook_reference = excluded.runbook_reference,
    occurrence_count = least(
      vortex_platform.alert_signals.occurrence_count + 1, 9007199254740991
    ),
    last_seen_at = greatest(
      vortex_platform.alert_signals.last_seen_at, excluded.last_seen_at
    ),
    state = 'open'
  returning * into stored;

  return pg_catalog.jsonb_build_object(
    'signalId', stored.signal_id,
    'code', stored.code,
    'severity', stored.severity,
    'affectedService', stored.affected_service,
    'deduplicationKey', stored.deduplication_key,
    'owningRole', stored.owning_role,
    'runbookReference', stored.runbook_reference,
    'occurrenceCount', stored.occurrence_count,
    'firstSeenAt', pg_catalog.to_char(stored.first_seen_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'lastSeenAt', pg_catalog.to_char(stored.last_seen_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'state', stored.state
  );
end
$function$;

comment on function vortex_platform.record_alert_signal(
  text, text, text, text, text, text
) is
  'Validates one contract alert record and upserts it by deduplication key, incrementing the occurrence count, refreshing last-seen and reopening a resolved signal.';

alter function vortex_platform.record_alert_signal(text, text, text, text, text, text)
  owner to vortex_owner;

create or replace function vortex_platform.record_connection_health_check_for_administration(
  p_connection_instance_id uuid,
  p_expected_revision bigint,
  p_new_health_outcome text,
  p_administrator_activity_id uuid
)
returns bigint
language plpgsql
volatile
security definer
set search_path = ''
as $function$
begin
  perform vortex_platform.assert_human_administration_request();

  return vortex_platform.record_connection_health_check_internal(
    p_connection_instance_id,
    p_expected_revision,
    p_new_health_outcome,
    p_administrator_activity_id
  );
end
$function$;

comment on function vortex_platform.record_connection_health_check_for_administration(uuid, bigint, text, uuid) is
  'Human request entry point for recording a revision-checked connection health outcome; delegates to record_connection_health_check_internal.';
alter function vortex_platform.record_connection_health_check_for_administration(uuid, bigint, text, uuid) owner to vortex_owner;

create or replace function vortex_platform.record_connection_health_check_internal(
  p_connection_instance_id uuid,
  p_expected_revision bigint,
  p_new_health_outcome text,
  p_administrator_activity_id uuid default null
)
returns bigint
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  operation_at timestamptz := pg_catalog.statement_timestamp();
  conn_row vortex_platform.connection_instances%rowtype;
  next_state text;
  new_revision bigint;
  administration_context jsonb;
begin
  if p_new_health_outcome not in ('healthy', 'unhealthy') then
    raise exception using
      errcode = '22023',
      message = 'Invalid health outcome: must be healthy or unhealthy';
  end if;

  if p_expected_revision is null
    or p_expected_revision not between 1 and 9007199254740991 then
    raise exception using
      errcode = '22023',
      message = 'Connection health update requires a valid expected revision';
  end if;

  if p_administrator_activity_id is null
    or p_administrator_activity_id = '00000000-0000-0000-0000-000000000000'::uuid then
    raise exception using
      errcode = '22023',
      message = 'Connection health update requires non-nil administrator activity ID';
  end if;

  -- Validate administration context before locking, then bind the lock to the
  -- context organisation so a foreign or missing identifier is indistinguishable.
  administration_context := vortex_platform.validated_administration_context(vortex_platform.organization_id());

  -- Lock row for update
  select conn.* into conn_row
  from vortex_platform.connection_instances as conn
  where conn.connection_instance_id = p_connection_instance_id
    and conn.organization_id = (administration_context ->> 'organizationId')::uuid
  for update;

  if not found or conn_row.revision <> p_expected_revision then
    raise exception using
      errcode = 'P0002',
      message = 'Connection instance health update failed: revision mismatch or not found';
  end if;

  -- Terminal revocation check
  if conn_row.state = 'revoked' then
    raise exception using
      errcode = '42501',
      message = 'Connection instance is revoked; revocation is terminal and cannot transition via health check';
  end if;

  -- Explicit monotonic state transition matrix
  if p_new_health_outcome = 'healthy' then
    next_state := 'active';
  else
    next_state := 'unhealthy';
  end if;

  update vortex_platform.connection_instances
  set last_health_outcome = p_new_health_outcome,
      state = next_state,
      revision = revision + 1,
      administrator_activity_id = p_administrator_activity_id,
      updated_at = operation_at
  where connection_instance_id = p_connection_instance_id
    and revision = p_expected_revision
  returning revision into new_revision;

  perform vortex_platform.append_connection_instance_activity_internal(
    administration_context,
    p_administrator_activity_id,
    p_connection_instance_id,
    'connection_health_recorded',
    operation_at
  );

  return new_revision;
end
$function$;

comment on function vortex_platform.record_connection_health_check_internal(uuid, bigint, text, uuid) is null;

revoke all on function
  vortex_platform.record_connection_health_check_internal(uuid, bigint, text, uuid) from public, anon, authenticated, service_role, vortex_runtime, vortex_request;

grant execute on function
  vortex_platform.record_connection_health_check_internal(uuid, bigint, text, uuid) to vortex_runtime;
alter function vortex_platform.record_connection_health_check_internal(uuid, bigint, text, uuid) owner to vortex_owner;

create or replace function vortex_platform.record_consumer_occurrence_delivery_failure(
  p_consumer_key text,
  p_occurrence_id uuid,
  p_claim_cursor uuid,
  p_failure_code text,
  p_max_attempts integer,
  p_retry_backoff_seconds integer
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  maximum_retry_attempts constant integer := 20;
  maximum_retry_backoff_seconds constant integer := 86400;
  failure_time timestamptz := pg_catalog.statement_timestamp();
  progress_row vortex_platform.consumer_occurrence_progress%rowtype;
  next_failure_count integer;
  next_lease_expires_at timestamptz;
begin
  if p_consumer_key is null
    or pg_catalog.octet_length(p_consumer_key) not between 1 and 128
    or p_consumer_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_occurrence_id is null or p_occurrence_id = nil_uuid
    or p_claim_cursor is null or p_claim_cursor = nil_uuid
    or p_failure_code is null
    or p_failure_code not in (
      'transient_dependency_unavailable', 'transient_timeout', 'validation_rejected',
      'authorization_denied', 'conflict_or_duplicate', 'unclassified'
    )
    or p_max_attempts is null or p_max_attempts not between 1 and maximum_retry_attempts
    or p_retry_backoff_seconds is null
      or p_retry_backoff_seconds not between 1 and maximum_retry_backoff_seconds then
    raise exception using errcode = '22023',
      message = 'Event delivery failure input is invalid';
  end if;

  select progress.* into progress_row
  from vortex_platform.consumer_occurrence_progress as progress
  where progress.consumer_key = p_consumer_key
    and progress.occurrence_id = p_occurrence_id
  for update;

  if not found then
    return pg_catalog.jsonb_build_object('outcome', 'claim_unavailable');
  end if;
  if progress_row.claim_cursor <> p_claim_cursor then
    return pg_catalog.jsonb_build_object('outcome', 'mismatched');
  end if;
  if progress_row.acknowledged_at is not null then
    return pg_catalog.jsonb_build_object('outcome', 'already_acknowledged');
  end if;
  if progress_row.terminally_failed_at is not null then
    return pg_catalog.jsonb_build_object(
      'outcome', 'terminal_failure',
      'failureCount', progress_row.failure_count,
      'failureCode', progress_row.last_failure_code
    );
  end if;

  next_failure_count := progress_row.failure_count + 1;

  if next_failure_count >= p_max_attempts then
    update vortex_platform.consumer_occurrence_progress
    set failure_count = next_failure_count,
        last_failure_code = p_failure_code,
        last_failed_at = failure_time,
        terminally_failed_at = failure_time
    where consumer_key = p_consumer_key and occurrence_id = p_occurrence_id;

    return pg_catalog.jsonb_build_object(
      'outcome', 'terminal_failure',
      'failureCount', next_failure_count,
      'failureCode', p_failure_code
    );
  end if;

  -- Releasing the lease at the backoff instant is what schedules the retry:
  -- #639's claim reclaims exactly this consumer/occurrence row once the lease
  -- has lapsed, so no fresh work is claimed and no ordering is skipped.
  next_lease_expires_at := failure_time + pg_catalog.make_interval(secs => p_retry_backoff_seconds);
  update vortex_platform.consumer_occurrence_progress
  set failure_count = next_failure_count,
      last_failure_code = p_failure_code,
      last_failed_at = failure_time,
      lease_expires_at = next_lease_expires_at
  where consumer_key = p_consumer_key and occurrence_id = p_occurrence_id;

  return pg_catalog.jsonb_build_object(
    'outcome', 'retry_scheduled',
    'failureCount', next_failure_count,
    'retryNotBefore', pg_catalog.to_char(
      pg_catalog.timezone('UTC', next_lease_expires_at), 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
    )
  );
end
$function$;

comment on function vortex_platform.record_consumer_occurrence_delivery_failure(
  text, uuid, uuid, text, integer, integer
) is
  'Records one failed delivery attempt against an existing claim, scheduling a bounded retry or marking it terminally failed.';

create or replace function vortex_platform.record_file_download_grant(
  p_one_time_id uuid,
  p_file_id uuid,
  p_owner_record_type_id uuid,
  p_owner_record_id uuid,
  p_owner_field_id uuid,
  p_actor jsonb,
  p_purpose text,
  p_correlation_id uuid,
  p_expires_at timestamptz
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.statement_timestamp();
  established jsonb := vortex_platform.validated_service_context();
  request_actor jsonb := vortex_platform.upload_request_actor(established);
  request_organization_id uuid := (established ->> 'organizationId')::uuid;
  stored vortex_platform.file_records%rowtype;
begin
  if request_actor is null
    or p_actor is distinct from request_actor then
    raise exception using errcode = '42501', message = 'File read scope is unavailable';
  end if;

  if p_one_time_id is null
    or p_file_id is null
    or p_owner_record_type_id is null
    or p_owner_record_id is null
    or p_owner_field_id is null
    or p_correlation_id is null
    or p_purpose is null or p_purpose not in ('download', 'preview')
    or p_expires_at is null
    or p_expires_at <= evaluated_at
    or p_expires_at > evaluated_at + interval '65 seconds' then
    raise exception using errcode = '22023', message = 'File read grant is invalid';
  end if;

  select candidate.* into stored
  from vortex_platform.file_records as candidate
  where candidate.file_id = p_file_id
    and candidate.organization_id = request_organization_id;
  if not found
    or stored.lifecycle_state <> 'active'
    or stored.scanner_result <> 'clean'
    or stored.owner_record_type_id is distinct from p_owner_record_type_id
    or stored.owner_record_id is distinct from p_owner_record_id
    or stored.owner_field_id is distinct from p_owner_field_id then
    return pg_catalog.jsonb_build_object('outcome', 'refused');
  end if;

  delete from vortex_platform.download_grants as expired
  where expired.ctid in (
    select candidate.ctid
    from vortex_platform.download_grants as candidate
    where candidate.organization_id = request_organization_id
      and candidate.expires_at < evaluated_at - interval '1 hour'
    order by candidate.expires_at
    limit 100
  );

  insert into vortex_platform.download_grants (
    one_time_id, file_id, organization_id,
    owner_record_type_id, owner_record_id, owner_field_id,
    actor, purpose, correlation_id, expires_at, created_at
  ) values (
    p_one_time_id, p_file_id, request_organization_id,
    p_owner_record_type_id, p_owner_record_id, p_owner_field_id,
    request_actor, p_purpose, p_correlation_id, p_expires_at, evaluated_at
  );

  return pg_catalog.jsonb_build_object('outcome', 'recorded');
end
$function$;

