  p_token_expires_at timestamptz default null
)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  operation_at timestamptz := pg_catalog.statement_timestamp();
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  administration_context jsonb;
begin
  -- Validate administration context for target organization
  administration_context := vortex_platform.validated_administration_context(p_organization_id);

  if p_administrator_activity_id is null or p_administrator_activity_id = nil_uuid then
    raise exception using
      errcode = '22023',
      message = 'Connection registration requires non-nil administrator activity ID';
  end if;

  insert into vortex_platform.connection_instances (
    connection_instance_id,
    organization_id,
    connection_type_id,
    connection_type_version,
    destination_key,
