create or replace function vortex_platform.renew_consumer_occurrence_lease(
  p_consumer_key text,
  p_ack_cursor uuid,
  p_occurrence_id uuid,
  p_lease_seconds integer
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  maximum_lease_seconds constant integer := 300;
  renewal_time timestamptz := pg_catalog.statement_timestamp();
  renewed_until timestamptz;
begin
  if p_consumer_key is null
    or pg_catalog.octet_length(p_consumer_key) not between 1 and 128
    or p_consumer_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
    or p_ack_cursor is null or p_ack_cursor = nil_uuid
    or p_occurrence_id is null or p_occurrence_id = nil_uuid
    or p_lease_seconds is null
    or p_lease_seconds not between 1 and maximum_lease_seconds then
    raise exception using errcode = '22023', message = 'Event consumer lease renewal input is invalid';
  end if;

  update vortex_platform.consumer_occurrence_progress
  set lease_expires_at = renewal_time + pg_catalog.make_interval(secs => p_lease_seconds)
  where consumer_key = p_consumer_key
    and occurrence_id = p_occurrence_id
    and claim_cursor = p_ack_cursor
    and acknowledged_at is null
    and terminally_failed_at is null
    and lease_expires_at > renewal_time
  returning lease_expires_at into renewed_until;

  if renewed_until is null then
    return pg_catalog.jsonb_build_object('outcome', 'claim_unavailable');
  end if;
  return pg_catalog.jsonb_build_object(
    'outcome', 'renewed',
    'leaseExpiresAt', pg_catalog.to_char(
      pg_catalog.timezone('UTC', renewed_until), 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
    )
  );
end
$function$;

comment on function vortex_platform.renew_consumer_occurrence_lease(text, uuid, uuid, integer) is
  'Renews one still-live consumer Event occurrence claim without changing immutable occurrence evidence.';

create or replace function vortex_platform.renew_file_upload(
  p_file_id uuid,
  p_expected_revision bigint,
  p_previous_one_time_id uuid,
  p_new_one_time_id uuid,
  p_policy_fingerprint text,
  p_grant_expires_at timestamptz
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.statement_timestamp();
  established jsonb := vortex_platform.upload_validated_context();
  request_actor jsonb := vortex_platform.upload_request_actor(established);
  reservation vortex_platform.upload_reservations%rowtype;
  uploaded vortex_platform.file_records%rowtype;
  current_grant_id uuid;
begin
  select stored.* into reservation
  from vortex_platform.upload_reservations as stored
  where stored.file_id = p_file_id
    and stored.organization_id = (established ->> 'organizationId')::uuid
  for update;
  if not found then
    return vortex_platform.upload_refusal('file_not_found');
  end if;
  if request_actor is null or reservation.uploaded_by is distinct from request_actor then
    return vortex_platform.upload_refusal('caller_not_authorized');
  end if;

  select stored.* into strict uploaded
  from vortex_platform.file_records as stored
  where stored.file_id = p_file_id;
  if uploaded.lifecycle_state <> 'pending' then
    return vortex_platform.upload_refusal('invalid_lifecycle_state');
  end if;
  if reservation.upload_expires_at <= evaluated_at then
    return vortex_platform.upload_refusal('upload_expired');
  end if;

  select current_grant.one_time_id into current_grant_id
  from vortex_platform.upload_grants as current_grant
  where current_grant.file_id = p_file_id
    and current_grant.superseded_at is null
  for update;
  if reservation.revision is distinct from p_expected_revision
    or current_grant_id is distinct from p_previous_one_time_id then
    return vortex_platform.upload_refusal('grant_mismatch');
  end if;

  if p_new_one_time_id is null
    or p_policy_fingerprint is null
    or p_grant_expires_at is null
    or p_grant_expires_at <= evaluated_at
    or p_grant_expires_at > evaluated_at + interval '65 seconds'
    or p_grant_expires_at > reservation.upload_expires_at then
    raise exception using errcode = '22023', message = 'File upload renewal is invalid';
  end if;

  update vortex_platform.upload_grants
  set superseded_at = evaluated_at
  where one_time_id = p_previous_one_time_id;

  insert into vortex_platform.upload_grants (
    one_time_id, file_id, organization_id, actor, maximum_bytes,
    policy_fingerprint, expires_at, created_at
  ) values (
    p_new_one_time_id, p_file_id, reservation.organization_id, reservation.uploaded_by,
    reservation.maximum_bytes, p_policy_fingerprint, p_grant_expires_at, evaluated_at
  );

  update vortex_platform.upload_reservations
  set revision = revision + 1, updated_at = evaluated_at
  where file_id = p_file_id;

  return pg_catalog.jsonb_build_object('outcome', 'renewed');
end
$function$;

