    raise exception using errcode = '55000', message = 'Vortex Identity Authority context is required';
  end if;
  return value::uuid;
end
$$;

COMMENT ON FUNCTION vortex_platform.identity_authority_id(required boolean) IS 'Returns the trusted Identity Authority for human/federated context, or fails when required and absent.';

REVOKE ALL ON FUNCTION vortex_platform.identity_authority_id(required boolean) FROM PUBLIC;
GRANT ALL ON FUNCTION vortex_platform.identity_authority_id(required boolean) TO vortex_request;

CREATE OR REPLACE FUNCTION vortex_platform.initialize(candidate jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  checked jsonb;
  established integer;
begin
  checked := vortex_platform.validated(candidate);

  insert into vortex_platform.request_contexts as stored (backend_pid, transaction_id, context)
  values (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), checked)
  on conflict on constraint request_contexts_pk do update
    set transaction_id = excluded.transaction_id, context = excluded.context
    where stored.transaction_id <> excluded.transaction_id;
  get diagnostics established = row_count;

  if established = 0 then
    raise exception using errcode = '55000', message = 'Vortex request context is already established';
  end if;
end
$$;

COMMENT ON FUNCTION vortex_platform.initialize(candidate jsonb) IS 'Validates and stores one trusted request context for the current transaction; refuses a second establishment in the same transaction.';

REVOKE ALL ON FUNCTION vortex_platform.initialize(candidate jsonb) FROM PUBLIC;
GRANT ALL ON FUNCTION vortex_platform.initialize(candidate jsonb) TO vortex_runtime;

create or replace function vortex_platform.is_non_nil_uuid(candidate text)
returns boolean
language sql
immutable
parallel safe
security invoker
set search_path = ''
as $function$
  select
    coalesce(
      candidate ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      and candidate <> '00000000-0000-0000-0000-000000000000',
      false
    )
$function$;

comment on function vortex_platform.is_non_nil_uuid(text) is
  'Accepts only a non-nil RFC UUID with a version nibble from 1 through 8 and an RFC variant nibble.';

create or replace function vortex_platform.list_connection_instances_for_administration(
  p_organization_id uuid,
  p_after_connection_instance_id uuid,
  p_page_size integer
)
returns table (
  organization_id uuid,
  connection_instances jsonb,
  next_after_connection_instance_id uuid
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  administration_context jsonb;
  page_items jsonb;
  page_connection_instance_ids uuid[];
  candidate_count integer;
begin
  if p_organization_id is null or p_organization_id = nil_uuid
    or p_after_connection_instance_id = nil_uuid
    or p_page_size is null or p_page_size not between 1 and 100 then
    raise exception using
      errcode = '22023',
      message = 'Connection instance page input is invalid';
  end if;

  perform vortex_platform.assert_human_administration_request();
  administration_context :=
    vortex_platform.validated_administration_context(p_organization_id);

  with candidates as (
    select
      conn.connection_instance_id,
      conn.connection_type_id,
      conn.connection_type_version,
      conn.state,
      conn.last_health_outcome,
      conn.revision,
      conn.token_expires_at,
      coalesce(
        (
          select pg_catalog.array_agg(
            grant_entry.application_root_id order by grant_entry.application_root_id
          )
          from vortex_platform.connection_application_grants as grant_entry
          join vortex_definition.roots as app_root
            on app_root.root_id = grant_entry.application_root_id
            and app_root.organization_id = grant_entry.organization_id
            and app_root.kind = 'application'
          where grant_entry.connection_instance_id = conn.connection_instance_id
            and grant_entry.organization_id = conn.organization_id
        ),
        array[]::uuid[]
      ) as authorized_application_ids,
      pg_catalog.row_number() over (order by conn.connection_instance_id) as ordinal
    from vortex_platform.connection_instances as conn
    where conn.organization_id = (administration_context ->> 'organizationId')::uuid
      and (p_after_connection_instance_id is null
        or conn.connection_instance_id > p_after_connection_instance_id)
    order by conn.connection_instance_id
    limit p_page_size + 1
  )
  select
    coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_strip_nulls(
          pg_catalog.jsonb_build_object(
            'connectionInstanceId', candidate.connection_instance_id,
            'connectionTypeId', candidate.connection_type_id,
            'connectionTypeVersion', candidate.connection_type_version,
            'state', candidate.state,
            'lastHealthOutcome', candidate.last_health_outcome,
            'revision', candidate.revision,
            'tokenExpiresAt', case
              when candidate.token_expires_at is null
                or not pg_catalog.isfinite(candidate.token_expires_at)
              then null
              else pg_catalog.to_jsonb(candidate.token_expires_at)
            end,
            'authorizedApplicationIds',
              pg_catalog.to_jsonb(candidate.authorized_application_ids),
            'grantedScopes', '[]'::jsonb
          )
        ) order by candidate.connection_instance_id
      ) filter (where candidate.ordinal <= p_page_size),
      '[]'::jsonb
    ),
    pg_catalog.array_agg(candidate.connection_instance_id order by candidate.ordinal)
      filter (where candidate.ordinal <= p_page_size),
    pg_catalog.count(*)
  into page_items, page_connection_instance_ids, candidate_count
  from candidates as candidate;

  return query
  select
    (administration_context ->> 'organizationId')::uuid,
    page_items,
    case when candidate_count > p_page_size
      then page_connection_instance_ids[p_page_size] else null end;
end
$function$;

comment on function
  vortex_platform.list_connection_instances_for_administration(uuid, uuid, integer) is
  'Reads one bounded page of connection instance safe statuses for the administration page in the request context organisation. Returns state, health, expiry, authority revision and both scope lists per instance; never a secret, a secret reference, an organisation identity or another organisation instance.';

create or replace function vortex_platform.may_receive_topic(p_topic text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $function$
  select exists (
    select 1
    from vortex_identity.identity_projections as projection
    join vortex_identity.organization_accounts as account
      on account.identity_id = projection.identity_id
    join vortex_identity.organizations as organization
      on organization.organization_id = account.organization_id
    join vortex_identity.tenants as tenant
      on tenant.tenant_id = organization.tenant_id
    where projection.identity_id = auth.uid()
      and projection.state = 'active'
      and account.state = 'active'
      and organization.state = 'active'
      and tenant.state = 'active'
      and organization.organization_id = vortex_platform.topic_organization_id(p_topic)
      and vortex_platform.application_is_installed(
        organization.organization_id,
        vortex_platform.topic_application_root_id(p_topic)
      )
  )
$function$;

comment on function vortex_platform.may_receive_topic(text) is
  'Authorises one authenticated identity to read a private topic only for an active organisation account it holds and an application currently installed there.';

alter function vortex_platform.may_receive_topic(text)
  owner to postgres;

create or replace function vortex_platform.organization_id()
returns uuid
language sql
