create or replace function vortex_platform.publish_change_notice(
  p_organization_id uuid,
  p_application_root_id uuid,
  p_record_type_id uuid,
  p_record_id uuid,
  p_record_version bigint,
  p_change_kind text,
  p_data_version bigint,
  p_sequence bigint,
  p_correlation_id uuid
)
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  operation_at timestamptz := pg_catalog.clock_timestamp();
  selected_topic text;
  selected_payload jsonb;
  stored_context text;
begin
  if p_organization_id is null
    or not vortex_platform.is_non_nil_uuid(p_organization_id::text)
    or p_application_root_id is null
    or not vortex_platform.is_non_nil_uuid(p_application_root_id::text)
    or p_record_type_id is null
    or not vortex_platform.is_non_nil_uuid(p_record_type_id::text)
    or (p_record_id is not null and not vortex_platform.is_non_nil_uuid(p_record_id::text))
    or (p_record_version is not null
      and p_record_version not between 1 and 9007199254740991)
    or p_change_kind is null
    or not (
      p_change_kind = any (
        vortex_access.validation_reference_list('private_invalidation_change_kind')
      )
    )
    or p_data_version is null
    or p_data_version not between 1 and 9007199254740991
    or p_sequence is null
    or p_sequence not between 1 and 9007199254740991
    or p_correlation_id is null
    or not vortex_platform.is_non_nil_uuid(p_correlation_id::text) then
    raise exception using errcode = '22023',
      message = 'Invalidation notice command is invalid';
  end if;

  stored_context := pg_catalog.current_setting('vortex.request_context', true);
  if stored_context is not null and stored_context <> ''
    and (vortex_platform.current_context() ->> 'organizationId')::uuid
      is distinct from p_organization_id then
    raise exception using errcode = '42501',
      message = 'Invalidation notice scope is unavailable';
  end if;

  if not exists (
    select 1
    from vortex_identity.organizations as organization
    join vortex_identity.tenants as tenant
      on tenant.tenant_id = organization.tenant_id
    where organization.organization_id = p_organization_id
      and organization.state = 'active'
      and tenant.state = 'active'
  ) or not vortex_platform.application_is_installed(
    p_organization_id, p_application_root_id
  ) then
    raise exception using errcode = 'P0002',
      message = 'Invalidation notice scope is unavailable';
  end if;

  selected_topic := vortex_platform.change_topic(p_organization_id, p_application_root_id);

  selected_payload := pg_catalog.jsonb_build_object(
    'contractVersion', '1.0.0',
    'organizationId', p_organization_id,
    'applicationRootId', p_application_root_id,
    'recordTypeId', p_record_type_id,
    'changeKind', p_change_kind,
    'dataVersion', p_data_version,
    'sequence', p_sequence,
    'occurredAt', vortex_platform.format_timestamp_utc(operation_at),
    'correlationId', p_correlation_id
  )
  || case when p_record_id is null then '{}'::jsonb
    else pg_catalog.jsonb_build_object('recordId', p_record_id) end
  || case when p_record_version is null then '{}'::jsonb
    else pg_catalog.jsonb_build_object('recordVersion', p_record_version) end;

  perform realtime.send(selected_payload, 'invalidation', selected_topic, true);

  return selected_topic;
end
$function$;

comment on function vortex_platform.publish_change_notice(
  uuid, uuid, uuid, uuid, bigint, text, bigint, bigint, uuid
) is
  'Protected post-commit broadcast of the bounded content-free invalidation envelope on the private topic for one organisation and application.';

create or replace function vortex_platform.read_active_connection_evidence(
  p_connection_instance_id uuid
)
returns table (
  connection_instance_id uuid,
  destination_key text,
  destination_fingerprint text,
  organization_id uuid,
  authorized_application_ids uuid[],
  state text,
  revision bigint,
  last_health_outcome text
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  context_org_id uuid;
  conn_row vortex_platform.connection_instances%rowtype;
  locked_authorized_application_ids uuid[];
begin
  context_org_id := vortex_platform.organization_id();

  select conn.* into conn_row
  from vortex_platform.connection_instances as conn
  where conn.connection_instance_id = p_connection_instance_id
    and conn.organization_id = context_org_id
    and conn.state = 'active'
    and conn.last_health_outcome = 'healthy'
    and (conn.token_expires_at is null
      or (pg_catalog.isfinite(conn.token_expires_at)
        and conn.token_expires_at > pg_catalog.statement_timestamp()))
  for share;

  if not found then
    return;
  end if;

  select pg_catalog.array_agg(
    locked_grant.application_root_id order by locked_grant.application_root_id
  )
  into locked_authorized_application_ids
  from (
    select grant_entry.application_root_id
    from vortex_platform.connection_application_grants as grant_entry
    join vortex_definition.roots as app_root
      on app_root.root_id = grant_entry.application_root_id
      and app_root.organization_id = grant_entry.organization_id
      and app_root.kind = 'application'
    where grant_entry.connection_instance_id = conn_row.connection_instance_id
      and grant_entry.organization_id = conn_row.organization_id
    for share of grant_entry, app_root
  ) as locked_grant;

  if locked_authorized_application_ids is null then
    return;
  end if;

  return query
  select
    conn_row.connection_instance_id,
    conn_row.destination_key,
    conn_row.destination_fingerprint,
    conn_row.organization_id,
    locked_authorized_application_ids,
    conn_row.state,
    conn_row.revision,
    conn_row.last_health_outcome;
end
$function$;

comment on function vortex_platform.read_active_connection_evidence(uuid) is
  '#408: Reads active healthy Connection instance evidence scoped to current context organization.';

revoke all on function
  vortex_platform.read_active_connection_evidence(uuid) from public, anon, authenticated, service_role, vortex_runtime, vortex_request;

grant execute on function
  vortex_platform.read_active_connection_evidence(uuid) to vortex_request, vortex_runtime;

create or replace function vortex_platform.read_connection_instance_for_administration(
  p_organization_id uuid,
  p_connection_instance_id uuid
)
returns table (
  organization_id uuid,
  connection_instance jsonb
)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  administration_context jsonb;
  conn_row vortex_platform.connection_instances%rowtype;
  authorized_application_ids uuid[];
begin
  if p_organization_id is null or p_organization_id = nil_uuid
    or p_connection_instance_id is null or p_connection_instance_id = nil_uuid then
    raise exception using
      errcode = '22023',
      message = 'Connection instance read input is invalid';
  end if;

  perform vortex_platform.assert_human_administration_request();
  administration_context :=
    vortex_platform.validated_administration_context(p_organization_id);

  select conn.* into conn_row
  from vortex_platform.connection_instances as conn
  where conn.connection_instance_id = p_connection_instance_id
    and conn.organization_id = (administration_context ->> 'organizationId')::uuid;

  if not found then
    return;
  end if;

  select coalesce(
    pg_catalog.array_agg(
      grant_entry.application_root_id order by grant_entry.application_root_id
    ),
    array[]::uuid[]
  )
  into authorized_application_ids
  from vortex_platform.connection_application_grants as grant_entry
  join vortex_definition.roots as app_root
    on app_root.root_id = grant_entry.application_root_id
    and app_root.organization_id = grant_entry.organization_id
    and app_root.kind = 'application'
  where grant_entry.connection_instance_id = conn_row.connection_instance_id
    and grant_entry.organization_id = conn_row.organization_id;

  return query
  select
    conn_row.organization_id,
    pg_catalog.jsonb_strip_nulls(
      pg_catalog.jsonb_build_object(
        'connectionInstanceId', conn_row.connection_instance_id,
        'connectionTypeId', conn_row.connection_type_id,
        'connectionTypeVersion', conn_row.connection_type_version,
        'state', conn_row.state,
        'lastHealthOutcome', conn_row.last_health_outcome,
        'revision', conn_row.revision,
        'tokenExpiresAt', case
          when conn_row.token_expires_at is null
            or not pg_catalog.isfinite(conn_row.token_expires_at)
          then null
          else pg_catalog.to_jsonb(conn_row.token_expires_at)
        end,
        'authorizedApplicationIds', pg_catalog.to_jsonb(authorized_application_ids),
        'grantedScopes', '[]'::jsonb
      )
    );
end
$function$;

comment on function
  vortex_platform.read_connection_instance_for_administration(uuid, uuid) is
  'Reads one connection instance safe status for the administration page in the request context organisation. Returns state, health, expiry, authority revision and both scope lists; never a secret, a secret reference, an organisation identity or another organisation instance.';

CREATE OR REPLACE FUNCTION vortex_platform.read_file_application(p_file_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  located_application_root_id uuid;
begin
  if p_file_id is null
    or p_file_id = '00000000-0000-0000-0000-000000000000'::uuid then
    return pg_catalog.jsonb_build_object('outcome', 'refused');
  end if;

  select stored.application_root_id into located_application_root_id
  from vortex_platform.file_records as stored
  where stored.file_id = p_file_id
    and stored.lifecycle_state = 'active'
    and stored.owner_record_id is not null;
  if not found or located_application_root_id is null then
    return pg_catalog.jsonb_build_object('outcome', 'refused');
  end if;

  return pg_catalog.jsonb_build_object(
    'outcome', 'located',
    'applicationRootId', located_application_root_id
  );
end
$$;

COMMENT ON FUNCTION vortex_platform.read_file_application(p_file_id uuid) IS 'Locates the application of an active attached file of the request organisation.';

REVOKE ALL ON FUNCTION vortex_platform.read_file_application(p_file_id uuid) FROM PUBLIC;
GRANT ALL ON FUNCTION vortex_platform.read_file_application(p_file_id uuid) TO vortex_request;

create or replace function vortex_platform.read_protected_node_effect(
  p_run_id uuid,
  p_organization_id uuid,
  p_identity_id uuid,
  p_task_path text,
  p_iteration text,
  p_operation_key text
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  existing record;
begin
  if not exists (
    select 1
    from vortex_platform.protected_workflow_runs as stored
    where stored.run_id = p_run_id
      and stored.organization_id = p_organization_id
      and stored.identity_id = p_identity_id
      and exists (
        select 1
        from pg_catalog.jsonb_array_elements(stored.run_record -> 'nodes') as node(value)
        where pg_catalog.lower(node.value ->> 'nodeId') = pg_catalog.lower(p_task_path)
          and node.value ->> 'operationKey' = p_operation_key
      )
  ) then
    return pg_catalog.jsonb_build_object('kind', 'unavailable');
  end if;

  select ledger.state, ledger.outcome, ledger.outputs into existing
  from vortex_platform.flow_effect_ledger as ledger
  where ledger.run_id = p_run_id
    and ledger.organization_id = p_organization_id
    and ledger.identity_id = p_identity_id
    and ledger.task_path = p_task_path
    and ledger.iteration = p_iteration;
  if not found then
    return pg_catalog.jsonb_build_object('kind', 'missing');
  end if;
  if existing.state = 'completed' then
    return pg_catalog.jsonb_build_object(
      'kind', 'completed',
      'outcome', existing.outcome,
      'outputs', coalesce(existing.outputs, '{}'::jsonb)
    );
  end if;
  return pg_catalog.jsonb_build_object('kind', 'in_progress');
end
$function$;

comment on function vortex_platform.read_protected_node_effect(
  uuid, uuid, uuid, text, text, text
) is
  'Reads a prior protected node response only for the exact retained run and node binding; it never claims or changes an effect.';

create or replace function vortex_platform.read_protected_workflow_run_registration(p_run_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  stored vortex_platform.protected_workflow_runs%rowtype;
  run_value jsonb;
  field_path text[];
  application_id uuid;
  permanent_flow_id uuid;
  compiler_revision bigint;
  version_value text;
  matched record;
  matched_count integer := 0;
  declarations jsonb;
  release_value jsonb;
begin
  if p_run_id is null or not vortex_platform.is_non_nil_uuid(p_run_id::text) then
    return null;
  end if;

  select run.* into stored
  from vortex_platform.protected_workflow_runs as run
  where run.run_id = p_run_id;
  if not found then
    return null;
  end if;
  run_value := stored.run_record;
  if pg_catalog.jsonb_typeof(run_value) is distinct from 'object'
    or pg_catalog.jsonb_typeof(run_value -> 'authority') is distinct from 'object'
    or pg_catalog.jsonb_typeof(run_value -> 'executionReference') is distinct from 'object'
    or pg_catalog.jsonb_typeof(run_value -> 'kestra') is distinct from 'object' then
    return null;
  end if;

  -- Check JSON types and RFC UUIDs before casts. NULL comparisons always refuse.
  for field_path in select path from (values
    (array['authority', 'runId']),
    (array['authority', 'organizationId']),
    (array['authority', 'applicationRootId']),
    (array['authority', 'workflowId']),
    (array['executionReference', 'runId']),
    (array['executionReference', 'tenantId']),
    (array['executionReference', 'organizationId']),
    (array['executionReference', 'applicationRootId']),
    (array['executionReference', 'workflowId'])
  ) as required(path) loop
    if pg_catalog.jsonb_typeof(run_value #> field_path) is distinct from 'string'
      or not vortex_platform.is_non_nil_uuid(run_value #>> field_path) then
      return null;
    end if;
  end loop;
  if pg_catalog.lower(run_value #>> '{authority,runId}') is distinct from p_run_id::text
    or pg_catalog.lower(run_value #>> '{executionReference,runId}') is distinct from p_run_id::text
    or pg_catalog.lower(run_value #>> '{authority,organizationId}') is distinct from stored.organization_id::text
    or pg_catalog.lower(run_value #>> '{executionReference,organizationId}') is distinct from stored.organization_id::text
    or pg_catalog.lower(run_value #>> '{authority,applicationRootId}') is distinct from pg_catalog.lower(run_value #>> '{executionReference,applicationRootId}')
    or pg_catalog.lower(run_value #>> '{authority,workflowId}') is distinct from pg_catalog.lower(run_value #>> '{executionReference,workflowId}') then
    return null;
  end if;

  for field_path in select path from (values
    (array['authority', 'workflowRevision']),
    (array['executionReference', 'workflowRevision'])
  ) as required(path) loop
    if pg_catalog.jsonb_typeof(run_value #> field_path) is distinct from 'number'
      or (run_value #>> field_path) !~ '^[1-9][0-9]{0,15}$' then
      return null;
    end if;
    if (run_value #>> field_path)::bigint not between 1 and 9007199254740991 then
      return null;
    end if;
  end loop;
  compiler_revision := (run_value #>> '{authority,workflowRevision}')::bigint;
  if compiler_revision <> (run_value #>> '{executionReference,workflowRevision}')::bigint
    or pg_catalog.jsonb_typeof(run_value #> '{authority,applicationReleaseVersion}') is distinct from 'string'
    or pg_catalog.jsonb_typeof(run_value #> '{executionReference,applicationVersion}') is distinct from 'string'
    or (run_value #>> '{authority,applicationReleaseVersion}') !~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$'
    or run_value #>> '{authority,applicationReleaseVersion}' is distinct from run_value #>> '{executionReference,applicationVersion}'
    or pg_catalog.jsonb_typeof(run_value #> '{kestra,namespace}') is distinct from 'string'
    or pg_catalog.jsonb_typeof(run_value #> '{kestra,flowId}') is distinct from 'string' then
    return null;
  end if;
  application_id := (run_value #>> '{authority,applicationRootId}')::uuid;
  permanent_flow_id := (run_value #>> '{authority,workflowId}')::uuid;
  version_value := run_value #>> '{authority,applicationReleaseVersion}';

  -- Only the stored organization can supply the Vortex tenant. Provider tenant
  -- labels remain private mapping metadata and confer no Vortex authority.
  perform 1 from vortex_identity.organizations as organization
  where organization.organization_id = stored.organization_id
    and organization.tenant_id = (run_value #>> '{executionReference,tenantId}')::uuid;
  if not found then
    return null;
  end if;

  -- Do not consult current_release_revision or reinterpret inactive preparation
  -- status as current installation activation or provider execution state.
  for matched in
    select registration.*, published.compilation_output,
      published.content_fingerprint, published.resolution_fingerprint
    from vortex_platform.flow_registrations as registration
    join vortex_definition.releases as published
      on published.root_id = registration.application_root_id
      and published.release_revision = registration.installation_revision
      and published.release_version = registration.application_version
    join vortex_definition.roots as root
      on root.root_id = published.root_id
      and root.organization_id = registration.organization_id
      and root.kind = 'application'
    where registration.organization_id = stored.organization_id
      and registration.application_root_id = application_id
      and registration.application_version = version_value
      and registration.workflow_revision = compiler_revision
      and registration.namespace = run_value #>> '{kestra,namespace}'
      and registration.flow_id = run_value #>> '{kestra,flowId}'
      and registration.namespace = pg_catalog.concat_ws('.', 'vortex', 'application',
        registration.environment, stored.organization_id::text,
        application_id::text, 'i' || registration.installation_revision::text)
      and registration.flow_id = 'w_' || permanent_flow_id::text || '_'
        || pg_catalog.replace(version_value, '.', '-') || '_r' || compiler_revision::text
      and published.compilation_output ->> 'kind' = 'application'
      and published.compilation_output #>> '{canonical,envelope,kind}' = 'application'
      and published.compilation_output #>> '{canonical,envelope,key}' = root.key
      and published.compilation_output #>> '{canonical,envelope,rootId}' = application_id::text
      and published.compilation_output #>> '{canonical,envelope,organizationId}' = stored.organization_id::text
      and published.compilation_output #>> '{artifact,kind}' = 'application'
      and published.compilation_output #>> '{artifact,rootId}' = application_id::text
      and published.compilation_output #>> '{artifact,definitionKey}' = root.key
      and published.compilation_output #>> '{artifact,exactVersion}' = version_value
      and published.compilation_output #>> '{artifact,contentFingerprint}' = published.content_fingerprint
      and published.compilation_output #>> '{artifact,resolutionFingerprint}' = published.resolution_fingerprint
      and published.compilation_output ->> 'resolutionFingerprint' = published.resolution_fingerprint
  loop
    matched_count := matched_count + 1;
    if matched_count <> 1 then
      return null;
    end if;
    if pg_catalog.jsonb_typeof(matched.compilation_output #> '{canonical,content,flows}') is distinct from 'array' then
      return null;
    end if;
    select pg_catalog.jsonb_agg(flow.value) into declarations
    from pg_catalog.jsonb_array_elements(matched.compilation_output #> '{canonical,content,flows}') as flow(value)
    where pg_catalog.jsonb_typeof(flow.value) = 'object'
      and pg_catalog.jsonb_typeof(flow.value -> 'id') = 'string'
      and pg_catalog.lower(flow.value ->> 'id') = permanent_flow_id::text;
    if declarations is null or pg_catalog.jsonb_array_length(declarations) <> 1 then
      return null;
    end if;
    if declarations #> '{0,execution}' is distinct from '"durable"'::jsonb then
      return null;
    end if;
    release_value := pg_catalog.jsonb_build_object(
      'environment', matched.environment,
      'organizationId', matched.organization_id,
      'applicationRootId', matched.application_root_id,
      'applicationVersion', matched.application_version,
      'installationRevision', matched.installation_revision,
      'compilerWorkflowRevision', matched.workflow_revision,
      'namespace', matched.namespace,
      'providerFlowId', matched.flow_id,
      'candidateFingerprint', matched.candidate_fingerprint,
      'permanentFlowId', permanent_flow_id,
      'contentFingerprint', matched.content_fingerprint,
      'resolutionFingerprint', matched.resolution_fingerprint,
      'definition', declarations -> 0
    );
  end loop;
  if matched_count <> 1 then
    return null;
  end if;
  return pg_catalog.jsonb_build_object('runRecord', run_value, 'registeredRelease', release_value);
end
$function$;

comment on function vortex_platform.read_protected_workflow_run_registration(uuid) is
  'Private registered-run metadata reader: validates the retained run against its exact stored candidate identity and immutable published durable Flow; no provider, viewer or candidate-body authority.';

create or replace function vortex_platform.read_protected_workflow_run(p_run_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $function$
  select stored.run_record
  from vortex_platform.protected_workflow_runs as stored
  where vortex_platform.is_non_nil_uuid(p_run_id::text)
    and stored.run_id = p_run_id
$function$;

comment on function vortex_platform.read_protected_workflow_run(uuid) is
  'Private protected workflow run reader: returns the retained Vortex authority and private Kestra mapping for one run id to the trusted runtime only.';

create or replace function vortex_platform.refresh_protected_workflow_run_state(
  p_run_id uuid,
  p_state text,
  p_refreshed_at timestamptz
)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $function$
begin
  if not vortex_platform.is_non_nil_uuid(p_run_id::text)
    or p_state is null
    or p_state not in ('queued', 'running', 'waiting', 'completed', 'cancelled', 'failed')
    or p_refreshed_at is null then
    return false;
  end if;

  update vortex_platform.protected_workflow_runs as stored
  set run_record = pg_catalog.jsonb_set(
      pg_catalog.jsonb_set(
        pg_catalog.jsonb_set(
          stored.run_record,
          '{executionReference,lastKnownState}',
          pg_catalog.to_jsonb(p_state),
          false
        ),
        '{executionReference,lastRefreshedAt}',
        pg_catalog.to_jsonb(
          pg_catalog.to_char(
            p_refreshed_at at time zone 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
          )
        ),
        false
      ),
      '{authority,state}',
      pg_catalog.to_jsonb(case p_state
        when 'completed' then 'completed'
        when 'cancelled' then 'cancelled'
        when 'failed' then 'refused'
        else stored.run_record #>> '{authority,state}'
      end),
      false
    ),
    updated_at = pg_catalog.statement_timestamp()
  where stored.run_id = p_run_id
    and (stored.run_record #>> '{executionReference,lastRefreshedAt}')::timestamptz <= p_refreshed_at;

  return found;
end
$function$;

comment on function vortex_platform.refresh_protected_workflow_run_state(uuid, text, timestamptz) is
  'Private protected workflow run refresh: caches a safe Kestra state and closes callback authority after a terminal state.';

CREATE OR REPLACE FUNCTION vortex_platform.refuse_event_outbox_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception using errcode = '23514', message = 'Event outbox evidence is immutable';
end
$$;

create or replace function vortex_platform.register_workflow_flow_candidate(
  p_environment text,
  p_organization_id uuid,
  p_application_root_id uuid,
  p_application_version text,
  p_installation_revision bigint,
  p_workflow_revision bigint,
  p_candidate jsonb
)
returns table (outcome text, result jsonb)
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  expected_namespace text;
  flow_id_value text;
  workflow_id_value text;
  expected_id_suffix text;
  candidate_fingerprint text;
  stored vortex_platform.flow_registrations%rowtype;
begin
  if p_environment is null
    or p_environment not in ('local', 'testing', 'production')
    or p_organization_id is null
    or not vortex_platform.is_non_nil_uuid(p_organization_id::text)
    or p_application_root_id is null
    or not vortex_platform.is_non_nil_uuid(p_application_root_id::text)
    or p_application_version is null
    or p_application_version !~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$'
    or p_installation_revision is null
    or p_installation_revision not between 1 and 9007199254740991
    or p_workflow_revision is null
    or p_workflow_revision not between 1 and 9007199254740991
    or p_candidate is null
    or pg_catalog.jsonb_typeof(p_candidate) <> 'object' then
    raise exception using errcode = '22023',
      message = 'Workflow flow registration command is invalid';
  end if;

  -- A candidate is prepared inactive: registration must never hold a runnable
  -- flow. The typed fields are checked before any value is read out of them.
  if p_candidate -> 'active' is distinct from 'false'::jsonb
    or p_candidate #> '{trigger,disabled}' is distinct from 'true'::jsonb
    or coalesce(pg_catalog.jsonb_typeof(p_candidate -> 'id'), 'missing') <> 'string'
    or coalesce(pg_catalog.jsonb_typeof(p_candidate -> 'namespace'), 'missing') <> 'string'
    or coalesce(pg_catalog.jsonb_typeof(p_candidate -> 'workflowRevision'), 'missing')
      <> 'number' then
    raise exception using errcode = '22023',
      message = 'Workflow flow candidate is invalid or active';
  end if;

  if (p_candidate ->> 'workflowRevision') !~ '^[1-9][0-9]{0,15}$' then
    raise exception using errcode = '22023',
      message = 'Workflow flow candidate revision is invalid';
  end if;
  if (p_candidate ->> 'workflowRevision')::bigint <> p_workflow_revision then
    raise exception using errcode = '22023',
      message = 'Workflow flow candidate revision does not match its identity';
  end if;

  -- The namespace and flow id are derived only from permanent identity, exactly
  -- as the part A compiler derives them: `w_<workflow id>_<version>_r<revision>`
  -- with the lower-case workflow UUID, so the flow names one exact workflow of
  -- this exact release.
  expected_namespace := pg_catalog.concat_ws(
    '.',
    'vortex',
    'application',
    p_environment,
    p_organization_id::text,
    p_application_root_id::text,
    'i' || p_installation_revision::text
  );
  flow_id_value := p_candidate ->> 'id';
  expected_id_suffix := '_' || pg_catalog.replace(p_application_version, '.', '-')
    || '_r' || p_workflow_revision::text;
  workflow_id_value := pg_catalog.substr(flow_id_value, 3, 36);
  if (p_candidate ->> 'namespace') <> expected_namespace
    or pg_catalog.char_length(flow_id_value) > 100
    or flow_id_value <> 'w_' || workflow_id_value || expected_id_suffix
    or workflow_id_value !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or not vortex_platform.is_non_nil_uuid(workflow_id_value) then
    raise exception using errcode = '22023',
      message = 'Workflow flow candidate identity does not match its installation';
  end if;

  -- The identity must name a real published release of an Application the
  -- organisation owns, and the flow's workflow must be published in exactly that
  -- release. A caller can never register a mapping for another organisation's
  -- Application, an unpublished revision or a workflow the release lacks. The
  -- key-share locks keep that release evidence in place for this transaction.
  perform 1
  from vortex_definition.releases as application_release
  join vortex_definition.roots as application_root
    on application_root.root_id = application_release.root_id
  where application_release.root_id = p_application_root_id
    and application_release.release_revision = p_installation_revision
    and application_release.release_version = p_application_version
    and application_root.organization_id = p_organization_id
    and application_root.kind = 'application'
    and application_release.compilation_output #>> '{kind}' = 'application'
    and application_release.compilation_output #>> '{canonical,envelope,rootId}'
      = p_application_root_id::text
    and 1 = (
      select pg_catalog.count(*)
      from pg_catalog.jsonb_array_elements(
        case
          when pg_catalog.jsonb_typeof(
            application_release.compilation_output #> '{canonical,content,flows}'
          ) = 'array'
            then application_release.compilation_output #> '{canonical,content,flows}'
          else '[]'::jsonb
        end
      ) as published_flow(value)
      where pg_catalog.jsonb_typeof(published_flow.value) = 'object'
        and pg_catalog.jsonb_typeof(published_flow.value -> 'id') = 'string'
        and pg_catalog.lower(published_flow.value ->> 'id') = workflow_id_value
    )
    and exists (
      select 1
      from pg_catalog.jsonb_array_elements(
        case when pg_catalog.jsonb_typeof(
          application_release.compilation_output #> '{canonical,content,flows}'
        ) = 'array' then application_release.compilation_output #> '{canonical,content,flows}'
        else '[]'::jsonb end
      ) as published_flow(value)
      where pg_catalog.lower(published_flow.value ->> 'id') = workflow_id_value
        and published_flow.value -> 'execution' = '"durable"'::jsonb
    )
  for key share of application_release, application_root;
  if not found then
    raise exception using errcode = '22023',
      message = 'Workflow flow candidate does not belong to a published release';
  end if;

  candidate_fingerprint := 'sha256:' || pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(p_candidate::text, 'UTF8'), 'sha256'),
    'hex'
  );

  insert into vortex_platform.flow_registrations as registration (
    environment, organization_id, application_root_id, application_version,
    installation_revision, workflow_revision, namespace, flow_id,
    candidate_fingerprint, status, registered_at
  ) values (
    p_environment, p_organization_id, p_application_root_id, p_application_version,
    p_installation_revision, p_workflow_revision,
    p_candidate ->> 'namespace', flow_id_value,
    candidate_fingerprint, 'inactive', pg_catalog.statement_timestamp()
  )
  on conflict (
    environment, organization_id, application_root_id, application_version,
    installation_revision, workflow_revision, flow_id
  ) do nothing
  returning registration.* into stored;

  if stored.environment is not null then
    return query select 'registered'::text,
      vortex_platform.flow_registration_to_json_internal(stored);
    return;
  end if;

  -- The row existed already (or a concurrent transaction committed it first).
  -- The fingerprint decides: an exact retry converges, changed content is
  -- refused and left untouched.
  select registration.* into stored
  from vortex_platform.flow_registrations as registration
  where registration.environment = p_environment
    and registration.organization_id = p_organization_id
    and registration.application_root_id = p_application_root_id
    and registration.application_version = p_application_version
    and registration.installation_revision = p_installation_revision
    and registration.workflow_revision = p_workflow_revision
    and registration.flow_id = flow_id_value;
  -- Rows are never deleted, so a conflict always leaves one row to compare.
  if not found then
    raise exception using errcode = '55000',
      message = 'Workflow flow registration is unavailable';
  end if;

  if stored.candidate_fingerprint <> candidate_fingerprint then
    return query select 'refused'::text,
      pg_catalog.jsonb_build_object('reasonCode', 'candidate_changed');
    return;
  end if;

  return query select 'existing'::text,
    vortex_platform.flow_registration_to_json_internal(stored);
end
$function$;

comment on function vortex_platform.register_workflow_flow_candidate(
  text, uuid, uuid, text, bigint, bigint, jsonb
) is
  'Idempotently registers one inactive durable Flow candidate under its exact published Application release identity, refusing a changed candidate for an existing identity.';

create or replace function vortex_platform.request_event_dispatch_wakeup()
returns trigger
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  endpoint_url text := nullif(
    pg_catalog.current_setting('vortex.event_dispatch_wakeup_url', true), ''
  );
  bearer_credential text := nullif(
    pg_catalog.current_setting('vortex.event_dispatch_wakeup_bearer', true), ''
  );
  failure_sqlstate text;
  failure_message text;
begin
  -- Fail closed: an unconfigured endpoint or credential sends nothing.
  if endpoint_url is null or bearer_credential is null then
    return null;
  end if;
  -- Only a whitespace-free HTTPS endpoint is accepted, so a database setting
  -- cannot point the hint at a plaintext or non-HTTP target.
  if endpoint_url !~ '^https://[^[:space:]]+$' then
    return null;
  end if;
  -- The bearer must have the exact printable-ASCII shape and length the #641
  -- route accepts; anything else would only queue a doomed request.
  if bearer_credential !~ '^[!-~]+$'
    or pg_catalog.octet_length(bearer_credential) not between 32 and 512 then
    return null;
  end if;

  -- One hint per transaction is enough: a multi-occurrence append is one
  -- durable unit of work, and the scheduled recovery tick covers a missed
  -- hint. A later inserted row in the same transaction queues no second
  -- request.
  if pg_catalog.current_setting('vortex.event_dispatch_wakeup_sent', true) = 'true' then
    return null;
  end if;

  -- pg_net queues the request transactionally and sends it only after this
  -- transaction commits; a rolled-back append sends nothing. The hint must
  -- never make the durable append fail, so an enqueue failure is logged with
  -- its cause and leaves the sent flag unset: a later row in this transaction
  -- tries again, and the scheduled recovery tick covers a hint that never left.
  begin
    perform net.http_post(
      url := endpoint_url,
      headers := pg_catalog.jsonb_build_object(
        'Authorization', 'Bearer ' || bearer_credential,
        'Content-Type', 'application/json'
      ),
      body := pg_catalog.jsonb_build_object('source', 'database_webhook'),
      timeout_milliseconds := 5000
    );
    perform pg_catalog.set_config('vortex.event_dispatch_wakeup_sent', 'true', true);
  exception when others then
    get stacked diagnostics failure_sqlstate = returned_sqlstate,
      failure_message = message_text;
    raise warning 'Event dispatch wake-up was not queued: SQLSTATE %, %',
      failure_sqlstate, failure_message;
  end;
  return null;
end
$function$;

comment on function vortex_platform.request_event_dispatch_wakeup() is
  'Best-effort database-webhook wake-up hint for the protected Vercel event dispatcher, queued once per appending transaction and sent after commit. Reads its HTTPS endpoint and bearer credential from the vortex.event_dispatch_wakeup_url and vortex.event_dispatch_wakeup_bearer database settings at runtime and sends nothing when either is absent or unusable.';

create or replace function vortex_platform.reserve_file_upload(
  p_file_id uuid,
  p_organization_id uuid,
  p_application_root_id uuid,
  p_owner_record_type_id uuid,
  p_owner_record_id uuid,
  p_owner_field_id uuid,
  p_original_safe_display_name text,
  p_extension text,
  p_storage_key text,
  p_uploaded_by jsonb,
  p_maximum_bytes bigint,
  p_max_files integer,
  p_existing_attachment_count integer,
  p_replacing_file_id uuid,
  p_capability_reservation_id uuid,
  p_one_time_id uuid,
  p_policy_fingerprint text,
  p_grant_expires_at timestamptz,
  p_upload_expires_at timestamptz
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  evaluated_at timestamptz := pg_catalog.statement_timestamp();
  established jsonb := vortex_platform.upload_validated_context();
  request_actor jsonb := vortex_platform.upload_request_actor(established);
  in_flight_count bigint;
  existing_count bigint;
  reserved vortex_platform.file_records%rowtype;
begin
  if request_actor is null
    or p_organization_id is distinct from (established ->> 'organizationId')::uuid
    or p_application_root_id is distinct from (established ->> 'applicationRootId')::uuid
    or p_uploaded_by is distinct from request_actor then
    raise exception using errcode = '42501', message = 'File upload scope is unavailable';
  end if;

  if p_file_id is null
    or p_owner_record_type_id is null
    or p_owner_record_id is null
    or p_owner_field_id is null
    or p_maximum_bytes is null or p_maximum_bytes < 1
    or p_maximum_bytes > vortex_platform.upload_maximum_bytes_limit()
    or p_max_files is null or p_max_files < 1
    or p_existing_attachment_count is null or p_existing_attachment_count < 0
    or p_capability_reservation_id is null
    or p_one_time_id is null
    or p_policy_fingerprint is null
    or p_grant_expires_at is null
    or p_grant_expires_at <= evaluated_at
    or p_grant_expires_at > evaluated_at + interval '65 seconds'
    or p_upload_expires_at is null
    or p_upload_expires_at < p_grant_expires_at
    or p_upload_expires_at > evaluated_at + interval '24 hours 5 minutes' then
    raise exception using errcode = '22023', message = 'File upload reservation is invalid';
  end if;

  -- Admissions to one attachment field are serialised so concurrent uploads
  -- cannot together exceed its file count.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(pg_catalog.concat_ws(E'\x1f',
      'vortex_platform.upload_field', p_organization_id::text,
      p_owner_record_type_id::text, p_owner_record_id::text, p_owner_field_id::text), 652)
  );

  perform 1
  from vortex_access.capability_reservations as funding
  where funding.reservation_id = p_capability_reservation_id
    and funding.tenant_id = (established ->> 'tenantId')::uuid
    and funding.request_organization_id = p_organization_id
    and funding.correlation_id = (established ->> 'correlationId')::uuid
    and funding.state = 'active'
    and funding.expires_at > evaluated_at
    and funding.reserved_quantity - funding.consumed_quantity - funding.released_quantity > 0
  for update;
  if not found then
    if not exists (
      select 1 from vortex_platform.upload_reservations as retried
      where retried.capability_reservation_id = p_capability_reservation_id
        and retried.file_id = p_file_id
    ) then
      perform vortex_platform.append_file_activity_internal(
        'file_upload_refused', p_organization_id);
    end if;
    return vortex_platform.upload_refusal('capability_refused');
  end if;

  if exists (
    select 1 from vortex_platform.upload_reservations as reservation
    where reservation.capability_reservation_id = p_capability_reservation_id
  ) then
    if not exists (
      select 1 from vortex_platform.upload_reservations as retried
      where retried.capability_reservation_id = p_capability_reservation_id
        and retried.file_id = p_file_id
    ) then
      perform vortex_platform.append_file_activity_internal(
        'file_upload_refused', p_organization_id);
    end if;
    return vortex_platform.upload_refusal('capability_refused');
  end if;

  select pg_catalog.count(*) into existing_count
  from vortex_platform.file_records as attached
  where attached.organization_id = p_organization_id
    and attached.owner_record_type_id = p_owner_record_type_id
    and attached.owner_record_id = p_owner_record_id
    and attached.owner_field_id = p_owner_field_id
    and attached.lifecycle_state = 'active';

  if p_replacing_file_id is not null and (
    existing_count < 1
    or not exists (
      select 1 from vortex_platform.file_records as replaced
      where replaced.file_id = p_replacing_file_id
        and replaced.organization_id = p_organization_id
        and replaced.owner_record_type_id = p_owner_record_type_id
        and replaced.owner_record_id = p_owner_record_id
        and replaced.owner_field_id = p_owner_field_id
        and replaced.lifecycle_state = 'active'
    )
  ) then
    return vortex_platform.upload_refusal('replacement_file_not_found');
  end if;

  select pg_catalog.count(*) into in_flight_count
  from vortex_platform.upload_reservations as reservation
  join vortex_platform.file_records as uploaded
    on uploaded.file_id = reservation.file_id
  where reservation.organization_id = p_organization_id
    and reservation.owner_record_type_id = p_owner_record_type_id
    and reservation.owner_record_id = p_owner_record_id
    and reservation.owner_field_id = p_owner_field_id
    and reservation.upload_expires_at > evaluated_at
    and uploaded.lifecycle_state in ('pending', 'uploaded', 'scanning');

  if existing_count
    - (case when p_replacing_file_id is null then 0 else 1 end)
    + in_flight_count >= p_max_files then
    return vortex_platform.upload_refusal('field_capacity_exceeded');
  end if;

  insert into vortex_platform.file_records (
    file_id, organization_id, application_root_id,
    owner_record_type_id, owner_record_id, owner_field_id,
    owning_attachment_references, lifecycle_state, original_safe_display_name,
    detected_media_type, extension, size_bytes, checksum,
    storage_key, bucket_id, scanner_name, scanner_version, scanner_result,
    preview_references, uploaded_by, legal_hold, created_at
  ) values (
    p_file_id, p_organization_id, p_application_root_id,
    p_owner_record_type_id, p_owner_record_id, p_owner_field_id,
    '{}'::uuid[], 'pending', p_original_safe_display_name,
    'application/octet-stream', p_extension, 0, 'sha256:' || pg_catalog.repeat('0', 64),
    p_storage_key, 'private_files', 'vortex_file_preflight', '1', 'pending',
    '[]'::jsonb, request_actor, false, evaluated_at
  )
  returning * into reserved;

  insert into vortex_platform.upload_reservations (
    file_id, organization_id, owner_record_type_id, owner_record_id, owner_field_id,
    uploaded_by, maximum_bytes, capability_reservation_id, replacing_file_id,
    correlation_id, upload_expires_at, revision, created_at, updated_at, max_files
  ) values (
    p_file_id, p_organization_id, p_owner_record_type_id, p_owner_record_id, p_owner_field_id,
    request_actor, p_maximum_bytes, p_capability_reservation_id, p_replacing_file_id,
    (established ->> 'correlationId')::uuid, p_upload_expires_at, 1, evaluated_at, evaluated_at,
    p_max_files
  );

  insert into vortex_platform.upload_grants (
    one_time_id, file_id, organization_id, actor, maximum_bytes,
    policy_fingerprint, expires_at, created_at
  ) values (
    p_one_time_id, p_file_id, p_organization_id, request_actor, p_maximum_bytes,
    p_policy_fingerprint, p_grant_expires_at, evaluated_at
  );

  perform vortex_platform.append_file_activity_internal(
    'file_upload_admitted', p_file_id);

  return pg_catalog.jsonb_build_object(
    'outcome', 'reserved',
    'fileRecord', vortex_platform.upload_file_record(reserved)
  );
end
$function$;

comment on function vortex_platform.reserve_file_upload(
  uuid, uuid, uuid, uuid, uuid, uuid, text, text, text, jsonb, bigint, integer, integer,
  uuid, uuid, uuid, text, timestamptz, timestamptz
) is
  'Reserves a pending file, its capacity binding and its first grant under a lock on the owning attachment field.';

revoke execute on function
  vortex_platform.reserve_file_upload(
    uuid, uuid, uuid, uuid, uuid, uuid, text, text, text, jsonb, bigint, integer, integer,
    uuid, uuid, uuid, text, timestamptz, timestamptz
  ) from public, anon, authenticated, service_role, vortex_runtime, vortex_request, vortex_record_adapter;

grant execute on function
  vortex_platform.reserve_file_upload(
    uuid, uuid, uuid, uuid, uuid, uuid, text, text, text, jsonb, bigint, integer, integer,
    uuid, uuid, uuid, text, timestamptz, timestamptz
  ) to vortex_request;

alter function vortex_platform.reserve_file_upload(
  uuid, uuid, uuid, uuid, uuid, uuid, text, text, text, jsonb, bigint, integer, integer,
  uuid, uuid, uuid, text, timestamptz, timestamptz
) owner to postgres;

create or replace function vortex_platform.resolve_connection_instance_readiness(
  p_organization_id uuid,
  p_application_root_id uuid,
  p_connection_instance_id uuid,
  p_destination_key text,
  p_expected_revision bigint,
  p_expected_fingerprint text
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  nil_uuid constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  context_value jsonb;
  context_org_id uuid;
  context_app_id uuid;
  conn_row vortex_platform.connection_instances%rowtype;
  now_ts timestamptz := pg_catalog.statement_timestamp();
begin
  -- 1. Validate parameter shapes (all mandatory)
  if p_organization_id is null or p_organization_id = nil_uuid
    or p_connection_instance_id is null or p_connection_instance_id = nil_uuid
    or p_application_root_id is null or p_application_root_id = nil_uuid
    or p_destination_key is null
    or pg_catalog.char_length(p_destination_key) not between 1 and 80
    or p_destination_key !~ '^[a-z0-9]+(?:[-_][a-z0-9]+)*$'
    or p_expected_revision is null
    or p_expected_revision not between 1 and 9007199254740991
    or p_expected_fingerprint is null
    or p_expected_fingerprint !~ '^[a-f0-9]{64}$' then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused',
      'reasonCode', 'invalid_parameters'
    );
  end if;

  -- 2. Validate request context binding
  context_value := vortex_platform.current_context();
  context_org_id := vortex_platform.organization_id();
  if context_org_id is null or context_org_id <> p_organization_id then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused',
      'reasonCode', 'organization_mismatch'
    );
  end if;

  -- Connection instances strictly require permanent application scope (not organisation-shared)
  if context_value ? 'applicationRootId' then
    context_app_id := (context_value ->> 'applicationRootId')::uuid;
    if context_app_id is distinct from p_application_root_id then
      return pg_catalog.jsonb_build_object(
        'outcome', 'refused',
        'reasonCode', 'application_mismatch'
      );
    end if;
  end if;

  -- 3. Read connection instance row under FOR SHARE lock
  select conn.* into conn_row
  from vortex_platform.connection_instances as conn
  where conn.connection_instance_id = p_connection_instance_id
    and conn.organization_id = p_organization_id
  for share;

  if not found then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused',
      'reasonCode', 'connection_unavailable'
    );
  end if;

  -- 4. Check active state and health outcome
  if conn_row.state <> 'active' then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused',
      'reasonCode', 'connection_not_active',
      'currentState', conn_row.state
    );
  end if;

  if conn_row.last_health_outcome <> 'healthy' then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused',
      'reasonCode', 'connection_unhealthy',
      'currentHealthOutcome', conn_row.last_health_outcome
    );
  end if;

  -- 5. Check token expiry if set
  if conn_row.token_expires_at is not null
    and (not pg_catalog.isfinite(conn_row.token_expires_at)
      or conn_row.token_expires_at <= now_ts) then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused',
      'reasonCode', 'connection_token_expired'
    );
  end if;

  -- 6. Check destination key
  if conn_row.destination_key <> p_destination_key then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused',
      'reasonCode', 'destination_mismatch'
    );
  end if;

  -- 7. Mandatory revision freshness check
  if conn_row.revision <> p_expected_revision then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused',
      'reasonCode', 'stale_revision',
      'currentRevision', conn_row.revision
    );
  end if;

  -- 8. Mandatory destination fingerprint freshness check
  if conn_row.destination_fingerprint <> p_expected_fingerprint then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused',
      'reasonCode', 'stale_fingerprint'
    );
  end if;

  -- 9. Lock the exact application grant and its permanent root for the decision.
  perform 1
  from vortex_platform.connection_application_grants as grant_entry
  join vortex_definition.roots as app_root
    on app_root.root_id = grant_entry.application_root_id
    and app_root.organization_id = grant_entry.organization_id
    and app_root.kind = 'application'
  where grant_entry.connection_instance_id = p_connection_instance_id
    and grant_entry.application_root_id = p_application_root_id
    and grant_entry.organization_id = p_organization_id
  for share of grant_entry, app_root;

  if not found then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused',
      'reasonCode', 'grant_unauthorized'
    );
  end if;

  -- All Connection, exact grant and permanent App-root lock waits are complete.
  -- The early expiry refusal remains; a token that expired during either wait
  -- must be refused at this same timestamp used by the ready evidence.
  now_ts := pg_catalog.clock_timestamp();
  if conn_row.token_expires_at is not null
    and (not pg_catalog.isfinite(conn_row.token_expires_at)
      or conn_row.token_expires_at <= now_ts) then
    return pg_catalog.jsonb_build_object(
      'outcome', 'refused',
      'reasonCode', 'connection_token_expired'
    );
  end if;

  -- 10. Return authoritative owner-projected readiness evidence
  return pg_catalog.jsonb_build_object(
    'outcome', 'ready',
    'connectionInstanceId', conn_row.connection_instance_id,
    'organizationId', conn_row.organization_id,
    'applicationRootId', p_application_root_id,
    'destinationKey', conn_row.destination_key,
    'destinationFingerprint', conn_row.destination_fingerprint,
    'revision', conn_row.revision,
    'healthOutcome', conn_row.last_health_outcome,
    'state', conn_row.state,
    'tokenExpiresAt', pg_catalog.to_jsonb(conn_row.token_expires_at),
    'verifiedAt', pg_catalog.to_jsonb(now_ts)
  );
end
$function$;

comment on function vortex_platform.resolve_connection_instance_readiness(
  uuid, uuid, uuid, text, bigint, text
) is
  '#408: Authoritative owner-projected Connection-instance readiness resolver. Fails closed on inactive, unhealthy, expired, mismatched destination, ungranted application, or stale revision/fingerprint.';

revoke all on function
  vortex_platform.resolve_connection_instance_readiness(uuid, uuid, uuid, text, bigint, text) from public, anon, authenticated, service_role, vortex_runtime, vortex_request;

grant execute on function
  vortex_platform.resolve_connection_instance_readiness(uuid, uuid, uuid, text, bigint, text) to vortex_request, vortex_runtime;

grant execute on function vortex_platform.resolve_connection_instance_readiness(
  uuid, uuid, uuid, text, bigint, text
) to vortex_owner;

create or replace function vortex_platform.start_value_matches_type_internal(
  p_type text,
  p_value jsonb
)
returns boolean
language plpgsql
immutable
security invoker
set search_path = ''
as $function$
declare
  item jsonb;
begin
  if p_type is null or p_value is null then
    return false;
  end if;

  -- The published literal contract excludes template syntax at every JSON depth.
  -- Keep the private writer aligned when it is called without the TypeScript API.
  if pg_catalog.strpos(p_value::text, '{{') > 0
    or pg_catalog.strpos(p_value::text, '{%') > 0 then
    return false;
  end if;

  if p_type = 'json' then
    return true;
  elsif p_type = 'yes_no' then
    return pg_catalog.jsonb_typeof(p_value) = 'boolean';
  elsif p_type = 'whole_number' then
    return pg_catalog.jsonb_typeof(p_value) = 'number'
      and p_value::text ~ '^-?(0|[1-9][0-9]*)$'
      and (p_value::text)::numeric between -9007199254740991 and 9007199254740991;
  elsif p_type in ('decimal_number', 'money') then
    return pg_catalog.jsonb_typeof(p_value) = 'string'
      and p_value #>> '{}' ~ '^-?(0|[1-9][0-9]*)(\.[0-9]+)?$';
  elsif p_type in ('text', 'formatted_text') then
    return pg_catalog.jsonb_typeof(p_value) = 'string';
  elsif p_type = 'date' then
    if pg_catalog.jsonb_typeof(p_value) <> 'string'
      or p_value #>> '{}' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
      return false;
    end if;
    begin
      return pg_catalog.to_char((p_value #>> '{}')::date, 'YYYY-MM-DD')
        = p_value #>> '{}';
    exception when invalid_datetime_format or datetime_field_overflow then
      return false;
    end;
  elsif p_type = 'date_time' then
    if pg_catalog.jsonb_typeof(p_value) <> 'string'
      or p_value #>> '{}' !~
        '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$' then
      return false;
    end if;
    begin
      perform (p_value #>> '{}')::timestamptz;
      return true;
    exception when invalid_datetime_format or datetime_field_overflow then
      return false;
    end;
  elsif p_type in (
    'choice', 'record_reference', 'organization_account_reference',
    'workflow_run_reference', 'relationship_reference', 'file_reference'
  ) then
    return pg_catalog.jsonb_typeof(p_value) = 'string'
      and pg_catalog.length(p_value #>> '{}') > 0;
  elsif p_type in (
    'several_choices', 'record_reference_list', 'relationship_reference_list'
  ) then
    if pg_catalog.jsonb_typeof(p_value) <> 'array' then
      return false;
    end if;
    for item in select value from pg_catalog.jsonb_array_elements(p_value) loop
      if pg_catalog.jsonb_typeof(item) <> 'string'
        or pg_catalog.length(item #>> '{}') = 0 then
        return false;
      end if;
    end loop;
    return true;
  end if;
  return false;
end
$function$;

comment on function vortex_platform.start_value_matches_type_internal(text, jsonb) is
  'Checks the stored JSON shape of one declared flow input or trigger value; only the start-intent writer calls this private helper.';

create or replace function vortex_platform.topic_application_root_id(p_topic text)
returns uuid
language sql
stable
security invoker
set search_path = ''
as $function$
  select case
    when p_topic ~ (
      '^'
      || (
        vortex_access.validation_reference_list('private_invalidation_topic_prefix')
      )[1]
      || ':[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'
      || ':[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    )
      then pg_catalog.split_part(p_topic, ':', 4)::uuid
    else null
  end
$function$;

comment on function vortex_platform.topic_application_root_id(text) is
  'Extracts the application from a well-formed private topic, or null.';

