create or replace function vortex_record.document_entries_are_valid(p_entries jsonb)
returns boolean
language sql immutable strict parallel safe security invoker set search_path = ''
as $function$
  select case
    when pg_catalog.jsonb_typeof(p_entries) <> 'array' then false
    else pg_catalog.jsonb_array_length(p_entries) <= 100
      and pg_catalog.pg_column_size(p_entries) <= 262144
      and not exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_entries) as entry(value)
        where pg_catalog.jsonb_typeof(entry.value) <> 'object'
          or not (entry.value ?& array['fieldId', 'priority', 'weight', 'text'])
          or (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(entry.value)) <> 4
          or pg_catalog.jsonb_typeof(entry.value -> 'fieldId') <> 'string'
          or (entry.value ->> 'fieldId') !~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
          or pg_catalog.jsonb_typeof(entry.value -> 'priority') <> 'string'
          or pg_catalog.jsonb_typeof(entry.value -> 'weight') <> 'number'
          or pg_catalog.jsonb_typeof(entry.value -> 'text') <> 'string'
          or pg_catalog.length(entry.value ->> 'text') not between 1 and 4000
      )
      and (
        select pg_catalog.count(distinct entry.value ->> 'fieldId') = pg_catalog.count(*)
          and coalesce(pg_catalog.sum(pg_catalog.length(entry.value ->> 'text')), 0) <= 20000
        from pg_catalog.jsonb_array_elements(p_entries) as entry(value)
      )
  end;
$function$;

comment on function vortex_record.document_entries_are_valid(jsonb) is
  'Storage check for search document entries: bounded array of unique field entries with the exact entry shape, types and text sizes; ranking weights are derived by the runtime producer.';

create or replace function vortex_record.enforce_document_application_root()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
  application_root record;
begin
  if new.application_root_id is null then
    return new;
  end if;

  select root.organization_id, root.kind into application_root
  from vortex_definition.roots as root
  where root.root_id = new.application_root_id;

  if not found or application_root.kind <> 'application'
    or application_root.organization_id <> new.organization_id then
    raise exception using errcode = '23514',
      message = 'Search document application does not belong to the organisation';
  end if;

  return new;
end
$function$;

comment on function vortex_record.enforce_document_application_root() is
  'Checks that a search document application root is an Application root belonging to the same organisation.';

alter function vortex_record.enforce_document_application_root()
  owner to postgres;

create or replace function vortex_record.record_super_administrator_authority_internal()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
  actor_identity_id uuid;
  authority_assignment_id uuid;
begin
  if new.actor_kind = 'identity' then
    actor_identity_id := new.actor_id;
  elsif new.actor_kind = 'organization_account' then
    select account.identity_id
    into actor_identity_id
    from vortex_identity.organization_accounts as account
    where account.organization_id = new.organization_id
      and account.organization_account_id = new.actor_id;
  end if;

  if actor_identity_id is null then
    return new;
  end if;

  authority_assignment_id :=
    vortex_identity.resolve_active_vortex_super_administrator_assignment_internal(
      actor_identity_id, new.occurred_at
    );
  if authority_assignment_id is null then
    return new;
  end if;

  insert into vortex_record.organization_activity_super_administrator_authority (
    organization_id, activity_id, authority_kind, assignment_id
  ) values (
    new.organization_id, new.activity_id, 'vortex_super_administrator',
    authority_assignment_id
  );
  return new;
end
$function$;

comment on function vortex_record.record_super_administrator_authority_internal() is
  'Attributes each organisation activity by an assigned Vortex super administrator to the exact active assignment without changing activity writers.';

